#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CE_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_flame_sensor();
int read_mcp3008(int channel);
float approximate_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int flame_sensor_pin;
    int mcp3008_ce_pin;
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    char *log_file;
} config_t;

config_t config = {
    .flame_sensor_pin = FLAME_SENSOR_PIN,
    .mcp3008_ce_pin = MCP3008_CE_PIN,
    .spi_channel = SPI_CHANNEL,
    .spi_baud = SPI_BAUD,
    .mcp3008_channel = MCP3008_CHANNEL,
    .log_file = "flame_data.csv"
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(config.mcp3008_channel);
        float temperature = approximate_temperature(adc_value);

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    cleanup();
    return 0;
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set flame sensor pin as input
    gpioSetMode(config.flame_sensor_pin, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,FlameDetected,Temperature\n");
    }

    return 0;
}

// Read flame sensor value
int read_flame_sensor() {
    return gpioRead(config.flame_sensor_pin);
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Approximate temperature from ADC value
float approximate_temperature(int adc_value) {
    // Simple linear approximation (adjust as needed)
    // Assuming 0 ADC = 0°C, 1023 ADC = 100°C
    return (float)adc_value / 1023.0 * 100.0;
}

// Log data to CSV file
int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

