#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_GAIN_4_096V 0x4000
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0080
#define ADS1115_COMP_QUE_DISABLE 0x0003
#define TEMPERATURE_THRESHOLD 60.0
#define BUZZER_DURATION 2000 // milliseconds

// Global variables
static volatile bool running = true;
static int i2c_fd;
static FILE *log_file;

// Function prototypes
int init_gpio();
int init_i2c();
int init_ads1115();
int read_flame_sensor();
int read_temperature_sensor();
bool debounce_flame_sensor(int current_value);
bool is_fire_condition(int flame_value, int temperature_value);
void activate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int init_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(FLAME_SENSOR_PIN, INPUT);
    pinMode(BUZZER_PIN, OUTPUT);
    digitalWrite(BUZZER_PIN, LOW); // Ensure buzzer is initially off

    return 0;
}

// Function to initialize I2C communication
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(ADS1115_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the ADS1115 ADC
int init_ads1115() {
    // Configure ADS1115 for single-ended AIN0, 4.096V gain, 128 SPS, continuous mode disabled
    int config = ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_GAIN_4_096V | ADS1115_COMP_QUE_DISABLE;
    config = (config >> 8) | ((config & 0xFF) << 8); // Byte swap

    if (wiringPiI2CWriteReg16(i2c_fd, ADS1115_CONFIG_REG, config) == -1) {
        fprintf(stderr, "Error writing to ADS1115 config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return digitalRead(FLAME_SENSOR_PIN);
}

// Function to read the temperature sensor
int read_temperature_sensor() {
    int16_t raw_value = wiringPiI2CReadReg16(i2c_fd, ADS1115_CONVERSION_REG);
    if (raw_value == -1) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    // Byte swap
    raw_value = (raw_value >> 8) | ((raw_value & 0xFF) << 8);

    // Convert to temperature (example: assuming 0 counts = 0°C, 32767 counts = 100°C)
    float temperature = ((float)raw_value / 32767.0) * 100.0; // Example scaling
    return (int)temperature; // Return as integer
}

// Function to debounce the flame sensor
bool debounce_flame_sensor(int current_value) {
    static int last_value = HIGH; // Initialize to HIGH (assuming HIGH is no flame)
    static unsigned long last_debounce_time = 0;
    unsigned long current_time = millis();

    if (current_value != last_value) {
        last_debounce_time = current_time;
    }

    if (current_time - last_debounce_time > 50) { // Debounce time of 50ms
        if (current_value == last_value) {
            return true; // Valid reading
        }
    }

    last_value = current_value;
    return false; // Invalid reading
}

