void activate_buzzer() {
    digitalWrite(BUZZER_PIN, HIGH);
    delay(BUZZER_DURATION);
    digitalWrite(BUZZER_PIN, LOW);
}

// Function to log an event to the fire_log.txt file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    digitalWrite(BUZZER_PIN, LOW); // Ensure buzzer is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    // No need to explicitly close I2C in wiringPi, it's handled by the OS on exit
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() == -1) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_value = read_flame_sensor();
        int temperature_value = read_temperature_sensor();

        if (temperature_value == -1) {
            // Handle ADC read error (e.g., retry or skip)
            delay(100); // Small delay before retrying
            continue;
        }

        bool flame_debounced = debounce_flame_sensor(flame_value);

        if (flame_debounced) {
            if (is_fire_condition(flame_value, temperature_value)) {
                log_event("Fire detected!");
                activate_buzzer();
            } else if (flame_value == LOW) {
                log_event("Flame detected!");
            } else if (temperature_value > TEMPERATURE_THRESHOLD) {
                char temp_str[20];
                snprintf(temp_str, sizeof(temp_str), "Temperature above threshold: %.2f°C", (float)temperature_value);
                log_event(temp_str);
            }
        }

        delay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

