#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_GAIN_4_096V 0x4000 // +/- 4.096V
#define ADS1115_SINGLE_ENDED_0 0x4000 // Single-ended input A0
#define ADS1115_RATE_128SPS 0x0000 // 128 SPS
#define CO_LOG_FILE "co_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int ads1115_address;
    char *log_file;
} config_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_ads1115(int handle, int *raw_value);
float convert_to_resistance(int raw_value);
float calculate_ppm(float resistance);
int log_ppm(float ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c(int bus, int addr) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(bus, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return i2c_handle;
}

// Reads the raw ADC value from the ADS1115
int read_ads1115(int handle, int *raw_value) {
    char config[3];
    char data[2];
    int16_t adc_value;

    // Configure ADS1115 for single-ended A0, +/- 4.096V, 128 SPS
    config[0] = ADS1115_CONFIG_REG;
    config[1] = ADS1115_GAIN_4_096V | ADS1115_SINGLE_ENDED_0 | ADS1115_RATE_128SPS;
    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write configuration to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    config[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(handle, config, 1) != 0) {
        fprintf(stderr, "Failed to write conversion register address to ADS1115\n");
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data from ADS1115\n");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];
    *raw_value = (int)adc_value; // Cast to int

    return 0;
}

