    return resistance;
}

// Calculates the CO concentration in ppm (example formula)
float calculate_ppm(float resistance) {
    // This is a placeholder.  You'll need to calibrate this based on your sensor.
    // The MICS-4514 datasheet provides a resistance vs. CO concentration curve.
    // You'll need to determine the slope and intercept of that curve.
    // This example assumes a logarithmic relationship.
    float ppm = 100.0 * (1.0 - exp(-resistance / 1000.0)); // Example logarithmic scaling
    return ppm;
}

// Logs the CO concentration to a file
int log_ppm(float ppm) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm);
    fclose(fp);

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

