    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(config.i2c_bus, config.ads1115_address);
    if (i2c_handle < 0) {
        return 1;
    }

    printf("CO Sensor Monitoring Started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        if (read_ads1115(i2c_handle, &raw_value) == 0) {
            // Convert to resistance
            resistance = convert_to_resistance(raw_value);

            // Calculate CO concentration
            ppm = calculate_ppm(resistance);

            // Log the CO concentration
            if (log_ppm(ppm) != 0) {
                fprintf(stderr, "Failed to log CO concentration\n");
            }

            printf("CO Concentration: %.2f ppm\n", ppm);
        } else {
            fprintf(stderr, "Failed to read CO sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    printf("CO Sensor Monitoring Stopped.\n");
    return 0;
}

