// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008_channel(int channel);
float convert_adc_to_temperature(int adc_value);
int log_data(int flame_present, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read the MCP3008 ADC channel
int read_mcp3008_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_adc_to_temperature(int adc_value) {
    // Simple linear conversion (replace with actual calibration data)
    // Assuming 0 ADC = 0°C, 1023 ADC = 100°C
    return (float)adc_value * 100.0 / 1023.0;
}

// Function to log data to a CSV file
int log_data(int flame_present, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_present, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlamePresent,Temperature\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int flame_present = read_flame_sensor();
        if (flame_present == PI_BAD_GPIO) {
            fprintf(stderr, "Error: Invalid GPIO pin %d\n", FLAME_SENSOR_PIN);
            break;
        }

        int adc_value = read_mcp3008_channel(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break;
        }

        float temperature = convert_adc_to_temperature(adc_value);

        log_data(flame_present, temperature);

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

