#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define MIC1_CS 8
#define MIC2_CS 9
#define LED_PIN 27
#define SAMPLE_RATE 1000 // Hz
#define WINDOW_SIZE 100  // Number of samples per channel
#define HIGH_THRESHOLD 1000
#define LED_ON_TIME 500 // ms
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int spi_handle;

// Structure to hold microphone data
typedef struct {
    int16_t data[WINDOW_SIZE];
    int index;
} MicrophoneData;

// Function prototypes
int initialize();
int read_mcp3008(int cs_pin, int channel);
double calculate_rms(int16_t *data, int size);
void log_data(double mic1_rms, double mic2_rms);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn LED off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int cs_pin, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    gpioWrite(cs_pin, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(cs_pin, 1); // Deselect the chip

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate RMS level
double calculate_rms(int16_t *data, int size) {
    double sum_sq = 0.0;
    for (int i = 0; i < size; i++) {
        sum_sq += (double)data[i] * data[i];
    }
    return sqrt(sum_sq / size);
}

// Log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }
    rewind(log_file);

    MicrophoneData mic1_data = {0};
    mic1_data.index = 0;
    MicrophoneData mic2_data = {0};
    mic2_data.index = 0;

    // Main loop
    while (running) {
        // Read microphone data
        int mic1_value = read_mcp3008(MIC1_CS, 0);
        int mic2_value = read_mcp3008(MIC2_CS, 0);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error reading microphone data\n");
            continue; // Skip to the next iteration
        }

        mic1_data.data[mic1_data.index] = (int16_t)mic1_value;
        mic2_data.data[mic2_data.index] = (int16_t)mic2_value;

        mic1_data.index = (mic1_data.index + 1) % WINDOW_SIZE;
        mic2_data.index = (mic2_data.index + 1) % WINDOW_SIZE;

        // Calculate RMS levels
        double mic1_rms = calculate_rms(mic1_data.data, WINDOW_SIZE);
        double mic2_rms = calculate_rms(mic2_data.data, WINDOW_SIZE);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check for high-level threshold
        if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
            control_led(1); // Turn LED on
            gpioDelay(LED_ON_TIME * 1000); // Delay in microseconds
            control_led(0); // Turn LED off
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Delay for 1 ms (adjust for sample rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

