#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A
#define TCS34725_ID 0x12

// Expected TCS34725 ID
#define TCS34725_ID_VALUE 0x44

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    int status;

    // Enable the sensor (power on and enable RGBC)
    status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03); // PON | AEN
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }
    gpioDelay(3); // Wait 3ms

    // Set integration time (ATIME) - 2.4ms * 256 = 614.4ms
    status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xEB); // 2.4ms * 256 = 614.4ms
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", status);
        return -1;
    }

    // Set gain (AGAIN) - 60x
    status = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01); // 60x gain
    if (status < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %d\n", status);
        return -1;
    }

    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }

    if (sensor_id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", sensor_id, TCS34725_ID_VALUE);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int status;

    // Read clear data
    status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", status);
        return -1;
    }
    *clear = (uint16_t)status;

    // Read red data
    status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %d\n", status);
        return -1;
    }
    *red = (uint16_t)status;

    // Read green data
    status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %d\n", status);
        return -1;
    }
    *green = (uint16_t)status;

    // Read blue data
    status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", status);
        return -1;
    }
    *blue = (uint16_t)status;

    return 0;
}

// Function to log data to CSV file
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int status;
    uint16_t clear, red, green, blue;
    int i2c_attempts = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor with retry mechanism
    while (i2c_attempts < 3) {
        if (initialize_sensor() == 0) {
            break; // Initialization successful
        } else {
            fprintf(stderr, "Sensor initialization failed, retrying... (%d/3)\n", i2c_attempts + 1);
            i2c_attempts++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (i2c_attempts == 3) {
        fprintf(stderr, "Sensor initialization failed after multiple retries. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if it is
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
            // Log data
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

