        fprintf(log_file, "%s: Over-current detected! Disabling motor.\n", timestamp);
        fflush(log_file);
        sleep(1); // Wait 1 second
        gpioWrite(MOTOR_ENABLE_PIN, 1); // Enable motor
        fprintf(stderr, "%s: Motor re-enabled.\n", timestamp);
        fprintf(log_file, "%s: Motor re-enabled.\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure max speed hz
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed hz: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(MOTOR_ENABLE_PIN, 0); // Ensure motor is disabled on exit
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor enable pin as output
    gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_ENABLE_PIN, 1); // Enable motor initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is new or empty
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current(A)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t tx_buf[3];
        uint8_t rx_buf[3];
        int adc_value;

        // MCP3008 command to read channel 0 (single-ended)
        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = 0x80; // Single-ended, channel 0
        tx_buf[2] = 0x00; // Don't care

        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

            // Convert ADC value to current
            float current = adc_to_current(adc_value);

            // Log current
            log_current(current);

            // Motor control
            motor_control(current);
        } else {
            fprintf(stderr, "SPI transfer failed. Retrying...\n");
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

