        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read from ADS1115 with retry mechanism
int read_ads1115(int channel) {
    int handle = i2c_handle; // Use the global i2c_handle
    int retries = RETRY_COUNT;
    int raw_value = 0;
    int status;

    while (retries > 0) {
        // Construct the configuration register value for single-ended mode and 4.096V range
        int config = 0x4000 | (channel << 12) | 0x0003; // Single-ended, AIN0/AIN1, +/-4.096V

        status = i2cWriteWordData(handle, 0x01, config);
        if (status < 0) {
            fprintf(stderr, "Error writing to ADS1115: %d\n", status);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
