        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float voltage = voltage_conversion(adc_value, VREF);
            log_data(voltage);
            alarm_control(voltage);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

