        return -1; // Indicate an error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate methane concentration in ppm
float calculate_ppm(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float ppm = (voltage / 0.0005) * 1000; // Assuming 0.0005 V/ppm
    return ppm;
}

// Function to log data to file
void log_data(float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to check for alarm condition
void check_alarm(float ppm) {
    if (ppm > ALARM_THRESHOLD) {
        fprintf(stderr, "ALARM: Methane concentration exceeds threshold (%.2f ppm > %d ppm)!\n", ppm, ALARM_THRESHOLD);
    }
}

