        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            // Calculate methane concentration
            float ppm = calculate_ppm(adc_value);

            // Log data
            log_data(ppm);

            // Check for alarm
            check_alarm(ppm);
        }

        // Sleep for 1 second
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0);
    }

    return 0;
}

