#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3208
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3208

    if (spi_result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", spi_result);
        return -1;
    }

    // Extract ADC value from the response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A datasheet formulas (example, adjust as needed)
    float humidity = (adc_value / 4095.0) * 100.0; // Example linear conversion
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    // HIH-4602-A datasheet formulas (example, adjust as needed)
    float temperature = (adc_value / 4095.0) * 100.0; // Example linear conversion
    return temperature;
}

// Function to log data to a file
void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

// Function to send an email alert
void send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Humidity: %.2f%%\" | ssmtp -s \"Humidity Alert\" recipient@example.com", humidity);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error sending email.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3208 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC values
        int adc_humidity = read_mcp3208(0);
        int adc_temperature = read_mcp3208(1);

        if (adc_humidity < 0 || adc_temperature < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_humidity);
        float temperature = calculate_temperature(adc_temperature);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        sleep(5); // Read every 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

