#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define VREF 3.3
#define MIN_TEMP -40.0
#define MAX_TEMP 125.0
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_RATE_HZ 1

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3208_channel(int fd, int channel);
float adc_to_temperature(int adc_value);
int log_temperature(const char *filename, float temperature);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits_val = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read a specific channel from the MCP3208
int read_mcp3208_channel(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message to read from the MCP3208
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during SPI transfer for channel %d\n", channel);
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to temperature in Celsius
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value * VREF) / 4095.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to log temperature data to a file
int log_temperature(const char *filename, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "timestamp,temperature_celsius\n"); // Write header
    } else {
        fseek(log_file, 0, SEEK_END); // Ensure file pointer is at the end
        if (ftell(log_file) == 0) {
            fprintf(log_file, "timestamp,temperature_celsius\n"); // Write header if file is empty
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3208_channel(spi_fd, MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        float temperature = adc_to_temperature(adc_value);

        // Validate temperature
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            log_temperature(LOG_FILE, temperature); // Log the out-of-range temperature
        } else {
            if (log_temperature(LOG_FILE, temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        sleep(1 / SAMPLE_RATE_HZ); // Delay to achieve 1 Hz sampling rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

