#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define IMPACT_THRESHOLD 500
#define LOG_FILE "impact_log.txt"
#define SAMPLE_RATE 100 // Hz

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
void log_data(int x, int y, int z);
void check_impact(int x, int y, int z);
void signal_handler(int signal);
void cleanup();

// Structure to hold ADC data
typedef struct {
    int x;
    int y;
    int z;
} adc_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC values
        adc_data_t adc_values = {0};
        adc_values.x = read_adc(ADC_CHANNEL_X);
        adc_values.y = read_adc(ADC_CHANNEL_Y);
        adc_values.z = read_adc(ADC_CHANNEL_Z);

        // Log data
        log_data(adc_values.x, adc_values.y, adc_values.z);

        // Check for impact
        check_impact(adc_values.x, adc_values.y, adc_values.z);

        // Delay for 10ms (100Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Log data to file
void log_data(int x, int y, int z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Check for impact
void check_impact(int x, int y, int z) {
    if (x > IMPACT_THRESHOLD || x < -IMPACT_THRESHOLD ||
        y > IMPACT_THRESHOLD || y < -IMPACT_THRESHOLD ||
        z > IMPACT_THRESHOLD || z < -IMPACT_THRESHOLD) {
        fprintf(log_file, "IMPACT DETECTED\n");
        fflush(log_file);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

