#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICP-10125 I2C address
#define ICP10125_ADDR 0x69

// ICP-10125 register addresses
#define ICP10125_MEAS_CMD_REG 0x7E
#define ICP10125_PRESS_MSB_REG 0x00
#define ICP10125_TEMP_MSB_REG 0x03
#define ICP10125_CALIB_DATA_REG 0x10

// Calibration data structure
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} icp10125_calibration_data_t;

// Global variables
int i2c_handle;
FILE *log_file;
icp10125_calibration_data_t calibration_data;

// Function prototypes
int init_i2c();
int read_calibration_data(icp10125_calibration_data_t *calibration_data);
int read_raw_data(int32_t *pressure, int32_t *temperature);
double convert_temperature(int32_t raw_temperature, icp10125_calibration_data_t calibration_data);
double convert_pressure(int32_t raw_pressure, icp10125_calibration_data_t calibration_data);
int log_data(double temperature, double pressure);
void display_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from the sensor
int read_calibration_data(icp10125_calibration_data_t *calibration_data) {
    char buf[18];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10125_CALIB_DATA_REG, buf, 18);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calibration_data->c0 = (int32_t)((((uint32_t)buf[0]) << 24) | (((uint32_t)buf[1]) << 16) | (((uint32_t)buf[2]) << 8) | ((uint32_t)buf[3]));
    calibration_data->c1 = (int32_t)((((uint32_t)buf[4]) << 24) | (((uint32_t)buf[5]) << 16) | (((uint32_t)buf[6]) << 8) | ((uint32_t)buf[7]));
    calibration_data->c00 = (int32_t)((((uint32_t)buf[8]) << 24) | (((uint32_t)buf[9]) << 16) | (((uint32_t)buf[10]) << 8) | ((uint32_t)buf[11]));
    calibration_data->c10 = (int32_t)((((uint32_t)buf[12]) << 24) | (((uint32_t)buf[13]) << 16) | (((uint32_t)buf[14]) << 8) | ((uint32_t)buf[15]));
    calibration_data->c01 = (int32_t)((((uint32_t)buf[16]) << 24) | (((uint32_t)buf[17]) << 16) | (((uint32_t)0x00) << 8) | ((uint32_t)0x00));

    return 0;
}

// Read raw pressure and temperature data from the sensor
int read_raw_data(int32_t *pressure, int32_t *temperature) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10125_PRESS_MSB_REG, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)buf[0]) << 16) | (((uint32_t)buf[1]) << 8) | ((uint32_t)buf[2]));
    *temperature = (int32_t)((((uint32_t)buf[3]) << 16) | (((uint32_t)buf[4]) << 8) | ((uint32_t)buf[5]));

    return 0;
}

// Convert raw temperature data to degrees Celsius
double convert_temperature(int32_t raw_temperature, icp10125_calibration_data_t calibration_data) {
    double temperature = (double)raw_temperature;
    temperature = calibration_data.c0 + calibration_data.c1 * temperature;
    return temperature;
}

// Convert raw pressure data to pascals
double convert_pressure(int32_t raw_pressure, icp10125_calibration_data_t calibration_data) {
    double pressure = (double)raw_pressure;
    pressure = calibration_data.c00 + pressure * (calibration_data.c10 + pressure * (calibration_data.c20 + pressure * calibration_data.c30));
    return pressure;
}

// Log data to CSV file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Display data on the console
void display_data(double temperature, double pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }
    rewind(log_file);

    // Read calibration data
    if (read_calibration_data(&calibration_data) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int32_t raw_pressure, raw_temperature;

        // Read raw data
        if (read_raw_data(&raw_pressure, &raw_temperature) == 0) {
            // Convert data
            double temperature = convert_temperature(raw_temperature, calibration_data);
            double pressure = convert_pressure(raw_pressure, calibration_data);

            // Log data
            log_data(temperature, pressure);

            // Display data
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

