#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define VREF 3.3
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float compensate_voltage(int raw_adc, float ambient_temp);
int detect_flame(float compensated_voltage);
void log_data(int raw_adc, float voltage, float compensated_voltage, float ambient_temp, int flame_detected);
void signal_handler(int signal);
int read_ambient_temperature();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to compensate voltage with temperature
float compensate_voltage(int raw_adc, float ambient_temp) {
    // Simple linear compensation (adjust as needed)
    float voltage = (float)raw_adc * VREF / 1023.0;
    float temperature_compensation = voltage * (ambient_temp - 25.0); // Example compensation
    return voltage + temperature_compensation;
}

// Function to detect flame based on voltage
int detect_flame(float compensated_voltage) {
    // Define a threshold for flame detection
    float threshold = 1.5; // Adjust as needed

    if (compensated_voltage > threshold) {
        return 1; // Flame detected
    } else {
        return 0; // No flame detected
    }
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float ambient_temp, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read ambient temperature from file
int read_ambient_temperature() {
    FILE *fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open temperature file, using default value 25.0\n");
        return 25.0;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Warning: Could not read temperature from file, using default value 25.0\n");
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    return temperature;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ambient temperature
        float ambient_temp = read_ambient_temperature();

        // Read raw ADC value
        int raw_adc = read_mcp3008(0);
        if (raw_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping iteration\n");
            gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
            gpioDelay(500000); // Wait 500ms
            continue;
        }

        // Validate ADC value
        int retry_count = 0;
        while (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Error: ADC value out of range, retrying...\n");
            raw_adc = read_mcp3008(0);
            if (raw_adc < 0) {
                fprintf(stderr, "Error: Failed to read ADC value after retry, skipping iteration\n");
                gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
                gpioDelay(500000); // Wait 500ms
                continue;
            }
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Error: Max retries reached, skipping iteration\n");
                gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
                gpioDelay(500000); // Wait 500ms
                break;
            }
        }

        if (retry_count > 3) continue; // Skip if max retries reached

        // Compensate voltage
        float voltage = (float)raw_adc * VREF / 1023.0;
