        log_data(raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Wait 500ms
        gpioDelay(500000);
    }

    // Cleanup
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

