    int min_calibration;
    int max_calibration;
    int moisture_threshold;
    int logging_interval;
    char email_address[100];
    char msmtp_config_file[100];
} Config;

// Global variables
static volatile int running = 1;
static int spi_handle;
static Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
int read_mcp3008(int spi_handle, int channel);
float calibrate_moisture(int adc_value, int min_calibration, int max_calibration);
int log_data(const char *filename, float moisture_percent);
int send_email_alert(const char *email_address, const char *msmtp_config_file, float moisture_percent);
void signal_handler(int signal);

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(key, "adc_channel") == 0) {
            config->adc_channel = atoi(value);
        } else if (strcmp(key, "min_calibration") == 0) {
            config->min_calibration = atoi(value);
        } else if (strcmp(key, "max_calibration") == 0) {
            config->max_calibration = atoi(value);
        } else if (strcmp(key, "moisture_threshold") == 0) {
            config->moisture_threshold = atoi(value);
        } else if (strcmp(key, "logging_interval") == 0) {
            config->logging_interval = atoi(value);
        } else if (strcmp(key, "email_address") == 0) {
            strncpy(config->email_address, value, sizeof(config->email_address) - 1);
            config->email_address[sizeof(config->email_address) - 1] = '\0';
        } else if (strcmp(key, "msmtp_config_file") == 0) {
            strncpy(config->msmtp_config_file, value, sizeof(config->msmtp_config_file) - 1);
            config->msmtp_config_file[sizeof(config->msmtp_config_file) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

