int send_email_alert(const char *email_address, const char *msmtp_config_file, float moisture_percent) {
    char command[512];
    snprintf(command, sizeof(command), "echo \"Subject: Low Moisture Alert\n\nMoisture level: %.2f%%\" | msmtp -t -a default -c %s %s",
             moisture_percent, msmtp_config_file, email_address);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        perror("Error sending email");
        return -1;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", status);
        return -1;
    }

    return 0;
}

