#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // Channel connected to MLX90823
#define PRESSURE_MIN 0.0  // kPa
#define PRESSURE_MAX 100.0 // kPa
#define VOLTAGE_MIN 0.0   // V
#define VOLTAGE_MAX 3.3   // V
#define ADC_MIN 0         // Minimum ADC value (0-1023)
#define ADC_MAX 1023      // Maximum ADC value (0-1023)
#define READ_INTERVAL 1   // Seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float pressure_min;
    float pressure_max;
    float voltage_min;
    float voltage_max;
    int adc_min;
    int adc_max;
    int read_interval;
} config_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int speed);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0;
    }
    return ((float)adc_value / ADC_MAX) * (VOLTAGE_MAX - VOLTAGE_MIN) + VOLTAGE_MIN;
}

// Convert voltage to pressure (linear approximation)
float voltage_to_pressure(float voltage) {
    if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
        fprintf(stderr, "Voltage out of range: %.2f\n", voltage);
        return -1.0;
    }
    return ((voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN)) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
}

// Log data with timestamp
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    config_t config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .mcp3008_channel = MCP3008_CHANNEL,
        .pressure_min = PRESSURE_MIN,
        .pressure_max = PRESSURE_MAX,
        .voltage_min = VOLTAGE_MIN,
        .voltage_max = VOLTAGE_MAX,
        .adc_min = ADC_MIN,
        .adc_max = ADC_MAX,
        .read_interval = READ_INTERVAL
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(config.spi_channel, config.spi_speed) != 0) {
        cleanup();
        return 1;
    }

    printf("Pressure sensor monitoring started...\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC to voltage
        float voltage = adc_to_voltage(adc_value);
        if (voltage < 0) {
            fprintf(stderr, "Failed to convert ADC to voltage\n");
            continue;
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);
        if (pressure < 0) {
            fprintf(stderr, "Failed to convert voltage to pressure\n");
            continue;
        }

        // Log the data
        log_data(pressure);

        // Wait for the next reading
        sleep(config.read_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

