#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3f         // Reference voltage
#define NUM_SENSORS 4
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value, float vref);
int log_data(FILE *fp, float voltage0, float voltage1, float voltage2, float voltage3);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read ADC value from a specific channel
int spi_read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01;                           // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;                           // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value / 1023.0f) * vref;
}

// Function to log data to a file
int log_data(FILE *fp, float voltage0, float voltage1, float voltage2, float voltage3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, voltage0, voltage1, voltage2, voltage3) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Voltage0,Voltage1,Voltage2,Voltage3\n");
    }
    rewind(log_file);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        float voltage0 = adc_to_voltage(spi_read_adc(0), VREF);
        float voltage1 = adc_to_voltage(spi_read_adc(1), VREF);
        float voltage2 = adc_to_voltage(spi_read_adc(2), VREF);
        float voltage3 = adc_to_voltage(spi_read_adc(3), VREF);

        if (log_data(log_file, voltage0, voltage1, voltage2, voltage3) != 0) {
            fprintf(stderr, "Error logging data, but continuing...\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

