#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MAX30102 I2C address
#define MAX30102_I2C_ADDR 0x57

// MAX30102 Registers
#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVERFLOW_CTR 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x05
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED_CONFIG_1 0x0C
#define REG_LED_CONFIG_2 0x0D
#define REG_TEMP_INTEGER 0x1F
#define REG_TEMP_FRACTION 0x20
#define REG_PROX_INT_THRESH 0x30
#define REG_REV_ID 0xFE
#define REG_PART_ID 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_max30102_data(float *spo2, int *heart_rate);
void log_data(float spo2, int heart_rate);
void signal_handler(int signal);
int check_sensor_presence();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to check sensor presence
int check_sensor_presence() {
    int part_id;
    if (i2cReadByteData(i2c_handle, REG_PART_ID) < 0) {
        fprintf(stderr, "Error reading Part ID register.\n");
        return 0;
    }
    part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return 0;
    }
    return 1;
}

// Function to initialize the MAX30102 sensor
int init_max30102() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error writing to MODE_CONFIG register.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure FIFO
    if (i2cWriteByteData(i2c_handle, REG_FIFO_CONFIG, 0x0F) < 0) {
        fprintf(stderr, "Error writing to FIFO_CONFIG register.\n");
        return -1;
    }

    // Configure Mode
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error writing to MODE_CONFIG register.\n");
        return -1;
    }

    // Configure SPO2
    if (i2cWriteByteData(i2c_handle, REG_SPO2_CONFIG, 0x27) < 0) {
        fprintf(stderr, "Error writing to SPO2_CONFIG register.\n");
        return -1;
    }

    // Configure LED current (example values)
    if (i2cWriteByteData(i2c_handle, REG_LED_CONFIG_1, 0x3F) < 0) {
        fprintf(stderr, "Error writing to LED_CONFIG_1 register.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_LED_CONFIG_2, 0x3F) < 0) {
        fprintf(stderr, "Error writing to LED_CONFIG_2 register.\n");
        return -1;
    }

    return 0;
}

// Function to read SpO2 and heart rate data from the sensor
int read_max30102_data(float *spo2, int *heart_rate) {
    // Read FIFO data (example: read 100 samples)
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, buffer, 6) < 0) {
        fprintf(stderr, "Error reading FIFO data.\n");
        return -1;
    }

    // Process the data (example: calculate SpO2 and heart rate)
    // This is a simplified example and requires proper calibration and data processing
    // Refer to the MAX30102 datasheet for detailed instructions
    // For demonstration purposes, we'll just return some dummy values
    *spo2 = 98.0 + (float)(rand() % 20) / 100.0; // Simulate SpO2 between 98.0 and 100.0
    *heart_rate = 70 + (rand() % 30); // Simulate heart rate between 70 and 100

    return 0;
}

// Function to log data to a file
void log_data(float spo2, int heart_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s, SpO2: %.2f, Heart Rate: %d\n", timestamp, spo2, heart_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MAX30102_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (!check_sensor_presence()) {
        fprintf(stderr, "MAX30102 sensor not found.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_max30102() < 0) {
        fprintf(stderr, "MAX30102 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float spo2;
    int heart_rate;

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (read_max30102_data(&spo2, &heart_rate) == 0) {
            // Log data if out of range
            if (spo2 < 95.0 || heart_rate > 100) {
                log_data(spo2, heart_rate);
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // Cleanup (should not reach here if signal handler is working)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

