// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define LOG_FILE "analog_log.csv"
#define RETRY_COUNT 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_conversion(int adc_value, float vref);
void log_data(FILE *fp, int channel, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    char *log_file;
} config_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel number\n");
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    for (int i = 0; i < RETRY_COUNT; ++i) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 3) {
            // Extract ADC value
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to convert ADC value to voltage
float voltage_conversion(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Function to log data to CSV file
void log_data(FILE *fp, int channel, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to clean up resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    while (!terminate) {
        for (int channel = 0; channel < NUM_CHANNELS; ++channel) {
            int adc_value = read_mcp3008(channel);
            if (adc_value >= 0) {
                float voltage = voltage_conversion(adc_value, VREF);
                log_data(log_file, channel, voltage);
            } else {
                fprintf(stderr, "Failed to read channel %d\n", channel);
            }
        }
        gpioDelay(500000); // 500 ms
    }

    cleanup();
    return 0;
}

