#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define THRESHOLD 2000 // Calibrated threshold value
#define RELAY_PULSE_DURATION 3000 // milliseconds
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY 50 // milliseconds
#define SAMPLE_DELAY 200 // milliseconds
#define LOG_FILE "/var/log/door_events.log"

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int calibrate_sensor();
int read_sensor();
void control_relay(int state);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    uint16_t config;
} ads1115_config_t;

// Function to write to the ADS1115
int write_ads1115(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to ADS1115");
        return -1;
    }
    return 0;
}

// Function to read from the ADS1115
int read_ads1115(int fd, uint16_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to ADS1115 for reading");
        return -1;
    }

    uint8_t read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Calibrate the sensor
    if (calibrate_sensor() != 0) {
        fprintf(stderr, "Sensor calibration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Door lock control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor value
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value. Retrying.\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Check if distance is below threshold
        if (sensor_value < THRESHOLD) {
            printf("Distance below threshold. Activating relay.\n");

            // Activate relay
            control_relay(1);

            // Read door sensor
            int door_open = (gpioRead(GPIO_DOOR_SENSOR) == 0); // Reed sensor is active low

            // Log event
            if (door_open) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }

            // Deactivate relay
            control_relay(0);

            printf("Relay deactivated.\n");
        }

        // Delay before next sample
        gpioDelay(SAMPLE_DELAY * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Door lock control system stopped.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetMode(GPIO_DOOR_SENSOR, PI_INPUT);
    gpioSetPullUpDown(GPIO_DOOR_SENSOR, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Calibrate the sensor
int calibrate_sensor() {
    printf("Starting calibration...\n");
    int sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Calibration failed: Failed to read sensor value.\n");
            return -1;
        }
        sum += sensor_value;
        gpioDelay(CALIBRATION_DELAY * 1000); // Delay between samples
    }
    THRESHOLD = sum / CALIBRATION_SAMPLES;
    printf("Calibration complete. Threshold: %d\n", THRESHOLD);
    return 0;
}

// Read sensor value from ADS1115
int read_sensor() {
    uint16_t raw_value;
    if (read_ads1115(i2c_fd, 0x00, &raw_value) != 0) {
        fprintf(stderr, "Failed to read sensor value from ADS1115.\n");
        return -1;
    }

    // Convert raw value to distance (example conversion, adjust as needed)
    // Assuming ADS1115 is set to single-ended AIN0 and gain is 1
    // and the sensor outputs a voltage proportional to distance.
    // This is a simplified example and may need calibration.
    float voltage = (float)raw_value / 32767.0 * 4.096; // Assuming 4.096V range
    int distance = (int)(10000.0 / voltage); // Example inverse relationship

    return distance;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Log event to file
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Deactivate relay
    control_relay(0);

    // Close I2C file descriptor
    if (i2c_fd > 0) {
        close(i2c_fd);
    }

    // Terminate pigpio
    gpioTerminate();
}

