// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
int threshold = 30; // Default threshold
int pump_duration = 10; // Default pump duration
int sleep_interval = 60; // Default sleep interval
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int state);
void log_data(int adc_value, float moisture, int pump_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 3;
    int result = -1;

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            result = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Error: SPI transfer failed (channel %d), retrying...\n", channel);
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    if (result == -1) {
        fprintf(stderr, "Error: SPI transfer failed after multiple retries (channel %d)\n", channel);
        return -1; // Indicate failure
    }

    return result;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log data to file
void log_data(int adc_value, float moisture, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, ADC: %d, Moisture: %.2f%%, Pump: %s\n",
            timestamp, adc_value, moisture, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

