    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Try again
        }

        // Detect peak
        if (detect_peak(adc_value, THRESHOLD)) {
            // Log peak event
            log_peak(adc_value);
            printf("Peak detected: ADC value = %d\n", adc_value);
        }

        // Wait for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Sound event detection stopped.\n");

    return 0;
}

