#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// PCF8591 I2C address
#define PCF8591_ADDR 0x48

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// PCF8591 registers
#define PCF8591_CONTROL 0x40 // Control register
#define PCF8591_AIN0 0x41    // AIN0

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read from PCF8591
int read_pcf8591(int fd) {
    uint8_t buffer[2];
    int result;

    // Write control byte to start conversion on AIN0
    uint8_t control_byte = 0x40; // Enable ADC, AIN0
    result = ioctl(fd, I2C_SLAVE, PCF8591_ADDR);
    if (result < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    result = write(fd, &control_byte, 1);
    if (result != 1) {
        perror("Failed to write control byte");
        return -1;
    }

    // Read two bytes from the ADC
    result = read(fd, buffer, 2);
    if (result != 2) {
        perror("Failed to read from PCF8591");
        return -1;
    }

    // Discard the first byte (dummy read)
    //uint8_t dummy = buffer[0];

    // Return the second byte (AIN0 value)
    return buffer[1];
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Main loop
    while (1) {
        int value = read_pcf8591(i2c_fd);
        if (value < 0) {
            fprintf(stderr, "Error reading PCF8591, exiting...\n");
            close(i2c_fd);
            return 1;
        }

        printf("AIN0: %d\n", value);
        usleep(100000); // 100ms
    }

    return 0;
}

