#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_PIN 27
#define THRESHOLD_GAUSS 500.0
#define BUFFER_SIZE 10
#define SAMPLE_RATE_HZ 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int init_gpio();
int read_adc(int16_t *value);
float convert_to_voltage(int16_t raw_value);
float convert_to_gauss(float voltage);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void log_data(float voltage, float gauss, int threshold_crossed);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    memset(cb->buffer, 0, sizeof(cb->buffer));
    cb->head = 0;
    cb->count = 0;
}

int main() {
    // Initialize syslog
    openlog("magnetic_field_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        syslog(LOG_ERR, "I2C initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    CircularBuffer buffer;
    init_circular_buffer(&buffer);

    int16_t raw_value;
    float voltage, gauss, average_gauss;
    int threshold_crossed = 0;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_adc(&raw_value) == 0) {
            // Convert to voltage
            voltage = convert_to_voltage(raw_value);

            // Convert to Gauss
            gauss = convert_to_gauss(voltage);

            // Add to circular buffer
            add_to_buffer(&buffer, gauss);

            // Calculate average
            average_gauss = calculate_average(&buffer);

            // Check threshold
            if (average_gauss > THRESHOLD_GAUSS && !threshold_crossed) {
                gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
                threshold_crossed = 1;
                syslog(LOG_WARNING, "Threshold crossed! Average Gauss: %.2f", average_gauss);
            } else if (average_gauss <= THRESHOLD_GAUSS && threshold_crossed) {
                gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
                threshold_crossed = 0;
            }

            // Log data
            log_data(voltage, gauss, threshold_crossed);
        } else {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        // Delay for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V, continuous conversion
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW initially
    return 0;
}

// Read ADC value
int read_adc(int16_t *value) {
    char buf[1];
    char read_buf[2];

    // Start a single conversion
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    char config_buf[3];
    config_buf[0] = CONFIG_REG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;
