int spi_handle = -1;

// Function prototypes
int read_mcp3008(int channel);
int map_adc_to_rainfall(int adc_value);
void log_rainfall_data(int adc_value, int rainfall_intensity);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int cs_pin;
    int spi_channel;
    int spi_speed;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the SPI handle if it's open
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        printf("SPI handle closed.\n");
    }

    // Terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // Construct the SPI message to send to the MCP3008
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer the SPI message
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);

    if (spi_result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", spi_result);
        return -1; // Indicate an error
    }

    // Extract the ADC value from the received data
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map the ADC value to a rainfall intensity level
int map_adc_to_rainfall(int adc_value) {
    // Check for invalid ADC values
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1; // Indicate an error
    }

    // Calculate the rainfall intensity level
    int rainfall_intensity = (int)(((float)adc_value / 1023.0) * NUM_RAINFALL_LEVELS);

    return rainfall_intensity;
}

// Function to log the rainfall data to stdout
void log_rainfall_data(int adc_value, int rainfall_intensity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Print the data to stdout
    printf("%s, ADC Value: %d, Rainfall Intensity: %d\n", timestamp, adc_value, rainfall_intensity);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure the CS pin as an output
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioWrite(MCP3008_CS_PIN, 1); // Ensure CS is initially high

    // Open the SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle = %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("SPI handle: %d\n", spi_handle);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int adc_value = -1;
        int rainfall_intensity = -1;

        // Read the ADC value from the MCP3008
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Map the ADC value to a rainfall intensity level
        rainfall_intensity = map_adc_to_rainfall(adc_value);
        if (rainfall_intensity < 0) {
            fprintf(stderr, "Error: Failed to map ADC value to rainfall intensity\n");
            continue; // Skip to the next iteration
        }

        // Log the rainfall data
        log_rainfall_data(adc_value, rainfall_intensity);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    return 0;
}

