#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_adc(int16_t *value);
double convert_to_gauss(int16_t adc_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    double threshold;
} config_t;

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure ADS1115
int configure_ads1115() {
    // Configure for single-ended AIN0, 4.096V gain, continuous conversion
    uint16_t config = 0x4000; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read ADC value
int read_adc(int16_t *value) {
    char buf[1];
    char read_buf[2];

    buf[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from conversion register\n");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

