#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_monitor"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_COMMAND_TOPIC "pump_control"

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void publish_moisture(float moisture);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int sig);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0;
    }

    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the pump
void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", PUMP_GPIO);
    }
}

// Function to publish moisture value to MQTT
void publish_moisture(float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(ret));
    }
}

// MQTT callbacks
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_COMMAND_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "pump_on") == 0) {
            control_pump(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            control_pump(0);
        } else {
            syslog(LOG_WARNING, "Unknown command: %s", payload);
        }
    }
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        syslog(LOG_WARNING, "Disconnected from MQTT broker with error code %d", rc);
    }
}

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pump_state = 0; // 0 = off, 1 = on
    float moisture = 0.0;

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        moisture = calculate_moisture_percentage(adc_value);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to calculate moisture percentage, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        syslog(LOG_INFO, "Moisture: %.2f%%", moisture);

        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_pump(1);
            pump_state = 1;
            syslog(LOG_INFO, "Pump turned ON");
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            control_pump(0);
            pump_state = 0;
            syslog(LOG_INFO, "Pump turned OFF");
        }

        publish_moisture(moisture);

        sleep(60); // Publish every 60 seconds
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioWrite(PUMP_GPIO, 0); // Turn off pump
    gpioTerminate();
    closelog();

    return 0;
}

