    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // I2C1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sound Level (dB),Light Level (lux),Error Code\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Tamper detection system started. Logging to %s\n", LOG_FILE);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int sound_level_adc = read_mcp3008(0);
        float light_level_lux = read_bh1750();
        int error_code = 0;

        // Error handling
        if (sound_level_adc == -1) {
            error_code = 1; // ADC read error
        }
        if (light_level_lux == -1.0) {
            error_code = 2; // BH1750 read error
        }

        // Convert sound level to dB (example, adjust as needed)
        float sound_level_db = (float)sound_level_adc / 1023.0 * 100.0; // Example conversion

        // Log data
        log_data(sound_level_db, light_level_lux, error_code);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

