#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define PUMP_ON_DURATION 5 // seconds
#define MAX_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    int retries = 0;
    int adc_value = -1;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Error: Failed to read MCP3008 after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) {
        return -1.0; // Indicate error
    }
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    if (state == 1) {
        printf("Pump ON\n");
    } else {
        printf("Pump OFF\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 17 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Watering System\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        if (moisture_percentage < 0) {
            fprintf(stderr, "Error: Failed to calculate moisture percentage\n");
            continue; // Skip to the next iteration
        }

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        // Log data to console
        printf("%s - ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);

        // Control the pump
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%.2f%% < %.2f%%). Activating pump.\n", moisture_percentage, MOISTURE_THRESHOLD);
            control_pump(1); // Turn pump ON
            sleep(PUMP_ON_DURATION); // Run pump for 5 seconds
            control_pump(0); // Turn pump OFF
            printf("Pump OFF\n");
        }

        sleep(60); // Wait 60 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

