#define DEBOUNCE_DELAY 1000 // 1 second
#define LOG_FILE "door_events.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_distance(int adc_value);
void control_relay(int state);
void log_event(float distance);
