// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to distance (cm)
float adc_to_distance(int adc_value) {
    // Calibration curve for GP2Y0A21YK0F (example values)
    // This is a simplified linear approximation.  A proper calibration
    // would involve a more complex curve fitting.
    // The actual distance is inversely proportional to the ADC value.
    // This is a rough approximation and may need adjustment based on
    // the sensor's actual characteristics and the environment.
    // The distance is in cm.
    float distance = 29.16 * pow(adc_value / 1000.0, -1.10); // Example inverse relationship
    return distance;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log events to a file
void log_event(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

