    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Ensure relay is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Monitoring IR distance sensor... Press Ctrl+C to exit.\n");

    int last_relay_state = 0; // Track the last relay state to avoid redundant debouncing
    time_t last_debounce_time = 0; // Track the last debounce time

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);

        // Check if distance is below threshold
        if (distance < 20.0) {
            // Debounce logic
            time_t current_time = time(NULL);
            if (current_time - last_debounce_time >= DEBOUNCE_DELAY / 1000) {
                // Activate relay
                control_relay(1);
                last_relay_state = 1; // Update last relay state
                log_event(distance);

                // Wait for 1 second
                gpioDelay(1000000); // 1 second

                // Deactivate relay
                control_relay(0);
                last_relay_state = 0; // Update last relay state
            }
            last_debounce_time = current_time; // Update last debounce time
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Ensure relay is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

