#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_DELAY_MS 100

// Global variables
static volatile int keepRunning = 1;
static FILE *logFile = NULL;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int adc1, int adc2, int adc3);
void set_valve_position(float average);
void log_data(int adc1, int adc2, int adc3, float average, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1; // Initialize to an error value

    buffer[0] = 0x01; // Start bit
    buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1; // Indicate failure
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to calculate the average of three ADC values
float calculate_average(int adc1, int adc2, int adc3) {
    int valid_count = 0;
    int sum = 0;

    if (adc1 != -1) {
        sum += adc1;
        valid_count++;
    }
    if (adc2 != -1) {
        sum += adc2;
        valid_count++;
    }
    if (adc3 != -1) {
        sum += adc3;
        valid_count++;
    }

    if (valid_count == 0) {
        return -1.0; // Indicate failure
    }

    return (float)sum / valid_count;
}

// Function to set the valve position using PWM
void set_valve_position(float average) {
    int duty_cycle = (int)(average / 1023.0 * PWM_RANGE); // Assuming 10-bit ADC (0-1023)
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    pwmWrite(VALVE_GPIO, duty_cycle);
}

// Function to log data to a file
void log_data(int adc1, int adc2, int adc3, float average, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(logFile, "%s, ADC1: %d, ADC2: %d, ADC3: %d, Average: %.2f, Valve: %d\n",
            timestamp, adc1, adc2, adc3, average, valve_position);
    fflush(logFile); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    keepRunning = 0;

    // Close the log file
    if (logFile != NULL) {
        fclose(logFile);
        printf("Log file closed.\n");
    }

    // Set valve to 0% and stop PWM
    pwmWrite(VALVE_GPIO, 0);
    printf("Valve set to 0%%.\n");

    // Terminate wiringPi
    wiringPiSPIClose(SPI_CHANNEL);
    printf("SPI closed.\n");

    exit(0);
}

int main() {
    int adc1, adc2, adc3;
    float average;
    int valve_position;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set valve GPIO as PWM output
    pinMode(VALVE_GPIO, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired frequency (100Hz)

    // Open log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        // Read ADC values
        adc1 = read_mcp3008(0);
        adc2 = read_mcp3008(1);
        adc3 = read_mcp3008(2);

        // Calculate average
        average = calculate_average(adc1, adc2, adc3);

        if (average == -1.0) {
            fprintf(stderr, "Failed to calculate average, skipping valve control.\n");
        } else {
            // Set valve position
            valve_position = (int)(average / 1023.0 * 100.0); // Scale to 0-100
            set_valve_position(average);

            // Log data
            log_data(adc1, adc2, adc3, average, valve_position);
        }

        delay(SAMPLE_DELAY_MS);
    }

    return 0;
}

