#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_RANGE 1000
#define PWM_CLOCK 192

// Define distance and volume ranges
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 200.0 // cm
#define MIN_VOLUME 0.0
#define MAX_VOLUME 100.0

// Define timeout value for HC-SR04
#define TIMEOUT_US 50000 // 50ms

// Define calibration file
#define CALIBRATION_FILE "theremin_config.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold calibration data
typedef struct {
    float distance_offset;
    float distance_scale;
    float volume_offset;
    float volume_scale;
} CalibrationData;

CalibrationData calibration = {0.0, 1.0, 0.0, 1.0};

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_spi();
float read_distance();
int read_ldr();
float map_distance_to_frequency(float distance);
float map_ldr_to_volume(int ldr_value);
void generate_tone(float frequency, float volume);
void log_data(float distance, int ldr_value, float frequency, float volume);
void load_calibration();
void save_calibration();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Stop PWM
    pwmWrite(PWM_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO pins
int init_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(TRIG_PIN, OUTPUT);
    pinMode(ECHO_PIN, INPUT);
    pinMode(PWM_PIN, PWM_OUTPUT);

    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(PWM_CLOCK);

    return 0;
}

// Initialize SPI interface
int init_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from HC-SR04 sensor
float read_distance() {
    long startTime, endTime, pulseWidth;

    digitalWrite(TRIG_PIN, LOW);
    delayMicroseconds(2);
    digitalWrite(TRIG_PIN, HIGH);
    delayMicroseconds(10);
    digitalWrite(TRIG_PIN, LOW);

    startTime = micros();
    endTime = startTime + TIMEOUT_US;

    while (digitalRead(ECHO_PIN) == LOW) {
        if (micros() > endTime) {
            fprintf(stderr, "HC-SR04 timeout\n");
            return -1.0; // Indicate timeout error
        }
    }

    startTime = micros();

    while (digitalRead(ECHO_PIN) == HIGH) {
        if (micros() > endTime) {
            fprintf(stderr, "HC-SR04 timeout\n");
            return -1.0; // Indicate timeout error
        }
    }

    endTime = micros();

    pulseWidth = endTime - startTime;

    if (pulseWidth <= 0) {
        fprintf(stderr, "Invalid pulse width: %ld\n", pulseWidth);
        return -1.0; // Indicate invalid reading
    }

    float distance = (pulseWidth * 0.0343) / 2.0; // Calculate distance in cm

    return distance;
}

// Read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | 0x00) << 4; // Single-ended mode, channel 0
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Map distance to frequency
float map_distance_to_frequency(float distance) {
    // Clamp distance to defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Apply calibration
    float calibrated_distance = (distance - calibration.distance_offset) * calibration.distance_scale;

    // Map to frequency range (e.g., 200Hz - 2000Hz)
    float frequency = 200.0 + (calibrated_distance / MAX_DISTANCE) * 1800.0; // Example mapping

    return frequency;
}

// Map LDR value to volume
float map_ldr_to_volume(int ldr_value) {
    // Clamp LDR value to defined range
    if (ldr_value < 0) {
        ldr_value = 0;
    } else if (ldr_value > 1023) {
        ldr_value = 1023;
    }

    // Apply calibration
    float calibrated_ldr = (ldr_value - calibration.volume_offset) * calibration.volume_scale;

    // Map to volume range (e.g., 0% - 100%)
    float volume = (calibrated_ldr / 1023.0) * MAX_VOLUME; // Example mapping

    return volume;
}

// Generate PWM tone
void generate_tone(float frequency, float volume) {
    int duty_cycle = (int)(volume * PWM_RANGE / MAX_VOLUME);
    pwmWrite(PWM_PIN, duty_cycle);
}

// Log data to file
void log_data(float distance, int ldr_value, float frequency, float volume) {
    if (log_file == NULL) return;

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, LDR: %d, Frequency: %.2f Hz, Volume: %.2f%%\n",
            timestamp, distance, ldr_value, frequency, volume);
    fflush(log_file); // Ensure data is written to file immediately
}

// Load calibration data from file
void load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file %s, using default values.\n", CALIBRATION_FILE);
        return;
    }

    if (fscanf(fp, "%f %f %f %f", &calibration.distance_offset, &calibration.distance_scale,
               &calibration.volume_offset, &calibration.volume_scale) != 4) {
        fprintf(stderr, "Warning: Could not read calibration data from %s, using default values.\n", CALIBRATION_FILE);
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration data loaded: offset=%.2f, scale=%.2f, ldr_offset=%.2f, ldr_scale=%.2f\n",
           calibration.distance_offset, calibration.distance_scale,
           calibration.volume_offset, calibration.volume_scale);
}

// Save calibration data to file
void save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%f %f %f %f", calibration.distance_offset, calibration.distance_scale,
            calibration.volume_offset, calibration.volume_scale);

    fclose(fp);
    printf("Calibration data saved.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() == -1) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen("theremin_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }

    // Load calibration data
    load_calibration();

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read distance
        float distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, using last valid value.\n");
        } else {
            // Map distance to frequency
            float frequency = map_distance_to_frequency(distance);

            // Read LDR value
            int ldr_value = read_ldr();

            // Map LDR to volume
            float volume = map_ldr_to_volume(ldr_value);

            // Generate tone
            generate_tone(frequency, volume);

            // Log data
            log_data(distance, ldr_value, frequency, volume);

            // Update last valid values
            calibration.distance_offset = distance;
            calibration.volume_offset = ldr_value;
        }

        delay(50); // Delay for stability
    }

    // Stop PWM
    pwmWrite(PWM_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

