#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_SPI_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_aqi(int adc_value);
void control_fan(int aqi);
void log_data(int adc_value, float aqi);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int spi_result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (spi_result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, spi_result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate AQI (simplified linear approximation)
float calculate_aqi(int adc_value) {
    // This is a placeholder.  A real AQI calculation requires
    // a more complex algorithm based on sensor calibration data
    // and air quality standards.
    // This linear approximation is for demonstration purposes only.
    float aqi = (float)adc_value * 5.0; // Scale ADC value to AQI
    return aqi;
}

// Function to control the ventilation fan
void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        printf("Fan ON (AQI: %.2f)\n", (float)aqi);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        printf("Fan OFF (AQI: %.2f)\n", (float)aqi);
    }
}

// Function to log data to file
void log_data(int adc_value, float aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, AQI: %.2f\n", timestamp, adc_value, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Initialize SPI with retry mechanism
    int spi_init_result = -1;
    for (int i = 0; i < MAX_SPI_RETRIES; ++i) {
        if (initialize_spi() == 0) {
            spi_init_result = 0;
            break;
        } else {
            fprintf(stderr, "Error: SPI initialization failed (attempt %d/%d). Retrying in %d seconds...\n", i + 1, MAX_SPI_RETRIES, RETRY_DELAY);
            time_sleep(RETRY_DELAY);
        }
    }

    if (spi_init_result != 0) {
        fprintf(stderr, "Error: SPI initialization failed after multiple retries. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float aqi = calculate_aqi(adc_value);
            control_fan((int)aqi);
            log_data(adc_value, aqi);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value. Skipping AQI calculation and logging.\n");
        }

        time_sleep(5); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

