#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "alcohol_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define SENSOR_ABSENT_THRESHOLD 0.9 // Percentage of consistent 0 or 1023 readings

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
void log_data(float voltage, const char *classification);
void signal_handler(int signal);
int detect_sensor_absent();
int validate_adc_reading(int adc_value);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to log data to file
void log_data(float voltage, const char *classification) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Voltage: %.2f V, Classification: %s\n", timestamp, voltage, classification);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to detect sensor absence
int detect_sensor_absent() {
    int consistent_zero_count = 0;
    int consistent_max_count = 0;
    int total_readings = 0;

    for (int i = 0; i < 10; ++i) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC during sensor absence detection.\n");
            return 0; // Assume sensor present if reading fails
        }

        if (adc_value == 0) {
            consistent_zero_count++;
        } else if (adc_value == 1023) {
            consistent_max_count++;
        }

        total_readings++;
        gpioDelay(10000); // 10ms delay
    }

    float zero_percentage = (float)consistent_zero_count / total_readings;
    float max_percentage = (float)consistent_max_count / total_readings;

    if (zero_percentage >= SENSOR_ABSENT_THRESHOLD || max_percentage >= SENSOR_ABSENT_THRESHOLD) {
        return 1; // Sensor absent
    } else {
        return 0; // Sensor present
    }
}

// Function to validate ADC reading
int validate_adc_reading(int adc_value) {
    if (adc_value >= 0 && adc_value <= 1023) {
        return 1; // Valid reading
    } else {
        fprintf(stderr, "Error: Invalid ADC reading: %d\n", adc_value);
        return 0; // Invalid reading
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_absent_count = 0;
    int sensor_present_count = 0;

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        if (!validate_adc_reading(adc_value)) {
            fprintf(stderr, "Invalid ADC reading, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

