#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define constants
#define ACCELERATION_TIME 1 // seconds
#define HOLD_TIME 2         // seconds
#define DECELERATION_TIME 1 // seconds
#define PAUSE_TIME 5        // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int motor, int speed);
void accelerate(int motor, int direction, int speed);
void hold(int motor, int direction, int speed);
void decelerate(int motor, int direction, int speed);
void reverse_directions();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor != 1 && motor != 2) {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    int enable_pin, direction_pin;

    if (motor == 1) {
        enable_pin = MOTOR1_ENABLE;
        direction_pin = MOTOR1_DIRECTION;
    } else {
        enable_pin = MOTOR2_ENABLE;
        direction_pin = MOTOR2_DIRECTION;
    }

    // Set direction
    gpioWrite(direction_pin, speed > 0 ? 1 : 0);

    // Set PWM duty cycle
    int duty_cycle = abs(speed);
    if (duty_cycle > 255) {
        duty_cycle = 255;
    }
    gpioPWM(enable_pin, duty_cycle);
}

// Function to accelerate a motor
void accelerate(int motor, int direction, int speed) {
    if (speed < 0) {
        fprintf(stderr, "Error: Invalid speed for acceleration: %d\n", speed);
        return;
    }

    int current_speed = 0;
    int increment = 10; // Adjust increment for desired acceleration rate

    while (current_speed <= speed) {
        set_motor_speed(motor, direction * current_speed);
        gpioDelay(10000); // 10 ms delay
        current_speed += increment;
    }
}

// Function to hold a motor at a constant speed
void hold(int motor, int direction, int speed) {
    set_motor_speed(motor, direction * speed);
}

// Function to decelerate a motor
void decelerate(int motor, int direction, int speed) {
    if (speed < 0) {
        fprintf(stderr, "Error: Invalid speed for deceleration: %d\n", speed);
        return;
    }

    int current_speed = speed;
    int decrement = 10; // Adjust decrement for desired deceleration rate

    while (current_speed >= 0) {
        set_motor_speed(motor, direction * current_speed);
        gpioDelay(10000); // 10 ms delay
        current_speed -= decrement;
    }
}

// Function to reverse motor directions
void reverse_directions() {
    int temp = MOTOR1_DIRECTION;
    MOTOR1_DIRECTION = MOTOR2_DIRECTION;
    MOTOR2_DIRECTION = temp;

    temp = MOTOR1_ENABLE;
    MOTOR1_ENABLE = MOTOR2_ENABLE;
    MOTOR2_ENABLE = temp;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Map potentiometer values to motor speeds
        int motor1_speed = pot1_value * 255 / 1023; // Map 0-1023 to 0-255
        int motor2_speed = pot2_value * 255 / 1023; // Map 0-1023 to 0-255

        // Accelerate motors
        accelerate(1, 1, motor1_speed);
        accelerate(2, 1, motor2_speed);
        gpioDelay(ACCELERATION_TIME * 1000000); // Wait for acceleration time

        // Hold at constant speed
        hold(1, 1, motor1_speed);
        hold(2, 1, motor2_speed);
        gpioDelay(HOLD_TIME * 1000000); // Wait for hold time

        // Decelerate motors
        decelerate(1, 1, motor1_speed);
        decelerate(2, 1, motor2_speed);
        gpioDelay(DECELERATION_TIME * 1000000); // Wait for deceleration time

        // Pause
        gpioDelay(PAUSE_TIME * 1000000); // Wait for pause time

        // Reverse directions
        reverse_directions();

        // Accelerate motors in reverse direction
        accelerate(1, -1, motor1_speed);
        accelerate(2, -1, motor2_speed);
        gpioDelay(ACCELERATION_TIME * 1000000); // Wait for acceleration time

        // Hold at constant speed in reverse direction
        hold(1, -1, motor1_speed);
        hold(2, -1, motor2_speed);
        gpioDelay(HOLD_TIME * 1000000); // Wait for hold time

        // Decelerate motors in reverse direction
        decelerate(1, -1, motor1_speed);
        decelerate(2, -1, motor2_speed);
        gpioDelay(DECELERATION_TIME * 1000000); // Wait for deceleration time

        // Pause
        gpioDelay(PAUSE_TIME * 1000000); // Wait for pause time
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

