#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SPI_CS 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define constants
#define NUM_SAMPLES 1000
#define DEBOUNCE_DELAY 10 // milliseconds
#define NOISE_CALIBRATION_TIME 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int calibrate_noise_level(int num_samples);
int compare_sample_to_threshold(int sample, int threshold);
void debounce(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        return -1;
    }
    gpioWrite(LED_PIN, 0); // Turn LED off initially

    if (gpioSetMode(SPI_CS, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting CS pin mode\n");
        return -1;
    }
    gpioWrite(SPI_CS, 1); // Ensure CS is initially high

    if (gpioSetMode(SPI_MOSI, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MOSI pin mode\n");
        return -1;
    }

    if (gpioSetMode(SPI_MISO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting MISO pin mode\n");
        return -1;
    }

    if (gpioSetMode(SPI_SCLK, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting SCLK pin mode\n");
        return -1;
    }

    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(SPI_CS, 0); // Select the MCP3008
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(SPI_CS, 1); // Deselect the MCP3008

    // Extract the 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Calibrate noise level
int calibrate_noise_level(int num_samples) {
    int sum = 0;
    printf("Calibrating noise level for %d samples...\n", num_samples);
    for (int i = 0; i < num_samples; i++) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading sample %d\n", i);
            return -1;
        }
        sum += sample;
        gpioDelay(1); // Small delay between samples
    }
    int baseline = sum / num_samples;
    printf("Calibration complete. Baseline noise level: %d\n", baseline);
    return baseline;
}

// Compare sample to threshold with debouncing
int compare_sample_to_threshold(int sample, int threshold) {
    static int last_state = 0; // 0 = off, 1 = on
    static uint32_t last_tick = 0;

    int current_state = (sample > threshold) ? 1 : 0;

    if (current_state == 1 && last_state == 0) {
        // Rising edge
        uint32_t current_tick = gpioTick();
        if (current_tick - last_tick > DEBOUNCE_DELAY * 1000) { // Convert ms to microseconds
            last_state = 1;
            last_tick = current_tick;
            return 1; // Threshold exceeded
        }
    } else if (current_state == 0 && last_state == 1) {
        // Falling edge
        last_state = 0;
    }

    return 0; // Threshold not exceeded
}

// Debounce function (called on every sample)
void debounce(int gpio, int level, uint32_t tick) {
    // This function is called by the pigpio callback, but we don't need to use it directly here.
    // The threshold comparison is done in the main loop.
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI interface
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int baseline = calibrate_noise_level(NUM_SAMPLES);
    if (baseline < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up callback for LED control (not used directly, but needed for debounce)
    gpioSetAlertFunc(LED_PIN, debounce);

    printf("Monitoring sound levels...\n");

    // Main loop
    while (!terminate) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading sample\n");
            break; // Exit loop on error
        }

        int threshold_exceeded = compare_sample_to_threshold(sample, baseline);

        if (threshold_exceeded) {
            gpioWrite(LED_PIN, 1); // Turn LED on
        } else {
            gpioWrite(LED_PIN, 0); // Turn LED off
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

