#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the magnetic field strength range
#define MIN_MT -100.0
#define MAX_MT 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the digital value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the digital value to a magnetic field strength in millitesla
float convert_to_mT(int digital_value) {
    return (float)(digital_value * 3.3);
}

// Function to log the magnetic field strength values to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file %s\n", LOG_FILE);
        fclose(fp);
        return -1; // Indicate an error
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file %s\n", LOG_FILE);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to check if the magnetic field strength is within the valid range
int is_valid_mT(float mT) {
    return (mT >= MIN_MT && mT <= MAX_MT);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the digital values from the sensors
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensors, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Convert the digital values to magnetic field strength values
        float sensor1_mT = convert_to_mT(sensor1_value);
        float sensor2_mT = convert_to_mT(sensor2_value);
        float sensor3_mT = convert_to_mT(sensor3_value);

        // Check if the magnetic field strength values are within the valid range
        if (!is_valid_mT(sensor1_mT) || !is_valid_mT(sensor2_mT) || !is_valid_mT(sensor3_mT)) {
            fprintf(stderr, "Magnetic field strength out of range, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Log the magnetic field strength values to the file
        if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

