#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int calculate_moisture_percentage(int adc_value);
void control_pump(int moisture_level);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Error: SPI transfer failed (error code %d).", result);
        log_event(error_message);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
int calculate_moisture_percentage(int adc_value) {
    // Assuming 0 ADC value is fully saturated and 1023 is dry
    return 100 - (int)(((float)adc_value / 1023.0) * 100.0);
}

// Function to control the pump
void control_pump(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        log_event("Pump turned ON.");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        log_event("Pump turned OFF.");
    }
}

// Function to log events to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    gpioWrite(PUMP_GPIO, 0); // Turn pump off
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value != -1) {
            int moisture_level = calculate_moisture_percentage(adc_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Moisture level: %d%% (ADC: %d)", moisture_level, adc_value);
            log_event(log_message);
            control_pump(moisture_level);
        } else {
            log_event("Error reading moisture level.");
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup (should not reach here if signal handler works)
    gpioWrite(PUMP_GPIO, 0); // Turn pump off
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

