#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60.0

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int sig);
int mqtt_connect_with_backoff(struct mosquitto **mosq);
int mqtt_subscribe(struct mosquitto *mosq, const char *topic);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
void control_led(int led_state);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        running = 0;
    }
}

// Exponential backoff MQTT connection
int mqtt_connect_with_backoff(struct mosquitto **mosq) {
    int rc = 0;
    int reconnect_delay = 1;

    while (running) {
        rc = mosquitto_connect(*mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Connected to MQTT broker\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
            fprintf(stderr, "Retrying in %d seconds...\n", reconnect_delay);
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
        }
    }
    return -1; // Shutdown signal received
}

// MQTT subscribe
int mqtt_subscribe(struct mosquitto *mosq, const char *topic) {
    int rc = mosquitto_subscribe(mosq, NULL, topic, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to topic: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    printf("Subscribed to topic: %s\n", topic);
    return 0;
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        printf("Received message on topic: %s\n", message->topic);
        int led_state;
        if (parse_json_payload((const char *)message->payload, &led_state) == 0) {
            control_led(led_state);
        } else {
            fprintf(stderr, "Error parsing JSON payload\n");
        }
    } else {
        fprintf(stderr, "Empty message received on topic: %s\n", message->topic);
    }
}

// JSON parsing
int parse_json_payload(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        fprintf(stderr, "Error: 'led_state' key not found in JSON\n");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        fprintf(stderr, "Error: 'led_state' is not a boolean\n");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// LED control
void control_led(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
    printf("LED set to state: %d\n", led_state);
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();
    printf("Cleanup complete\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize LED to off

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create mosquitto instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        cleanup();
        return 1;
    }

    // Set callbacks
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    // Connect with backoff
    if (mqtt_connect_with_backoff(&mosq) != 0) {
        fprintf(stderr, "Failed to connect to MQTT broker after multiple retries\n");
        cleanup();
        return 1;
    }

    // Subscribe
    if (mqtt_subscribe(mosq, MQTT_TOPIC) != 0) {
        cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        mosquitto_loop(mosq, -1, 1); // Non-blocking loop
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

