#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int sound_level;
    int alarm_state = 0; // 0 = off, 1 = on

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_GPIO);
        gpioTerminate();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sound sensor value
        sound_level = gpioRead(SOUND_SENSOR_GPIO);

        // Print sound level
        printf("Sound level: %d\n", sound_level);

        // Check for alarm condition
        if (sound_level == 0 && alarm_state == 0) {
            printf("Alarm triggered!\n");
            gpioWrite(ALARM_LED_GPIO, 1); // Turn on alarm LED
            alarm_state = 1;
            gpioDelay(1000); // Wait for 1 second
            gpioWrite(ALARM_LED_GPIO, 0); // Turn off alarm LED
            alarm_state = 0;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

