#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t program_running = 1;

// Function to handle SIGINT signal
void sigint_handler(int signal) {
    program_running = 0;
    printf("Caught SIGINT, exiting...\n");
}

// Function to handle SIGTERM signal
void sigterm_handler(int signal) {
    program_running = 0;
    printf("Caught SIGTERM, exiting...\n");
}

// Function to initialize the GPIO pin
int initialize_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to open the GPIO chip
int open_gpio_chip(const char *chip_name) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    return fd;
}

// Function to open the GPIO line
int open_gpio_line(int chip_fd, int gpio_pin) {
    struct gpio_line_request line_request;
    line_request.consumer = "vibration-monitor";
    line_request.flags = GPIO_LINE_REQUEST_FLAG_EDGE_RISING; // Rising edge for falling edge detection
    line_request.consumer_name = "vibration-monitor";

    int line = ioctl(chip_fd, GPIO_GET_LINE, &line_request);
    if (line < 0) {
        perror("Failed to get GPIO line");
        return -1;
    }
    return line;
}

// Function to wait for an event on the GPIO line
int wait_for_event(int line_fd) {
    struct gpio_event event;
    int ret = read(line_fd, &event, sizeof(event));
    if (ret < 0) {
        perror("Failed to read GPIO event");
        return -1;
    }
    return 0;
}

// Function to log the event to a file
int log_event(const char *log_file) {
    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Vibration detected!\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to print the event to stdout
int print_event() {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    printf("%s: Vibration detected!\n", timestamp);
    return 0;
}

// Function to shutdown the system
int shutdown_system() {
    system("sudo shutdown -h now");
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize GPIO
    if (initialize_gpio(GPIO_PIN) != 0) {
        return 1;
    }

    // Open GPIO chip
    int chip_fd = open_gpio_chip("/dev/gpiochip0");
    if (chip_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open GPIO line
    int line_fd = open_gpio_line(chip_fd, GPIO_PIN);
    if (line_fd < 0) {
        close(chip_fd);
        gpioTerminate();
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (wait_for_event(line_fd) == 0) {
            if (log_event(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
            if (print_event() != 0) {
                fprintf(stderr, "Failed to print event\n");
            }
            if (shutdown_system() != 0) {
                fprintf(stderr, "Failed to shutdown system\n");
            }
            break; // Exit the loop after shutdown
        }
    }

    // Clean up
    close(line_fd);
    close(chip_fd);
    gpioTerminate();

    printf("Vibration monitoring stopped.\n");

    return 0;
}

