// BMP280 initialization function
int bmp280_init(int i2c_handle) {
    // Check the chip ID
    char chip_id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_ID, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading BMP280 chip ID\n");
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect BMP280 chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Set the sensor to forced mode and configure oversampling
    char config_data[2];
    config_data[0] = BMP280_REG_CTRL_MEAS;
    config_data[1] = 0b00110111; // Oversampling x16, forced mode

    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, &config_data[1], 1) != 1) {
        fprintf(stderr, "Error writing to BMP280 control register\n");
        return -1;
    }

