    char data[24];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int bmp280_read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Function to compensate temperature
double bmp280_compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib) {
    double var1, var2, T;
    double dig_T1 = (double)calib.dig_T1;
    double dig_T2 = (double)calib.dig_T2;
    double dig_T3 = (double)calib.dig_T3;

    var1 = (((double)raw_temperature / 16384.0) - (dig_T1 / 1024.0)) * dig_T2;
    var2 = ((((double)raw_temperature / 131072.0) - (dig_T1 / 8192.0)) * (((double)raw_temperature / 131072.0) - (dig_T1 / 8192.0))) * dig_T3;
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine, struct bmp280_calib_data calib) {
    double var1, var2, p;
    double dig_P1 = (double)calib.dig_P1;
    double dig_P2 = (double)calib.dig_P2;
    double dig_P3 = (double)calib.dig_P3;
    double dig_P4 = (double)calib.dig_P4;
    double dig_P5 = (double)calib.dig_P5;
    double dig_P6 = (double)calib.dig_P6;
    double dig_P7 = (double)calib.dig_P7;
    double dig_P8 = (double)calib.dig_P8;
    double dig_P9 = (double)calib.dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * (dig_P6 / 32768.0);
    var2 = var2 + var1 * (dig_P5 * 2.0);
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1;

    if (var1 == 0)
    {
        return 0; // avoid exception caused by division by zero
    }

    p = 1048576.0 - raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = dig_P9 * p * p / 2147483648.0;
    var2 = p * (dig_P8 / 32768.0);
    p = p + (var1 + var2 + dig_P7) / 16.0;

    return p;
}

// Function to calculate altitude
double bmp280_calculate_altitude(double pressure) {
    double sea_level_pressure = 101325.0; // Standard sea level pressure in Pascals
    return 44330.0 * (1.0 - pow(pressure / sea_level_pressure, 0.1903));
}

// Function to log altitude to a file
int log_altitude(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, altitude);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (bmp280_read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure, altitude;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (bmp280_read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = bmp280_compensate_temperature(raw_temperature, calib);
            pressure = bmp280_compensate_pressure(raw_pressure, temperature, calib);

            // Calculate altitude
            altitude = bmp280_calculate_altitude(pressure);

            // Log altitude
            log_altitude(altitude);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

