// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // LM35 connected to channel 0
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5 // seconds
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void store_temperature(float temperature);
void print_temperature(float temperature);
void write_to_file();
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    return (adc_value * 3.3 / 1024.0) * 100.0;
}

// Function to store temperature in the circular buffer
void store_temperature(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the temperature
void print_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

// Function to write the temperature buffer to a file
void write_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", LOG_FILE);
        return;
    }

    fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Store temperature in the buffer
        store_temperature(temperature);

        // Print the temperature
        print_temperature(temperature);

        // Write to file
        write_to_file();

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

