#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/file.h>
#include <errno.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x60
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 0.5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MAX_TEMP 50.0 // Maximum expected temperature (Celsius)
#define MIN_TEMP -40.0 // Minimum expected temperature (Celsius)

// Global variables
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int spi_close(int fd);
int i2c_init(const char *device);
int i2c_write(int fd, uint8_t reg, uint16_t value);
int i2c_close(int fd);
float read_temperature();
float convert_adc_to_celsius(int adc_value);
float calculate_dac_voltage(float temperature);
int log_data(float temperature, float dac_voltage);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = 500000; // 500kHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = 500000, // Keep the speed constant
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// SPI close function
int spi_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing SPI device");
        return -1;
    }
    return 0;
}

// I2C initialization function
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 4) & 0xFF; // MSB
    buf[2] = (value << 4) & 0xF0; // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// Function to read temperature from MCP3008
float read_temperature() {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int adc_value = 0;
    int retries = 0;

    // MCP3008 configuration: single-ended channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    while (retries < MAX_RETRIES) {
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return convert_adc_to_celsius(adc_value);
        } else {
            fprintf(stderr, "SPI transfer failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    return NAN; // Return NaN on failure
}

// Function to convert ADC value to Celsius
float convert_adc_to_celsius(int adc_value) {
    float voltage = (adc_value * 3.3) / 1024.0; // Assuming 3.3V reference
    float temperature = (voltage - 0.5) / 0.01; // TMP36: 10mV/°C, 0.5V offset
    return temperature;
}

// Function to calculate DAC voltage
float calculate_dac_voltage(float temperature) {
    // Linear relationship: 0°C -> 0V, 50°C -> 3.3V
    float voltage = (temperature / MAX_TEMP) * 3.3;
    return voltage;
}

// Function to log data to file
int log_data(float temperature, float dac_voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    // Acquire exclusive lock
    if (flock(fileno(log_file), LOCK_EX) == -1) {
        perror("Error acquiring file lock");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, dac_voltage);
    fflush(log_file);

    // Release lock
    if (flock(fileno(log_file), LOCK_UN) == -1) {
        perror("Error releasing file lock");
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        spi_close(spi_fd);
    }
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (!isnan(temperature)) {
            float dac_voltage = calculate_dac_voltage(temperature);

            printf("Temperature: %.2f °C, DAC Voltage: %.2f V\n", temperature, dac_voltage);

            if (log_data(temperature, dac_voltage) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

