#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void light_sequence();
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop: run the light sequence indefinitely
    while (program_running) {
        light_sequence();
    }

    // Cleanup GPIO pins before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially deactivated
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    return 0;
}

// Function to activate a relay by setting the corresponding GPIO pin HIGH
void activate_relay(int pin) {
    gpioWrite(pin, 1); // Set the pin HIGH to activate the relay
}

// Function to deactivate a relay by setting the corresponding GPIO pin LOW
void deactivate_relay(int pin) {
    gpioWrite(pin, 0); // Set the pin LOW to deactivate the relay
}

// Function to implement the light sequence
void light_sequence() {
    // Activate relay 1
    activate_relay(RELAY1_PIN);
    gpioDelay(1000); // Wait for 1 second
    deactivate_relay(RELAY1_PIN);

    // Activate relay 2
    activate_relay(RELAY2_PIN);
    gpioDelay(1000); // Wait for 1 second
    deactivate_relay(RELAY2_PIN);

    // Activate relay 3
    activate_relay(RELAY3_PIN);
    gpioDelay(1000); // Wait for 1 second
    deactivate_relay(RELAY3_PIN);

    // Activate relay 4
    activate_relay(RELAY4_PIN);
    gpioDelay(1000); // Wait for 1 second
    deactivate_relay(RELAY4_PIN);
}

// Function to deactivate all relays and terminate the pigpio library
void cleanup_gpio() {
    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Terminate the pigpio library
    gpioTerminate();
    printf("GPIO cleanup and pigpio termination complete.\n");
}

// Signal handler function to gracefully deactivate relays and terminate GPIO
void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down gracefully...\n", signal);
    program_running = 0; // Set the flag to exit the main loop
    cleanup_gpio();       // Call the cleanup function
    exit(0);              // Exit the program
}

