#define RAIN_SENSOR_CHANNEL 0 // MCP3008 Channel 0
#define RAIN_THRESHOLD 5
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_PWM_DUTY 150
#define MOTOR_FORWARD_DURATION 3 // seconds
#define MOTOR_REVERSE_DURATION 3 // seconds
#define LOG_FILE "rain_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int control_motor(int direction);
int log_data(int rain_level, int motor_direction);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control the motor
int control_motor(int direction) {
    if (direction != MOTOR_FORWARD && direction != MOTOR_REVERSE) {
        fprintf(stderr, "Error: Invalid motor direction: %d\n", direction);
        return -1;
    }

    if (direction == MOTOR_FORWARD) {
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, MOTOR_PWM_DUTY);
    } else {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, MOTOR_PWM_DUTY);
    }

    return 0;
}

// Function to log data to file
int log_data(int rain_level, int motor_direction) {
    time_t rawtime;
    struct tm *timeinfo;
