        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stdout, "Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int rain_level = read_mcp3008(RAIN_SENSOR_CHANNEL);
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor value\n");
        } else {
            int motor_direction = (rain_level > RAIN_THRESHOLD) ? MOTOR_FORWARD : MOTOR_REVERSE;

            if (control_motor(motor_direction) != 0) {
                fprintf(stderr, "Error: Failed to control motor\n");
            }

            if (log_data(rain_level, motor_direction) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }

            if (motor_direction == MOTOR_FORWARD) {
                sleep(MOTOR_FORWARD_DURATION);
                control_motor(MOTOR_REVERSE);
                sleep(MOTOR_REVERSE_DURATION);
            } else {
                sleep(MOTOR_REVERSE_DURATION);
                control_motor(MOTOR_FORWARD);
                sleep(MOTOR_FORWARD_DURATION);
            }
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup
    fprintf(stdout, "Cleaning up...\n");
    control_motor(MOTOR_FORWARD); // Stop the motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Rain sensor monitoring stopped.\n");
    return 0;
}

