#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define CLAP_THRESHOLD 500
#define DEBOUNCE_TIME 50 // milliseconds
#define LED_ON_TIME 500  // milliseconds
#define LED_GPIO 16
#define ADC_GPIO 26
#define ADC_SAMPLES 1000 // Number of samples for ADC

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int on);
void print_timestamped_message();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();        // Release GPIO resources
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetMode(ADC_GPIO, PI_INPUT); // Set ADC GPIO as input

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    // Set ADC GPIO as output and drive low
    gpioSetMode(ADC_GPIO, PI_OUTPUT);
    gpioWrite(ADC_GPIO, 0);
    gpioDelay(1); // Small delay

    // Set ADC GPIO as input and sample
    gpioSetMode(ADC_GPIO, PI_INPUT);

    // Read ADC value (simple averaging)
    for (i = 0; i < ADC_SAMPLES; i++) {
        adc_value += gpioRead(ADC_GPIO);
        gpioDelay(1); // Small delay between samples
    }
    adc_value /= ADC_SAMPLES;

    return adc_value;
}

// Detect clap event
int detect_clap(int adc_value) {
    return (adc_value > CLAP_THRESHOLD) ? 1 : 0;
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Print timestamped message
void print_timestamped_message() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s: Clap detected!\n", timestamp);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");

    int clap_detected = 0;
    time_t last_clap_time = 0;

    while (program_running) {
        int adc_value = read_adc();

        if (detect_clap(adc_value)) {
            time_t current_time = time(NULL);
            if (!clap_detected || (current_time - last_clap_time) * 1000 >= DEBOUNCE_TIME) {
                clap_detected = 1;
                last_clap_time = current_time;
                print_timestamped_message();
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME); // Wait for LED_ON_TIME milliseconds
                control_led(0); // Turn off LED
                clap_detected = 0; // Reset clap detection
            }
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return 0;
}

