    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for the interval
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to magnetic field strength
        float magnetic_field = voltage_to_magnetic_field(voltage);

        // Get current timestamp
        time_t now = time(NULL);

        // Log data
        if (log_data(log_file, now, magnetic_field) < 0) {
            fprintf(stderr, "Error logging data, continuing.\n");
        }

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

