    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float current = adc_to_current(adc_value);

        // Validate voltage
        if (current < 0 || current > MAX_VOLTAGE) {
            fprintf(stderr, "Warning: Current value out of range (%.2f A)\n", current);
            continue; // Skip to the next iteration
        }

        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log current value\n");
        }

        usleep(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

