#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value with debouncing
int read_sensor(int gpio_pin) {
    int count = 0;
    int value;

    // Read the sensor value five times with a 2ms delay
    for (int i = 0; i < 5; i++) {
        value = gpioRead(gpio_pin);
        if (value == 0) { // Active-low
            count++;
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }

    // Return 1 if the majority of readings indicate an object, 0 otherwise
    return (count > 2) ? 1 : 0;
}

// Function to log the sensor states to the console
void log_sensor_states(int sensor1_state, int sensor2_state) {
    printf("Sensor1: %d, Sensor2: %d\n", sensor1_state, sensor2_state);
}

// Function to check for both sensors detecting an object
void check_alert(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Set pull-up resistors (if needed, depends on sensor configuration)
    // gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    // gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        // Log sensor states
        log_sensor_states(sensor1_state, sensor2_state);

        // Check for alert condition
        check_alert(sensor1_state, sensor2_state);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

