// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60 // seconds
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Open SPI channel
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed: %d\n", spi_handle);
        return -1;
    }

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: spiXfer failed: %d\n", result);
        spiClose(spi_handle);
        spi_handle = -1;
        return -1;
    }

    spiClose(spi_handle);
    spi_handle = -1;

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture level
double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    double moisture_level = 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
    return moisture_level;
}

// Function to log data to file
void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_entry, sizeof(log_entry), "%s,%.2f\n", timestamp, moisture_level);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    if (fprintf(fp, "%s", log_entry) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(0);
}

// SPI setup function (minimal implementation, pigpio handles most of the setup)
int spi_setup(spi_config_t config) {
    // pigpio handles SPI configuration
    return 0; // Return 0 for success, -1 for failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to calculate moisture level\n");
            sleep(READ_DELAY);
            continue;
        }

        log_data(moisture_level);
        printf("%s,%.2f\n", LOG_FILE, moisture_level);

        sleep(READ_DELAY);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

