#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY 200 // milliseconds
#define CAPTURE_DELAY 500  // milliseconds
#define IMAGE_DIR "/home/pi/security_cam/"
#define IMAGE_FORMAT "image_%Y%m%d_%H%M%S.jpg"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int camera_process_id = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int capture_image();
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received SIGINT or SIGTERM, shutting down...");
        cleanup();
        exit(0);
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    log_event("GPIO initialised successfully");
    return 0;
}

// Read the PIR sensor state
int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

// Capture an image using libcamera-still
int capture_image() {
    char command[256];
    char timestamp[64];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), IMAGE_FORMAT, timeinfo);

    char filename[256];
    snprintf(filename, sizeof(filename), "%s%s", IMAGE_DIR, timestamp);

    snprintf(command, sizeof(command), "libcamera-still -o %s", filename);

    log_event("Capturing image...");

    pid_t pid = fork();

    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("execl failed");
        exit(1); // Exit if execl fails
    } else if (pid > 0) {
        // Parent process
        camera_process_id = pid; // Store the process ID
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            char message[256];
            snprintf(message, sizeof(message), "Image captured: %s", filename);
            log_event(message);
            return 0; // Success
        } else {
            char message[256];
            snprintf(message, sizeof(message), "Image capture failed with status: %d", WEXITSTATUS(status));
            log_event(message);
            return -1; // Failure
        }
    } else {
        // Fork failed
        log_event("Fork failed");
        return -1;
    }
}

// Log an event to syslog
int log_event(const char *message) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    log_event("Cleaning up resources...");

    // Terminate the camera process if it's running
    if (camera_process_id > 0) {
        kill(camera_process_id, SIGTERM);
        waitpid(camera_process_id, NULL, 0); // Wait for the process to terminate
    }

    gpioTerminate();
    log_event("GPIO terminated");
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        return 1;
    }

    // Create the image directory if it doesn't exist
    struct stat st = {0};
    if (stat(IMAGE_DIR, &st) == -1) {
        if (mkdir(IMAGE_DIR, 0777) == -1) {
            log_event("Failed to create image directory");
            cleanup();
            return 1;
        }
        log_event("Image directory created");
    }

    log_event("Security camera started");

    // Main loop
    while (program_running) {
        int pir_state = read_pir_sensor();

        if (pir_state == 1) {
            // Motion detected
            log_event("Motion detected");

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds

            // Re-read the sensor to confirm the state
            int confirmed_state = read_pir_sensor();
            if (confirmed_state == 1) {
                // Motion confirmed
                if (capture_image() != 0) {
                    log_event("Image capture failed");
                }
            } else {
                log_event("Motion detection debounced, no motion");
            }
        }

        gpioDelay(CAPTURE_DELAY * 1000); // Delay between checks
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

