#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/time.h>

#define VIDEO_DEVICE "/dev/video0"
#define DEFAULT_IP "127.0.0.1"
#define DEFAULT_PORT 8080
#define DEFAULT_FRAME_SIZE 640 * 480 * 2 // YUYV
#define DEFAULT_UDP_BUFFER_SIZE 65000
#define DEFAULT_UDP_PACKET_SIZE 64000

// Structure to hold frame data
typedef struct {
    unsigned char *data;
    size_t size;
} frame_data_t;

// Global variables
int fd = -1; // Video device file descriptor
int udp_socket = -1; // UDP socket file descriptor
struct sockaddr_in server_addr; // Server address
frame_data_t *frames = NULL; // Array of frame data
int num_frames = 0; // Number of frames
int frame_index = 0; // Current frame index
int running = 1; // Flag to control program execution

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    running = 0;
}

// Function to initialize the video device
int init_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    // Open the video device
    fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying device capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Set your desired width
    fmt.fmt.pix.height = 480; // Set your desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // YUYV format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting image format");
        close(fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    // Map the buffers
    frames = calloc(req.count, sizeof(frame_data_t));
    if (!frames) {
        perror("Error allocating memory for frames");
        close(fd);
        return -1;
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(frames);
            return -1;
        }

        frames[i].size = buf.length;
        frames[i].data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (frames[i].data == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(frames);
            return -1;
        }

        // Queue the buffers
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            free(frames);
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        free(frames);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame() {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Process the frame data (e.g., save to file, send over network)
    // For this example, we'll just print the frame index
    printf("Captured frame %d\n", frame_index++);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to fragment a frame into UDP datagrams
int fragment_frame(frame_data_t *frame, int frame_index, int total_frames, int payload_size) {
    int num_packets = (payload_size + DEFAULT_UDP_PACKET_SIZE - 1) / DEFAULT_UDP_PACKET_SIZE; // Calculate number of packets
    int packet_size = payload_size / num_packets; // Calculate packet size
    int i, j;

    for (i = 0; i < num_packets; i++) {
        int current_packet_size = (i == num_packets - 1) ? payload_size % num_packets : packet_size; // Handle remaining bytes

        // Create UDP datagram header
        unsigned char header[16]; // 4 bytes for frame index, 4 for fragment index, 4 for total fragments, 4 for payload size
        memcpy(header, &frame_index, 4);
        memcpy(header + 4, &i, 4);
        memcpy(header + 8, &total_frames, 4);
        memcpy(header + 12, &current_packet_size, 4);

        // Allocate memory for the datagram
        unsigned char *datagram = malloc(16 + current_packet_size);
        if (!datagram) {
            perror("Error allocating memory for datagram");
            return -1;
        }

        // Copy the header and frame data into the datagram
        memcpy(datagram, header, 16);
        memcpy(datagram + 16, frame->data + i * packet_size, current_packet_size);

        // Send the datagram
        if (sendto(udp_socket, datagram, 16 + current_packet_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("Error sending datagram");
            free(datagram);
            return -1;
        }

        free(datagram);
    }

    return 0;
}

// Function to stop the video device
void stop_device() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    // Unmap the buffers
    for (int i = 0; i < 4; i++) {
        if (munmap(frames[i].data, frames[i].size) < 0) {
            perror("Error unmapping buffer");
        }
    }

    // Close the video device
    close(fd);
}

int main(int argc, char *argv[]) {
    char *ip_address = DEFAULT_IP;
    int port = DEFAULT_PORT;
    int frame_size = DEFAULT_FRAME_SIZE;
    int udp_buffer_size = DEFAULT_UDP_BUFFER_SIZE;
    int udp_packet_size = DEFAULT_UDP_PACKET_SIZE;

    // Parse command-line arguments
    if (argc > 1) {
        ip_address = argv[1];
    }
    if (argc > 2) {
        port = atoi(argv[2]);
    }
    if (argc > 3) {
        frame_size = atoi(argv[3]);
    }
    if (argc > 4) {
        udp_buffer_size = atoi(argv[4]);
    }
    if (argc > 5) {
        udp_packet_size = atoi(argv[5]);
    }

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(udp_socket);
        return 1;
    }

    // Initialize the video device
    if (init_device() < 0) {
        close(udp_socket);
        return 1;
    }

    // Capture frames and fragment them
    while (running) {
        if (capture_frame() < 0) {
            fprintf(stderr, "Error capturing frame, exiting...\n");
            break;
        }

        // Fragment the frame
        if (fragment_frame(&frames[frame_index % 4], frame_index, 4, frame_size) < 0) {
            fprintf(stderr, "Error fragmenting frame, exiting...\n");
            break;
        }
    }

    // Stop the video device
    stop_device();

    // Close the UDP socket
    close(udp_socket);

    // Free allocated memory
    free(frames);

    printf("Program finished.\n");
    return 0;
}

