#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 192
#define IMAGE_HEIGHT 144
#define IMAGE_FILENAME "image.jpg"

static int fd = -1;
static unsigned char **buffers = NULL;
static unsigned int n_buffers = 0;
static FILE *image_file = NULL;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    printf("Caught signal %d, exiting gracefully.\n", sig);

    // Stop streaming
    if (fd != -1) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i] != NULL) {
                if (munmap(buffers[i], buffers[i]->length) == -1) {
                    perror("munmap");
                }
            }
        }
        free(buffers);
    }

    // Close file
    if (image_file != NULL) {
        if (fclose(image_file) == EOF) {
            perror("fclose");
        }
    }

    // Close device
    if (fd != -1) {
        if (close(fd) == -1) {
            perror("close");
        }
    }

    exit(0);
}

// Function to open the video device
static int open_device(const char *device_name)
{
    fd = open(device_name, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    return 0;
}

// Function to query device capabilities
static int query_capabilities(int fd)
{
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming.\n");
        return -1;
    }

    printf("Device capabilities:\n");
    printf("  Driver: %s\n", cap.driver);
    printf("  Card: %s\n", cap.card);
    printf("  Bus info: %s\n", cap.bus_info);
    printf("  Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("  Device capabilities: 0x%08X\n", cap.capabilities);

    return 0;
}

// Function to set the pixel format
static int set_format(int fd, unsigned int width, unsigned int height)
{
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    printf("Image format set to: %dx%d, MJPEG\n", width, height);

    return 0;
}

// Function to request buffers
static int request_buffers(int fd, unsigned int count)
{
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < count) {
        fprintf(stderr, "Insufficient buffer memory.\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        return -1;
    }

    n_buffers = req.count;

    return 0;
}

// Function to map buffers
static int map_buffers(int fd)
{
    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
static int start_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

// Function to dequeue a buffer
static int dequeue_buffer(int fd)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    return buf.index;
}

// Function to write the image to a file
static int write_image(const unsigned char *image_data, unsigned int image_size)
{
    image_file = fopen(IMAGE_FILENAME, "wb");
    if (!image_file) {
        perror("fopen");
        return -1;
    }

    if (fwrite(image_data, 1, image_size, image_file) != image_size) {
        perror("fwrite");
        fclose(image_file);
        return -1;
    }

    if (fclose(image_file) == EOF) {
        perror("fclose");
        return -1;
    }

    printf("Image saved to %s\n", IMAGE_FILENAME);

    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    if (open_device(DEVICE_NAME) == -1) {
        return 1;
    }

    // Query capabilities
    if (query_capabilities(fd) == -1) {
        close(fd);
        return 1;
    }

    // Set format
    if (set_format(fd, IMAGE_WIDTH, IMAGE_HEIGHT) == -1) {
        close(fd);
        return 1;
    }

    // Request buffers
    if (request_buffers(fd, 4) == -1) {
        close(fd);
        return 1;
    }

    // Map buffers
    if (map_buffers(fd) == -1) {
        close(fd);
        return 1;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        close(fd);
        return 1;
    }

    // Dequeue a buffer
    unsigned int buffer_index = dequeue_buffer(fd);
    if (buffer_index == -1) {
        close(fd);
        return 1;
    }

    // Verify bytesused is greater than zero
    if (buffers[buffer_index]->bytesused == 0) {
        fprintf(stderr, "Error: bytesused is zero.\n");
        close(fd);
        return 1;
    }

    // Write the image to a file
    if (write_image(buffers[buffer_index], buffers[buffer_index]->bytesused) == -1) {
        close(fd);
        return 1;
    }

    // Unmap buffers
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i], buffers[i]->length) == -1) {
            perror("munmap");
        }
    }
    free(buffers);

    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
    }

    // Close device
    if (close(fd) == -1) {
        perror("close");
    }

    return 0;
}

