#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define PWM range
#define PWM_RANGE 1000

// Define pan and tilt limits
#define PAN_MIN 25
#define PAN_MAX 125
#define TILT_MIN 25
#define TILT_MAX 125

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_pan_position(int position);
int set_tilt_position(int position);
int read_button_state(int pin);
void handle_button_press(int button_pin, int *position, int min, int max);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    return 0;
}

// Set pan servo position
int set_pan_position(int position) {
    if (position < PAN_MIN || position > PAN_MAX) {
        fprintf(stderr, "Error: Pan position out of range (%d)\n", position);
        return 1;
    }

    int pulse_width = (position - 25) * 10 + 500; // Calculate pulse width
    gpioPWM(PAN_SERVO_PIN, pulse_width); // Set PWM duty cycle
    return 0;
}

// Set tilt servo position
int set_tilt_position(int position) {
    if (position < TILT_MIN || position > TILT_MAX) {
        fprintf(stderr, "Error: Tilt position out of range (%d)\n", position);
        return 1;
    }

    int pulse_width = (position - 25) * 10 + 500; // Calculate pulse width
    gpioPWM(TILT_SERVO_PIN, pulse_width); // Set PWM duty cycle
    return 0;
}

// Read button state
int read_button_state(int pin) {
    return gpioRead(pin);
}

// Handle button press
void handle_button_press(int button_pin, int *position, int min, int max) {
    if (button_pin == TILT_UP_PIN) {
        *position += 5;
        if (*position > max) {
            *position = max;
        }
    } else if (button_pin == TILT_DOWN_PIN) {
        *position -= 5;
        if (*position < min) {
            *position = min;
        }
    } else if (button_pin == PAN_LEFT_PIN) {
        *position -= 5;
        if (*position < min) {
            *position = min;
        }
    } else if (button_pin == PAN_RIGHT_PIN) {
        *position += 5;
        if (*position > max) {
            *position = max;
        }
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial positions
    int pan_position = 75;
    int tilt_position = 75;

    if (set_pan_position(pan_position) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_tilt_position(tilt_position) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read button states
        int tilt_up_state = read_button_state(TILT_UP_PIN);
        int tilt_down_state = read_button_state(TILT_DOWN_PIN);
        int pan_left_state = read_button_state(PAN_LEFT_PIN);
        int pan_right_state = read_button_state(PAN_RIGHT_PIN);

        // Handle button presses
        if (tilt_up_state == 0) {
            handle_button_press(TILT_UP_PIN, &tilt_position, TILT_MIN, TILT_MAX);
            if (set_tilt_position(tilt_position) != 0) {
                program_running = 0; // Exit on error
            }
        }
        if (tilt_down_state == 0) {
            handle_button_press(TILT_DOWN_PIN, &tilt_position, TILT_MIN, TILT_MAX);
            if (set_tilt_position(tilt_position) != 0) {
                program_running = 0; // Exit on error
            }
        }
        if (pan_left_state == 0) {
            handle_button_press(PAN_LEFT_PIN, &pan_position, PAN_MIN, PAN_MAX);
            if (set_pan_position(pan_position) != 0) {
                program_running = 0; // Exit on error
            }
        }
        if (pan_right_state == 0) {
            handle_button_press(PAN_RIGHT_PIN, &pan_position, PAN_MIN, PAN_MAX);
            if (set_pan_position(pan_position) != 0) {
                program_running = 0; // Exit on error
            }
        }

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Clean up
    gpioTerminate();
    return 0;
}

