#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/types.h>
#include <sys/stat.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int              fd                  = -1;
static struct buffer    *buffers             = NULL;
static unsigned int     n_buffers            = 0;
static int              running              = 1;
static int              camera_fd            = -1;
static char             filename[256]       = {0};

static void int_handler(int dummy)
{
    running = 0;
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main(int argc, char **argv)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    fd_set fds;
    struct timeval tv;
    int i;
    unsigned char *frame = NULL;
    unsigned char *rgb_frame = NULL;
    unsigned char *jpeg_frame = NULL;
    FILE *jpeg_file = NULL;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    strncpy(filename, argv[1], sizeof(filename) - 1);
    filename[sizeof(filename) - 1] = '\0';

    signal(SIGINT, int_handler);

    camera_fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (camera_fd < 0) {
        perror("Error opening /dev/video0");
        return 1;
    }

    if (-1 == xioctl(camera_fd, VIDIOC_QUERYCAP, &cap)) {
        perror("Error querying capabilities");
        close(camera_fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", "/dev/video0");
        close(camera_fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", "/dev/video0");
        close(camera_fd);
        return 1;
    }

    CLEAR(fmt);
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = 640;
    fmt.fmt.pix.height      = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(camera_fd, VIDIOC_S_FMT, &fmt)) {
        perror("Error setting format");
        close(camera_fd);
        return 1;
    }

    CLEAR(req);
    req.count                = 4; // Number of buffers
    req.type                 = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory               = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(camera_fd, VIDIOC_REQBUFS, &req)) {
        perror("Error requesting buffers");
        close(camera_fd);
        return 1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(camera_fd);
        return 1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(camera_fd, VIDIOC_QUERYBUF, &buf)) {
            perror("Error querying buffer");
            close(camera_fd);
            free(buffers);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("Error mapping buffer");
            close(camera_fd);
            free(buffers);
            return 1;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(camera_fd, VIDIOC_QBUF, &buf)) {
            perror("Error queuing buffer");
            close(camera_fd);
            for (i = 0; i < n_buffers; ++i) {
                if (buffers[i].start != MAP_FAILED) {
                    munmap(buffers[i].start, buffers[i].length);
                }
            }
            free(buffers);
            return 1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(camera_fd, VIDIOC_STREAMON, &type)) {
        perror("Error starting stream");
        close(camera_fd);
        for (i = 0; i < n_buffers; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        return 1;
    }

    FD_ZERO(&fds);
    FD_SET(camera_fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    frame = calloc(fmt.fmt.pix.width * fmt.fmt.pix.height * 2, 1); // YUYV: 2 bytes per pixel
    if (!frame) {
        perror("Out of memory for frame buffer");
        close(camera_fd);
        for (i = 0; i < n_buffers; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        return 1;
    }

    rgb_frame = calloc(fmt.fmt.pix.width * fmt.fmt.pix.height * 3, 1); // RGB24: 3 bytes per pixel
    if (!rgb_frame) {
        perror("Out of memory for RGB buffer");
        close(camera_fd);
        for (i = 0; i < n_buffers; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        free(frame);
        return 1;
    }

    jpeg_frame = calloc(fmt.fmt.pix.width * fmt.fmt.pix.height * 3, 1); // JPEG: 3 bytes per pixel
    if (!jpeg_frame) {
        perror("Out of memory for JPEG buffer");
        close(camera_fd);
        for (i = 0; i < n_buffers; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        free(frame);
        free(rgb_frame);
        return 1;
    }

    while (running) {
        if (-1 == select(camera_fd + 1, &fds, NULL, NULL, &tv)) {
            perror("Error in select");
            break;
        }

        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(camera_fd, VIDIOC_DQBUF, &buf)) {
            perror("Error dequeuing buffer");
            break;
        }

        // Convert YUYV to RGB24 (simple conversion, not optimized)
        for (int y = 0; y < fmt.fmt.pix.height; y++) {
            for (int x = 0; x < fmt.fmt.pix.width; x += 2) {
                int index = (y * fmt.fmt.pix.width + x) * 2;
                unsigned char y1 = frame[index];
                unsigned char u = frame[index + 1];
                unsigned char y2 = frame[index + 2];
                unsigned char v = frame[index + 3];

                int r1 = y1 + (1.370705 * (v - 128));
                int g1 = y1 - (0.698001 * (v - 128)) - (0.336301 * (u - 128));
                int b1 = y1 + (1.732446 * (u - 128));

                int r2 = y2 + (1.370705 * (v - 128));
                int g2 = y2 - (0.698001 * (v - 128)) - (0.336301 * (u - 128));
                int b2 = y2 + (1.732446 * (u - 128));

                r1 = (r1 < 0) ? 0 : ((r1 > 255) ? 255 : r1);
                g1 = (g1 < 0) ? 0 : ((g1 > 255) ? 255 : g1);
                b1 = (b1 < 0) ? 0 : ((b1 > 255) ? 255 : b1);

                r2 = (r2 < 0) ? 0 : ((r2 > 255) ? 255 : r2);
                g2 = (g2 < 0) ? 0 : ((g2 > 255) ? 255 : g2);
                b2 = (b2 < 0) ? 0 : ((b2 > 255) ? 255 : b2);

                rgb_frame[(y * fmt.fmt.pix.width + x) * 3 + 0] = r1;
                rgb_frame[(y * fmt.fmt.pix.width + x) * 3 + 1] = g1;
                rgb_frame[(y * fmt.fmt.pix.width + x) * 3 + 2] = b1;
                rgb_frame[(y * fmt.fmt.pix.width + x + 1) * 3 + 0] = r2;
                rgb_frame[(y * fmt.fmt.pix.width + x + 1) * 3 + 1] = g2;
                rgb_frame[(y * fmt.fmt.pix.width + x + 1) * 3 + 2] = b2;
            }
        }

        // Apply a simple blur filter (simple averaging)
        for (int y = 1; y < fmt.fmt.pix.height - 1; y++) {
            for (int x = 1; x < fmt.fmt.pix.width - 1; x++) {
                int sum_r = 0, sum_g = 0, sum_b = 0;
                for (int i = -1; i <= 1; i++) {
                    for (int j = -1; j <= 1; j++) {
                        int index = ((y + i) * fmt.fmt.pix.width + (x + j)) * 3;
                        sum_r += rgb_frame[index + 0];
                        sum_g += rgb_frame[index + 1];
                        sum_b += rgb_frame[index + 2];
                    }
                }
                int index = (y * fmt.fmt.pix.width + x) * 3;
                rgb_frame[index + 0] = sum_r / 9;
                rgb_frame[index + 1] = sum_g / 9;
                rgb_frame[index + 2] = sum_b / 9;
            }
        }

        // Encode as JPEG (using a simple placeholder)
        jpeg_file = fopen(filename, "wb");
        if (!jpeg_file) {
            perror("Error opening JPEG file");
            break;
        }

        fprintf(jpeg_file, "This is a placeholder JPEG image.\n");
        fclose(jpeg_file);

        // Get timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

        // Rename the JPEG file with the timestamp
        char new_filename[256];
        snprintf(new_filename, sizeof(new_filename), "%s_%s.jpg", filename, timestamp);
        rename(filename, new_filename);

        if (-1 == xioctl(camera_fd, VIDIOC_QBUF, &buf)) {
            perror("Error queuing buffer");
            break;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(camera_fd, VIDIOC_STREAMOFF, &type)) {
        perror("Error stopping stream");
    }

    for (i = 0; i < n_buffers; ++i) {
        if (buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }
    free(buffers);
    free(frame);
    free(rgb_frame);
    free(jpeg_frame);

    close(camera_fd);

    return 0;
}

