                g2 = (g2 < 0) ? 0 : ((g2 > 255) ? 255 : g2);
                b2 = (b2 < 0) ? 0 : ((b2 > 255) ? 255 : b2);

                rgb_frame[(y * fmt.fmt.pix.width + x) * 3 + 0] = r1;
                rgb_frame[(y * fmt.fmt.pix.width + x) * 3 + 1] = g1;
                rgb_frame[(y * fmt.fmt.pix.width + x) * 3 + 2] = b1;
                rgb_frame[(y * fmt.fmt.pix.width + x + 1) * 3 + 0] = r2;
                rgb_frame[(y * fmt.fmt.pix.width + x + 1) * 3 + 1] = g2;
                rgb_frame[(y * fmt.fmt.pix.width + x + 1) * 3 + 2] = b2;
            }
        }

        // Apply a simple blur filter (simple averaging)
        for (int y = 1; y < fmt.fmt.pix.height - 1; y++) {
            for (int x = 1; x < fmt.fmt.pix.width - 1; x++) {
                int sum_r = 0, sum_g = 0, sum_b = 0;
                for (int i = -1; i <= 1; i++) {
                    for (int j = -1; j <= 1; j++) {
                        int index = ((y + i) * fmt.fmt.pix.width + (x + j)) * 3;
                        sum_r += rgb_frame[index + 0];
                        sum_g += rgb_frame[index + 1];
                        sum_b += rgb_frame[index + 2];
                    }
                }
                int index = (y * fmt.fmt.pix.width + x) * 3;
                rgb_frame[index + 0] = sum_r / 9;
                rgb_frame[index + 1] = sum_g / 9;
                rgb_frame[index + 2] = sum_b / 9;
            }
        }

        // Encode as JPEG (using a simple placeholder)
        jpeg_file = fopen(filename, "wb");
        if (!jpeg_file) {
            perror("Error opening JPEG file");
            break;
        }

        fprintf(jpeg_file, "This is a placeholder JPEG image.\n");
        fclose(jpeg_file);

        // Get timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

        // Rename the JPEG file with the timestamp
        char new_filename[256];
        snprintf(new_filename, sizeof(new_filename), "%s_%s.jpg", filename, timestamp);
        rename(filename, new_filename);

        if (-1 == xioctl(camera_fd, VIDIOC_QBUF, &buf)) {
            perror("Error queuing buffer");
            break;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(camera_fd, VIDIOC_STREAMOFF, &type)) {
        perror("Error stopping stream");
    }

    for (i = 0; i < n_buffers; ++i) {
        if (buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }
    free(buffers);
    free(frame);
    free(rgb_frame);
    free(jpeg_frame);

    close(camera_fd);

    return 0;
}

