#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define MAX_FRAMESIZES 10
#define MAX_FRAMEINTERVALS 5

struct v4l2_capability cap;
struct v4l2_frmsizeenum framesizes[MAX_FRAMESIZES];
struct v4l2_frmivalenum frameintervals[MAX_FRAMEINTERVALS];
struct v4l2_queryctrl queryctrl;

int main() {
    int fd;
    int i, j;
    struct v4l2_frmsizeenum *current_framesize;
    struct v4l2_frmivalenum *current_frameinterval;
    int framesize_index = 0;
    int frameinterval_index = 0;

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    printf("Device: %s\n", DEVICE_NAME);
    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08X\n", cap.capabilities);

    // Check if the device supports frame size enumeration
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    // Enumerate supported frame sizes
    current_framesize = &framesizes[0];
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, current_framesize) == 0) {
        if (current_framesize->type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  Supported Frame Size: %dx%d\n", current_framesize->discrete.width, current_framesize->discrete.height);
        } else if (current_framesize->type == V4L2_FRMSIZE_TYPE_CONTINUOUS) {
            printf("  Supported Frame Size: Continuous\n");
        } else if (current_framesize->type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  Supported Frame Size: Stepwise\n");
        }
        framesize_index++;
        current_framesize++;
    }
    if (errno != 0) {
        perror("Error enumerating frame sizes");
        close(fd);
        return 1;
    }

    // Check if the device supports frame interval enumeration
    if (!(cap.capabilities & V4L2_CAP_TIMEPERFRAME)) {
        fprintf(stderr, "Device does not support time per frame\n");
        close(fd);
        return 1;
    }

    // Enumerate supported frame intervals
    current_frameinterval = &frameintervals[0];
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, current_frameinterval) == 0) {
        printf("  Supported Frame Rate: %d/%d\n", current_frameinterval->numerator, current_frameinterval->denominator);
        frameinterval_index++;
        current_frameinterval++;
    }
    if (errno != 0) {
        perror("Error enumerating frame intervals");
        close(fd);
        return 1;
    }

    // Query focus control
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) < 0) {
        perror("Error querying focus control");
        close(fd);
        return 1;
    }

    if (queryctrl.flags & V4L2_CTRL_FLAG_AUTOSUSPEND) {
        printf("  Autofocus Supported\n");
    } else {
        printf("  Autofocus Not Supported\n");
    }

    close(fd);
    return 0;
}

