#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000 // milliseconds
#define IMAGE_QUALITY 85
#define HTTP_ENDPOINT "http://<IP>:<port>/upload" // Replace with your actual endpoint

// Global variables
static volatile int running = 1;
static char *ip_address = NULL;
static int port = 0;
static char *http_endpoint = NULL;

// Structure to hold the response from the HTTP POST request
typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

// Callback function to write the HTTP response to memory
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if (ptr == NULL) {
        fprintf(stderr, "realloc() failed\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure the GPIO pin as an input with a pull-down resistor
int configure_gpio() {
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Function to capture a JPEG image using the camera module
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-jpeg -o %s -q %d", filename, IMAGE_QUALITY);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Failed to execute capture command\n");
        return -1;
    }
    return 0;
}

// Function to generate an ISO 8601 timestamp with microseconds
int generate_timestamp(char *timestamp) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "clock_gettime failed\n");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 30 - strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000);

    return 0;
}

// Function to create the motion_captures directory if it doesn't exist
int create_directory() {
    struct stat st = {0};
