#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define PIR_GPIO 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_DELAY_MS 50
#define CAPTURE_TIMEOUT_MS 2000
#define CAPTURE_QUALITY 85

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_gpio();
int init_spi();
int read_mcp3008(int channel);
int capture_image(int light_level);
void log_message(const char *message);
void motion_detected_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor
    gpioSetAlertFuncEx(PIR_GPIO, motion_detected_callback, NULL); // Use alert function

    return 0;
}

// Function to initialize SPI
int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to capture image using raspistill
int capture_image(int light_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char command[512];
    int status;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%03d.jpg", timeinfo);
    snprintf(filename, sizeof(filename), "%s/%s", IMAGE_DIR, filename);

    snprintf(command, sizeof(command), "raspistill -o %s -w 640 -h 480 -q %d -t %d -nopreview", filename, CAPTURE_QUALITY, CAPTURE_TIMEOUT_MS);

    log_message("Capturing image...");
    status = system(command);

    if (status == -1) {
        log_message("Error executing raspistill command");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        log_message("raspistill command failed");
        return -1;
    }

    log_message("Image captured successfully");
    return 0;
}

// Function to log messages to file
void log_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected
        log_message("Motion detected!");

        // Debounce
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

        // Read light level from MCP3008
        int light_level = read_mcp3008(MCP3008_CHANNEL);
        if (light_level < 0) {
            log_message("Error reading light level");
            return;
        }

        // Capture image
        if (capture_image(light_level) != 0) {
            log_message("Error capturing image");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, exiting...");
}

// Cleanup function to release resources
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    log_message("Cleanup complete");
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_message("Starting motion capture program");

    // Initialize GPIO and SPI
    if (init_gpio() != 0) {
        log_message("GPIO initialization failed");
        cleanup();
        return 1;
    }

    if (init_spi() != 0) {
        log_message("SPI initialization failed");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

