#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_X 200
#define CROP_Y 150

#define FRAME_TIMEOUT_SEC 2

struct buffer {
    void   *start;
    size_t  length;
};

static int fd = -1;
static struct buffer *buffers = NULL;
static unsigned int n_buffers = 0;
static volatile sig_atomic_t stop = 0;

static void int_handler(int sig)
{
    (void)sig; /* unused parameter */
    stop = 1;
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main()
{
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT ||
        fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "V4L2_PIX_FMT_YUYV not set correctly\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; /* single buffer */
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return EXIT_FAILURE;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        close(fd);
        for (unsigned int i = 0; i < n_buffers; ++i) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = FRAME_TIMEOUT_SEC;
    tv.tv_usec = 0;

    unsigned char *frame = NULL;
    unsigned char *crop_frame = NULL;
    size_t frame_size = WIDTH * HEIGHT * 2; /* YUYV */
    size_t crop_size = CROP_WIDTH * CROP_HEIGHT * 2;

    while (!stop) {
        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            perror("select");
            break;
        }

        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            perror("VIDIOC_DQBUF");
            break;
        }

        frame = buffers[buf.index].start;
        frame_size = buffers[buf.index].length;

        if (frame == NULL || frame_size == 0) {
            fprintf(stderr, "Empty frame received\n");
            xioctl(fd, VIDIOC_QBUF, &buf);
            continue;
        }

        crop_frame = malloc(crop_size);
        if (crop_frame == NULL) {
            perror("malloc");
            break;
        }

        /* Crop the frame */
        unsigned char *yuyv = frame;
        unsigned char *cropped = crop_frame;
        for (int y = 0; y < CROP_HEIGHT; y++) {
            for (int x = 0; x < CROP_WIDTH; x++) {
                int src_x = CROP_X + x;
                int src_y = CROP_Y + y;
                int offset = (src_y * WIDTH + src_x) * 2;
                cropped[y * CROP_WIDTH * 2 + x * 2] = yuyv[offset]; // Y
                cropped[y * CROP_WIDTH * 2 + x * 2 + 1] = yuyv[offset + 1]; // U
            }
        }

        /* Write to file */
        FILE *fp = fopen("cropped.yuv", "wb");
        if (fp == NULL) {
            perror("fopen");
            free(crop_frame);
            xioctl(fd, VIDIOC_QBUF, &buf);
            continue;
        }

        size_t bytes_written = fwrite(crop_frame, 1, crop_size, fp);
        if (bytes_written != crop_size) {
            perror("fwrite");
            fclose(fp);
            free(crop_frame);
            xioctl(fd, VIDIOC_QBUF, &buf);
            continue;
        }

        fclose(fp);

        free(crop_frame);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    enum v4l2_buf_type type2 = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type2)) {
        perror("VIDIOC_STREAMOFF");
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
        }
    }
    free(buffers);

    close(fd);

    return EXIT_SUCCESS;
}

