#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <fcntl.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define PWM range (0-1000 for 0-180 degrees)
#define PWM_RANGE 1000

// Define delay between servo movements (100 ms)
#define DELAY_MS 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int gpio_pin, int angle);
int read_key();
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold servo positions
typedef struct {
    int pan_angle;
    int tilt_angle;
} ServoPositions;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    return 0;
}

// Function to set servo angle
int set_servo_angle(int gpio_pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-%d)\n", MAX_ANGLE);
        return 1;
    }

    // Calculate PWM duty cycle (0-1000)
    int duty_cycle = (int)(((float)angle / MAX_ANGLE) * PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(gpio_pin, duty_cycle);

    return 0;
}

// Function to read a key from stdin without echo
int read_key() {
    struct termios oldt, newt;
    int ch;
    int oldf;

    // Save the old settings
    tcgetattr(STDIN_FILENO, &oldt);
    oldt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);

    // Read a character
    ch = getchar();

    // Restore the old settings
    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);

    return ch;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    // Set servos to neutral position
    set_servo_angle(PAN_SERVO_PIN, 90);
    set_servo_angle(TILT_SERVO_PIN, 90);

    // Terminate pigpio
    gpioTerminate();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial servo positions
    if (set_servo_angle(PAN_SERVO_PIN, 90) != 0) {
        cleanup_gpio();
        return 1;
    }
    if (set_servo_angle(TILT_SERVO_PIN, 90) != 0) {
        cleanup_gpio();
        return 1;
    }

    printf("Servo control program. Press arrow keys to move, 'q' to quit.\n");

    // Main loop
    while (program_running) {
        int key = read_key();

        ServoPositions current_positions;
        current_positions.pan_angle = 90;
        current_positions.tilt_angle = 90;

        if (set_servo_angle(PAN_SERVO_PIN, current_positions.pan_angle) != 0) {
            fprintf(stderr, "Error setting pan servo angle\n");
        }
        if (set_servo_angle(TILT_SERVO_PIN, current_positions.tilt_angle) != 0) {
            fprintf(stderr, "Error setting tilt servo angle\n");
        }

        switch (key) {
            case 27: // Escape key (arrow key sequence starts with ESC)
                key = read_key(); // Read the next key
                if (key == 91) { // '['
                    key = read_key(); // Read the next key
                    if (key == 65) { // 'A' (up arrow)
                        current_positions.tilt_angle += 5;
                        if (current_positions.tilt_angle > MAX_ANGLE) {
                            current_positions.tilt_angle = MAX_ANGLE;
                        }
                        if (set_servo_angle(TILT_SERVO_PIN, current_positions.tilt_angle) != 0) {
                            fprintf(stderr, "Error setting tilt servo angle\n");
                        }
                    } else if (key == 66) { // 'B' (down arrow)
                        current_positions.tilt_angle -= 5;
                        if (current_positions.tilt_angle < MIN_ANGLE) {
                            current_positions.tilt_angle = MIN_ANGLE;
                        }
                        if (set_servo_angle(TILT_SERVO_PIN, current_positions.tilt_angle) != 0) {
                            fprintf(stderr, "Error setting tilt servo angle\n");
                        }
                    } else if (key == 67) { // 'C' (right arrow)
                        current_positions.pan_angle += 5;
                        if (current_positions.pan_angle > MAX_ANGLE) {
                            current_positions.pan_angle = MAX_ANGLE;
                        }
                        if (set_servo_angle(PAN_SERVO_PIN, current_positions.pan_angle) != 0) {
                            fprintf(stderr, "Error setting pan servo angle\n");
                        }
                    } else if (key == 68) { // 'D' (left arrow)
                        current_positions.pan_angle -= 5;
                        if (current_positions.pan_angle < MIN_ANGLE) {
                            current_positions.pan_angle = MIN_ANGLE;
                        }
                        if (set_servo_angle(PAN_SERVO_PIN, current_positions.pan_angle) != 0) {
                            fprintf(stderr, "Error setting pan servo angle\n");
                        }
                    }
                }
                break;
            case 113: // 'q' key
                program_running = 0;
                break;
        }

        gpioDelay(DELAY_MS * 1000); // Delay for 100 ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

