    FILE *fp;
    char buffer[10];
    float temp = -1.0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", TEMP_FILE);
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000.0;
    }

    fclose(fp);
    return temp;
