// Function to read CPU usage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    char buffer[1024];
    float user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    float total, idle_prev, total_prev;

    fp = fopen(CPU_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CPU file: %s\n", CPU_FILE);
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        return -1.0;
    }

    // Parse the first line of /proc/stat
    if (sscanf(buffer, "cpu  %f %f %f %f %f %f %f %f %f %f",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        return -1.0;
    }

    // Calculate CPU usage percentage
    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    // Read previous values (assuming the program runs continuously)
    // In a real application, you would store these values and use them for the next calculation.
    // For this example, we'll just use the current values.
    total_prev = total;
    idle_prev = idle;

    float total_diff = total - total_prev;
    float idle_diff = idle - idle_prev;

    float cpu_usage = (total_diff - idle_diff) / total_diff * 100.0;

    fclose(fp);
    return cpu_usage;
}

