// Function to write a pixel to the OLED display
void oled_write_pixel(int x, int y, int color) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) return;

    int page = y / 8;
    int bit = y % 8;

    char data[2];
    data[0] = 0x40; // Data command
    data[1] = 0x00; // Initial value

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, data, 1) < 0) {
        fprintf(stderr, "OLED pixel write error: %d\n", y);
        exit(1);
    }

    char buffer[1];
    buffer[0] = 0x00; // Initial value

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer, 1) < 0) {
        fprintf(stderr, "OLED pixel write error: %d\n", y);
        exit(1);
    }

    if (color) {
        buffer[0] = 0x01; // Set pixel to 1
    } else {
        buffer[0] = 0x00; // Set pixel to 0
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer, 1) < 0) {
        fprintf(stderr, "OLED pixel write error: %d\n", y);
        exit(1);
    }
}

