// I2C write function with error handling
int i2c_write_data(int handle, const char *data, int len) {
    int result = i2cWriteDevice(handle, data, len);
    if (result != len) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp = -1.0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", TEMP_FILE);
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000.0;
    }

    fclose(fp);
    return temp;
}

// Function to read CPU usage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    char buffer[1024];
    float user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    float total, idle_prev, total_prev;

    fp = fopen(CPU_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CPU file: %s\n", CPU_FILE);
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        return -1.0;
    }

    // Parse the first line of /proc/stat
    if (sscanf(buffer, "cpu  %f %f %f %f %f %f %f %f %f %f",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        return -1.0;
    }

    // Calculate CPU usage percentage
    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    // Read previous values (assuming the program runs continuously)
    // In a real application, you would store these values and use them for the next calculation.
    // For this example, we'll just use the current values.
    total_prev = total;
    idle_prev = idle;

    float total_diff = total - total_prev;
    float idle_diff = idle - idle_prev;

    float cpu_usage = (total_diff - idle_diff) / total_diff * 100.0;

    fclose(fp);
    return cpu_usage;
}

// Function to initialize the OLED display
void oled_init() {
    char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100Hz)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting (0x14 = enable)
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap (A0 = normal, A1 = reversed)
        0xC8,       // COM output scan direction (C0 = normal, C8 = reversed)
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (A4 = normal, A5 = all ON)
        0xA6,       // Normal / reverse display (A6 = normal, A7 = reverse)
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteByteData(i2c_handle, 0x00, init_commands[i]) < 0) {
            fprintf(stderr, "OLED initialization error: %d\n", i);
            exit(1);
        }
    }
}

// Function to clear the OLED display
void oled_clear() {
    char clear_buffer[OLED_WIDTH * 8 / 8]; // 128 bytes
    memset(clear_buffer, 0x00, sizeof(clear_buffer));
    for (int i = 0; i < OLED_HEIGHT / 8; i++) {
        if (i2cWriteI2CBlockData(i2c_handle, 0x40, clear_buffer, sizeof(clear_buffer)) < 0) {
            fprintf(stderr, "OLED clear error: %d\n", i);
            exit(1);
        }
    }
}

