    while (*str) {
        oled_write_char(x, y, *str++);
    }
}

// Function to write a character to the OLED display
void oled_write_char(int x, int y, char c) {
    if (c < 32 || c > 126) c = 0; // Handle out-of-range characters
    c -= 32; // Adjust index for font array

    for (int i = 0; i < 5; i++) {
        oled_write_pixel(x + i, y, (font[c][i] & 0x01));
    }
    for (int i = 0; i < 5; i++) {
        oled_write_pixel(x + i, y + 1, (font[c][i] & 0x02));
    }
    for (int i = 0; i < 5; i++) {
        oled_write_pixel(x + i, y + 2, (font[c][i] & 0x04));
    }
    for (int i = 0; i < 5; i++) {
        oled_write_pixel(x + i, y + 3, (font[c][i] & 0x08));
    }
    for (int i = 0; i < 5; i++) {
        oled_write_pixel(x + i, y + 4, (font[c][i] & 0x10));
    }
    for (int i = 0; i < 5; i++) {
        oled_write_pixel(x + i, y + 5, (font[c][i] & 0x20));
    }
    for (int i = 0; i < 5; i++) {
        oled_write_pixel(x + i, y + 6, (font[c][i] & 0x40));
    }
    for (int i = 0; i < 5; i++) {
        oled_write_pixel(x + i, y + 7, (font[c][i] & 0x80));
    }
}

// Function to write a pixel to the OLED display
void oled_write_pixel(int x, int y, int color) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) return;

    int page = y / 8;
    int bit = y % 8;

    char data[2];
    data[0] = 0x40; // Data command
    data[1] = 0x00; // Initial value

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, data, 1) < 0) {
        fprintf(stderr, "OLED pixel write error: %d\n", y);
        exit(1);
    }

    char buffer[1];
    buffer[0] = 0x00; // Initial value

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer, 1) < 0) {
        fprintf(stderr, "OLED pixel write error: %d\n", y);
        exit(1);
    }

    if (color) {
        buffer[0] = 0x01; // Set pixel to 1
    } else {
        buffer[0] = 0x00; // Set pixel to 0
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer, 1) < 0) {
        fprintf(stderr, "OLED pixel write error: %d\n", y);
        exit(1);
    }
}

