int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    oled_init();

    // Clear the display
    oled_clear();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        float temp = read_cpu_temp();
        float usage = read_cpu_usage();

        // Format the strings
        char temp_str[20];
        char usage_str[20];

        if (temp < 0) {
            strcpy(temp_str, "Temp: Error");
        } else {
            sprintf(temp_str, "Temp: %.1fC", temp);
        }

        if (usage < 0) {
            strcpy(usage_str, "Usage: Error");
        } else {
            sprintf(usage_str, "Usage: %.1f%%", usage);
        }

        // Write the strings to the display
        oled_write_string(0, 0, temp_str);
        oled_write_string(0, 8, usage_str);

        // Update the display
        oled_update();

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

