#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17 // BCM numbering
#define LCD_RS_PIN 25      // BCM numbering
#define LCD_EN_PIN 24      // BCM numbering
#define LCD_D4_PIN 23      // BCM numbering
#define LCD_D5_PIN 22      // BCM numbering
#define LCD_D6_PIN 21      // BCM numbering
#define LCD_D7_PIN 18      // BCM numbering

// Define LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Define scaling factor (pulses per liter)
#define PULSES_PER_LITER 450.0

// Global variables
volatile unsigned long pulse_count = 0;
volatile int running = 1;
int lcd_fd;

// Function prototypes
void pulse_counter_isr(void);
float calculate_flow_rate(unsigned long pulse_count, float time_interval);
void log_data(float flow_rate, float total_volume);
void update_lcd(float flow_rate, float total_volume);
void lcd_init(void);
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear(void);
void signal_handler(int signal);
void delay_ms(int delay_time);

// Interrupt service routine for pulse counting
void pulse_counter_isr(void) {
    pulse_count++;
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(unsigned long pulse_count, float time_interval) {
    return (float)pulse_count / PULSES_PER_LITER / (time_interval / 60.0);
}

// Function to log data to the console
void log_data(float flow_rate, float total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Flow Rate: %.2f LPM, Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
}

// Function to update LCD display
void update_lcd(float flow_rate, float total_volume) {
    char flow_str[17];
    char volume_str[17];
    char buffer[32];

    // Format flow rate string
    snprintf(flow_str, sizeof(flow_str), "Flow: %.2f LPM", flow_rate);

    // Format total volume string
    snprintf(volume_str, sizeof(volume_str), "Volume: %.2f L", total_volume);

    // Combine strings into a single buffer for display
    snprintf(buffer, sizeof(buffer), "%s\r\n%s", flow_str, volume_str);

    lcd_clear();
    lcd_string(buffer);
}

// LCD initialization function
void lcd_init(void) {
    // Initialise LCD
    delay_ms(50); // Wait for LCD to power up
    lcd_byte(0x33, 0); // Initialise
    lcd_byte(0x32, 0); // Initialise
    lcd_byte(0x06, 0); // Cursor move direction
    lcd_byte(0x0C, 0); // Turn on display, cursor off, blink off
    lcd_byte(0x28, 0); // Data length, number of lines, font size
    lcd_byte(0x01, 0); // Clear display
    delay_ms(500);
}

// Send byte to LCD
void lcd_byte(int bits, int mode) {
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command

    int bits_high = mode | (bits & 0xF0) | 0x08; // Enable bit set
    int bits_low = mode | ((bits << 4) & 0xF0) | 0x08; // Enable bit set

    // High bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high | 0x04); // Enable bit
    delay_ms(1); // Delay for enable pulse
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high & 0xFB); // Disable bit
    delay_ms(1);

    // Low bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low | 0x04); // Enable bit
    delay_ms(1); // Delay for enable pulse
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low & 0xFB); // Disable bit
    delay_ms(1);
}

// Send string to LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, 1);
    }
}

// Clear LCD display
void lcd_clear(void) {
    lcd_byte(0x01, 0); // Clear display command
    delay_ms(500);      // Delay for clear display
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
    running = 0;
    // Disable interrupt
    wiringPiISR(FLOW_SENSOR_PIN, INT_EDGE_RISING, NULL);

    // Clear LCD
    lcd_clear();

    // Close I2C connection
    close(lcd_fd);

    exit(0);
}

// Delay function using wiringPiI2C
void delay_ms(int delay_time) {
    delay(delay_time);
}

int main(void) {
    float flow_rate, total_volume;
    time_t start_time, current_time;
    float time_interval;
    unsigned long last_pulse_count;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C for LCD
    lcd_fd = wiringPiI2CSetup(0x27); // I2C address of LCD
    if (lcd_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up interrupt on rising edge
    if (wiringPiISR(FLOW_SENSOR_PIN, INT_EDGE_RISING, pulse_counter_isr) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize variables
    last_pulse_count = 0;
    total_volume = 0.0;
    time(&start_time);

    printf("Water Flow Monitoring System\n");

    while (running) {
        delay_ms(1000); // Wait for 1 second

        // Calculate time interval
        time(&current_time);
        time_interval = difftime(current_time, start_time);

        // Calculate flow rate
        flow_rate = calculate_flow_rate(pulse_count - last_pulse_count, time_interval);

        // Accumulate total volume
        total_volume += flow_rate * time_interval / 60.0; // LPM to L

        // Log data
        log_data(flow_rate, total_volume);

        // Update LCD
        update_lcd(flow_rate, total_volume);

        // Update last pulse count
        last_pulse_count = pulse_count;
    }

    return 0;
}

