    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high & 0xFB); // Disable bit
    delay_ms(1);

    // Low bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low | 0x04); // Enable bit
    delay_ms(1); // Delay for enable pulse
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low & 0xFB); // Disable bit
    delay_ms(1);
}

