    wiringPiISR(FLOW_SENSOR_PIN, INT_EDGE_RISING, NULL);

    // Clear LCD
    lcd_clear();

    // Close I2C connection
    close(lcd_fd);

    exit(0);
}

// Delay function using wiringPiI2C
void delay_ms(int delay_time) {
    delay(delay_time);
}

int main(void) {
