    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize variables
    last_pulse_count = 0;
    total_volume = 0.0;
    time(&start_time);

    printf("Water Flow Monitoring System\n");

    while (running) {
        delay_ms(1000); // Wait for 1 second

        // Calculate time interval
        time(&current_time);
        time_interval = difftime(current_time, start_time);

        // Calculate flow rate
        flow_rate = calculate_flow_rate(pulse_count - last_pulse_count, time_interval);

