#include <wiringPiSPI.h>
#include <wiringPiI2C.h>
#include <sys/time.h>

// Constants
#define ANEMOMETER_PIN 17 // BCM GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define LCD_CHR 1
#define LCD_CMD 0

#define LCD_BACKLIGHT 0x08  // On
#define LCD_ENABLE 0x04     // Enable bit
#define LCD_BACKLIGHT_OFF 0x00

// Global variables
volatile int pulse_count = 0;
int spi_fd = -1;
int lcd_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void anemometer_interrupt();
int read_mcp3008(int channel);
float calculate_wind_speed(int pulse_count, float time_interval);
float calculate_wind_direction(int adc_value);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void display_data(float wind_speed, float wind_direction);
void signal_handler(int signal);
int check_adc_calibration(int adc_value);

// Anemometer interrupt handler
void anemometer_interrupt() {
    pulse_count++;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "Error: SPI data transfer failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to calculate wind speed
float calculate_wind_speed(int pulse_count, float time_interval) {
    float frequency = (float)pulse_count / time_interval;
    float wind_speed = frequency * 4.44822; // m/s
    return wind_speed;
}

// Function to calculate wind direction
float calculate_wind_direction(int adc_value) {
    float direction = 0.0;
    if (adc_value > 0 && adc_value < 1023) {
        direction = (float)adc_value / 1023.0 * 360.0;
    } else {
        fprintf(stderr, "Error: ADC value out of range (0-1023): %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return direction;
}

// LCD initialization function
void lcd_init() {
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "Error: LCD I2C setup failed: %s\n", strerror(errno));
        return;
    }

    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // Turn on display, cursor off, blink off
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    delay(500);              // Wait for clear display to complete
}

// LCD byte transmission function
void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high);
    digitalWrite(0, HIGH);
    delayMicroseconds(1);
    digitalWrite(0, LOW);
    delayMicroseconds(500);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low);
    digitalWrite(0, HIGH);
    delayMicroseconds(1);
    digitalWrite(0, LOW);
}

// LCD string transmission function
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// LCD clear function
void lcd_clear() {
    lcd_byte(0x01, LCD_CMD);
    delay(500);
}

