void display_data(float wind_speed, float wind_direction) {
    char buffer[17];
    lcd_clear();

    snprintf(buffer, sizeof(buffer), "Speed: %.2f m/s", wind_speed);
    lcd_string(buffer);

    snprintf(buffer, sizeof(buffer), "Dir: %.2f deg", wind_direction);
    lcd_string(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (lcd_fd != -1) {
        // No direct SPI close function in wiringPi, but we can reset the device.
