int check_adc_calibration(int adc_value) {
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC value is at the extremes (0 or 1023). Check sensor calibration.\n");
        return 1; // Indicate calibration issue
    }
    return 0; // Indicate normal operation
}

int main() {
    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error: SPI setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LCD
    lcd_init();
    if (lcd_fd == -1) {
        fprintf(stderr, "Error: LCD initialization failed.\n");
        return 1;
    }

