    float time_interval;
    int adc_value;
    float wind_speed, wind_direction;

    printf("Wind monitoring system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        gettimeofday(&start_time, NULL);

        // Read wind direction from MCP3008
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Check for ADC calibration issues
        if (check_adc_calibration(adc_value)) {
            fprintf(stderr, "Warning: ADC calibration issue detected.\n");
        }

        // Calculate wind direction
        wind_direction = calculate_wind_direction(adc_value);
        if (wind_direction == -1.0) {
            fprintf(stderr, "Error: Failed to calculate wind direction.\n");
            continue; // Skip to the next iteration
        }

        // Calculate wind speed
        gettimeofday(&current_time, NULL);
        time_interval = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_usec - start_time.tv_usec) / 1000000.0;
        wind_speed = calculate_wind_speed(pulse_count, time_interval);
        pulse_count = 0; // Reset pulse count for the next interval

        // Display data on LCD
        display_data(wind_speed, wind_direction);

        // Wait for 500ms
        delay(500);
    }

    return 0;
}

