#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows (common anode)
#define ROW1 17
#define ROW2 18
#define ROW3 27
#define ROW4 22
#define ROW5 23
#define ROW6 24
#define ROW7 25
#define ROW8 4

// Define GPIO pins for columns (common cathode)
#define COL1 5
#define COL2 6
#define COL3 12
#define COL4 13
#define COL5 19
#define COL6 16
#define COL7 26
#define COL8 20

// Define the size of the LED matrix
#define MATRIX_SIZE 8

// Define the delay between row scans (in microseconds)
#define SCAN_DELAY 800

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set row pins as outputs
    gpioSetMode(ROW1, PI_OUTPUT);
    gpioSetMode(ROW2, PI_OUTPUT);
    gpioSetMode(ROW3, PI_OUTPUT);
    gpioSetMode(ROW4, PI_OUTPUT);
    gpioSetMode(ROW5, PI_OUTPUT);
    gpioSetMode(ROW6, PI_OUTPUT);
    gpioSetMode(ROW7, PI_OUTPUT);
    gpioSetMode(ROW8, PI_OUTPUT);

    // Set column pins as outputs
    gpioSetMode(COL1, PI_OUTPUT);
    gpioSetMode(COL2, PI_OUTPUT);
    gpioSetMode(COL3, PI_OUTPUT);
    gpioSetMode(COL4, PI_OUTPUT);
    gpioSetMode(COL5, PI_OUTPUT);
    gpioSetMode(COL6, PI_OUTPUT);
    gpioSetMode(COL7, PI_OUTPUT);
    gpioSetMode(COL8, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to clear the LED matrix
void clear_matrix()
{
    gpioWrite(ROW1, 1);
    gpioWrite(ROW2, 1);
    gpioWrite(ROW3, 1);
    gpioWrite(ROW4, 1);
    gpioWrite(ROW5, 1);
    gpioWrite(ROW6, 1);
    gpioWrite(ROW7, 1);
    gpioWrite(ROW8, 1);

    gpioWrite(COL1, 1);
    gpioWrite(COL2, 1);
    gpioWrite(COL3, 1);
    gpioWrite(COL4, 1);
    gpioWrite(COL5, 1);
    gpioWrite(COL6, 1);
    gpioWrite(COL7, 1);
    gpioWrite(COL8, 1);
}

// Function to set the LED at a specific row and column
void set_led(int row, int col)
{
    gpioWrite(ROW1 + row, 1); // Set row HIGH
    gpioWrite(COL1 + col, 0);  // Set column LOW
}

// Function to clear the LED at a specific row and column
void clear_led(int row, int col)
{
    gpioWrite(ROW1 + row, 1); // Set row HIGH
    gpioWrite(COL1 + col, 1); // Set column HIGH
}

// Function to perform a left-to-right wave animation
void left_to_right_wave()
{
    for (int i = 0; i < MATRIX_SIZE; i++)
    {
        for (int j = 0; j < MATRIX_SIZE; j++)
        {
            set_led(j, i);
            gpioDelay(SCAN_DELAY);
            clear_led(j, i);
        }
    }
}

// Function to perform a right-to-left wave animation
void right_to_left_wave()
{
    for (int i = 0; i < MATRIX_SIZE; i++)
    {
        for (int j = MATRIX_SIZE - 1; j >= 0; j--)
        {
            set_led(j, i);
            gpioDelay(SCAN_DELAY);
            clear_led(j, i);
        }
    }
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0)
    {
        return 1; // Exit if initialization fails
    }

    // Main loop
    while (!terminate)
    {
        // Clear the matrix
        clear_matrix();

        // Perform the left-to-right wave animation
        left_to_right_wave();

        // Perform the right-to-left wave animation
        right_to_left_wave();
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

