    gpioWrite(ROW6, 1);
    gpioWrite(ROW7, 1);
    gpioWrite(ROW8, 1);

    gpioWrite(COL1, 1);
    gpioWrite(COL2, 1);
    gpioWrite(COL3, 1);
    gpioWrite(COL4, 1);
    gpioWrite(COL5, 1);
    gpioWrite(COL6, 1);
    gpioWrite(COL7, 1);
    gpioWrite(COL8, 1);
}

// Function to set the LED at a specific row and column
void set_led(int row, int col)
{
    gpioWrite(ROW1 + row, 1); // Set row HIGH
    gpioWrite(COL1 + col, 0);  // Set column LOW
}

