{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0)
    {
        return 1; // Exit if initialization fails
    }

    // Main loop
    while (!terminate)
    {
        // Clear the matrix
        clear_matrix();

        // Perform the left-to-right wave animation
        left_to_right_wave();

        // Perform the right-to-left wave animation
        right_to_left_wave();
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

