#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75031_ADDR 0x4A

// Define the register addresses for the MLX75031
#define DISTANCE_HIGH_REG 0x00
#define DISTANCE_LOW_REG 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int sample_interval_ms;
} sensor_config_t;

// Function prototypes
int initialize_sensor(sensor_config_t *config);
int read_distance(int i2c_handle);
int log_data(FILE *log_file, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor(sensor_config_t *config) {
    i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int result;

    // Read high byte
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading high byte: %d\n", result);
        return -1;
    }

    // Read low byte
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_LOW_REG, buf + 1, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading low byte: %d\n", result);
        return -1;
    }

    // Combine the bytes into a 16-bit distance value
    int distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Function to log data to the CSV file
int log_data(FILE *log_file, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    sensor_config_t sensor_config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75031_ADDR,
        .sample_interval_ms = 100
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor(&sensor_config) != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("depth_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            if (initialize_sensor(&sensor_config) != 0) {
                fprintf(stderr, "Sensor re-initialization failed. Continuing with previous state.\n");
            }
        }
        gpioDelay(sensor_config.sample_interval_ms * 1000); // Delay in microseconds
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

