#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MIN_DISTANCE 2.0       // Minimum distance in cm
#define MAX_DISTANCE 400.0     // Maximum distance in cm
#define WATER_THRESHOLD 15.0    // Watering threshold in cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void trigger_pulse();
long echo_pulse_width();
double calculate_distance(long pulse_width);
void log_data(double distance, const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    double distance;
    char message[50];
} SensorData;

// Function to initialize the pigpio library and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1 ms

    return 0;
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long echo_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // 1 us delay
        count++;
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // 1 us delay
        count++;
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log data to a file
void log_data(double distance, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm, Message: %s\n", timestamp, distance, message);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize()) {
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_pulse();
        long pulse_width = echo_pulse_width();

        if (pulse_width < 0) {
            log_data(-1.0, "Timeout waiting for echo rise or echo pulse width");
            fprintf(stderr, "Timeout waiting for echo rise or echo pulse width\n");
        } else {
            double distance = calculate_distance(pulse_width);

            if (distance < 0) {
                log_data(-1.0, "Error calculating distance");
                fprintf(stderr, "Error calculating distance\n");
            } else {
                if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                    log_data(distance, "Distance out of range");
                    fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
                } else {
                    char message[50];
                    if (distance < WATER_THRESHOLD) {
                        strcpy(message, "Time to water the plant!");
                    } else {
                        strcpy(message, "OK");
                    }
                    log_data(distance, message);
                    printf("Distance: %.2f cm, %s\n", distance, message);
                }
            }
        }

        sleep(60); // Log data every 60 seconds
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

