#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_proximity();
int apds9960_read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t red, uint16_t green, uint16_t blue, int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    terminate = 1;
}

// APDS9960 initialization function
int apds9960_init() {
    // Enable proximity and color sensing
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to APDS9960_ENABLE register.\n");
        return -1;
    }

    // Set proximity wait time
    if (i2cWriteByteData(i2c_handle, APDS9960_PTIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to APDS9960_PTIME register.\n");
        return -1;
    }

    // Set proximity pulse length
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to APDS9960_PPULSE register.\n");
        return -1;
    }

    // Set control register (gain, integration time)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to APDS9960_CONTROL register.\n");
        return -1;
    }

    // Set configuration register (gain, integration time)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG1, 0x60) < 0) {
        fprintf(stderr, "Error writing to APDS9960_CONFIG1 register.\n");
        return -1;
    }

    return 0;
}

// Function to read proximity value
int apds9960_read_proximity() {
    int proximity = i2cReadByteData(i2c_handle, APDS9960_PDATA);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity value.\n");
        return -1;
    }
    return proximity;
}

// Function to read RGB values
int apds9960_read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[6];

    if (i2cReadI2CBlockData(i2c_handle, APDS9960_RDATAL, (char *)data, 6) < 0) {
        fprintf(stderr, "Error reading RGB values.\n");
