void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    uint8_t led_drive_strength;
    uint8_t measurement_mode;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read proximity data from the sensor
int read_proximity() {
    int proximity_value = i2cReadByteData(i2c_handle, PROX_DATA_REG);
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", proximity_value);
        return -1;
    }
    return proximity_value;
}

// Function to calculate BPM from proximity value
float calculate_bpm(int proximity_value) {
    // Simple linear mapping for demonstration purposes
    // Adjust the formula based on the Si1182-A-GMR datasheet
    return (float)proximity_value * 0.5; // Example: 0-255 -> 0-127.5 BPM
}

// Function to write data to CSV file
int write_to_csv(const char *timestamp, float bpm) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, bpm);
    fflush(fp);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read proximity data
        int proximity_value = read_proximity();
        if (proximity_value < 0) {
            // Error already printed to stderr
            continue; // Skip to the next iteration
        }

        // Calculate BPM
        float bpm = calculate_bpm(proximity_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ\0

        time(&rawtime);
        timeinfo = gmtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Write to CSV file
        if (write_to_csv(timestamp, bpm) != 0) {
            fprintf(stderr, "Error writing to CSV file!\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

