// VL53L0X Registers
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L0X_REG_SYSRANGE_START 0x0040
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_SPAD_NB 0x0022
#define VL53L0X_REG_RESULT_SIGNAL_RATE 0x001E
#define VL53L0X_REG_RESULT_AMBIENT_RATE 0x0020
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l0x_init();
int vl53l0x_read_distance(int *distance);
void log_distance(int distance);
void signal_handler(int signal);
int check_sensor_presence();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Check sensor presence
int check_sensor_presence() {
    int model_id, revision_id;

    model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return 0;
    }

    revision_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_REVISION_ID);
    if (revision_id < 0) {
        fprintf(stderr, "Error reading revision ID: %s\n", strerror(errno));
        return 0;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return 0;
    }

    printf("VL53L0X sensor found (Model ID: 0x%02X, Revision ID: 0x%02X)\n", model_id, revision_id);
    return 1;
}

