#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x70
#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define SAMPLE_INTERVAL_MS 200
#define TRIGGER_PULSE_US 10
#define MAX_DISTANCE_MM 4000 // Maximum measurable distance in mm

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int trigger_pulse_us;
} sensor_config_t;

// Function prototypes
int initialize_sensor(sensor_config_t *config);
int trigger_sensor(int i2c_handle);
int read_distance(int i2c_handle);
void log_distance(FILE *fp, int distance_mm);
void print_distance(int distance_mm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the CH101 sensor
int initialize_sensor(sensor_config_t *config) {
    int status;

    // Check if pigpio is initialized
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Verify I2C open
    status = i2cReadByteData(i2c_handle, 0x00); // Read from any register to verify
    if (status < 0) {
        fprintf(stderr, "Error verifying I2C open: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    printf("Sensor initialized successfully\n");
    return 0;
}

// Trigger the ultrasonic sensor
int trigger_sensor(int i2c_handle) {
    int status;

    status = i2cWriteByteData(i2c_handle, TRIGGER_REG, 0x00); // Send trigger pulse
    if (status < 0) {
        fprintf(stderr, "Error triggering sensor: %d\n", status);
        return -1;
    }

    gpioDelay(TRIGGER_PULSE_US); // Wait for trigger pulse

    return 0;
}

// Read the distance from the ultrasonic sensor
int read_distance(int i2c_handle) {
    int distance;
    int status;

    status = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }

    distance = status; // Distance is returned in mm
    return distance;
}

// Log the distance to a file
void log_distance(FILE *fp, int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d\n", timestamp, distance_mm);
    fflush(fp); // Ensure data is written to file immediately
}

// Print the distance to stdout
void print_distance(int distance_mm) {
    printf("%d\n", distance_mm);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    sensor_config_t sensor_config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = CH101_ADDR,
        .trigger_pulse_us = TRIGGER_PULSE_US
    };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor(&sensor_config) != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance_mm;

        // Trigger the sensor
        if (trigger_sensor(i2c_handle) != 0) {
            fprintf(stderr, "Error triggering sensor, skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for next sample
            continue;
        }

        // Wait for a short period to allow the sensor to measure the distance
        gpioDelay(50 * 1000); // 50ms

        // Read the distance
        distance_mm = read_distance(i2c_handle);
        if (distance_mm < 0) {
            fprintf(stderr, "Error reading distance, skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for next sample
            continue;
        }

        // Validate the distance reading
        if (distance_mm < 0 || distance_mm > MAX_DISTANCE_MM) {
            fprintf(stderr, "Invalid distance reading: %d mm. Skipping sample.\n", distance_mm);
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for next sample
            continue;
        }

        // Log the distance
        log_distance(log_file, distance_mm);

        // Print the distance
        print_distance(distance_mm);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

