// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int icu20201_address;
    int led_pin;
    float distance_threshold;
    int sample_interval_ms;
} config_t;

config_t config = {
    I2C_BUS,
    ICU20201_ADDR,
    LED_GPIO,
    DISTANCE_THRESHOLD,
    SAMPLE_INTERVAL_MS
};

