    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    // Convert raw data to distance (cm) - Example conversion, adjust as needed
    int raw_distance = (buf[0] << 8) | buf[1];
    float distance_cm = (float)raw_distance / 10.0; // Example scaling

    return (int)distance_cm;
}

