#include <string.h>
#include <unistd.h>

// Define the I2C address of the Si1182-GMR sensor
#define SI1182_I2C_ADDR 0x60

// Define register addresses (replace with actual values from datasheet)
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x10
#define REG_PS1_DATA0 0x18
#define REG_COMMAND 0x30

// Define commands (replace with actual values from datasheet)
#define CMD_ALS_FORCE 0x01
#define CMD_PS_FORCE 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t ambient_light;
    uint16_t proximity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
sensor_data_t read_sensor_data();
char* format_log_entry(sensor_data_t data);
int write_to_log(char *log_entry);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SI1182_I2C_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the Si1182-GMR sensor
int init_sensor() {
    // Example initialization sequence (replace with actual values from datasheet)
    // This is a placeholder, refer to the Si1182-GMR datasheet for the correct initialization sequence
    char init_data[] = {0x01, 0x00}; // Example: Reset command
    int result = i2cWriteDevice(i2c_handle, init_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Small delay after initialization

    // Enable ALS and PS (replace with actual register and values)
    char enable_data[] = {REG_COMMAND, CMD_ALS_FORCE | CMD_PS_FORCE}; // Example: Enable ALS and PS
    result = i2cWriteDevice(i2c_handle, enable_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }

    return 0;
}

// Read sensor data from the Si1182-GMR sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char read_buffer[4]; // Buffer to hold ALS and proximity data

    // Read ALS data (2 bytes)
    int result = i2cReadDevice(i2c_handle, read_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        data.ambient_light = 0; // Set to default value in case of error
    } else {
        data.ambient_light = (read_buffer[1] << 8) | read_buffer[0];
    }

    // Read Proximity data (2 bytes)
    result = i2cReadDevice(i2c_handle, read_buffer + 2, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        data.proximity = 0; // Set to default value in case of error
    } else {
        data.proximity = (read_buffer[3] << 8) | read_buffer[2];
    }

    return data;
}

// Format the sensor data and timestamp into a log entry
char* format_log_entry(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char log_entry[100]; // Static to preserve across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, Ambient Light: %u, Proximity: %u\n",
             timestamp, data.ambient_light, data.proximity);

    return log_entry;
}

// Write the log entry to the file
int write_to_log(char *log_entry) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fputs(log_entry, log_file) == EOF) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Format the log entry
        char *log_entry = format_log_entry(sensor_data);

        // Write to the log file
        if (write_to_log(log_entry) != 0) {
            fprintf(stderr, "Error writing to log, but continuing...\n");
        }

        // Wait for 500ms
        gpioDelay(500);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

