    int result = i2cReadDevice(i2c_handle, read_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        data.ambient_light = 0; // Set to default value in case of error
    } else {
        data.ambient_light = (read_buffer[1] << 8) | read_buffer[0];
    }

    // Read Proximity data (2 bytes)
    result = i2cReadDevice(i2c_handle, read_buffer + 2, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        data.proximity = 0; // Set to default value in case of error
    } else {
        data.proximity = (read_buffer[3] << 8) | read_buffer[2];
