#define DISTANCE_HIGH_REG 0x01
#define DISTANCE_LOW_REG 0x02
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm

// Global variables
int i2c_handle;
int threshold = DEFAULT_THRESHOLD;
FILE *log_file;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void control_led(int distance);
void log_data(int distance);
void signal_handler(int signal);
