int initialize_sensor() {
    int who_am_i;

    // Verify WHO_AM_I register
    if (verify_who_am_i() != 0) {
        fprintf(stderr, "Error: WHO_AM_I verification failed.\n");
        return -1;
    }

    // Configure the sensor (example: set operating mode)
