        return -1;
    }

    return 0;
}

// Reads the distance from the ICU-20201 sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (read %d bytes): %d\n", result, result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

