        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Control LED
            control_led(distance);

            // Log data
            log_data(distance);

            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        // Wait for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

