#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define MEASURE_COMMAND 0x01
#define MEASUREMENT_SIZE 15
#define INTRUSION_THRESHOLD 1000 // mm
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for command frame (example, adjust based on datasheet)
typedef struct {
    uint8_t command;
    uint8_t data[3]; // Example: 3 bytes of data for the command
} command_frame_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint8_t command);
int read_response(int handle, uint8_t *buffer, int size);
int parse_distance(uint8_t *buffer);
float calculate_average_distance(int distances[], int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint8_t command) {
    uint8_t buffer[1];
    buffer[0] = command;
    int result = i2cWriteDevice(handle, buffer, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read a response from the sensor
int read_response(int handle, uint8_t *buffer, int size) {
    int result = i2cReadDevice(handle, buffer, size);
    if (result != size) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Parse the distance from the response buffer
int parse_distance(uint8_t *buffer) {
    if (buffer == NULL) return -1;
    // Assuming distance is in bytes 11 and 12 (big-endian)
    int distance = (buffer[11] << 8) | buffer[12];
    return distance;
}

// Calculate the average distance
float calculate_average_distance(int distances[], int num_samples) {
    if (num_samples == 0) return 0.0;
    long sum = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return (float)sum / num_samples;
}

// Log intrusion event to file
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t response_buffer[MEASUREMENT_SIZE];
    int distances[10];
    int distance_index = 0;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_COMMAND) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (adjust delay as needed)
        gpioDelay(10); // 10 ms delay

        // Read measurement response
        if (read_response(i2c_handle, response_buffer, MEASUREMENT_SIZE) != 0) {
            fprintf(stderr, "Error reading measurement response, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Parse distance
        int distance = parse_distance(response_buffer);
        if (distance < 0) {
            fprintf(stderr, "Error parsing distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        distances[distance_index] = distance;
        distance_index = (distance_index + 1) % 10;

        // Calculate average distance
        float average_distance = calculate_average_distance(distances, 10);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion event.\n");
            }
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

