    int proximity_data = -1; // Initialize to an error value
    int result;

    // Read the proximity data registers
    result = i2cReadWordData(i2c_handle, SI1182_REG_ALS_VIS_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0 register: %d\n", result);
        return -1; // Indicate an error
    }
    int low_byte = result & 0xFF;
    int high_byte = (result >> 8) & 0xFF;

    proximity_data = (high_byte << 8) | low_byte;

