// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read the distance from the MLX75030 sensor
int read_distance(int fd) {
    uint8_t data[2]; // Assuming 2 bytes for distance
    int result;

    // Write the register address to be read
    result = write(fd, &DISTANCE_REG, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read the distance data
    result = read(fd, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t distance = (data[0] << 8) | data[1];

    return distance;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device file
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify that the sensor is present by reading a register (optional)
    uint8_t test_reg = 0x00; // Example register to test
    uint8_t test_data;
    int result = write(i2c_fd, &test_reg, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device during verification: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    result = read(i2c_fd, &test_data, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from I2C device during verification: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

