#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000       // 200 ms timeout in microseconds
#define MAX_DISTANCE 400.0      // Maximum measurable distance in cm

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to measure the echo pulse duration
long measurePulse() {
    long start_tick, end_tick, pulse_duration;

    // Wait for echo pin to go HIGH with timeout
    long timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout (rising edge).\n");
            return -1; // Timeout error
        }
    }
    start_tick = gpioTick();

    // Wait for echo pin to go LOW with timeout
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout (falling edge).\n");
            return -1; // Timeout error
        }
    }
    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration <= 0) {
        fprintf(stderr, "Error: Invalid pulse duration: %ld\n", pulse_duration);
        return -1.0; // Indicate an error
    }

    float distance = (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
    return distance;
}

// Function to log the distance with a timestamp
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor reading started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_duration = measurePulse();

        if (pulse_duration > 0) {
            float distance = calculateDistance(pulse_duration);

            if (distance > 0 && distance <= MAX_DISTANCE) {
                logDistance(distance);
            } else {
                fprintf(stderr, "Error: Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Error: Failed to measure pulse duration.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

