#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define TARGET_DISTANCE_THRESHOLD 1.0 // meters
#define ALERT_LED_GPIO 17
#define ALERT_DURATION_MS 2000

// Global variables
int uart_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_uart();
int read_uart_data(unsigned char *buffer, int buffer_size);
int decode_range_profile(unsigned char *buffer, int buffer_size, int *range_profile);
int detect_target(int *range_profile, int range_profile_size, float distance_threshold);
int log_intrusion(const char *timestamp, float distance);
int activate_alert();
void signal_handler(int signal);

