int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the UART
int read_uart_data(unsigned char *buffer, int buffer_size) {
    int bytes_read = serRead(uart_handle, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Function to decode the range profile
int decode_range_profile(unsigned char *buffer, int buffer_size, int *range_profile) {
    if (buffer_size < MAGIC_WORD_SIZE + RANGE_PROFILE_SIZE) {
        fprintf(stderr, "Incomplete data received\n");
        return -1;
    }

    // Check for magic word
    unsigned char magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(buffer, magic_word, MAGIC_WORD_SIZE) != 0) {
        fprintf(stderr, "Invalid magic word\n");
        return -1;
    }

    // Convert raw data to range profile
    for (int i = 0; i < RANGE_PROFILE_SIZE / 2; i++) {
        range_profile[i] = (buffer[MAGIC_WORD_SIZE + 2 * i + 1] << 8) | buffer[MAGIC_WORD_SIZE + 2 * i];
    }

    return 0;
}

