    gpioWrite(ALERT_LED_GPIO, 1); // Turn LED on
    gpioDelay(ALERT_DURATION_MS);  // Wait for 2 seconds
    gpioWrite(ALERT_LED_GPIO, 0); // Turn LED off
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the alert LED
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);

    // Initialize UART
    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char buffer[RANGE_PROFILE_SIZE + MAGIC_WORD_SIZE];
    int range_profile[RANGE_PROFILE_SIZE / 2];

    printf("Starting intrusion detection...\n");

    while (program_running) {
        // Read data from UART
        int bytes_read = read_uart_data(buffer, sizeof(buffer));
        if (bytes_read > 0) {
            // Decode range profile
            if (decode_range_profile(buffer, bytes_read, range_profile) == 0) {
                // Detect target
                if (detect_target(range_profile, RANGE_PROFILE_SIZE, TARGET_DISTANCE_THRESHOLD)) {
                    // Get current timestamp
                    time_t rawtime;
                    struct tm *timeinfo;
                    char timestamp[20];

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

                    // Log intrusion
                    if (log_intrusion(timestamp, (float)range_profile[0] / 100.0) != 0) {
                        fprintf(stderr, "Error logging intrusion\n");
                    }

                    // Activate alert
                    activate_alert();
                }
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    printf("Cleaning up...\n");
    serClose(uart_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

