#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x41
#define DISTANCE_REG 0x00
#define LED_GPIO 18
#define BLINK_FREQUENCY_MIN 100  // Hz
#define BLINK_FREQUENCY_MAX 1000 // Hz
#define BLINK_FREQUENCY_RANGE (BLINK_FREQUENCY_MAX - BLINK_FREQUENCY_MIN)
#define MAX_DISTANCE 100.0       // cm
#define MIN_DISTANCE 1.0        // cm
#define MAX_DISTANCE_RAW 65535.0 // Raw value for MAX_DISTANCE
#define MIN_DISTANCE_RAW 0.0     // Raw value for MIN_DISTANCE
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance();
float calculate_distance(uint16_t raw_distance);
void set_led_frequency(float distance);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ch201_address;
    int led_pin;
    float min_frequency;
    float max_frequency;
    float distance_range;
    float max_distance_raw;
    float min_distance_raw;
    int i2c_retry_count;
    int i2c_retry_delay_ms;
} config_t;

config_t config = {
    I2C_BUS,
    CH201_ADDR,
    LED_GPIO,
    BLINK_FREQUENCY_MIN,
    BLINK_FREQUENCY_MAX,
    BLINK_FREQUENCY_RANGE,
    MAX_DISTANCE_RAW,
    MIN_DISTANCE_RAW,
    I2C_RETRY_COUNT,
    I2C_RETRY_DELAY_MS
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        int raw_distance = read_distance();
        if (raw_distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate distance in cm
        float distance = calculate_distance((uint16_t)raw_distance);

        // Set LED frequency
        set_led_frequency(distance);

        // Get current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Log data
        printf("%ld,%.2f\n", timestamp_ms, distance);

        // Delay
        gpioDelay(100); // 100ms
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ch201_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201
int read_distance() {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < config.i2c_retry_count) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            return (buf[0] << 8) | buf[1]; // Combine high and low bytes
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(config.i2c_retry_delay_ms);
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", config.i2c_retry_count);
    return -1; // Indicate failure
}

// Calculate distance in cm
float calculate_distance(uint16_t raw_distance) {
    // Linear interpolation
    float distance = config.distance_range * (raw_distance - config.min_distance_raw) / (config.max_distance_raw - config.min_distance_raw) + config.min_distance;
    return distance;
}

// Set LED frequency based on distance
void set_led_frequency(float distance) {
    // Map distance to frequency range
    float frequency = config.min_frequency + (config.max_frequency - config.min_frequency) * (distance - config.min_distance) / (config.max_distance - config.min_distance);

    // Set PWM frequency (pigpio uses Hz)
    gpioSetPWMfrequency(config.led_pin, (int)frequency);

    // Set PWM range (0-255)
    gpioSetPWMrange(config.led_pin, 255);

    // Set PWM duty cycle (50% for on/off)
    gpioPWM(config.led_pin, 128); // 128 out of 255
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    // Turn off LED
    gpioWrite(config.led_pin, 0);

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();
}

