    while (!terminate) {
        // Trigger measurement
        if (write_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before retrying
            continue;
        }

        // Wait for measurement to complete (adjust as needed)
        gpioDelay(1000); // 1ms delay

        // Read distance
        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Failed to read distance, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before retrying
            continue;
        }

        // Log data
        if (log_data(log_file, distance) != 0) {
            fprintf(stderr, "Failed to log data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

