// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file name
#define LOG_FILE "proximity_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio);
void debounce(int gpio);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Function to read the sensor value with retry logic
int read_sensor(int gpio) {
    int value = -1; // Initialize to an invalid value
    int retries = 3;
    while (retries > 0) {
        value = gpioRead(gpio);
        if (value >= 0) { // Check if gpioRead was successful
            return value;
        } else {
            fprintf(stderr, "Error reading GPIO %d, retrying...\n", gpio);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read GPIO %d after multiple retries.\n", gpio);
    return -1; // Indicate failure
}

// Function to implement software debounce
void debounce(int gpio) {
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
}

// Function to log events to a file
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate(); // Clean up pigpio before exiting
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor1_state = -1; // Initialize to an invalid state
    int sensor2_state = -1;

    // Main loop
    while (program_running) {
        // Read sensor 1
        int new_sensor1_value = read_sensor(SENSOR_1_GPIO);
        if (new_sensor1_value != -1) {
            if (new_sensor1_value != sensor1_state) {
                if (new_sensor1_value == 0) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
                sensor1_state = new_sensor1_value;
            }
        }

        // Read sensor 2
        int new_sensor2_value = read_sensor(SENSOR_2_GPIO);
        if (new_sensor2_value != -1) {
            if (new_sensor2_value != sensor2_state) {
                if (new_sensor2_value == 0) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
                sensor2_state = new_sensor2_value;
            }
        }

        // Debounce sensors
        debounce(SENSOR_1_GPIO);
        debounce(SENSOR_2_GPIO);

        gpioDelay(10000); // Delay for 10ms
    }

    // Clean up resources before exiting
    fclose(log_file);
    gpioTerminate();

    return 0;
}

