#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x50

// Define the MEAS_STATUS register address
#define MEAS_STATUS_REG 0x00

// Define the distance register address
#define DISTANCE_REG 0x02

// Define the distance data length
#define DISTANCE_DATA_LENGTH 2

// Define the CSV file name
#define CSV_FILE "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance_mm;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int open_i2c_device(int bus, int address);
int read_sensor_data(int fd, int reg, unsigned char *data, int length);
int write_sensor_data(int fd, int reg, unsigned char *data, int length);
int get_distance_mm(int fd);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);
void close_resources();

// Function to open the I2C device
int open_i2c_device(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s (errno: %d)\n", filename, errno);
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: 0x%02x (errno: %d)\n", address, errno);
        close(fd);
        return -1;
    }
    return fd;
}

// Function to read data from the sensor
int read_sensor_data(int fd, int reg, unsigned char *data, int length) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: errno: %d\n", errno);
        return -1;
    }
    if (read(fd, data, length) != length) {
        fprintf(stderr, "Error reading data: errno: %d\n", errno);
        return -1;
    }
    return 0;
}

// Function to write data to the sensor
int write_sensor_data(int fd, int reg, unsigned char *data, int length) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for write: errno: %d\n", errno);
        return -1;
    }
    if (write(fd, data, length) != length) {
        fprintf(stderr, "Error writing data: errno: %d\n", errno);
        return -1;
    }
    return 0;
}

// Function to get the distance in millimeters
int get_distance_mm(int fd) {
    unsigned char data[2];
    if (read_sensor_data(fd, DISTANCE_REG, data, DISTANCE_DATA_LENGTH) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Function to log the data to a CSV file
int log_data(FILE *fp, sensor_data_t data) {
    if (fprintf(fp, "%s,%d\n", data.timestamp, data.distance_mm) < 0) {
        fprintf(stderr, "Error writing to CSV file: errno: %d\n", errno);
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Function to close resources
