// Global variables for I2C handle and program state
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int retry_count;
    int delay_ms;
} sensor_config_t;

// Function prototypes
int initialize_i2c(int bus, int address);
int read_distance(int handle, uint16_t *distance);
void log_data(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

