int read_distance(int handle, uint16_t *distance) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

