void log_data(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    printf("Timestamp: %ld ms, Distance: %u mm\n", timestamp_ms, distance);
}

// Function to cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        printf("I2C bus closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

