    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, MLX75030_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    uint16_t distance;
    sensor_config_t config = {I2C_BUS, MLX75030_ADDR, 3, 10};

    // Main loop
    while (program_running) {
        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

