#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L4CX_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L4CX_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0024
#define VL53L4CX_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0082
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    uint8_t pre_range_min_snr;
    uint8_t final_range_min_count_rate;
} sensor_config_t;

// Function prototypes
int init_sensor();
int read_distance(int *distance);
void log_data(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Initialize the VL53L4CX sensor
int init_sensor() {
    // Example initialization sequence (refer to datasheet for complete sequence)
    // This is a simplified example and may need adjustments based on your specific setup
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_SYSTEM_SEQUENCE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error writing to system sequence config register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); // Delay for 1ms

    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x07) < 0) {
        fprintf(stderr, "Error writing to pre-range min SNR register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN, 0x0A) < 0) {
        fprintf(stderr, "Error writing to final range min count rate register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    return 0;
}

// Read distance from the VL53L4CX sensor
int read_distance(int *distance) {
    uint8_t range_status;
    uint8_t data[2];

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt: %s\n", strerror(errno));
        return -1;
    }

    // Read range status
    range_status = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status: %s\n", strerror(errno));
        return -1;
    }

    // Read distance data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2) < 0) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Log distance data with timestamp
void log_data(int distance) {
    struct timespec ts;
    char timestamp[30];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return;
    }

    // Format timestamp
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(500000); // 500ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

