#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define TIMEOUT_US 50000 // 50ms timeout
#define MIN_DISTANCE 2.0  // Minimum distance in cm
#define MAX_DISTANCE 400.0 // Maximum distance in cm
#define MIN_ANGLE -90.0   // Minimum servo angle
#define MAX_ANGLE 90.0    // Maximum servo angle

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulseWidth);
float mapDistanceToAngle(float distance);
void setServoAngle(float angle);
void logData(float distance, float angle);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    long startTime = gpioTick();

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        if (gpioTick() - startTime > timeout) {
            return -1; // Timeout
        }
    }

    long pulseStart = gpioTick();

    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        if (gpioTick() - pulseStart > timeout) {
            return -1; // Timeout
        }
    }

    long pulseEnd = gpioTick();
    width = pulseEnd - pulseStart;

    return width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Error code for timeout
    }
    return (float)pulseWidth / 2.0 / 29.1;
}

// Function to map the distance to a servo angle
float mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    }
}

// Function to set the servo angle
void setServoAngle(float angle) {
    int pulseWidth = (int)(angle / 180.0 * 2000 + 500); // Map angle to pulse width (500-2500)
    gpioServo(SERVO_PIN, pulseWidth);
}

// Function to log the data to a file
void logData(float distance, float angle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        triggerSensor();
        long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);
            if (distance > 0) {
                float angle = mapDistanceToAngle(distance);
                setServoAngle(angle);
                logData(distance, angle);
            } else {
                fprintf(stderr, "Error: Invalid distance reading.\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor timeout.\n");
        }

        gpioDelay(200); // 200ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioServo(SERVO_PIN, 0); // Stop servo
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

