#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/msg.h>
#include <pigpio.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_KEY 1234
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Message structure for the message queue
typedef struct {
    long mtype; // Message type (must be > 0)
    int distance; // Measured distance in mm
} message_t;

// Global variables
int i2c_handle;
int message_queue_id;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_message_queue();
int read_distance();
void activate_buzzer(int activate);
void log_distance(int distance);
void cleanup();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to initialize the message queue
int init_message_queue() {
    message_queue_id = msgget(MESSAGE_QUEUE_KEY, IPC_CREAT | 0666);
    if (message_queue_id < 0) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read distance from VL53L1X sensor
int read_distance() {
    int distance = -1;
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        // Read status register
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY);
        if (status < 0) {
            fprintf(stderr, "Error reading status register: %s\n", strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Check if data is ready
        if ((status & 0x01) == 0) {
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Read distance data
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Basic data validation
        if (distance < 0 || distance > 2000) {
            fprintf(stderr, "Invalid distance reading: %d\n", distance);
            distance = -1; // Indicate error
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        return distance;
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1;
}

// Function to activate/deactivate the buzzer
void activate_buzzer(int activate) {
    gpioWrite(BUZZER_GPIO, activate);
}

// Function to log distance to the message queue
void log_distance(int distance) {
    message_t message;
    message.mtype = 1; // Message type (arbitrary)
    message.distance = distance;

    if (msgsnd(message_queue_id, &message, sizeof(message.distance), 0) == -1) {
        fprintf(stderr, "Error sending message to queue: %s\n", strerror(errno));
    }
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (message_queue_id >= 0) {
        msgctl(message_queue_id, IPC_RMID, NULL);
    }
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Terminating program.\n");
        terminate = 1;
        cleanup();
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize message queue
    if (init_message_queue() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance();

        if (distance >= 0) {
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer(1); // Activate buzzer
            } else {
                activate_buzzer(0); // Deactivate buzzer
            }
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(50 * 1000); // Delay for 50ms (50000 microseconds)
    }

    return 0;
}

