#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)
#define BUZZER_ON_DISTANCE 30.0 // Distance in cm to turn buzzer on
#define BUZZER_OFF_DISTANCE 30.0 // Distance in cm to turn buzzer off

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;
volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width_us);
void control_buzzer(float distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0) {
        if (echo_received) {
            end_tick = tick;
            echo_received = 0; // Reset the flag after reading the pulse width
        } else {
            timeout_flag = 1; // Timeout occurred
        }
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width_us) {
    if (pulse_width_us == 0) {
        return -1.0; // Indicate invalid reading
    }
    return (float)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Distance in cm
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance < BUZZER_ON_DISTANCE) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    } else if (distance >= BUZZER_OFF_DISTANCE) {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt callback function
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo
        gpioDelay(10000); // Wait 10ms for echo

        // Calculate pulse width
        unsigned int pulse_width_us = 0;
        if (timeout_flag) {
            printf("Timeout: No echo received.\n");
            timeout_flag = 0; // Reset the flag
        } else {
            if (end_tick >= start_tick) {
                pulse_width_us = end_tick - start_tick;
            } else {
                pulse_width_us = (0xFFFFFFFF - start_tick) + end_tick; // Handle tick wraparound
            }
        }

        // Calculate distance
        float distance = calculate_distance(pulse_width_us);

        // Control buzzer
        control_buzzer(distance);

        // Print distance
        if (distance > 0 && distance <= 400) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Invalid reading: %.2f cm\n", distance);
        }

        gpioDelay(100000); // Wait 100ms
    }

    return 0;
}

