#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define DISTANCE_THRESHOLD 200 // 20cm in mm
#define OPEN_ANGLE 180
#define CLOSE_ANGLE 0
#define PWM_FREQUENCY 50 // Hz
#define PWM_RANGE 2000
#define SERVER_PORT 12345
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
int server_socket;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void handle_remote_command(const char *command);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        log_event("I2C write error");
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *data) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        log_event("I2C write (reg addr) error");
        return -1;
    }
    if (i2cReadDevice(handle, data, 1) != 1) {
        log_event("I2C read error");
        return -1;
    }
    return 0;
}

// Function to write a word (2 bytes) to a VL53L1X register
int vl53l1x_write_word(int handle, uint8_t reg, uint16_t data) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (data >> 8) & 0xFF; // MSB
    buf[2] = data & 0xFF;        // LSB
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        log_event("I2C write (word) error");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint8_t reg, uint16_t *data) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        log_event("I2C write (reg addr) error");
        return -1;
    }
    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        log_event("I2C read error");
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize PWM for servo control
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create server socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        cleanup();
        return 1;
    }

    listen(server_socket, 3); // Listen for incoming connections

    printf("Server listening on port %d\n", SERVER_PORT);

    while (program_running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        char buffer[1024];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            printf("Received command: %s\n", buffer);
            handle_remote_command(buffer);
        } else if (bytes_received == 0) {
            printf("Client disconnected\n");
        } else {
            perror("Error receiving data");
        }

        close(client_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int init_vl53l1x() {
    // Reset the sensor
    if (vl53l1x_write_byte(i2c_handle, 0x0000, 0x01) != 0) return -1;
    gpioDelay(10000); // Wait 10ms

    // Check sensor ID
    uint8_t sensor_id;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id) != 0) return -1;
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Configure sensor for short-range mode
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x40) != 0) return -1; // Enable only short range

    // Set timeout values
    if (vl53l1x_write_word(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00FF) != 0) return -1;
    if (vl53l1x_write_word(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00FF) != 0) return -1;

    return 0;
}

int read_distance() {
    uint16_t distance;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) == 0) {
            return distance;
        } else {
            log_event("VL53L1X read failed, retrying...");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    log_event("VL53L1X read failed after multiple retries");
    return -1; // Indicate error
}

void open_gate() {
    gpioPWM(SERVO_GPIO, OPEN_ANGLE * PWM_RANGE / 180); // Convert angle to PWM value
    log_event("Gate opened");
}

void close_gate() {
    gpioPWM(SERVO_GPIO, CLOSE_ANGLE * PWM_RANGE / 180); // Convert angle to PWM value
    log_event("Gate closed");
}

void handle_remote_command(const char *command) {
    if (strcmp(command, "force_open") == 0) {
        open_gate();
    } else if (strcmp(command, "force_close") == 0) {
        close_gate();
    } else if (strcmp(command, "status_request") == 0) {
        // Implement status request and send response
        // For example, read the distance and send it back
        int distance = read_distance();
        if (distance > 0) {
            char response[50];
            snprintf(response, sizeof(response), "Distance: %d mm", distance);
            // In a real distributed system, you would send this response to the server
            printf("Sending status: %s\n", response);
            // For this example, we just log it
            log_event(response);
        } else {
            log_event("Status request failed");
        }
    } else {
        log_event("Invalid command");
    }
}

void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the log is written immediately
}

void signal_handler(int signal) {
    printf("Signal received, exiting...\n");
    program_running = 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_socket > 0) {
        close(server_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

