#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_CLOSE 50 // cm
#define DISTANCE_THRESHOLD_OPEN 60   // cm
#define SERVO_OPEN_PULSE_WIDTH 2000 // us
#define SERVO_CLOSED_PULSE_WIDTH 1000 // us
#define LOG_FILE "parking_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void servo_set_position(int pulse_width);
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, int *data) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *data = buf[0];
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int reg, int *data) {
    char buf[2];
    buf[0] = reg;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *data = (buf[0] << 8) | buf[1];
    return 0;
}

