    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;

    // Start ranging
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x40) != 0) return -1; // Example: Start continuous ranging

    return 0;
}

// Function to read the distance from the VL53L1X sensor
