    uint16_t distance;
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        return -1;
    }
    return (int)distance;
}

// Function to control the gate based on the distance
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_18, 1); // Open gate
        gpioWrite(GPIO_19, 0); // Close gate
        log_event("Gate opened");
    } else {
        gpioWrite(GPIO_18, 0); // Close gate
        gpioWrite(GPIO_19, 1); // Open gate
        log_event("Gate closed");
