// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to read a single byte from an I2C register with retry and exponential backoff
int i2c_read_reg(int handle, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int delay_ms = 1;
    int result;

    while (retries < 5) {
        result = i2cReadI2CBlockData(handle, reg, (char *)data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, len %d, retries %d): %d\n", reg, len, retries, result);
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, len %d)\n", reg, len);
    return -1; // Failure
}

// Function to write a single byte to an I2C register with retry and exponential backoff
int i2c_write_reg(int handle, uint8_t reg, uint8_t data) {
    int retries = 0;
    int delay_ms = 1;
    int result;

    while (retries < 5) {
        result = i2cWriteByteData(handle, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, data 0x%02X, retries %d): %d\n", reg, data, retries, result);
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, data 0x%02X)\n", reg, data);
    return -1; // Failure
}

// Function to read a 16-bit value from an I2C register with retry and exponential backoff
int i2c_read_reg16(int handle, uint8_t reg, uint16_t *data) {
    uint8_t buffer[2];
    int result;

    result = i2c_read_reg(handle, reg, buffer, 2);
    if (result != 0) {
        return -1;
    }

    *data = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to write a 16-bit value to an I2C register with retry and exponential backoff
int i2c_write_reg16(int handle, uint8_t reg, uint16_t data) {
    uint8_t buffer[2];
    buffer[0] = (data >> 8) & 0xFF;
    buffer[1] = data & 0xFF;
    return i2c_write_reg(handle, reg, buffer[0]) + i2c_write_reg(handle, reg + 1, buffer[1]);
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    int retries = 0;
    int delay_ms = 1;
    int result;

    // Reset the sensor
    result = i2c_write_reg(i2c_handle, 0x00, 0x01); // Software reset
    if (result != 0) {
        fprintf(stderr, "VL53L1X reset failed\n");
        return -1;
    }
    gpioDelay(1000); // Wait for reset to complete

    // Apply initialization sequence
    for (int i = 0; i < sizeof(init_sequence) / 2; i++) {
        result = i2c_write_reg(i2c_handle, init_sequence[2 * i], init_sequence[2 * i + 1]);
        if (result != 0) {
            fprintf(stderr, "VL53L1X init sequence failed at register 0x%02X\n", init_sequence[2 * i]);
            return -1;
        }
    }

    // Start measurement
    result = i2c_write_reg(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (result != 0) {
        fprintf(stderr, "VL53L1X start measurement failed\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int *distance) {
    uint16_t status;
    int retries = 0;
    int delay_ms = 1;
    int result;

    // Poll status register for data ready
    while (retries < 5) {
        result = i2c_read_reg16(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status);
        if (result == 0) {
            if (status & 0x01) {
                break; // Data ready
            } else {
                retries++;
                gpioDelay(delay_ms * 1000); // Delay in microseconds
                delay_ms *= 2; // Exponential backoff
            }
        } else {
            fprintf(stderr, "VL53L1X status read failed, retries %d\n", retries);
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    if (retries >= 5) {
        fprintf(stderr, "VL53L1X status read failed after multiple retries\n");
        return -1;
    }

    // Read distance
    result = i2c_read_reg16(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance);
    if (result != 0) {
        fprintf(stderr, "VL53L1X distance read failed\n");
        return -1;
    }

    return 0;
}

// Function to control the DC motor
void motor_control(int distance) {
    if (distance < DISTANCE_THRESHOLD_LOW) {
        motor_forward();
    } else if (distance > DISTANCE_THRESHOLD_HIGH) {
        motor_backward();
    } else {
        motor_stop();
    }
}

