#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// Global Variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int mpr121_init(int fd);
int read_touch_status(int fd);
void set_led_pattern(int gpio_base, uint8_t pattern);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// I2C Read Function
int i2c_read_register(int fd, uint8_t reg) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return value;
}

// I2C Write Function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

// MPR121 Initialization Function
int mpr121_init(int fd) {
    // Soft Reset
    if (i2c_write_register(fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Configuration (Enable all electrodes)
    if (i2c_write_register(fd, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to configure MPR121.\n");
        return -1;
    }

    return 0;
}

// Read Touch Status Function
int read_touch_status(int fd) {
    uint8_t touch_status_l, touch_status_h;

    touch_status_l = i2c_read_register(fd, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) return -1;

    touch_status_h = i2c_read_register(fd, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) return -1;

    return (touch_status_h << 8) | touch_status_l;
}

// Set LED Pattern Function
void set_led_pattern(int gpio_base, uint8_t pattern) {
    gpioWrite(gpio_base, (pattern >> 0) & 1);
    gpioWrite(gpio_base + 1, (pattern >> 1) & 1);
    gpioWrite(gpio_base + 2, (pattern >> 2) & 1);
    gpioWrite(gpio_base + 3, (pattern >> 3) & 1);
}

// Log Event Function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up resources...\n");

    // Release GPIO pins
    for (int i = LED_GPIO_BASE; i < LED_GPIO_BASE + NUM_ELECTRODES; i++) {
        gpioSetMode(i, PI_INPUT); // Set to input to avoid shorts
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO pins as output
    for (int i = LED_GPIO_BASE; i < LED_GPIO_BASE + NUM_ELECTRODES; i++) {
        gpioSetMode(i, PI_OUTPUT);
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 proximity sensor interface started.\n");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_fd);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status.\n");
            break; // Exit loop on error
        }

        if (touch_status > 0) {
            // Find the first touched electrode
            int electrode = 0;
            while (electrode < NUM_ELECTRODES && (touch_status & (1 << electrode)) == 0) {
                electrode++;
            }

            if (electrode < NUM_ELECTRODES) {
                // Calculate the LED pattern (simple mapping)
                uint8_t pattern = electrode % 4; // Example: 0, 1, 2, 3, 0, 1, 2, 3, ...

                // Set the LED pattern
                set_led_pattern(LED_GPIO_BASE, pattern);

                // Log the event
                char message[64];
                snprintf(message, sizeof(message), "Electrode %d touched (Pattern: 0x%02X)", electrode, pattern);
                log_event(message);
            }
        }

        gpioDelay(POLL_INTERVAL_MS); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

