// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define PROXIMITY_THRESHOLD 50
#define LOG_FILE "proximity.log"

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTERING 0x24
#define MPR121_FILTER_CONFIG 0x2B
#define MPR121_FILTERTH 0x2C
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_data(uint16_t *touch_data);
int is_proximity_event(uint16_t touch_data);
void log_proximity_event();
void turn_led_on();
void turn_led_off();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    turn_led_off();
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// MPR121 initialization function
int mpr121_init() {
    // Check device ID
    int device_id = i2cReadByteData(i2c_handle, 0x05);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0x5A) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error resetting MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure MPR121 registers
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) { // Enable electrode 0-11
        fprintf(stderr, "Error configuring electrode config\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTERING, 0x05) < 0) { // Baseline filtering
        fprintf(stderr, "Error configuring baseline filtering\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_FILTER_CONFIG, 0x06) < 0) { // Filter config
        fprintf(stderr, "Error configuring filter config\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH, 0x0A) < 0) { // Filter threshold
        fprintf(stderr, "Error configuring filter threshold\n");
        return -1;
    }

    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error configuring touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error configuring release threshold for electrode %d\n", i);
            return -1;
        }
    }

    return 0;
}

