#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MIN_DISTANCE 2.0       // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0     // Maximum measurable distance (cm)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse(int pin);
long measure_pulse_width(int pin);
double calculate_distance(long pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse(int pin) {
    gpioWrite(pin, 1);
    gpioDelay(10);
    gpioWrite(pin, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width(int pin) {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(pin) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse never started.\n");
        return -1; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(pin) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse never ended.\n");
        return -1; // Indicate timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate distance from pulse width
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse(TRIGGER_PIN);
        long pulse_width = measure_pulse_width(ECHO_PIN);

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);

            if (distance > MIN_DISTANCE && distance < MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Error: Distance out of range (%.2f cm).\n", distance);
            }
        } else {
            fprintf(stderr, "Error: Invalid pulse width.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

