#define MIN_PULSE_WIDTH 58.0   // Minimum expected pulse width in µs
#define MAX_PULSE_WIDTH 25000.0 // Maximum expected pulse width in µs
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int pulse_width = 0;
static volatile int running = 1;
