void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
    } else if (level == 0) {
        echo_end_tick = tick;
        pulse_width = echo_end_tick - echo_start_tick;

        // Handle tick wrap-around
        if (echo_start_tick > echo_end_tick) {
            pulse_width = (0xFFFFFFFF - echo_start_tick) + echo_end_tick;
        }

        // Validate pulse width
        if (pulse_width > 0 && pulse_width <= MAX_PULSE_WIDTH) {
            double distance = calculate_distance(pulse_width);
