#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <errno.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for XSHUT control
#define XSHUT_PIN 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *data) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (register address) error: %s", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, 1) != 1) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint8_t reg, uint16_t *data) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        syslog(LOG_ERR, "I2C write (register address) error: %s", strerror(errno));
        return -1;
    }
    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Set XSHUT pin as output
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1); // Enable sensor

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed.");
        gpioWrite(XSHUT_PIN, 0); // Disable sensor
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    int distance;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            syslog(LOG_INFO, "Distance: %d mm", distance);
        } else {
            syslog(LOG_ERR, "Failed to read distance.");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    gpioWrite(XSHUT_PIN, 0); // Disable sensor
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

