#define GPIO_GATE 24
#define DISTANCE_THRESHOLD 20.0 // cm
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
float convert_to_cm(int distance_mm);
void control_gate(float distance_cm);
void log_data(int distance_mm, float distance_cm, int gate_state);
void signal_handler(int signal);
void cleanup();

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    char init_data[] = {
        0x00, 0x01, // Example register and value
        0x01, 0x02, // Another example
        0x02, 0x03
    };

    // Write initialization data to the sensor
    if (i2cWriteDevice(i2c_handle, init_data, sizeof(init_data)) != 0) {
        fprintf(stderr, "Error: Failed to write initialization data to VL53L1X\n");
        return -1;
    }

    // Add more initialization steps as needed based on the VL53L1X datasheet

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    char cmd[1];
    char data[2];
    int distance_mm;

    // Write command to start a measurement (adjust based on datasheet)
    cmd[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0; // Example command
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write command to VL53L1X\n");
        return -1;
    }

    // Read the distance data (2 bytes)
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data from VL53L1X\n");
        return -1;
    }

    // Combine the two bytes to form the distance in millimeters
    distance_mm = (data[0] << 8) | data[1];

    return distance_mm;
}

