    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GPIO_GATE, PI_OUTPUT);
