#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_RANGE 180
#define MOVING_AVG_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    double distance;
    int angle;
} SensorData;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick, void *user);
double calculateDistance(uint32_t pulseWidth);
double filterDistance(double newDistance, double *distanceHistory, int *historyIndex, int historySize);
void setServoAngle(int angle);
void logData(double distance, int angle);
void signalHandler(int signal);

// Moving average filter history
double distanceHistory[MOVING_AVG_SIZE] = {0.0};
int historyIndex = 0;

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t startTick = 0;
    static uint32_t endTick = 0;
    static int new_pulse = 0;

    if (level == 1) {
        startTick = tick;
    } else if (level == 0) {
        endTick = tick;

        if (startTick != 0 && endTick != 0) {
            uint32_t pulseWidth = endTick - startTick;
            if (pulseWidth > TIMEOUT_US) {
                // Timeout occurred
                pulseWidth = 0; // Reset pulse width
            }

            double distance = calculateDistance(pulseWidth);
            if (distance > 0 && distance <= 400) {
                // Valid distance reading
                distanceHistory[historyIndex] = distance;
                historyIndex = (historyIndex + 1) % MOVING_AVG_SIZE;
                double filteredDistance = filterDistance(distance, distanceHistory, &historyIndex, MOVING_AVG_SIZE);
                int angle = (int)((filteredDistance / 400.0) * 180.0); // Map distance to angle (0-180)
                setServoAngle(angle);
                logData(filteredDistance, angle);
            } else {
                // Invalid distance reading
                setServoAngle(90);
                logData(-1.0, 90);
            }

            startTick = 0; // Reset start tick
            endTick = 0;    // Reset end tick
            new_pulse = 1;  // Set new pulse flag
        }
    }
}

// Function to calculate distance in centimeters
double calculateDistance(uint32_t pulseWidth) {
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to apply moving average filter
double filterDistance(double newDistance, double *distanceHistory, int *historyIndex, int historySize) {
    double sum = 0.0;
    for (int i = 0; i < historySize; i++) {
        sum += distanceHistory[i];
    }
    return sum / historySize;
}

// Function to set the servo angle
void setServoAngle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulseWidth = (int)((angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    gpioServo(SERVO_PIN, pulseWidth);
}

// Function to log data to CSV file
void logData(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
        fflush(log_file); // Flush the buffer to ensure data is written to the file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Stop the servo
    setServoAngle(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Cleanup pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set up interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    }
    fflush(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        gpioDelay(100); // Trigger every 100 ms
    }

    return 0;
}

