#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <pthread.h>

// Constants
#define SI1102_I2C_ADDR 0x60
#define SI1102_REG_PART_ID 0x00
#define SI1102_REG_ALS_VIS_DATA0 0x22
#define SI1102_REG_ALS_VIS_DATA1 0x23
#define SI1102_REG_PS1_DATA0 0x24
#define SI1102_REG_PS1_DATA1 0x25
#define SI1102_REG_MEAS_RATE0 0x08
#define SI1102_REG_MEAS_RATE1 0x09
#define SI1102_REG_IRQ_ENABLE 0x0A
#define SI1102_REG_IRQ_MODE1 0x0B
#define SI1102_REG_IRQ_MODE2 0x0C
#define SI1102_REG_COMMAND 0x18
#define SI1102_REG_HW_KEY 0x07

#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables
static int i2c_fd = -1;
static int i2c_address = SI1102_I2C_ADDR;
static int threshold = 1000;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(int address);
int si1102_init(int fd);
int si1102_read_proximity(int fd);
int si1102_read_part_id(int fd);
int si1102_write_register(int fd, uint8_t reg, uint8_t value);
int si1102_read_register(int fd, uint8_t reg);
int gpio_init(int pin);
int gpio_set_mode(int pin, int mode);
int gpio_set_pull(int pin, int pull);
int gpio_set_edge(int pin, int edge);
int gpio_set_callback(int pin, void (*callback)(int));
void log_proximity_data(int proximity, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int i2c_init(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Si1102 initialization function
int si1102_init(int fd) {
    // Reset the device
    if (si1102_write_register(fd, SI1102_REG_COMMAND, 0x01) < 0) {
        fprintf(stderr, "Error resetting Si1102\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rate
    if (si1102_write_register(fd, SI1102_REG_MEAS_RATE0, 0x08) < 0) {
        fprintf(stderr, "Error configuring measurement rate 0\n");
        return -1;
    }
    if (si1102_write_register(fd, SI1102_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error configuring measurement rate 1\n");
        return -1;
    }

    // Enable proximity interrupt on rising edge
    if (si1102_write_register(fd, SI1102_REG_IRQ_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error enabling proximity interrupt\n");
        return -1;
    }

    // Set interrupt mode to rising edge
    if (si1102_write_register(fd, SI1102_REG_IRQ_MODE1, 0x01) < 0) {
        fprintf(stderr, "Error setting interrupt mode 1\n");
        return -1;
    }

    // Enable proximity sensor
    if (si1102_write_register(fd, SI1102_REG_COMMAND, 0x02) < 0) {
        fprintf(stderr, "Error enabling proximity sensor\n");
        return -1;
    }

    return 0;
}

// Si1102 read proximity function
int si1102_read_proximity(int fd) {
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    return (data[1] << 8) | data[0];
}

// Si1102 read part ID function
int si1102_read_part_id(int fd) {
    uint8_t part_id;
    if (si1102_read_register(fd, SI1102_REG_PART_ID) < 0) {
        fprintf(stderr, "Error reading part ID\n");
        return -1;
    }
    part_id = si1102_read_register(fd, SI1102_REG_PART_ID);
    return part_id;
}

// Si1102 write register function
int si1102_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Si1102 read register function
int si1102_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return buf[0];
}

// GPIO initialization function
int gpio_init(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return -1;
    }

    return 0;
}

// GPIO set mode function
int gpio_set_mode(int pin, int mode) {
    gpioSetMode(pin, mode);
    return 0;
}

// GPIO set pull function
int gpio_set_pull(int pin, int pull) {
    gpioSetPullUpDown(pin, pull);
    return 0;
}

// GPIO set edge function
int gpio_set_edge(int pin, int edge) {
    gpioSetAlertFuncEx(pin, edge, interrupt_handler, NULL);
    return 0;
}

// GPIO set callback function
int gpio_set_callback(int pin, void (*callback)(int)) {
    gpioSetAlertFuncEx(pin, callback, NULL);
    return 0;
}

// Log proximity data function
void log_proximity_data(int proximity, const char *status) {
    pthread_mutex_lock(&log_mutex);
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    int proximity = si1102_read_proximity(i2c_fd);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity in interrupt handler\n");
        return;
    }

    char *status = (proximity <= threshold) ? "SAFE" : "ALERT";
    log_proximity_data(proximity, status);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize I2C
    i2c_fd = i2c_init(i2c_address);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize Si1102
    if (si1102_init(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_PIN) < 0) {
        cleanup();
        return 1;
    }

    // Set GPIO mode to input
    if (gpio_set_mode(GPIO_PIN, PI_INPUT) < 0) {
        cleanup();
        return 1;
    }

    // Set GPIO pull-up/down resistor
    if (gpio_set_pull(GPIO_PIN, PI_PUD_DOWN) < 0) {
        cleanup();
        return 1;
    }

    // Set GPIO edge trigger to rising
    if (gpio_set_edge(GPIO_PIN, RISING_EDGE) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

