    int proximity = si1102_read_proximity(i2c_fd);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity in interrupt handler\n");
        return;
    }

    char *status = (proximity <= threshold) ? "SAFE" : "ALERT";
    log_proximity_data(proximity, status);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize I2C
    i2c_fd = i2c_init(i2c_address);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize Si1102
    if (si1102_init(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_PIN) < 0) {
        cleanup();
        return 1;
    }

    // Set GPIO mode to input
    if (gpio_set_mode(GPIO_PIN, PI_INPUT) < 0) {
        cleanup();
        return 1;
    }

    // Set GPIO pull-up/down resistor
    if (gpio_set_pull(GPIO_PIN, PI_PUD_DOWN) < 0) {
        cleanup();
        return 1;
    }

    // Set GPIO edge trigger to rising
    if (gpio_set_edge(GPIO_PIN, RISING_EDGE) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

