#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000       // 200 ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0    // Hz
#define MAX_FREQUENCY 2000.0   // Hz
#define PWM_RANGE 1000000      // PWM range (0-1000000)

// Global variables
volatile sig_atomic_t program_running = 1;
double previous_frequency = 440.0; // Initial frequency

// Function prototypes
void trigger_pulse();
double measure_distance();
double map_distance_to_frequency(double distance);
void set_pwm_frequency(double frequency);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    trigger_pulse();

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // 1 us delay
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // 1 us delay
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (low)\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    double distance = (double)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

// Function to map distance to frequency using a logarithmic scale
double map_distance_to_frequency(double distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Calculate frequency using logarithmic mapping
    double frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * log10(distance / MIN_DISTANCE) / log10(MAX_DISTANCE / MIN_DISTANCE);

    return frequency;
}

// Function to set the PWM frequency
void set_pwm_frequency(double frequency) {
    // Clamp frequency to the defined range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    // Calculate duty cycle (50%)
    int duty_cycle = (int)(PWM_RANGE * 0.5);

    // Set PWM frequency and duty cycle
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    gpioPWM(PWM_PIN, duty_cycle);
}

