    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Set PWM frequency (initial value)
    set_pwm_frequency(previous_frequency);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        double distance = measure_distance();

        if (distance > 0) {
            // Distance measurement successful
            double frequency = map_distance_to_frequency(distance);
            set_pwm_frequency(frequency);
            previous_frequency = frequency; // Update previous frequency
        } else {
            // Distance measurement failed (timeout or error)
            // Keep the previous frequency
