#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TOO_CLOSE_DISTANCE_CM 10.0

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse duration
long measurePulse() {
    long start_tick, end_tick, pulse_duration;

    gpioSetMode(ECHO_PIN, PI_INPUT); // Ensure echo pin is input

    // Wait for echo to go high with timeout
    long timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    return pulse_duration;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate timeout
    }
    return (float)pulse_duration / 58.0; // Speed of sound approximation
}

// Function to print the distance
void printDistance(float distance) {
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        printf("Invalid reading\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < TOO_CLOSE_DISTANCE_CM) {
            printf("Too close!\n");
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set trigger pin as output
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is initially low

    // Set echo pin as input
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_duration = measurePulse();
        float distance = calculateDistance(pulse_duration);

        if (distance >= 0) {
            printDistance(distance);
        } else {
            printf("Timeout occurred\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

