#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_PART_ID 0x00
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define SI1175_REG_MEAS_RATE0 0x08
#define SI1175_REG_MEAS_RATE1 0x09
#define SI1175_REG_ALS_IR_DATA0 0x24
#define SI1175_REG_ALS_IR_DATA1 0x25
#define SI1175_REG_PS1_DATA0 0x26
#define SI1175_REG_PS1_DATA1 0x27
#define SI1175_REG_PS2_DATA0 0x28
#define SI1175_REG_PS2_DATA1 0x29
#define SI1175_REG_PS3_DATA0 0x2A
#define SI1175_REG_PS3_DATA1 0x2B
#define SI1175_REG_IRQ_ENABLE 0x04
#define SI1175_REG_IRQ_MODE1 0x05
#define SI1175_REG_HW_KEY 0x07
#define SI1175_REG_MEAS_CONFIG 0x0F
#define SI1175_REG_ALS_IR_ADCMUX 0x18
#define SI1175_REG_PS1_ADCMUX 0x1A
#define SI1175_REG_PS2_ADCMUX 0x1C
#define SI1175_REG_PS3_ADCMUX 0x1E

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als_visible(uint16_t *als_visible);
int log_data(uint16_t als_visible);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize the Si1175 sensor
int initialize_sensor() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, SI1175_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1175\n");
        return -1;
    }
    gpioDelay(10); // Delay after reset

    // Configure measurement rate
    if (i2cWriteByteData(i2c_handle, SI1175_REG_MEAS_RATE0, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set measurement rate\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1175_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set measurement rate\n");
        return -1;
    }

    // Configure ALS IR ADC MUX
    if (i2cWriteByteData(i2c_handle, SI1175_REG_ALS_IR_ADCMUX, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to configure ALS IR ADC MUX\n");
        return -1;
    }

    // Configure PS1 ADC MUX
    if (i2cWriteByteData(i2c_handle, SI1175_REG_PS1_ADCMUX, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to configure PS1 ADC MUX\n");
        return -1;
    }

    // Configure PS2 ADC MUX
    if (i2cWriteByteData(i2c_handle, SI1175_REG_PS2_ADCMUX, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to configure PS2 ADC MUX\n");
        return -1;
    }

    // Configure PS3 ADC MUX
    if (i2cWriteByteData(i2c_handle, SI1175_REG_PS3_ADCMUX, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to configure PS3 ADC MUX\n");
        return -1;
    }

    // Enable ALS visible channel
    if (i2cWriteByteData(i2c_handle, SI1175_REG_MEAS_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to enable ALS visible channel\n");
        return -1;
    }

    return 0;
}

// Function to read the ambient light value from the Si1175
int read_als_visible(uint16_t *als_visible) {
    int als_vis_low, als_vis_high;

    als_vis_low = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA0);
    if (als_vis_low < 0) {
        fprintf(stderr, "Error: Failed to read ALS visible data (low byte)\n");
        return -1;
    }

    als_vis_high = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA1);
    if (als_vis_high < 0) {
        fprintf(stderr, "Error: Failed to read ALS visible data (high byte)\n");
        return -1;
    }

    *als_visible = (als_vis_high << 8) | als_vis_low;
    return 0;
}

// Function to log the data to a file
int log_data(uint16_t als_visible) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to get timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1175_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    uint16_t als_visible;

    // Main loop
    while (!terminate) {
        if (read_als_visible(&als_visible) == 0) {
            if (log_data(als_visible) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read ALS visible data\n");
        }

        sleep(5);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

