#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define LUX_REG 0x10
#define PROX_REG 0x12

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int si1182_init(int fd);
int read_sensor_data(int fd, float *lux, int *proximity);
void log_data(FILE *fp, float lux, int proximity);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg(fd, PART_ID_REG, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read part ID\n");
        return -1;
    }

    if (part_id != 0x41) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure measurement rate (example value, adjust as needed)
    if (i2c_write_reg(fd, MEAS_RATE_REG, 0x0A) != 0) {
        fprintf(stderr, "Failed to write measurement rate\n");
        return -1;
    }

    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, float *lux, int *proximity) {
    uint8_t lux_data[2];
    uint8_t prox_data[2];

    if (i2c_read_reg(fd, LUX_REG, lux_data, 2) != 0) {
        fprintf(stderr, "Failed to read lux data\n");
        return -1;
    }

    if (i2c_read_reg(fd, PROX_REG, prox_data, 2) != 0) {
        fprintf(stderr, "Failed to read proximity data\n");
        return -1;
    }

    *lux = (float)((lux_data[0] << 8) | lux_data[1]) / 10.0; // Example conversion
    *proximity = (prox_data[0] << 8) | prox_data[1];

    return 0;
}

// Log data function
void log_data(FILE *fp, float lux, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    float lux;
    int proximity;

    // Main loop
    while (program_running) {
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
            printf("%f,%d\n", lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(100000); // 100 ms
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

