#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02

#define SI1145_REG_UCOEF0 0x13
#define SI1145_REG_UCOEF1 0x14
#define SI1145_REG_UCOEF2 0x15
#define SI1145_REG_UCOEF3 0x16

#define SI1145_REG_PARAM_WR 0x17
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE0 0x20
#define SI1145_REG_RESPONSE1 0x21

#define SI1145_REG_IRQ_ENABLE 0x03
#define SI1145_REG_IRQ_MODE1 0x04
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_RATE 0x0A
#define SI1145_REG_ALS_IR_ADCMUX 0x0B
#define SI1145_REG_PS_LED21_SELECT 0x0C
#define SI1145_REG_PS_LED3_SELECT 0x0D
#define SI1145_REG_PS1_ADCMUX 0x0E
#define SI1145_REG_PS2_ADCMUX 0x0F
#define SI1145_REG_PS3_ADCMUX 0x10
#define SI1145_REG_PS1_TH1 0x11
#define SI1145_REG_PS1_TH0 0x12
#define SI1145_REG_PS2_TH1 0x14
#define SI1145_REG_PS2_TH0 0x15
#define SI1145_REG_PS3_TH1 0x17
#define SI1145_REG_PS3_TH0 0x18
#define SI1145_REG_PS1_DATA0 0x22
#define SI1145_REG_PS1_DATA1 0x23
#define SI1145_REG_PS2_DATA0 0x24
#define SI1145_REG_PS2_DATA1 0x25
#define SI1145_REG_PS3_DATA0 0x26
#define SI1145_REG_PS3_DATA1 0x27
#define SI1145_REG_ALS_DATA0 0x28
#define SI1145_REG_ALS_DATA1 0x29
#define SI1145_REG_ALS_DATA2 0x2A
#define SI1145_REG_ALS_DATA3 0x2B
#define SI1145_REG_ALS_IR_DATA0 0x2C
#define SI1145_REG_ALS_IR_DATA1 0x2D
#define SI1145_REG_ALS_IR_DATA2 0x2E
#define SI1145_REG_ALS_IR_DATA3 0x2F

// Commands
#define SI1145_COMMAND_RESET 0x01
#define SI1145_COMMAND_ALS_FORCE 0x06
#define SI1145_COMMAND_PS_FORCE 0x07

// Function prototypes
int si1145_init(int i2c_handle);
int si1145_read_proximity(int i2c_handle);
int log_proximity_data(int proximity_value);
void signal_handler(int signal);

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int si1145_init(int i2c_handle) {
    int retries = 3;
    int status;

    // Reset the device
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_COMMAND_RESET);
        if (status >= 0) {
            gpioDelay(10); // Wait for reset to complete
            break;
        } else {
            fprintf(stderr, "Error resetting Si1145: %d\n", status);
            retries--;
            gpioDelay(10); // Small delay before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1145 after multiple retries.\n");
        return -1;
    }

    // Configure the sensor (example configuration)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, 0x17);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing HW_KEY: %d\n", status);
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write HW_KEY after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE0, 0x08);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing MEAS_RATE0: %d\n", status);
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write MEAS_RATE0 after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
