    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_PS_LED21_SELECT, 0x1B);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing PS_LED21_SELECT: %d\n", status);
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS_LED21_SELECT after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_PS_LED3_SELECT, 0x00);
        if (status >= 0) {
