    }

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_PS1_ADCMUX, 0x01);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing PS1_ADCMUX: %d\n", status);
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_ADCMUX after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_PS2_ADCMUX, 0x01);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing PS2_ADCMUX: %d\n", status);
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS2_ADCMUX after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_PS3_ADCMUX, 0x01);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing PS3_ADCMUX: %d\n", status);
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS3_ADCMUX after multiple retries.\n");
        return -1;
