    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_PS1_TH1, 0x00);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing PS1_TH1: %d\n", status);
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_TH1 after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1145_REG_PS1_TH0, 0x00);
        if (status >= 0) {
