#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 200.0     // Maximum measurable distance in cm
#define MIN_DISTANCE 20.0      // Minimum measurable distance in cm
#define MAX_PULSE_WIDTH 2500   // Maximum pulse width for servo (us)
#define MIN_PULSE_WIDTH 500    // Minimum pulse width for servo (us)
#define MAX_ANGLE 180          // Maximum servo angle
#define MIN_ANGLE 0            // Minimum servo angle
#define TIMEOUT_US 50000        // Timeout for echo pulse (us)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
float measure_distance();
int set_servo_angle(float distance);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high with timeout
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        timeout_count++;
        if (timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout (high)\n");
            return -1.0; // Timeout error
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        timeout_count++;
        if (timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout (low)\n");
            return -1.0; // Timeout error
        }
        gpioDelay(1);
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set servo angle based on distance
int set_servo_angle(float distance) {
    float angle;

    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Calculate angle based on distance
    angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;

    // Clamp angle to the defined range
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    // Calculate pulse width based on angle
    int pulse_width = (int)(angle / MAX_ANGLE * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

    // Set servo pulse width
    gpioServo(SERVO_PIN, pulse_width);

    return 0;
}

// Cleanup function to terminate pigpio
void cleanup() {
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            set_servo_angle(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

