#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MODE 0x001E
#define VL53L1X_REG_TIMING_BUDGET 0x001A
#define VL53L1X_REG_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// GPIO pin for servo control
#define SERVO_PIN 18

// Distance thresholds for servo control
#define OPEN_DISTANCE 250
#define CLOSE_DISTANCE 200

// Servo pulse widths
#define OPEN_PULSE_WIDTH 1000
#define CLOSE_PULSE_WIDTH 2000

// I2C handle
int i2c_handle;

// Log file pointer
FILE *log_file;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void servo_control(int gpio_pin, int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Set ranging mode to short distance
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error setting ranging mode\n");
        return -1;
    }

    // Set timing budget to 50ms
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_TIMING_BUDGET, 0x00) < 0) {
        fprintf(stderr, "Error setting timing budget\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle) {
    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    // Wait for measurement to be ready (polling the status register)
    int status = 0;
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading range status\n");
            return -1;
        }
        if (status & 0x01) {
            break; // Measurement ready
        }
        gpioDelay(1); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read distance
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Stop ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP, 0x00) < 0) {
        fprintf(stderr, "Error stopping ranging\n");
        return -1;
    }

    return distance;
}

// Servo control function
void servo_control(int gpio_pin, int pulse_width) {
    gpioPWM(gpio_pin, pulse_width);
}

// Logging function
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioPWM(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int last_distance = 0; // Store the last measured distance
    int current_distance;

    // Main loop
    while (1) {
        current_distance = vl53l1x_read_distance(i2c_handle);
        if (current_distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Servo control logic with hysteresis
        if (current_distance > OPEN_DISTANCE && last_distance <= OPEN_DISTANCE) {
            servo_control(SERVO_PIN, OPEN_PULSE_WIDTH);
            log_event("Gate opened");
        } else if (current_distance < CLOSE_DISTANCE && last_distance >= CLOSE_DISTANCE) {
            servo_control(SERVO_PIN, CLOSE_PULSE_WIDTH);
            log_event("Gate closed");
        }

        last_distance = current_distance;
        gpioDelay(100); // Delay 100ms
    }

    return 0;
}

