        fprintf(stderr, "Error stopping ranging\n");
        return -1;
    }

    return distance;
}

// Servo control function
void servo_control(int gpio_pin, int pulse_width) {
    gpioPWM(gpio_pin, pulse_width);
}

// Logging function
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioPWM(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int last_distance = 0; // Store the last measured distance
    int current_distance;

    // Main loop
    while (1) {
        current_distance = vl53l1x_read_distance(i2c_handle);
        if (current_distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Servo control logic with hysteresis
        if (current_distance > OPEN_DISTANCE && last_distance <= OPEN_DISTANCE) {
            servo_control(SERVO_PIN, OPEN_PULSE_WIDTH);
            log_event("Gate opened");
        } else if (current_distance < CLOSE_DISTANCE && last_distance >= CLOSE_DISTANCE) {
            servo_control(SERVO_PIN, CLOSE_PULSE_WIDTH);
            log_event("Gate closed");
        }

        last_distance = current_distance;
        gpioDelay(100); // Delay 100ms
    }

    return 0;
}

