#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0        // degrees

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulseWidth);
float mapDistanceToAngle(float distance);
void setServoAngle(float angle);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    long startTime = time_time();

    while (gpioRead(pin) != level) {
        if (time_time() - startTime > timeout) {
            return -1; // Timeout
        }
    }

    long pulseStart = time_time();

    while (gpioRead(pin) == level) {
        if (time_time() - startTime > timeout) {
            return -1; // Timeout
        }
    }

    long pulseEnd = time_time();

    width = pulseEnd - pulseStart;
    return width;
}

// Function to calculate the distance from the pulse width
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Timeout or error
    }
    return (float)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to map the distance to a servo angle
float mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the servo angle using pigpio
void setServoAngle(float angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%.2f degrees)\n", angle);
        return;
    }

    int pulseWidth = (int)(500 + (angle / 180.0) * 2000); // Map angle to pulse width (500-2500 us)
    gpioServo(SERVO_PIN, pulseWidth);
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("Caught signal %d, stopping servo and exiting...\n", signal);
    program_running = 0;
    setServoAngle(0.0); // Stop the servo
    gpioTerminate();     // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signalHandler);

    printf("Ultrasonic distance measurement and servo control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        triggerSensor();
        long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulseWidth < 0) {
            printf("Timeout waiting for echo\n");
        } else {
            float distance = calculateDistance(pulseWidth);
            if (distance < 0) {
                printf("Error: Invalid distance reading\n");
            } else {
                float angle = mapDistanceToAngle(distance);
                printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
                setServoAngle(angle);
            }
        }

        gpioDelay(100); // 100ms delay
    }

    return 0;
}

