#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SI7005_ADDR 0x40

// Define the CONFIG register address
#define CONFIG_REG 0x00

// Define the temperature and humidity register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x01

// Global variables
int i2c_handle = -1; // Initialize to -1 to indicate not opened
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Function to initialize the I2C bus
int init_i2c()
{
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the Si7005 sensor
int config_sensor()
{
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = 0x00; // Example configuration value

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0)
    {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data
int read_sensor(float *temperature, float *humidity)
{
    char temp_buf[1];
    char humid_buf[1];
    char temp_data[2];
    char humid_data[2];

    // Read temperature
    temp_buf[0] = TEMP_REG;
    int result = i2cWriteDevice(i2c_handle, temp_buf, 1);
    if (result != 0)
    {
        fprintf(stderr, "Error writing to temperature register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, temp_data, 2);
    if (result != 2)
    {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    uint16_t raw_temp = (temp_data[0] << 8) | temp_data[1];
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Read humidity
    humid_buf[0] = HUMID_REG;
    result = i2cWriteDevice(i2c_handle, humid_buf, 1);
    if (result != 0)
    {
        fprintf(stderr, "Error writing to humidity register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, humid_data, 2);
    if (result != 2)
    {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    uint16_t raw_humidity = (humid_data[0] << 8) | humid_data[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the I2C bus
    if (init_i2c() != 0)
    {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (config_sensor() != 0)
    {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    float temperature, humidity;
    while (!terminate)
    {
        if (read_sensor(&temperature, &humidity) == 0)
        {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        }
        else
        {
            fprintf(stderr, "Error reading sensor data\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (init_i2c() != 0)
            {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                break;
            }
            if (config_sensor() != 0)
            {
                fprintf(stderr, "Failed to re-configure sensor, exiting\n");
                break;
            }
        }
        gpioSleep(PI_TIME_RELATIVE, 2, 0); // Sleep for 2 seconds
    }

    // Close the I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

