#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 commands
#define SHT40_MEASURE_HIGH 0xFD

// CRC-8 polynomial: 0x31 (x^8 + x^5 + x^4 + 1)
#define CRC_POLYNOMIAL 0x31

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} sht40_data_t;

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
sht40_data_t read_sht40() {
    sht40_data_t data = {0.0, 0.0};
    uint8_t buffer[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, SHT40_MEASURE_HIGH);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return data; // Return default values on error
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return data; // Return default values on error
    }

    // Validate temperature CRC
    uint8_t temp_crc = crc8(buffer, 2);
    if (temp_crc != buffer[2]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return data; // Return default values on error
    }

    // Validate humidity CRC
    uint8_t hum_crc = crc8(buffer + 3, 2);
    if (hum_crc != buffer[5]) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return data; // Return default values on error
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    uint16_t raw_humidity = (buffer[3] << 8) | buffer[4];

    data.temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    data.humidity = 100.0 * (float)raw_humidity / 65535.0;

    return data;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        sht40_data_t sensor_data = read_sht40();

        // Print temperature and humidity readings
        printf("Temperature: %.2f °C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

