#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int i2c_handle, float *ambient_temp, float *object_temp);
int log_data(FILE *log_file, float ambient_temp, float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature data from the sensor
int read_sensor_data(int i2c_handle, float *ambient_temp, float *object_temp) {
    char buf[3];
    int result;

    // Read ambient temperature
    result = i2cReadI2CBlockData(i2c_handle, AMBIENT_TEMP_REG, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", result);
        return -1;
    }
    int16_t raw_ambient = (buf[0] << 8) | buf[1];
    *ambient_temp = (float)raw_ambient * 0.02 - 273.15;

    // Read object temperature
    result = i2cReadI2CBlockData(i2c_handle, OBJECT_TEMP_REG, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading object temperature: %d\n", result);
        return -1;
    }
    int16_t raw_object = (buf[0] << 8) | buf[1];
    *object_temp = (float)raw_object * 0.02 - 273.15;

    return 0;
}

// Function to log data to a file
int log_data(FILE *log_file, float ambient_temp, float object_temp) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data.ambient_temp, &sensor_data.object_temp) == 0) {
            if (log_data(log_file, sensor_data.ambient_temp, sensor_data.object_temp) != 0) {
                fprintf(stderr, "Error logging data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, but continuing...\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

