#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts30_address;
    char log_file_name[64];
    char error_log_file_name[64];
    int sample_interval;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .sts30_address = STS30_ADDR,
    .log_file_name = LOG_FILE,
    .error_log_file_name = ERROR_LOG_FILE,
    .sample_interval = SAMPLE_INTERVAL
};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log files
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    error_log_file = fopen(config.error_log_file_name, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        cleanup();
        return 1;
    }

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                log_error("Failed to log temperature");
            }
        } else {
            log_error("Failed to read temperature");
        }

        gpioSleep(PI_TIME_RELATIVE, config.sample_interval, 0); // Sleep for sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.sts30_address, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }
    return 0;
}

// Read temperature from STS30-DIS sensor
int read_temperature(float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return 1;
    }

    gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Wait for measurement (100ms)

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        log_error("Failed to read temperature data");
        return 1;
    }

    // Convert raw data to temperature (Celsius)
    unsigned int temp_raw = (buffer[0] << 8) | buffer[1];
    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);

    return 0;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, temperature) < 0) {
        log_error("Failed to write to log file");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Log error message to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
