// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts30_address;
    char log_file_name[64];
    char error_log_file_name[64];
    int sample_interval;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .sts30_address = STS30_ADDR,
    .log_file_name = LOG_FILE,
    .error_log_file_name = ERROR_LOG_FILE,
    .sample_interval = SAMPLE_INTERVAL
};

