#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define LOG_FILE "pressure_log.csv"
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint8_t *data);
sensor_data_t convert_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the SDP810 sensor
int configure_sensor() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to configure sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SDP810 sensor
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Extract scale factors
    float pressure_scale = (float)((data[6] << 8) | data[7]) / 100.0f;
    float temperature_scale = (float)((data[8] << 8) | data[9]) / 100.0f;

    // Validate CRC
    uint8_t crc_pressure = data[2];
    uint8_t crc_temperature = data[5];
    uint8_t crc_scale_pressure = data[6];
    uint8_t crc_scale_temperature = data[8];

    uint8_t crc_calculated_pressure = crc8(data, 2);
    uint8_t crc_calculated_temperature = crc8(data + 3, 2);
    uint8_t crc_calculated_scale_pressure = crc8(data + 6, 2);
    uint8_t crc_calculated_scale_temperature = crc8(data + 8, 2);

    if (crc_calculated_pressure != crc_pressure) {
        fprintf(stderr, "Pressure CRC check failed\n");
        sensor_data.pressure = -999.0f; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / pressure_scale;
    }

    if (crc_calculated_temperature != crc_temperature) {
        fprintf(stderr, "Temperature CRC check failed\n");
        sensor_data.temperature = -999.0f; // Indicate error
    } else {
        sensor_data.temperature = (float)raw_temperature / temperature_scale;
    }

    return sensor_data;
}

// Log data to CSV file
int log_data(const sensor_data_t *data) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data->pressure, data->temperature);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[9];
    sensor_data_t sensor_values;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Convert data
            sensor_values = convert_data(sensor_data);

            // Log data
            if (sensor_values.pressure != -999.0f && sensor_values.temperature != -999.0f) {
                if (log_data(&sensor_values) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor data, skipping logging\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

