#define LOGGING_INTERVAL_S 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sht40(float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 algorithm
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_HIGH_REPEATABILITY;
    uint8_t buffer[6];

    if (i2cWriteByte(i2c_handle, cmd) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    uint16_t temp_raw = (buffer[0] << 8) | buffer[1];
    uint16_t hum_raw = (buffer[3] << 8) | buffer[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

