    return 0;
}

// Read data from SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_HIGH_REPEATABILITY;
    uint8_t buffer[6];

    if (i2cWriteByte(i2c_handle, cmd) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    uint16_t temp_raw = (buffer[0] << 8) | buffer[1];
    uint16_t hum_raw = (buffer[3] << 8) | buffer[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sht40(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(LOGGING_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

