        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int read_i2c(int handle, uint8_t *buf, int count) {
    int result = i2cReadDevice(handle, (char *)buf, count);
    if (result != count) {
        fprintf(stderr, "Failed to read %d bytes: %s\n", count, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from the sensor
float read_temperature(int handle) {
    uint8_t buf[2];
