    if (write_i2c(handle, TEMP_MEASURE_CMD) != 0) {
        return -1000.0; // Indicate error
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

    if (read_i2c(handle, buf, 2) != 0) {
        return -1000.0; // Indicate error
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    return temperature;
}

