    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

    if (read_i2c(handle, buf, 2) != 0) {
        return -1000.0; // Indicate error
    }

    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    return humidity;
}

