#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
float calculate_crc(const uint8_t *data, int count);
int validate_crc(const uint8_t *data, int count, uint8_t crc);
float convert_to_celsius(uint16_t raw_temperature);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} SensorData;

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to write command to I2C device");
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        log_error("Failed to read data from I2C device");
        return -1;
    }

    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int count) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC-8 checksum
int validate_crc(const uint8_t *data, int count, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, count);
    return (calculated_crc == crc);
}

// Function to convert raw temperature data to Celsius
float convert_to_celsius(uint16_t raw_temperature) {
    return -45.0 + (175.0 * raw_temperature / 65535.0);
}

// Function to log temperature data to a file
int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);

    return 0;
}

// Function to log error messages to a file
int log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(fp, "%s, %s\n", timestamp, message);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[3];
        uint16_t raw_temperature;
        float temperature;

        // Send measurement command
        if (send_command(MEASURE_CMD) != 0) {
            continue; // Retry on error
        }

        // Wait for conversion (at least 15 ms)
        gpioDelay(15000); // 15 ms

        // Read data
        if (read_data(data, 3) != 0) {
            continue; // Retry on error
        }

        // Validate CRC
        if (!validate_crc(data, 2, data[2])) {
            log_error("CRC validation failed");
            continue; // Retry on error
        }

        // Convert to Celsius
        raw_temperature = (data[0] << 8) | data[1];
        temperature = convert_to_celsius(raw_temperature);

        // Log temperature
        if (log_temperature(temperature) != 0) {
            log_error("Failed to log temperature");
        }

        printf("Temperature: %.2f °C\n", temperature);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

