// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_MS 1000
#define DATA_FILE "airflow_data.txt"

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
SensorData process_data(char *buffer);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Process raw data and convert to pressure and temperature
SensorData process_data(char *buffer) {
    SensorData data;
    // Extract raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    // CRC check
    uint8_t crc_pressure = buffer[2];
    uint8_t crc_temperature = buffer[5];

    uint8_t data_pressure[2] = {buffer[0], buffer[1]};
    uint8_t data_temperature[2] = {buffer[3], buffer[4]};

    if (crc8(data_pressure, 2) != crc_pressure) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        data.pressure = -1.0; // Indicate error
    } else if (crc8(data_temperature, 2) != crc_temperature) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        data.temperature = -1.0; // Indicate error
    } else {
        // Convert to physical units (refer to SDP800-500Pa datasheet)
        data.pressure = (float)raw_pressure / 240.0; // Pa
        data.temperature = (float)raw_temperature / 200.0; // °C
    }

    return data;
}

