    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data_file != NULL) {
        fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
        fflush(data_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Data file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    char buffer[6];
    SensorData data;

    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Wait for measurement (at least 1ms)
        gpioDelay(1000); // 1ms delay

        // Read data
        if (read_data(i2c_handle, buffer, 6) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Process data
        data = process_data(buffer);

        // Log data
        if (data.pressure != -1.0 && data.temperature != -1.0) {
            log_data(data);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

