#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define HUMIDITY_THRESHOLD 60.0
#define TEMPERATURE_THRESHOLD 28.0
#define HUMIDITY_HYSTERESIS 62.0
#define TEMPERATURE_HYSTERESIS 26.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entry
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void add_to_buffer(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(float *temperature, float *humidity) {
    int retries = 0;
    int result;
    uint8_t data[2];
    uint16_t raw_temperature, raw_humidity;

    // Read temperature
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing temperature command (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write temperature command after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    gpioDelay(30000); // Wait for conversion (30ms)

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read temperature data after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    raw_temperature = (data[0] << 8) | data[1];
    *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    // Read humidity
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, HUMID_CMD);
        if (result >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing humidity command (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write humidity command after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    gpioDelay(30000); // Wait for conversion (30ms)

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading humidity data (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read humidity data after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    raw_humidity = (data[0] << 8) | data[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Function to control the fan
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMPERATURE_THRESHOLD && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
