#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_I2C_ADDR 0x62

// SCD40 commands
#define SCD40_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_READ_MEASUREMENT 0xE4B8
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial: 0x31 (x^8 + x^5 + x^4 + 1)
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int start_periodic_measurement();
int read_measurement(uint8_t *data);
int read_data_ready_flag();
int verify_crc(uint8_t *data, int length);
int extract_data(uint8_t *data, sensor_data_t *sensor_data);
int log_data(sensor_data_t sensor_data);
void stop_periodic_measurement();
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int length) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to start periodic measurement. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Wait for data ready flag
        if (read_data_ready_flag() == 1) {
            uint8_t data[9];
            if (read_measurement(data) == 0) {
                sensor_data_t sensor_data;
                if (verify_crc(data, 9) == 0) {
                    if (extract_data(data, &sensor_data) == 0) {
                        if (log_data(sensor_data) != 0) {
                            fprintf(stderr, "Failed to log data.\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to extract data.\n");
                    }
                } else {
                    fprintf(stderr, "CRC check failed.\n");
                }
            } else {
                fprintf(stderr, "Failed to read measurement.\n");
            }
        } else {
            //fprintf(stderr, "Data not ready yet.\n"); // Commented out to reduce console spam
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (SCD40_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD40_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send start periodic measurement command: %d\n", result);
        return 1;
    }
    return 0;
}

// Read measurement
int read_measurement(uint8_t *data) {
    char buf[2];
    buf[0] = (SCD40_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD40_READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return 1;
    }

    gpioDelay(1); // Small delay after sending the command

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return 1;
    }
    return 0;
}

// Read data ready flag
int read_data_ready_flag() {
    uint8_t data[2];
    char buf[2];
    buf[0] = 0xE8; // Read data ready command
    buf[1] = 0x05;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read data ready command: %d\n", result);
        return 0; // Return 0 to avoid further issues, but log the error
    }

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data ready data: %d\n", result);
        return 0; // Return 0 to avoid further issues, but log the error
    }

    return (data[0] == 0x00 && data[1] == 0x00);
}

// Verify CRC
int verify_crc(uint8_t *data, int length) {
    for (int i = 0; i < length - 2; i += 2) {
        uint8_t crc = crc8(data + i, 2);
        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC check failed at byte %d\n", i);
            return 1;
        }
    }
    return 0;
}

// Extract data
int extract_data(uint8_t *data, sensor_data_t *sensor_data) {
    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[3] << 8) | data[4];
    uint16_t humidity_raw = (data[6] << 8) | data[7];

    sensor_data->co2 = (float)co2_raw;
    sensor_data->temperature = -45 + 175 * ((float)temperature_raw / 65535.0);
    sensor_data->humidity = 100 * ((float)humidity_raw / 65535.0);

    return 0;
}

// Log data
int log_data(sensor_data_t sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor_data.co2, sensor_data.temperature, sensor_data.humidity);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Stop periodic measurement
void stop_periodic_measurement() {
    char buf[2];
    buf[0] = (SCD40_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD40_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send stop periodic measurement command: %d\n", result);
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

