#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_scd40();
int read_scd40_data(sensor_data_t *data);
uint8_t calculate_crc8(const uint8_t *data, int len);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
void print_buffer(const circular_buffer_t *buffer);
void control_led(int co2_ppm);
void signal_handler(int signal);
void stop_scd40();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SCD40 sensor
int init_scd40() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait for sensor to start
    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(sensor_data_t *data) {
    char buf[2];
    char read_buf[6];
    uint8_t crc;
    uint16_t co2_raw, temp_raw, humidity_raw;

    // Send read measurement command
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, read_buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Extract raw data
    co2_raw = (read_buf[0] << 8) | read_buf[1];
    temp_raw = (read_buf[2] << 8) | read_buf[3];
    humidity_raw = (read_buf[4] << 8) | read_buf[5];

    // CRC validation
    crc = calculate_crc8(read_buf, 2);
    if (crc != read_buf[2]) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }

    crc = calculate_crc8(read_buf + 3, 2);
    if (crc != read_buf[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Convert raw data to physical units
    data->co2 = co2_raw;
    data->temperature = -45 + 175 * (float)temp_raw / 65535.0;
    data->humidity = 100 * (float)humidity_raw / 65535.0;

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

