void control_led(int co2_ppm) {
    if (co2_ppm > CO2_THRESHOLD) {
        gpioWrite(CO2_LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(CO2_LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Stop SCD40 sensor
void stop_scd40() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
    }
}

