    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(CO2_LED_PIN, PI_OUTPUT);

    sensor_data_t sensor_data;
    // Main loop
    while (!terminate) {
        // Read data from SCD40
        if (read_scd40_data(&sensor_data) == 0) {
            // Add data to circular buffer
            add_to_buffer(&buffer, sensor_data);

            // Control LED
            control_led(sensor_data.co2);

            // Print data
            printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", sensor_data.co2, sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Stop SCD40 sensor
    stop_scd40();

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(CO2_LED_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

