#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define TIMEOUT_US 50000 // 50ms timeout
#define NUM_SAMPLES 1000 // Number of samples for averaging

// Structure to hold temperature data
typedef struct {
    double temperature;
    int valid;
} TemperatureData;

// Global variables
FILE *log_file = NULL;
int sensor_failure_count = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
double read_temperature();
void log_temperature(double temperature);
void handle_signal(int signal);
void cleanup();

// Signal handler for graceful shutdown
void handle_signal(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

// Initializes the pigpio library and configures the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Reads the temperature from the TMP05 sensor
double read_temperature() {
    uint32_t start_time, end_time, cycle_time;
    int high_pulse_count = 0;
    int valid_samples = 0;
    double temperature = 0.0;
    uint32_t last_time = 0;

    // Sample the GPIO pin for a short period
    for (int i = 0; i < NUM_SAMPLES; i++) {
        uint32_t current_time = gpioTick();

        if (current_time - last_time > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for GPIO to change state.\n");
            return -1000.0; // Indicate an error
        }

        if (gpioRead(GPIO_PIN) == 1) {
            start_time = current_time;
            while (gpioRead(GPIO_PIN) == 1 && (current_time - start_time) < TIMEOUT_US) {
                current_time = gpioTick();
            }
            end_time = current_time;
            cycle_time = end_time - start_time;

            if (cycle_time > 0) {
                high_pulse_count++;
            }
        }
        last_time = current_time;
    }

    // Calculate the average high pulse width
    double average_high_pulse_width = (double)high_pulse_count / NUM_SAMPLES;

    // Convert the average pulse width to temperature (linear approximation)
    // This is a placeholder; replace with the actual TMP05 formula
    temperature = average_high_pulse_width * 10.0; // Example conversion

    // Validate the temperature reading
    if (temperature < -40.0 || temperature > 150.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -1000.0; // Indicate an error
    }

    return temperature;
}

// Logs the temperature reading to a file
void log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        double temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            log_temperature(temperature);
            sensor_failure_count = 0; // Reset failure count on success
        } else {
            sensor_failure_count++;
            fprintf(stderr, "Sensor failure count: %d\n", sensor_failure_count);

            if (sensor_failure_count >= 3) {
                fprintf(stderr, "SENSOR MALFUNCTION\n");
                if (log_file != NULL) {
                    fprintf(log_file, "SENSOR MALFUNCTION\n");
                    fflush(log_file);
                }
                sensor_failure_count = 3; // Prevent further logging
            }
        }

        sleep(5); // Sample every 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

