#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define CRC_POLYNOMIAL 0x31
#define OFFSET_AMPLITUDE_TEMP 2.0
#define OFFSET_AMPLITUDE_HUMIDITY 5.0
#define OFFSET_PERIOD 3600.0 // 1 hour
#define SAMPLE_INTERVAL 5.0 // seconds
#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
uint8_t crc8(const uint8_t *data, int len);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
void add_offset(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (retry %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            retries++;
            continue;
        }

        gpioDelay(15000); // Wait 15ms

        if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
            fprintf(stderr, "I2C read failed (retry %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            retries++;
            continue;
        }

        // CRC validation
        if (crc8((uint8_t *)buffer, 2) != buffer[2] || crc8((uint8_t *)buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC validation failed (retry %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            retries++;
            continue;
        }

        *temperature = (buffer[0] << 8) | buffer[1];
        *humidity = (buffer[3] << 8) | buffer[4];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    *temperature = NAN;
    *humidity = NAN;
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

// Function to convert raw humidity to percent relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to add sinusoidal offset
void add_offset(float *temperature, float *humidity) {
    time_t now = time(NULL);
    double time_seconds = (double)now;
    double offset_temp = OFFSET_AMPLITUDE_TEMP * sin(2 * M_PI * time_seconds / OFFSET_PERIOD);
    double offset_humidity = OFFSET_AMPLITUDE_HUMIDITY * sin(2 * M_PI * time_seconds / OFFSET_PERIOD);
    *temperature += offset_temp;
    *humidity += offset_humidity;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (isnan(temperature) || isnan(humidity)) {
        fprintf(log_file, "%s,NaN,NaN\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    }
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);
            add_offset(&temperature, &humidity);
            log_data(temperature, humidity);
        } else {
            log_data(NAN, NAN);
        }

        gpioDelay((int)(SAMPLE_INTERVAL * 1000)); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

