    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "ERROR: I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temp, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(i2c_handle, TEMP_CMD, &raw_temp) != 0) {
            fprintf(stderr, "ERROR: Failed to read temperature\n");
            continue; // Retry on next cycle
        }

        // Read humidity
        if (read_sensor_data(i2c_handle, HUMID_CMD, &raw_humidity) != 0) {
            fprintf(stderr, "ERROR: Failed to read humidity\n");
            continue; // Retry on next cycle
        }

        // Convert data
        temperature = convert_temperature(raw_temp);
        humidity = convert_humidity(raw_humidity);

        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "ERROR: Failed to log data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "ERROR: Could not open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with timeout
int read_sensor_data(int handle, uint8_t command, uint16_t *data) {
    uint8_t buffer[3];
    int result;
    int retries = 0;

    // Send measurement command
    result = i2cWriteByte(handle, command);
    if (result != 0) {
        fprintf(stderr, "ERROR: I2C write failed (command): %d\n", result);
        return -1;
    }

    // Wait for measurement (datasheet specifies 20ms for high precision mode)
    gpioDelay(25000); // 25ms

    // Read data with timeout
    while (retries < 5) {
        result = i2cReadDevice(handle, (char *)buffer, 3);
        if (result == 3) {
            // Verify CRC
            uint8_t crc = crc8(buffer, 2);
            if (crc != buffer[2]) {
                fprintf(stderr, "ERROR: CRC check failed\n");
                return -1;
            }

            // Combine MSB and LSB
            *data = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "ERROR: I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(20000); // 20ms delay
            retries++;
        }
    }

    fprintf(stderr, "ERROR: I2C read failed after multiple retries\n");
    return -1; // Failure after retries
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Log data to CSV file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "ERROR: Could not open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Reset sensor
void reset_sensor(int handle) {
    i2cWriteByte(handle, 0xFE); // Reset command
    gpioDelay(10000); // Wait 10ms for reset to complete
}

