        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD & 0xFF); // LSB
    if (result != 0) {
        fprintf(stderr, "Error writing LSB of measurement command: %d\n", result);
        return -1;
