#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_response(int handle, char *buffer, int count);
int validate_crc(char *data, int len);
sensor_data_t process_data(char *buffer);
void log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read response from the sensor
int read_response(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading response: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8
int validate_crc(char *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", crc, data[len - 1]);
        return -1;
    }
    return 0;
}

// Process raw data into sensor data
sensor_data_t process_data(char *buffer) {
    sensor_data_t data;
    data.pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data.status = (uint16_t)((buffer[6] << 8) | buffer[7]);
    return data;
}

// Log data to file
void log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa, Temperature: %.2f °C, Status: 0x%04X\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.pressure / 20.0, data.temperature / 200.0, data.status);
    fflush(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        char buffer[9];
        sensor_data_t data;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for conversion (45 ms)
        gpioDelay(45000); // 45 ms

        // Read response
        if (read_response(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Error reading response, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(buffer, 9) != 0) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Process data
        data = process_data(buffer);

        // Log data
        log_data(log_file, data);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

