            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Process data
        data = process_data(buffer);

        // Log data
        log_data(log_file, data);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

