#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_pressure(float *pressure);
int read_temperature(float *temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function to initialize the LPS33HW sensor
int initialize_sensor() {
    // Enable continuous data acquisition (ODR = 100 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x84) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Function to read pressure data from the sensor
int read_pressure(float *pressure) {
    char buffer[3];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    int32_t raw_pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
    *pressure = (float)raw_pressure / 4096.0; // Convert to hPa
    return 0;
}

// Function to read temperature data from the sensor
int read_temperature(float *temperature) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    int16_t raw_temperature = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);
    *temperature = (float)raw_temperature / 100.0; // Convert to degrees Celsius
    return 0;
}

// Function to log data to a file
int log_data(float pressure, float temperature) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for logging\n");
        return -1;
    }

    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f \u00b0C\n", timestamp, pressure, temperature);
    fflush(fp); // Flush the buffer to ensure data is written to the file
    fclose(fp);
    return 0;
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&sensor_data.pressure) == 0 && read_temperature(&sensor_data.temperature) == 0) {
            // Log the data
            if (log_data(sensor_data.pressure, sensor_data.temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

