#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_CONT_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define SCD30_CMD_STOP_CONT_MEASUREMENT 0x0104

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 5

// CO2 thresholds for ventilation control
#define CO2_LOW_THRESHOLD 800
#define CO2_HIGH_THRESHOLD 1200

