    char cmd[2] = {SCD30_CMD_STOP_CONT_MEASUREMENT >> 8, SCD30_CMD_STOP_CONT_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop continuous measurement: %d\n", result);
        return 1;
    }
    return 0;
}

