    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Control ventilation based on CO2 level
int control_ventilation(sensor_data_t data) {
    if (data.co2 < CO2_LOW_THRESHOLD) {
        printf("Ventilation OFF\n");
    } else if (data.co2 >= CO2_LOW_THRESHOLD && data.co2 <= CO2_HIGH_THRESHOLD) {
        printf("Ventilation LOW\n");
    } else {
        printf("Ventilation HIGH\n");
    }
    return 0;
}

