#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SDP32 I2C address
#define SDP32_ADDR 0x21

// I2C bus
#define I2C_BUS 1

// Default sampling interval (in milliseconds)
#define DEFAULT_INTERVAL 1000

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t scale_factor;
} sdp32_data_t;

// Global variables
int i2c_handle;
int sampling_interval = DEFAULT_INTERVAL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sdp32(sdp32_data_t *data);
int verify_crc(uint8_t *data, int len, uint8_t crc);
void print_data(sdp32_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SDP32
int read_sdp32(sdp32_data_t *data) {
    char buf[9];
    int result = i2cReadDevice(i2c_handle, buf, 9);

    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Extract data
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = buf[6];

    // Verify CRC
    if (verify_crc((uint8_t *)buf, 3, buf[2]) != 0 ||
        verify_crc((uint8_t *)buf + 3, 3, buf[5]) != 0 ||
        verify_crc((uint8_t *)buf + 6, 2, buf[8]) != 0) {
        fprintf(stderr, "CRC verification failed\n");
        return -1;
    }

    return 0;
}

// Verify CRC-8
int verify_crc(uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = crc8(data, len);
    return (calculated_crc != crc) ? -1 : 0;
}

// Print data with timestamp
void print_data(sdp32_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Pressure: %d Pa, Temperature: %d °C, Scale Factor: %d\n",
           timestamp, data.pressure, data.temperature, data.scale_factor);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        sampling_interval = atoi(argv[1]);
        if (sampling_interval <= 0) {
            fprintf(stderr, "Invalid sampling interval. Using default: %d ms\n", DEFAULT_INTERVAL);
            sampling_interval = DEFAULT_INTERVAL;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sdp32_data_t data;

    // Main loop
    while (!terminate) {
        if (read_sdp32(&data) == 0) {
            print_data(data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(sampling_interval * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

