#include <time.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the HDC1000 sensor
int init_hdc1000() {
    // Configure the sensor for temperature and humidity measurement
    // 14-bit resolution, enable temperature and humidity measurement
    uint16_t config_value = 0x0000; // Default configuration
    if (i2cWriteWordData(i2c_handle, CONFIGURATION_REG, config_value) != 0) {
        fprintf(stderr, "Error writing to configuration register\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int read_hdc1000(float *temperature, float *humidity) {
    // Trigger temperature and humidity measurement
    if (i2cWriteByte(i2c_handle, 0x00) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for at least 20ms for conversion
    gpioDelay(20000); // 20ms

    // Read temperature data
    uint16_t raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
    if (raw_temperature == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    // Read humidity data
    uint16_t raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_REG);
    if (raw_humidity == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HDC1000 sensor
    if (init_hdc1000() != 0) {
        fprintf(stderr, "HDC1000 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_hdc1000(&temperature, &humidity) == 0) {
            // Log temperature and humidity to console
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

