// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define MEASUREMENT_DELAY_MS 20
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7051_address;
    int measurement_delay_ms;
    int retry_count;
    int retry_delay_ms;
} config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from Si7051 sensor
int read_temperature(float *temperature) {
    int raw_temperature;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD) != 0) {
            fprintf(stderr, "Error writing temperature command (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

        raw_temperature = i2cReadWordData(i2c_handle, 0); // Read temperature data
        if (raw_temperature < 0) {
            fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", retries + 1, raw_temperature);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Convert raw temperature to Celsius
        *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Log temperature to console
void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

