#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX90821_ADDR 0x60

// Define the pressure range
#define MIN_PRESSURE 200.0
#define MAX_PRESSURE 250.0

// Define the log file name
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_kPa;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_pressure(float *pressure);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read pressure from the sensor
int read_pressure(float *pressure) {
    char buf[2];
    int bytes_read;
    int retries = 3;

    while (retries > 0) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            // Convert the raw data to pressure (kPa)
            int16_t raw_pressure = (buf[0] << 8) | buf[1];
            *pressure = (float)raw_pressure / 100.0; // Example conversion, adjust as needed
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed, retrying... (%d retries left)\n", retries);
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait before retrying
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C initialization failed after retry\n");
                return -1; // Fatal error
            }
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure after retries
}

// Function to log data to the CSV file
int log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }

        // Check if the file is newly created and write the header if needed
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }
        rewind(log_file);
    }

    fprintf(log_file, "%s,%.2f\n", timestamp_str, data.pressure_kPa);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        float pressure;

        // Read pressure from the sensor
        if (read_pressure(&pressure) == 0) {
            data.pressure_kPa = pressure;
            data.timestamp = time(NULL);

            // Log the data
            if (log_data(data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Check for safe pressure range
            if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
                fprintf(stderr, "WARNING: Pressure out of safe range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

