#include <sys/stat.h>
#include <sys/types.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE (1024 * 1024) // 1 MB
#define MEASUREMENT_DELAY_MS 40
#define READ_DELAY_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
int check_log_size();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[4];
        sensor_data_t data;

        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Convert raw data to temperature and humidity
            uint16_t raw_temp = (sensor_data[0] << 8) | sensor_data[1];
            uint16_t raw_humidity = (sensor_data[2] << 8) | sensor_data[3];

            data.temperature = convert_temperature(raw_temp);
            data.humidity = convert_humidity(raw_humidity);

            // Log data
            if (log_data(data.temperature, data.humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Check log size and truncate if necessary
        if (check_log_size() != 0) {
            fprintf(stderr, "Failed to check or truncate log file\n");
        }

        // Wait for the next measurement
        gpioDelay(READ_DELAY_S * 1000000); // microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

