int read_sensor_data(uint8_t *data) {
    // Trigger measurement (no command needed for HIH6130, just read)
    if (i2cReadDevice(i2c_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", i2c_handle);
        return 1;
    }

    // Check status bits
    uint8_t status = (data[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Sensor status error: %d\n", status);
        return 1;
    }

    return 0;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return ((float)raw_temp / 16383) * 165 - 40;
}

// Convert raw humidity data to percentage
float convert_humidity(uint16_t raw_humidity) {
    return ((float)raw_humidity / 16383) * 100;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);

    return 0;
}

// Check log size and truncate if necessary
int check_log_size() {
    struct stat st;
    if (stat(LOG_FILE, &st) == 0) {
        if (st.st_size > MAX_LOG_SIZE) {
            FILE *fp = fopen(LOG_FILE, "w");
            if (fp == NULL) {
                fprintf(stderr, "Failed to open log file for truncation\n");
                return 1;
            }
            fclose(fp);
        }
    } else {
        fprintf(stderr, "Failed to get log file size\n");
        return 1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

