#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x04
#define DEVICE_ID 0x5441
#define LOG_FILE "greenhouse_temps.dat"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
int read_temperature(float *temperature);
int log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the TMP117 device ID
int verify_device_id() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading device ID: %d\n", result);
        return -1;
    }

    uint16_t id = (buf[0] << 8) | buf[1];
    if (id != DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%04X (expected 0x%04X)\n", id, DEVICE_ID);
        return -1;
    }

    printf("Device ID verified: 0x%04X\n", id);
    return 0;
}

// Read the temperature from the TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 8.0f; // Convert to Celsius

    return 0;
}

// Log the temperature to a binary file
int log_temperature(float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature, retrying...\n");
        }

        sleep(60);
    }

    // Cleanup
    printf("Closing I2C handle...\n");
    i2cClose(i2c_handle);

    printf("Closing log file...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

