#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 commands
#define SHT40_MEASURE_HIGH_PRECISION 0xFD

// CRC-8 polynomial: 0x31 (x^8 + x^5 + x^4 + 1)
#define CRC_POLYNOMIAL 0x31

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} SHT40Data;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c(int addr);
int write_i2c(int handle, uint8_t cmd);
int read_i2c(int handle, uint8_t *buf, int count);
SHT40Data read_sht40(int handle);
uint8_t crc8(const uint8_t *data, int len);
void log_data(SHT40Data data);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c(int addr) {
    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write a command to the SHT40
int write_i2c(int handle, uint8_t cmd) {
    int result = i2cWriteByte(handle, cmd);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SHT40
int read_i2c(int handle, uint8_t *buf, int count) {
    int result = i2cReadDevice(handle, (char *)buf, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHT40
SHT40Data read_sht40(int handle) {
    SHT40Data data = {0.0, 0.0};
    uint8_t buf[6];

    // Send measurement command
    if (write_i2c(handle, SHT40_MEASURE_HIGH_PRECISION) != 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        return data; // Return default values on error
    }

    // Wait for measurement (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read data
    if (read_i2c(handle, buf, 6) != 0) {
        fprintf(stderr, "Failed to read data from SHT40\n");
        return data; // Return default values on error
    }

    // CRC validation
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return data; // Return default values on error
    }

    // Convert data
    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    uint16_t hum_raw = (buf[3] << 8) | buf[4];

    data.temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    data.humidity = 100.0 * (float)hum_raw / 65535.0;

    return data;
}

// CRC-8 validation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to file
void log_data(SHT40Data data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c(SHT40_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        SHT40Data data = read_sht40(i2c_handle);
        if (data.temperature != 0.0 || data.humidity != 0.0) {
            log_data(data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

