#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 command for high precision measurement
#define SHTC3_MEASURE_CMD 0x7866

// CRC-8 polynomial: 0x31 (x^8 + x^5 + x^4 + 1)
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_shtc3(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
void log_data(sensor_data_t data);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// SHTC3 data reading function
int read_shtc3(sensor_data_t *data) {
    uint8_t cmd[2] = {(SHTC3_MEASURE_CMD >> 8) & 0xFF, SHTC3_MEASURE_CMD & 0xFF};
    uint8_t buffer[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for measurement (at least 12.4 ms)
    gpioDelay(15000); // 15 ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    int temperature_raw = (buffer[0] << 8) | buffer[1];
    int humidity_raw = (buffer[3] << 8) | buffer[4];

    data->temperature = 175.0 * temperature_raw / 65535.0 - 45.0;
    data->humidity = 100.0 * humidity_raw / 65535.0;

    return 0;
}

// Data logging function
void log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Data printing function
void print_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_shtc3(&sensor_data) == 0) {
            // Validate data
            if (sensor_data.temperature >= -40.0 && sensor_data.temperature <= 125.0 &&
                sensor_data.humidity >= 0.0 && sensor_data.humidity <= 100.0) {
                print_data(sensor_data);
                log_data(sensor_data);
            } else {
                fprintf(stderr, "Out-of-range values: Temperature=%.2f, Humidity=%.2f\n", sensor_data.temperature, sensor_data.humidity);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

