#define SPEED_SCALE_FACTOR 0.1 // Example scaling factor
#define TEMPERATURE_SCALE_FACTOR 0.01 // Example scaling factor
#define LOG_FILE "mag_temp_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(float *rotational_speed, float *temperature);
int log_data(float rotational_speed, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float rotational_speed;
    float temperature;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Rotational Speed (RPM),Temperature (C)\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.rotational_speed, &sensor_data.temperature) == 0) {
            // Log the data
            if (log_data(sensor_data.rotational_speed, sensor_data.temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for one second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor() {
    char buf[2];
    buf[0] = SI7202_REG_CONFIG;
    buf[1] = SI7202_CONFIG_VALUE;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to sensor config register: %d\n", result);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(float *rotational_speed, float *temperature) {
    char buf[1];
    char read_buf[2];
    int result;

    // Read rotational speed
    buf[0] = SI7202_REG_SPEED;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to speed register: %d\n", result);
        *rotational_speed = NAN;
        return 1;
    }
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read speed data: %d\n", result);
        *rotational_speed = NAN;
        return 1;
    }
    *rotational_speed = (float)((read_buf[0] << 8) | read_buf[1]) * SPEED_SCALE_FACTOR;

    // Read temperature
    buf[0] = SI7202_REG_TEMP;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to temperature register: %d\n", result);
        *temperature = NAN;
        return 1;
    }
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        *temperature = NAN;
        return 1;
    }
    *temperature = (float)((read_buf[0] << 8) | read_buf[1]) * TEMPERATURE_SCALE_FACTOR;

    return 0;
}

// Log data to file
int log_data(float rotational_speed, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, rotational_speed, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

