#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold program state
typedef struct {
    int i2c_handle;
    char log_file[64];
} ProgramState;

// Function prototypes
int initialize_i2c();
float read_temperature();
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    int handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Reads the temperature from the TMP117 sensor
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = raw_temp * 0.0078125;

    return temperature;
}

// Logs the temperature to a file
int log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    FILE *fp;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);

    return 0;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    ProgramState state = { .i2c_handle = -1, .log_file = LOG_FILE };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = -1000.0; // Initialize to an invalid value
        int retry = 0;

        // Attempt to initialize I2C with retries
        while (i2c_handle < 0 && retry < RETRY_COUNT) {
            i2c_handle = initialize_i2c();
            if (i2c_handle < 0) {
                fprintf(stderr, "I2C initialization failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                gpioDelay(1000); // Wait 1 second before retrying
                retry++;
            }
        }

        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to initialize I2C after multiple retries. Exiting.\n");
            break; // Exit the loop if I2C initialization fails
        }

        // Read temperature
        temperature = read_temperature();

        if (temperature > -999.0) {
            // Log temperature
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping logging.\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

