// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_slpm;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads data from the sensor
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Processes the raw sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract flow and temperature values from the raw data
    int16_t raw_flow = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[2] << 8) | data[3];

    // Convert raw values to SLPM and °C (refer to Honeywell HAFUHH0025PA3 datasheet)
    sensor_data.flow_slpm = (float)raw_flow / 100.0; // Example conversion
    sensor_data.temperature_c = (float)raw_temperature / 10.0; // Example conversion

    return sensor_data;
}

// Logs the data to a file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, data->flow_slpm, data->temperature_c);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup function to close I2C and file handles
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[4];
        sensor_data_t processed_data;

        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            if (log_data(&processed_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Attempting to re-initialize I2C...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit the loop if re-initialization fails
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

