#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 100000 // 100ms timeout
#define MAX_RETRIES 3

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int humidity_decimal;
    int temperature;
    int temperature_decimal;
    int checksum;
} DHT11Data;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

// Function prototypes
int dht11_read(DHT11Data *data);
int dht11_start();
int dht11_read_data(unsigned char *data);
int dht11_decode_data(unsigned char *data, DHT11Data *dht11_data);
int dht11_checksum(DHT11Data *dht11_data);
int log_data(DHT11Data *dht11_data);
int log_error(int status_code, const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the pigpio library and GPIO pin
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT); // Set GPIO as output initially
    gpioSetPullUpDown(DHT11_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to cleanup GPIO resources and close files
void cleanup() {
    gpioSetMode(DHT11_GPIO, PI_INPUT); // Set GPIO back to input
    gpioSetPullUpDown(DHT11_GPIO, PI_PUD_OFF); // Disable pull-up resistor

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
    cleanup();
    exit(0);
}

// Function to read data from the DHT11 sensor
int dht11_read(DHT11Data *data) {
    unsigned char data_buffer[5] = {0, 0, 0, 0, 0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (dht11_start() == 0) {
            if (dht11_read_data(data_buffer) == 0) {
                if (dht11_decode_data(data_buffer, data) == 0) {
                    if (dht11_checksum(data) == 0) {
                        return 0; // Success
                    } else {
                        log_error(4, "Checksum failure");
                    }
