                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC-8 checksum
int validate_crc8(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc8(data, len);
    return (calculated_crc == crc);
}

// Function to convert raw data to float
int convert_data_to_float(const uint8_t *data, float *value) {
    uint16_t raw_value = (data[0] << 8) | data[1];
    *value = -45.0 + (175.0 * (float)raw_value / 65535.0);
    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection(1, SHT31_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht31d_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        float temperature, humidity;

        // Send measurement command
        if (send_measurement_command(i2c_handle) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement (at least 15 ms)
        gpioDelay(20); // Wait 20 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc8(data, 2, data[2])) {
            fprintf(stderr, "Temperature CRC validation failed\n");
            continue;
        }

        // Validate CRC for humidity
        if (!validate_crc8(data + 3, 2, data[5])) {
            fprintf(stderr, "Humidity CRC validation failed\n");
            continue;
        }

        // Convert data to float
        if (convert_data_to_float(data, &temperature) != 0) {
            fprintf(stderr, "Failed to convert temperature data\n");
            continue;
        }
        if (convert_data_to_float(data + 3, &humidity) != 0) {
            fprintf(stderr, "Failed to convert humidity data\n");
            continue;
        }

        // Log data
        if (log_data(log_file, temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

