#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define SAMPLE_RATE 1 // seconds
#define BUFFER_SIZE 60
#define TEMP_HYSTERESIS 2.0
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
float read_temperature();
float calculate_average();
void control_fan(float average_temperature);
void signal_handler(int signal);
void initialize();
void cleanup();

// Function to initialize the system
void initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        exit(1);
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
}

// Function to read temperature from LM75B
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return NAN; // Return NaN on failure
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125; // Each bit is 0.125 degrees

    return temperature;
}

// Function to calculate the running average
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    if (buffer_count > 0) {
        return sum / buffer_count;
    } else {
        return NAN; // Return NaN if the buffer is empty
    }
}

// Function to control the fan based on temperature
void control_fan(float average_temperature) {
    static int fan_on = 0; // Track fan state

    if (isnan(average_temperature)) {
        fprintf(stderr, "Invalid temperature reading, not controlling fan\n");
        return;
