#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x43
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define HYSTERESIS_DELAY 5 // seconds

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_fd);
float convert_temperature(int raw_temp);
void control_led(int gpio_pin, int state);
void log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read temperature from STTS2004 sensor
int read_temperature(int i2c_fd) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1; // Indicate error
    }

    return (buf[0] << 8) | buf[1]; // Combine the two bytes into a 16-bit value
}

// Function to convert raw temperature data to Celsius
float convert_temperature(int raw_temp) {
    // The STTS2004 returns a 12-bit temperature value, left-aligned.
    // Shift right by 4 bits to get the correct value.
    int16_t temp = (int16_t)(raw_temp >> 4);
    return (float)temp * 0.0625; // Each bit represents 0.0625 degrees Celsius
}

// Function to control the LED state
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log the temperature to stdout
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int led_state = 0; // 0 = off, 1 = on
    float last_temperature = 0.0;

    // Main loop
    while (!terminate) {
        int raw_temp = read_temperature(i2c_fd);
        if (raw_temp >= 0) {
            float temperature = convert_temperature(raw_temp);
            log_temperature(temperature);

            // Temperature control with hysteresis
            if (temperature > TEMP_THRESHOLD_HIGH && led_state == 0) {
                control_led(LED_GPIO, 1); // Turn LED on
                led_state = 1;
                last_temperature = temperature; // Update last temperature
                sleep(HYSTERESIS_DELAY);
            } else if (temperature < TEMP_THRESHOLD_LOW && led_state == 1) {
                control_led(LED_GPIO, 0); // Turn LED off
                led_state = 0;
                last_temperature = temperature; // Update last temperature
                sleep(HYSTERESIS_DELAY);
            } else if (temperature > last_temperature + 0.01 || temperature < last_temperature - 0.01) {
                // Check if temperature has changed significantly
                last_temperature = temperature;
            }
        } else {
            fprintf(stderr, "Error reading temperature, retrying...\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_fd);
    control_led(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

