#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define MEASUREMENT_DELAY_MS 45
#define DATA_FILE "flow_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
sensor_data_t process_data(const char *data);
int validate_crc(const char *data, int length);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const char *data, int length) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }

    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    return 0;
}

// Process raw data and convert to physical units
sensor_data_t process_data(const char *data) {
    sensor_data_t sensor_data;
    // Extract differential pressure
    int16_t dp_raw = (data[0] << 8) | data[1];
    sensor_data.differential_pressure = (float)dp_raw / 20.0; // Scale factor from datasheet

    // Extract temperature
    int16_t temp_raw = (data[3] << 8) | data[4];
    sensor_data.temperature = (float)temp_raw / 200.0; // Scale factor from datasheet

    return sensor_data;
}

// Validate CRC checksum
int validate_crc(const char *data, int length) {
    uint8_t calculated_crc = crc8(data, length - 1);
    uint8_t received_crc = data[length - 1];

    if (calculated_crc != received_crc) {
        fprintf(stderr, "CRC check failed! Calculated: 0x%02X, Received: 0x%02X\n", calculated_crc, received_crc);
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa, %.2f °C\n", timestamp, data->differential_pressure, data->temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        // Wait for measurement to complete
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to microseconds

        // Read data from sensor
        char data[9];
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Validate CRC checksum
        if (validate_crc(data, 9) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            break;
        }

        // Process data
        sensor_data_t sensor_data = process_data(data);

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
            break;
        }

        // Wait before next measurement
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

