#define MEASURE_HUMIDITY_CMD 0xE5
#define MEASURE_TEMPERATURE_CMD 0xE3
#define READ_TEMP_FROM_RH_CMD 0xE0
#define LOG_FILE "environment.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *raw_humidity, uint16_t *raw_temperature);
float convert_humidity(uint16_t raw_humidity);
float convert_temperature(uint16_t raw_temperature);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read raw sensor data
int read_sensor_data(uint16_t *raw_humidity, uint16_t *raw_temperature) {
    char buf[2];
    int result;
    int retries = 0;

    // Measure Humidity
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEASURE_HUMIDITY_CMD);
        if (result == 0) break;
        fprintf(stderr, "Error writing humidity command, retry %d\n", retries + 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) return -1;

    gpioDelay(20000); // Wait 20ms

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Error reading humidity data, retry %d\n", retries + 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) return -1;
    *raw_humidity = (buf[0] << 8) | buf[1];

    // Measure Temperature
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEASURE_TEMPERATURE_CMD);
        if (result == 0) break;
        fprintf(stderr, "Error writing temperature command, retry %d\n", retries + 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) return -1;

    gpioDelay(20000); // Wait 20ms

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Error reading temperature data, retry %d\n", retries + 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) return -1;
    *raw_temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return ((125.0 * raw_humidity) / 65536.0) - 6.0;
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return ((175.72 * raw_temperature) / 65536.0) - 46.85;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_humidity, raw_temperature;

        // Read sensor data
        if (read_sensor_data(&raw_humidity, &raw_temperature) == 0) {
            // Convert data
            float humidity = convert_humidity(raw_humidity);
            float temperature = convert_temperature(raw_temperature);

            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            log_data(-999.0, -999.0); // Log error values
        }

        // Sleep for 60 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

