#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// STS40 I2C address
#define STS40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// Measurement command (High Precision)
#define MEASURE_CMD 0xFD

// CRC8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int crc8(const uint8_t *data, int len);
int read_sts40(int i2c_handle, float *temperature);
int log_temperature(FILE *log_file, float temperature);
void signal_handler(int signal);

// CRC8 calculation function
int crc8(const uint8_t *data, int len) {
    int crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40 sensor
int read_sts40(int i2c_handle, float *temperature) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t buffer[3];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 3 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC check
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

// Function to log temperature to file
int log_temperature(FILE *log_file, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write to log file
    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    float temperature;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, STS40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature from sensor
        result = read_sts40(i2c_handle, &temperature);
        if (result == 0) {
            // Log temperature to file
            log_temperature(log_file, temperature);
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

