#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_MS 1000
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int initialize();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, size_t len);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD >> 8); // MSB
    if (result < 0) {
        fprintf(log_file, "%ld,ERROR,Failed to write MSB of measurement command: %d\n", time(NULL), result);
        fflush(log_file);
        return 1;
    }
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD & 0xFF); // LSB
    if (result < 0) {
        fprintf(log_file, "%ld,ERROR,Failed to write LSB of measurement command: %d\n", time(NULL), result);
        fflush(log_file);
        return 1;
    }

    // Wait for measurement (at least 50ms)
    gpioDelay(50000); // 50ms

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 9);
    if (result < 0) {
        fprintf(log_file, "%ld,ERROR,Failed to read sensor data: %d\n", time(NULL), result);
        fflush(log_file);
        return 1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 3) != buffer[8]) {
        fprintf(log_file, "%ld,ERROR,CRC validation failed\n", time(NULL));
        fflush(log_file);
        return 1;
    }

    // Convert data
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data->pressure_Pa = (float)raw_pressure / 240.0; // Scale factor from datasheet
    data->temperature_C = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Function to log data to file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure_Pa, data->temperature_C);
    fflush(log_file);

    return 0;
}

int main() {
    sensor_data_t sensor_data;

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Monitoring air duct pressure... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

