#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// SCD40 I2C address
#define SCD40_I2C_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// Circular buffer size
#define BUFFER_SIZE 100

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 5

// CSV file path
#define CSV_FILE_PATH "/var/log/scd40_data/data.csv"

// Error log file path
#define ERROR_LOG_PATH "/var/log/scd40_error.log"

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int mutex; // Mutex for thread safety
} circular_buffer_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_measurement(sensor_data_t *data);
int stop_periodic_measurement();
int buffer_init(circular_buffer_t *buffer);
