int log_error(const char *message);
void *logging_thread(void *arg);
void signal_handler(int signal);

// CRC-8 calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    unsigned char command[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        log_error("Failed to send start periodic measurement command");
        return -1;
    }
    return 0;
}

// Read measurement
int read_measurement(sensor_data_t *data) {
    unsigned char command[2] = {0xE4, 0xB8};
    unsigned char buffer[9];
