    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // CRC check
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 2) != buffer[8]) {
        log_error("CRC check failed");
        return -1;
    }

    // Convert data
    unsigned int co2 = (buffer[0] << 8) | buffer[1];
    unsigned int temperature = (buffer[3] << 8) | buffer[4];
    unsigned int humidity = (buffer[6] << 8) | buffer[7];

    data->co2 = (float)co2;
    data->temperature = -45 + 175 * ((float)temperature / 65535.0);
    data->humidity = 100 * ((float)humidity / 65535.0);

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    unsigned char command[2] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        log_error("Failed to send stop periodic measurement command");
        return -1;
    }
    return 0;
}

// Initialize circular buffer
int buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    buffer->mutex = 0; // Initialize mutex to 0 (unlocked)
    return 0;
}

// Add data to circular buffer
int buffer_add(circular_buffer_t *buffer, sensor_data_t data) {
    if (buffer->mutex != 0) {
        log_error("Buffer mutex is locked, skipping add operation");
        return -1;
    }
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    buffer->mutex = 1; // Lock the mutex after adding
    return 0;
}

// Get data from circular buffer
int buffer_get(circular_buffer_t *buffer, int index, sensor_data_t *data) {
    if (buffer->mutex != 0) {
        log_error("Buffer mutex is locked, skipping get operation");
        return -1;
    }
    if (index < 0 || index >= buffer->count) {
        log_error("Index out of bounds");
        return -1;
    }

    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    *data = buffer->buffer[actual_index];
    buffer->mutex = 1; // Lock the mutex after getting
    return 0;
}

// Check if circular buffer is empty
int buffer_is_empty(circular_buffer_t *buffer) {
    return buffer->count == 0;
}

// Check if circular buffer is full
int buffer_is_full(circular_buffer_t *buffer) {
    return buffer->count == BUFFER_SIZE;
}

