        log_error("Failed to open CSV file for writing");
        return -1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (°C),Humidity (%%RH)\n");
    }

    for (int i = 0; i < count; i++) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
                data[i].co2, data[i].temperature, data[i].humidity);
    }

    fclose(fp);
    return 0;
}

// Log error to file
int log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_PATH, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);

    fclose(fp);
    return 0;
}

// Logging thread function
void *logging_thread(void *arg) {
    circular_buffer_t *buffer = (circular_buffer_t *)arg;
    sensor_data_t data[BUFFER_SIZE];
    int i;

    while (running) {
        sleep(60); // Wait for 60 seconds

        if (buffer_is_empty(buffer)) {
            continue; // No data to write
        }

        // Copy data from buffer to local array
        for (i = 0; i < buffer->count; i++) {
            buffer_get(buffer, i, &data[i]);
        }

        // Write to CSV file
        if (write_to_csv(CSV_FILE_PATH, data, buffer->count) != 0) {
            log_error("Failed to write data to CSV file");
        }

        // Reset buffer
        buffer_init(buffer);
    }

    return NULL;
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

int main() {
    sensor_data_t sensor_data;
    circular_buffer_t buffer;

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    if (buffer_init(&buffer) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create logging thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, logging_thread, &buffer) != 0) {
        log_error("Failed to create logging thread");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        if (read_measurement(&sensor_data) == 0) {
            // Add data to circular buffer
            if (buffer_add(&buffer, sensor_data) != 0) {
                log_error("Failed to add data to circular buffer");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Join logging thread
    pthread_join(thread_id, NULL);

    // Write remaining data to CSV file
    if (!buffer_is_empty(&buffer)) {
        sensor_data_t data[BUFFER_SIZE];
        int i;
        for (i = 0; i < buffer->count; i++) {
            buffer_get(&buffer, i, &data[i]);
        }
        write_to_csv(CSV_FILE_PATH, data, buffer->count);
    }

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

