#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define ICP_10125_ADDR 0x69
#define ICP_10125_REG_PRESSURE 0x00
#define ICP_10125_REG_TEMP 0x03
#define ICP_10125_REG_CONFIG 0x06
#define ICP_10125_CMD_MEASURE 0x07
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 95000.0f
#define MEASUREMENT_DELAY_US 20000 // 20ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_sensor_data(uint8_t *data);
float calculate_crc(uint8_t data[], int len);
float convert_pressure(uint8_t data[]);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_value;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP_10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    if (i2cWriteByteData(i2c_handle, ICP_10125_REG_CONFIG, ICP_10125_CMD_MEASURE) < 0) {
        fprintf(stderr, "Error writing to I2C\n");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);

    int bytes_read = i2cReadI2CBlockData(i2c_handle, ICP_10125_REG_PRESSURE, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to calculate CRC
float calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (float)crc;
}

// Function to convert pressure data
float convert_pressure(uint8_t data[]) {
    int32_t raw_pressure = (data[0] << 8) | data[1];
    return (float)raw_pressure / 4096.0f; // Example conversion, adjust as needed
}

// Function to control LED based on pressure
void control_led(float pressure) {
    if (pressure < PRESSURE_THRESHOLD) {
        // 5Hz pattern
        gpioWrite(GPIO_LED, 1);
        gpioDelay(100000); // 100ms
        gpioWrite(GPIO_LED, 0);
        gpioDelay(100000); // 100ms
    } else {
        // 1Hz pattern
        gpioWrite(GPIO_LED, 1);
        gpioDelay(500000); // 500ms
        gpioWrite(GPIO_LED, 0);
        gpioDelay(500000); // 500ms
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Release GPIO
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
