#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int read_temperature(int handle, int reg);
float convert_to_celsius(int raw_temp);
void control_fan(int gpio, float object_temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read temperature from sensor with retries
int read_temperature(int handle, int reg) {
    int raw_temp = -1;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        raw_temp = i2cReadWordData(handle, reg);
        if (raw_temp >= 0) {
            return raw_temp;
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
    return -1;
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Control the cooling fan
void control_fan(int gpio, float object_temp) {
    if (object_temp > TEMP_THRESHOLD_HIGH) {
        gpioWrite(gpio, 1); // Turn fan on
    } else if (object_temp < TEMP_THRESHOLD_LOW) {
        gpioWrite(gpio, 0); // Turn fan off
    }
}

