    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, MLX90614_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Set fan GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read temperature data
        int raw_ambient_temp = read_temperature(i2c_handle, AMBIENT_TEMP_REG);
        int raw_object_temp = read_temperature(i2c_handle, OBJECT_TEMP_REG);

        if (raw_ambient_temp != -1 && raw_object_temp != -1) {
            // Convert to Celsius
            float ambient_temp = convert_to_celsius(raw_ambient_temp);
            float object_temp = convert_to_celsius(raw_object_temp);

            // Control fan
            control_fan(FAN_GPIO, object_temp);

            // Log temperature data
            log_temperature(ambient_temp, object_temp);

            printf("Ambient: %.2f C, Object: %.2f C\n", ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping logging\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

