#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define HUMIDITY_MIN 0.0
#define HUMIDITY_MAX 100.0

// Global variables
int i2c_handle;
int server_socket = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(sensor_data_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void handle_client(int client_socket);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    char cmd[1] = {MEASURE_HIGH_PRECISION};
    char buffer[6];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device (retry %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10000); // Wait 10ms

        bytes_read = i2cReadDevice(i2c_handle, buffer, 6);
        if (bytes_read == 6) {
            uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
            uint16_t raw_humidity = (buffer[3] << 8) | buffer[4];

            data->temperature = convert_temperature(raw_temp);
            data->humidity = convert_humidity(raw_humidity);

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device (retry %d): %d bytes read\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read from SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Function to convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;
    sensor_data_t sensor_data;
    char html_response[2048];

    // Read data from the client (not used in this example, but good practice)
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
    } else {
        perror("Error receiving data");
    }

    // Read sensor data
    if (read_sht40(&sensor_data) == 0) {
        // Clamp humidity to 0-100%
        if (sensor_data.humidity < HUMIDITY_MIN) {
            sensor_data.humidity = HUMIDITY_MIN;
        } else if (sensor_data.humidity > HUMIDITY_MAX) {
            sensor_data.humidity = HUMIDITY_MAX;
        }

        // Format HTML response
        snprintf(html_response, sizeof(html_response), 
                 "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n" 
                 "<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body>" 
                 "<h1>SHT40 Sensor Data</h1>" 
                 "<p>Temperature: %.2f &deg;C</p>" 
                 "<p>Humidity: %.2f %%</p>" 
                 "</body></html>",
                 sensor_data.temperature, sensor_data.humidity);
    } else {
        snprintf(html_response, sizeof(html_response), 
                 "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n" 
                 "<!DOCTYPE html><html><head><title>Error</title></head><body>" 
                 "<h1>Error reading sensor data</h1>" 
                 "</body></html>");
    }

    // Send response to client
    send(client_socket, html_response, strlen(html_response), 0);

    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_socket >= 0) {
        close(server_socket);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    struct sockaddr_in server_address, client_address;
    socklen_t client_len = sizeof(client_address);
    int client_socket;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_socket, 5) < 0) {
        perror("Error listening on socket");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Main loop
    while (!terminate) {
        // Accept connection
        client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        // Handle client connection
        handle_client(client_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

