// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x00
#define TEMPERATURE_REGISTER 0x02
#define HUMIDITY_REGISTER 0x04

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a register from the HDC2010
int read_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write a register to the HDC2010
int write_register(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteI2CBlockData(handle, reg, (char *)&data, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC2010
int read_hdc2010(int handle, float *temperature, float *humidity) {
    uint8_t data[4];
    int retries = 0;
    int result;

    // Configure for temperature and humidity measurement
    while (retries < 3) {
        if (write_register(handle, MEASUREMENT_CONFIG, 0x00) == 0) {
            break;
        } else {
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries >= 3) {
        fprintf(stderr, "Failed to configure HDC2010 after multiple retries.\n");
        return -1;
    }

    // Wait for measurement to complete (at least 7ms)
    gpioDelay(10000); // Wait 10ms

    // Read temperature and humidity data
    while (retries < 3) {
        if (read_register(handle, TEMPERATURE_REGISTER, data, 4) == 0) {
            break;
        } else {
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries >= 3) {
        fprintf(stderr, "Failed to read HDC2010 data after multiple retries.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[2] << 8) | data[3];

    *temperature = ((float)temperature_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humidity_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    // Main loop
    while (!terminate) {
        result = read_hdc2010(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

