#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25

// Define the measurement command
#define MEASURE_COMMAND 0x362F

// Define the CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, int16_t *pressure, int16_t *temperature) {
    uint8_t buffer[6];
    int result;

    // Send the measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_COMMAND >> 8); // MSB
    if (result != 0) {
        fprintf(stderr, "Error writing MSB of measurement command: %d\n", result);
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_COMMAND & 0xFF); // LSB
    if (result != 0) {
        fprintf(stderr, "Error writing LSB of measurement command: %d\n", result);
        return -1;
    }

    // Wait for the measurement to complete (at least 45ms)
    gpioDelay(50); // Wait 50ms

    // Read six bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data from sensor: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        return -1;
    }
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Convert the raw data to pressure and temperature values
    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

int main() {
    int16_t pressure, temperature;
    int result;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from the sensor
        result = read_sdp800(i2c_handle, &pressure, &temperature);
        if (result == 0) {
            // Log the raw pressure and temperature values
            printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 500ms
        gpioDelay(500);
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

