#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define RELAY_GPIO 17
#define SPI_CHANNEL 0
#define SPI_CE 0 // CE0 or CE1
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000000 // 1 MHz * 1000
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
static volatile int running = 1;
static FILE *log_fp = NULL;
static FILE *profile_fp = NULL;
static int spi_handle = -1;

// PID Variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function Prototypes
void signal_handler(int signal);
int init_gpio();
int init_spi();
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void control_relay(double duty_cycle);
void log_data(double temperature, double setpoint, double duty_cycle);
int load_profile(double *times, double *temperatures, int max_points);
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioPWM(RELAY_GPIO, 0); // Initialize relay to OFF
    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read Temperature from MAX6675
double read_temperature() {
    unsigned char data[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiRead(spi_handle, data, 2);
        if (result == 2) {
            // Check for fault bit (bit 0 of data[1])
            if (data[1] & 0x01) {
                fprintf(stderr, "MAX6675 Fault detected!\n");
                return -273.15; // Return absolute zero on fault
            }

            // Convert data to temperature (Celsius)
            int16_t raw_temp = ((data[0] << 8) | data[1]) >> 3;
            double temperature = (double)raw_temp * 0.25;

            return temperature;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "MAX6675 read failed after %d retries.\n", MAX_RETRIES);
    return -273.15; // Return absolute zero on failure
}

// Calculate PID Output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;

    integral += error;
    // Anti-windup
    if (integral > 100) integral = 100;
    if (integral < -100) integral = -100;

    double derivative = error - previous_error;

    double output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Clamp output to 0.0 to 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Control Relay with PWM
void control_relay(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * PWM_RANGE);
    gpioPWM(RELAY_GPIO, pwm_value);
}

// Log Data to CSV File
void log_data(double temperature, double setpoint, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, setpoint, duty_cycle);
    fflush(log_fp); // Ensure data is written to disk immediately
}

// Load Temperature Profile from File
int load_profile(double *times, double *temperatures, int max_points) {
    char line[256];
    int i = 0;

    profile_fp = fopen(PROFILE_FILE, "r");
    if (profile_fp == NULL) {
        fprintf(stderr, "Error opening profile file: %s\n", PROFILE_FILE);
        return -1;
    }

    while (fgets(line, sizeof(line), profile_fp) != NULL && i < max_points) {
        if (sscanf(line, "%lf,%lf", &times[i], &temperatures[i]) == 2) {
            i++;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
        }
    }

    fclose(profile_fp);
    return i;
}

// Cleanup Resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioPWM(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate();
    if (log_fp != NULL) {
        fclose(log_fp);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Temperature(C),Setpoint(C),DutyCycle\n");
    }
    rewind(log_fp);

    // Load temperature profile
    double times[100]; // Assuming a maximum of 100 points
    double temperatures[100];
    int num_points = load_profile(times, temperatures, 100);
    if (num_points <= 0) {
        fprintf(stderr, "Error loading profile, using constant temperature.\n");
        // Use a constant temperature if the profile is invalid
        times[0] = 0.0;
        temperatures[0] = 200.0;
        num_points = 1;
    }

    // PID Variables
    double setpoint = 0.0;
    double actual_temperature;
    double duty_cycle;
    double pid_output;
    int i = 0;

    // Main loop
    while (running) {
        // Read temperature
        actual_temperature = read_temperature();

        if (actual_temperature < -273.0) {
            fprintf(stderr, "Error reading temperature, skipping iteration.\n");
            gpioDelay(1000000); // Wait 1 second
            continue;
        }

        // Calculate PID output
        pid_output = calculate_pid(temperatures[i], actual_temperature);

        // Control relay
        duty_cycle = pid_output;
        control_relay(duty_cycle);

        // Log data
        log_data(actual_temperature, temperatures[i], duty_cycle);

        // Update setpoint and index
        if (i < num_points - 1 && times[i] < time(NULL)) {
            i++;
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

