#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define DS18B20_PATH "/sys/bus/w1/devices/"
#define DS18B20_ID_FILE "28-*/w1_slave"
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "greenhouse.log"

// Global variables
double setpoint = 25.0; // Default setpoint
double Kp = 1.0;        // Default gains
double Ki = 0.1;
double Kd = 0.01;
int running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
double read_temperature_ds18b20(const char *id);
double read_temperature_i2c();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_relay_state(int state);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(double temperature, double setpoint, double pid_output, int pwm_duty_cycle);
void signal_handler(int signal);

// Function to read temperature from DS18B20 sensor
double read_temperature_ds18b20(const char *id) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s", DS18B20_PATH, id);

    char *id_file = strstr(path, DS18B20_ID_FILE);
    if (id_file == NULL) {
        fprintf(stderr, "Error: Could not find DS18B20 ID file.\n");
        return -1000.0; // Indicate error
    }

    char buffer[256];
    int fd = open(id_file, O_RDONLY);
    if (fd < 0) {
        perror("Error opening DS18B20 file");
        return -1000.0;
    }

    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        perror("Error reading DS18B20 file");
        return -1000.0;
    }

    buffer[bytes_read] = '\0';

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "Error: DS18B20 CRC check failed.\n");
        return -1000.0;
    }

    // Extract temperature
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: Could not find temperature in DS18B20 data.\n");
        return -1000.0;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    return (double)temp_raw / 1000.0;
}

// Function to read temperature from I2C sensor
double read_temperature_i2c() {
    unsigned char buf[2];
    int result;

    result = i2cReadDevice(i2c_fd, buf, 2);
    if (result != 2) {
        perror("Error reading from I2C device");
        return -1000.0;
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    return (double)raw_temp / 16.0;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set relay state
void set_relay_state(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, double setpoint, double pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %d\n", timestamp, temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Turn off relay
    set_relay_state(0);

    // Set PWM to zero
    set_pwm_duty_cycle(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set PWM GPIO as PWM output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, 1000); // Set PWM range to 0-1000

    // Open I2C device
