    double integral = 0.0;
    double previous_error = 0.0;

    // Main loop
    while (running) {
        // Read temperatures
        double temperature_ds18b20 = read_temperature_ds18b20(NULL); // Use NULL to get the first available ID
        double temperature_i2c = read_temperature_i2c();

        // Calculate average temperature
        double average_temperature = (temperature_ds18b20 + temperature_i2c) / 2.0;

        // Calculate PID output
        double pid_output = calculate_pid(setpoint, average_temperature, &integral, &previous_error);

        // Set relay and PWM
        int pwm_duty_cycle = (int)pid_output;
