// Constants
#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init(int i2c_handle);
int aht20_measure(int i2c_handle, uint8_t *data);
float aht20_convert_data(uint8_t *data);
void relay_control(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
    relay_control(GPIO_RELAY, 0); // Deactivate relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Initialize AHT20 sensor
int aht20_init(int i2c_handle) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    int result = i2cWriteDevice(i2c_handle, (char *)init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for initialization
    return 0;
}

// Trigger measurement and read data
int aht20_measure(int i2c_handle, uint8_t *data) {
    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    int result = i2cWriteDevice(i2c_handle, (char *)measure_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS);

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    return 0;
}

// Convert raw data to humidity percentage
float aht20_convert_data(uint8_t *data) {
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    return ((float)humidity_raw / 0x100000) * 100;
}

// Control the relay
void relay_control(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(1, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_handle) != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[6];
    float humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Main loop
    while (!terminate) {
        // Retry loop for I2C communication
        int retry = 0;
        int result = -1;
        while (retry < RETRY_COUNT && result != 0) {
            result = aht20_measure(i2c_handle, data);
            if (result != 0) {
                fprintf(stderr, "I2C retry %d failed, retrying in %d ms...\n", retry + 1, RETRY_DELAY_MS);
                gpioDelay(RETRY_DELAY_MS);
                retry++;
            }
        }

        if (result == 0) {
            // Verify status byte
            if ((data[0] & 0x80) == 0) {
                // Convert data to humidity
                humidity = aht20_convert_data(data);

                // Get current timestamp
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log humidity reading
                printf("%s Humidity: %.2f %%\n", timestamp, humidity);

                // Control relay based on humidity
                if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                    relay_control(GPIO_RELAY, 1); // Activate relay
                } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                    relay_control(GPIO_RELAY, 0); // Deactivate relay
                }
            } else {
                fprintf(stderr, "AHT20 busy or calibration failed\n");
            }
        } else {
            fprintf(stderr, "AHT20 measurement failed after multiple retries\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    relay_control(GPIO_RELAY, 0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

