#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <jansson.h>

// Configuration
#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define HUMIDITY_CMD 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLLING_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to read humidity from HTU21D sensor
float read_humidity() {
    unsigned char buf[3];
    int result;

    // Send humidity measurement command
    result = i2cWriteByte(i2c_handle, HUMIDITY_CMD);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to write humidity command: %d", result);
        return -1.0;
    }

    // Wait for measurement (at least 50ms)
    gpioDelay(50000); // 50ms

    // Read 3 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %d", result);
        return -1.0;
    }

    // CRC check (simplified, assumes no CRC implementation in pigpio)
    // In a real application, implement a proper CRC check using the datasheet
    // For this example, we assume the data is valid if the first byte is not 0x00

    // Convert data to humidity (see HTU21D datasheet)
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    return humidity;
}

// Function to format data as JSON
char* format_json(float humidity) {
    json_t *root = json_object();
    json_t *timestamp = json_integer(time(NULL));
    json_t *humidity_json = json_real(humidity);

    json_object_set_new(root, "timestamp", timestamp);
    json_object_set_new(root, "humidity", humidity_json);

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(2));
    json_decref(root);
    return json_str;
}

// Function to post data to API endpoint
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, API_ENDPOINT);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            syslog(LOG_INFO, "Data posted successfully");
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        syslog(LOG_ERR, "Failed to initialize libcurl");
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    // Initialize syslog
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D monitor started");

    // Main loop
    while (!terminate) {
        float humidity = read_humidity();
        if (humidity >= 0) {
            char *json_data = format_json(humidity);
            if (json_data != NULL) {
                if (post_data(json_data) != 0) {
                    syslog(LOG_ERR, "Failed to post data");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(POLLING_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

