        gpioDelay(1000); // Wait 1 second before retrying
    }

    if (retries == 3) {
        fprintf(stderr, "Failed to initialize BMP280 after multiple retries. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure, temperature);

            // Log pressure if it's out of range
            if (pressure > 1020.0 || pressure < 980.0) {
                log_pressure(pressure);
            }

            printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

