        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read humidity from AHT20
int read_aht20(float *temperature, float *humidity) {
    unsigned char buf[6];
    int result;
    int retries = 0;

    // Trigger measurement (AHT20 requires a specific sequence)
    unsigned char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    if (i2cWriteDevice(i2c_handle_aht20, (char *)trigger_cmd, 3) != 3) {
        fprintf(stderr, "Error triggering AHT20 measurement.\n");
        return -1;
