    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle_aht20, (char *)buf, 6);
        if (result == 6) {
            // Convert raw data to humidity and temperature
            unsigned char status = buf[0];
            if (status & 0x80) {
