        time(&now);
        struct tm *now_time = localtime(&now);
        int now_midnight = (now_time->tm_hour == 0 && now_time->tm_min == 0 && now_time->tm_sec == 0);

        if (now_midnight && !midnight) {
            if (create_log_file() != 0) {
                fprintf(stderr, "Failed to create log file at midnight.\n");
            }
            midnight = 1; // Set the flag to avoid creating a new file every second
        }

        sleep(1); // Sample every 1 second
    }

    // Close I2C connections
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

