#define IN2_PIN 24

// Define motor direction
#define MOTOR_FORWARD 1
#define MOTOR_STOP 0

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);
void log_message(const char *message);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, stopping program...");
    stop_motor();
    gpioTerminate();
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        char error_message[100];
        sprintf(error_message, "Error reading rain sensor: %d", sensor_value);
        log_message(error_message);
        return -1; // Indicate an error
    }
    return (sensor_value == 0) ? 1 : 0; // Return 1 if rain detected (active low), 0 otherwise
}

// Function to close the window
void close_window() {
    log_message("Closing window...");
    if (gpioWrite(ENA_PIN, 1) < 0) {
        log_message("Error setting ENA pin high");
    }
    if (gpioWrite(IN1_PIN, 1) < 0) {
        log_message("Error setting IN1 pin high");
    }
    if (gpioWrite(IN2_PIN, 0) < 0) {
        log_message("Error setting IN2 pin low");
    }
    gpioDelay(5000000); // 5 seconds
    stop_motor();
}

// Function to stop the motor
void stop_motor() {
    log_message("Stopping motor...");
    if (gpioWrite(ENA_PIN, 0) < 0) {
        log_message("Error setting ENA pin low");
    }
    if (gpioWrite(IN1_PIN, 0) < 0) {
        log_message("Error setting IN1 pin low");
    }
    if (gpioWrite(IN2_PIN, 0) < 0) {
        log_message("Error setting IN2 pin low");
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        log_message("Error setting rain sensor pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ENA_PIN, PI_OUTPUT) < 0) {
        log_message("Error setting ENA pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN1_PIN, PI_OUTPUT) < 0) {
        log_message("Error setting IN1 pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN2_PIN, PI_OUTPUT) < 0) {
        log_message("Error setting IN2 pin mode");
        gpioTerminate();
        return 1;
    }

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 1) {
            log_message("Rain detected, closing window...");
            close_window();
        } else if (rain_detected < 0) {
            log_message("Error reading rain sensor, retrying...");
        }
        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    return 0;
}

