// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal) {
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to read CPU load from /proc/stat
float read_cpu_load() {
    FILE *fp;
    char line[256];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0, prev_idle_total = 0;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open /proc/stat\n");
        return -1.0; // Indicate error
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        fprintf(stderr, "Error: Could not read /proc/stat\n");
        return -1.0; // Indicate error
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fclose(fp);
        fprintf(stderr, "Error: Invalid format in /proc/stat\n");
        return -1.0; // Indicate error
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        fprintf(stderr, "Error: Could not parse /proc/stat\n");
        return -1.0; // Indicate error
    }

    fclose(fp);

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;

    if (prev_total == 0) {
        prev_total = total;
        prev_idle_total = idle_total;
        return 0.0; // Return 0% on first call
    }

    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff = idle_total - prev_idle_total;

    float cpu_usage = (float)(total_diff - idle_diff) / total_diff * 100.0;

    prev_total = total;
    prev_idle_total = idle_total;

    return cpu_usage;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load <= 50.0) {
        // Green to Yellow
        *green = 255;
        *red = (int)((cpu_load / 50.0) * 255);
    } else {
        // Yellow to Red
        *green = 255 - (int)(((cpu_load - 50.0) / 50.0) * 255);
        *red = 255;
    }
    *blue = 0; // Keep blue at 0 for common anode
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    printf("CPU Load to RGB LED mapping started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU load
        float cpu_load = read_cpu_load();
        if (cpu_load < 0.0) {
            fprintf(stderr, "Error: Failed to read CPU load, exiting...\n");
            break; // Exit loop on error
        }

        // Map CPU load to RGB color values
        int red, green, blue;
        map_load_to_color(cpu_load, &red, &green, &blue);

        // Set PWM duty cycles
        set_pwm(RED_PIN, red);
        set_pwm(GREEN_PIN, green);
        set_pwm(BLUE_PIN, blue);

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Turn off LED (set all pins high for common anode)
    set_pwm(RED_PIN, 255);
    set_pwm(GREEN_PIN, 255);
    set_pwm(BLUE_PIN, 255);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

