#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
int udp_socket;
struct sockaddr_in server_addr;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int bmp280_init();
int bmp280_read_calibration_data();
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
int create_json(double temperature, double pressure, char *json_string, size_t json_string_size);
int send_udp_packet(const char *json_string);
void signal_handler(int signal);

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init() != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (bmp280_read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating UDP socket: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(udp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;
        char json_string[128];

        // Read raw data from BMP280
        if (bmp280_read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw data\n");
            continue; // Try again
        }

        // Compensate temperature and pressure
        double t_fine = bmp280_compensate_temperature(raw_temperature);
        pressure = bmp280_compensate_pressure(raw_pressure, t_fine);

        // Create JSON string
        if (create_json(temperature, pressure, json_string, sizeof(json_string)) != 0) {
            fprintf(stderr, "Failed to create JSON string\n");
            continue; // Try again
        }

        // Send UDP packet
        if (send_udp_packet(json_string) != 0) {
            fprintf(stderr, "Failed to send UDP packet\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    close(udp_socket);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

int bmp280_init() {
    uint8_t chip_id;
    // Check the chip ID
    if (i2c_read_byte(i2c_handle, BMP280_REG_ID, &chip_id) != 0) {
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "BMP280 not found, chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Reset the sensor
    if (i2c_write_byte(i2c_handle, BMP280_REG_RESET, 0xB6) != 0) {
        return -1;
    }
    gpioDelay(10); // Wait for the reset to complete

    // Set oversampling and power mode
    // Temperature oversampling x1, pressure oversampling x1, normal mode
    if (i2c_write_byte(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        return -1;
    }

    // Set filter and standby time
    if (i2c_write_byte(i2c_handle, BMP280_REG_CONFIG, 0x00) != 0) {
        return -1;
    }

    return 0;
}

int bmp280_read_calibration_data() {
    uint8_t data[24];
    int i;

    // Read calibration data from registers 0x88 to 0xA1
    for (i = 0; i < 24; i++) {
        if (i2c_read_byte(i2c_handle, BMP280_REG_CALIB_00 + i, &data[i]) != 0) {
            return -1;
        }
    }

    // Populate the calibration data structure
    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    // Read temperature and pressure data
    if (i2c_read_byte(i2c_handle, BMP280_REG_PRESS_MSB, &data[0]) != 0 ||
        i2c_read_byte(i2c_handle, BMP280_REG_PRESS_LSB, &data[1]) != 0 ||
        i2c_read_byte(i2c_handle, BMP280_REG_PRESS_XLSB, &data[2]) != 0 ||
        i2c_read_byte(i2c_handle, BMP280_REG_TEMP_MSB, &data[3]) != 0 ||
        i2c_read_byte(i2c_handle, BMP280_REG_TEMP_LSB, &data[4]) != 0 ||
        i2c_read_byte(i2c_handle, BMP280_REG_TEMP_XLSB, &data[5]) != 0) {
        return -1;
    }

    // Combine the data into 24-bit values
    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double dig_T1 = (double)calib.dig_T1;
    double dig_T2 = (double)calib.dig_T2;
    double dig_T3 = (double)calib.dig_T3;

    var1 = (((double)raw_temperature / 16384.0) - (dig_T1 / 1024.0)) * dig_T2;
    var2 = ((((double)raw_temperature / 131072.0) - (dig_T1 / 8192.0)) * (((double)raw_temperature / 131072.0) - (dig_T1 / 8192.0))) * dig_T3;
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
