#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define FAN_PIN 18          // GPIO18 (BCM) for hardware PWM
#define SPI_CHANNEL 0       // SPI0 (CE0)
#define SPI_SPEED 500000     // 500kHz
#define BUFFER_SIZE 20      // Circular buffer size
#define PWM_RANGE 255       // PWM duty cycle range
#define PWM_FREQUENCY 1000  // 1kHz

// Temperature thresholds and corresponding duty cycles
#define TEMP_LOW 25.0
#define TEMP_HIGH 60.0

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd;

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} log_entry_t;

// Circular buffer
log_entry_t log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_spi();
float read_temperature();
int calculate_duty_cycle(float temperature);
void update_fan(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int init_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int i;

    for (i = 0; i < 3; i++) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, data, 4) == -1) {
            fprintf(stderr, "Error reading SPI data: %s\n", strerror(errno));
            return -273.15; // Return absolute zero on error
        }
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault detected!\n");
        return -273.15; // Return absolute zero on fault
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature < TEMP_HIGH) {
        duty_cycle = (int)((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW) * PWM_RANGE);
    } else {
        duty_cycle = (int)(((temperature - TEMP_HIGH) / (100.0 - TEMP_HIGH)) * PWM_RANGE) + PWM_RANGE;
    }

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    return duty_cycle;
}

// Function to update fan speed using hardware PWM
void update_fan(int duty_cycle) {
    pwmWrite(FAN_PIN, duty_cycle);
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("-----------------------\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to stop PWM and close SPI
void cleanup() {
    printf("Stopping PWM...\n");
    pwmWrite(FAN_PIN, 0); // Turn off the fan

    printf("Closing SPI...\n");
    close(spi_fd);

    printf("Cleaning up wiringPi...\n");
    wiringPiSetupGpio(); // Reset GPIO pins to default state

    printf("Exiting.\n");
}

int main() {
    // Initialize wiringPi using GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (init_spi() == -1) {
        return 1;
    }

    // Set PWM mode to mark:space and range
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for 1kHz (19.2MHz / 192 = 1kHz)

    // Set fan pin as PWM output
    pinMode(FAN_PIN, PWM_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring and fan control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read temperature
        float temperature = read_temperature();

        // Calculate duty cycle
        int duty_cycle = calculate_duty_cycle(temperature);

        // Update fan speed
        update_fan(duty_cycle);

        // Log data
        log_data(temperature, duty_cycle);

        // Print buffer every 60 seconds
        if (time(NULL) % 60 == 0) {
            print_buffer();
        }

        // Wait for 1 second
        delay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

