#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting
#define BMP180_OSS 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t logging_active = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temp);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
void log_data(double temperature, double pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature value
int read_raw_temperature(int32_t *raw_temp) {
    char buf[2];
    char write_buf[1];

    write_buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure value
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[3];
    char write_buf[1];

    write_buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms for OSS=3

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(int32_t raw_temp) {
    double X1 = ((double)raw_temp - (double)ac6) * ((double)ac5 / pow(2, 15));
    double X2 = ((double)mc * pow(2, 11)) / (X1 + (double)md);
    double B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4);
    return temperature / 10.0;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    double X1 = ((double)raw_temp - (double)ac6) * ((double)ac5 / pow(2, 15));
    double X2 = ((double)mc * pow(2, 11)) / (X1 + (double)md);
    double B5 = X1 + X2;

    double B6 = B5 - 4000;
    double X3 = ((double)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    double X4 = ((double)ac2 * B6) / pow(2, 11);
    double B3 = (((double)ac1 * 4 + X3 + X4 + 2) / 4);

    double X1_pressure = ((double)ac3 * B6) / pow(2, 13);
    double X2_pressure = ((double)b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    double X3_pressure = ((X1_pressure + X2_pressure + 2) / 4);
    double B4 = ((double)ac4 * (X3_pressure + 32768)) / pow(2, 15);
    double B7 = ((double)raw_pressure - B3) * (50000 / pow(2, BMP180_OSS));

    double pressure;
    if (B7 < 0x80000000) {
        pressure = (B7 * 2) / B4;
    } else {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * pressure) / pow(2, 16);

    pressure = pressure + (X1_pressure + X2_pressure + 3791) / pow(2, 4);

    return pressure;
}

// Function to log data to file
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    logging_active = !logging_active;
    printf("Interrupt occurred, logging %s\n", logging_active ? "active" : "inactive");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO2 as input with pull-up enabled
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_temp, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (1) {
        if (logging_active) {
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                temperature = calculate_temperature(raw_temp);
                pressure = calculate_pressure(raw_pressure, raw_temp);
                log_data(temperature, pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        gpioDelay(1000000); // 1 second delay
    }

    return 0;
}

