#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // No special flags
#define CS_PIN 8          // GPIO8 (CE0)
#define LOG_FILE "rtd_log.csv"

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// RTD Constants
#define RREF 430.0  // Reference resistor value
#define A 0.0039083
#define B -0.0000005775
#define P 100.0   // PT100 RTD nominal resistance at 0°C

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int reg, uint8_t *data, int len);
int spi_write_register(int reg, uint8_t data);
float read_temperature();
void log_temperature(float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read a register from the MAX31865 via SPI
int spi_read_register(int reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    memset(tx_buf + 1, 0, len); // Fill with dummy data for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) != len + 1) {
        fprintf(stderr, "SPI read error: Register 0x%02X\n", reg);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to write a register to the MAX31865 via SPI
int spi_write_register(int reg, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error: Register 0x%02X, Data 0x%02X\n", reg, data);
        return -1;
    }

    return 0;
}

// Function to read the temperature from the MAX31865
float read_temperature() {
    uint8_t rtd_msb, rtd_lsb, fault_reg;
    int32_t rtd_raw;
    float rtd_resistance, temperature;

    // Read RTD MSB and LSB registers
    if (spi_read_register(MAX31865_RTD_MSB_REG, &rtd_msb, 1) != 0) return -1000.0; // Indicate error
    if (spi_read_register(MAX31865_RTD_LSB_REG, &rtd_lsb, 1) != 0) return -1000.0; // Indicate error

    // Combine MSB and LSB to get the RTD raw value
    rtd_raw = ((int32_t)rtd_msb << 8) | rtd_lsb;

    // Check for fault
    if (spi_read_register(MAX31865_FAULT_REG, &fault_reg, 1) != 0) return -1000.0; // Indicate error

    if (fault_reg != 0) {
        fprintf(stderr, "MAX31865 Fault: 0x%02X\n", fault_reg);
        return -1000.0; // Indicate error
    }

    // Convert RTD raw value to resistance
    rtd_resistance = ((float)rtd_raw / 32768.0) * RREF;

    // Callendar-Van Dusen equation
    temperature = (float)((A * rtd_resistance + B * rtd_resistance * rtd_resistance) / (1.0 + B * rtd_resistance));

    return temperature;
}

// Function to log the temperature to a file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
