#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// RTD Constants
#define RREF 430.0  // Reference resistor value
#define A 0.0039083
#define B -0.0000005775
#define P 100.0   // PT100 RTD nominal resistance at 0°C

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

