// Function to read a register from the MAX31865 via SPI
int spi_read_register(int reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    memset(tx_buf + 1, 0, len); // Fill with dummy data for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) != len + 1) {
        fprintf(stderr, "SPI read error: Register 0x%02X\n", reg);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to write a register to the MAX31865 via SPI
int spi_write_register(int reg, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error: Register 0x%02X, Data 0x%02X\n", reg, data);
        return -1;
