        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity, pressure;

    // Main loop
    while (!terminate) {
        if (bme280_read_data(&temperature, &humidity, &pressure) == 0) {
            log_data(temperature, humidity, pressure);
        } else {
