#include <wiringPiI2C.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_PIN 24

// Circular buffer size (60 seconds * 100ms = 6000 entries)
#define BUFFER_SIZE 6000

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure and temperature readings
typedef struct {
    time_t timestamp;
    float pressure;
    float temperature;
} pressure_reading_t;

// Structure for the circular buffer
typedef struct {
    pressure_reading_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd;
static bmp180_calibration_data_t calibration_data;
static circular_buffer_t pressure_buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int bmp180_init();
int bmp180_read_calibration_data(bmp180_calibration_data_t *calibration_data);
int bmp180_read_raw_temperature(int *raw_temperature);
int bmp180_read_raw_pressure(int *raw_pressure);
float bmp180_calculate_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data);
float bmp180_calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data);
void circular_buffer_init(circular_buffer_t *buffer);
bool circular_buffer_add(circular_buffer_t *buffer, pressure_reading_t reading);
bool circular_buffer_get_average(circular_buffer_t *buffer, float *average_pressure);
void gpio_alert(int alert_state);
void timer_callback();
void signal_handler(int signal);
void log_error(const char *message);

// Function to initialize the BMP180 sensor
int bmp180_init() {
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        log_error("Failed to initialize I2C communication.");
        return -1;
    }

    if (bmp180_read_calibration_data(&calibration_data) != 0) {
        log_error("Failed to read calibration data.");
        return -1;
    }

    circular_buffer_init(&pressure_buffer);
    return 0;
}

// Function to read calibration data from the BMP180
int bmp180_read_calibration_data(bmp180_calibration_data_t *calibration_data) {
    calibration_data->ac1 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC1);
    calibration_data->ac2 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC2);
    calibration_data->ac3 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC3);
    calibration_data->ac4 = (uint16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC4);
    calibration_data->ac5 = (uint16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC5);
    calibration_data->ac6 = (uint16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC6);
    calibration_data->b1 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B1);
    calibration_data->b2 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B2);
    calibration_data->mb = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MB);
    calibration_data->mc = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MC);
    calibration_data->md = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MD);

    return 0;
}

// Function to read the raw temperature value from the BMP180
int bmp180_read_raw_temperature(int *raw_temperature) {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x2E); // Request temperature reading
    delay(5); // Wait for conversion (at least 4.5ms)
    *raw_temperature = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_MSB);
    return 0;
}

// Function to read the raw pressure value from the BMP180
int bmp180_read_raw_pressure(int *raw_pressure) {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)); // Request pressure reading
    delay(2 + (3 << BMP180_OSS)); // Wait for conversion (adjust based on OSS)

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB);

    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate the temperature in degrees Celsius
float bmp180_calculate_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long X1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long X2 = ((long)calibration_data.mc * pow(2, 11)) / (X1 + calibration_data.md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate the pressure in hPa
float bmp180_calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long X1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long X2 = ((long)calibration_data.mc * pow(2, 11)) / (X1 + calibration_data.md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)calibration_data.b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)calibration_data.ac2 * B6) / pow(2, 11);
    long B3 = (((((long)calibration_data.ac1) * 4 + X3) << BMP180_OSS) + 2) / 4;

    unsigned long X5 = ((unsigned long)calibration_data.ac3 * B6) / pow(2, 13);
    unsigned long X6 = ((unsigned long)calibration_data.b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    unsigned long B4 = X5 + X6;
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> BMP180_OSS);

    long pressure;
    if (B7 < 0x80000000) {
        pressure = (B7 * 2) / B4;
    } else {
        pressure = (B7 / B4) * 2;
    }

    X1 = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * pressure) / pow(2, 16);

    float pressure_hpa = pressure + (X1 + X2 + 3791) / pow(2, 4);
    return pressure_hpa / 100.0; // Convert to hPa
}

// Function to initialize the circular buffer
void circular_buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Function to add a reading to the circular buffer
bool circular_buffer_add(circular_buffer_t *buffer, pressure_reading_t reading) {
    if (buffer == NULL) {
        log_error("Circular buffer is NULL.");
        return false;
    }

    buffer->buffer[buffer->head] = reading;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
    return true;
}

// Function to calculate the rolling average pressure
bool circular_buffer_get_average(circular_buffer_t *buffer, float *average_pressure) {
    if (buffer == NULL || buffer->count == 0) {
        return false;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i].pressure;
    }
    *average_pressure = sum / buffer->count;
    return true;
}

// Function to control the GPIO alert pin
void gpio_alert(int alert_state) {
    digitalWrite(ALERT_PIN, alert_state);
}

// Timer callback function
void timer_callback() {
    int raw_temperature, raw_pressure;
    float temperature, pressure;
    pressure_reading_t reading;
    float average_pressure;

    if (bmp180_read_raw_temperature(&raw_temperature) != 0) {
        log_error("Failed to read raw temperature.");
        return;
    }

    if (bmp180_read_raw_pressure(&raw_pressure) != 0) {
        log_error("Failed to read raw pressure.");
        return;
    }

    temperature = bmp180_calculate_temperature(raw_temperature, calibration_data);
    pressure = bmp180_calculate_pressure(raw_pressure, raw_temperature, calibration_data);

    reading.timestamp = time(NULL);
    reading.temperature = temperature;
    reading.pressure = pressure;

    if (!circular_buffer_add(&pressure_buffer, reading)) {
        log_error("Failed to add reading to circular buffer.");
        return;
    }

    if (!circular_buffer_get_average(&pressure_buffer, &average_pressure)) {
        log_error("Failed to get average pressure from circular buffer.");
        return;
    }

    float pressure_difference = fabs(pressure - average_pressure);
    if (pressure_difference > 5.0) {
        gpio_alert(HIGH);
        fprintf(stderr, "Alert: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa, Difference: %.2f hPa\n", pressure, average_pressure, pressure_difference);
    } else {
        gpio_alert(LOW);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d)\n", message, errno);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to initialize wiringPi.\n");
        return 1;
    }

    // Initialize GPIO pin for alert
    pinMode(ALERT_PIN, OUTPUT);
    gpio_alert(LOW); // Ensure alert is initially low

    // Initialize BMP180 sensor
    if (bmp180_init() != 0) {
        fprintf(stderr, "Failed to initialize BMP180 sensor.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer callback (every 50ms)
    if (wiringPiISR(0, INT_EDGE_RISING, timer_callback) < 0) {
        fprintf(stderr, "Unable to setup ISR.\n");
        return 1;
    }

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        delay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup before exiting
    gpio_alert(LOW); // Ensure alert is low before exiting
    close(i2c_fd);
    return 0;
}

