    X1_pressure = (pressure >> 8) * (pressure >> 8);
    X1_pressure = (X1_pressure * 3038) >> 16;
    X2_pressure = (-7357 * pressure) >> 16;

    double pressure_pascals = pressure + ((X1_pressure + X2_pressure + 3791) >> 4);
    return pressure_pascals;
}

// Function to log data to a file
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

// Timer interrupt handler
void timer_interrupt_handler() {
    int32_t raw_temp, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);
        log_data(temperature, pressure);
    } else {
        fprintf(stderr, "Error reading sensor data in interrupt handler\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer interrupt (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL);

    printf("BMP180 data logging started. Press Ctrl+C to exit.\n");

    // Main loop (wait for termination signal)
    while (!terminate) {
        sleep(1); // Reduce CPU usage
    }

    // Clean up
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("BMP180 data logging stopped.\n");

    return 0;
}

