#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define DUTY_MIN 0
#define DUTY_MAX 255

// Global variables
static volatile int running = 1;
static FILE *log_fp = NULL;

// Function prototypes
double read_cpu_temperature();
int map_temperature_to_duty_cycle(double temperature);
int set_fan_speed(int duty_cycle);
int log_data(double temperature, int duty_cycle);
void signal_handler(int signal);

// Function to read CPU temperature from file
double read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    double temperature = -1.0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0;
    } else {
        perror("Error reading temperature from file");
    }

    fclose(fp);
    return temperature;
}

// Function to map temperature to duty cycle
int map_temperature_to_duty_cycle(double temperature) {
    int duty_cycle;

    if (temperature < TEMP_MIN) {
        duty_cycle = DUTY_MIN;
    } else if (temperature > TEMP_MAX) {
        duty_cycle = DUTY_MAX;
    } else {
        duty_cycle = (int)(((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (DUTY_MAX - DUTY_MIN) + DUTY_MIN);
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
int set_fan_speed(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(double temperature, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_fp, "%s, %.2f, %d\n", timestamp, temperature, duty_cycle);
    fflush(log_fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Stop the fan
    set_fan_speed(0);

    // Close the log file
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        double temperature = read_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or default\n");
            // Consider using a default temperature or skipping this iteration
        } else {
            // Map temperature to duty cycle
            int duty_cycle = map_temperature_to_duty_cycle(temperature);

            // Set fan speed
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed\n");
            }

            // Log data
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

