#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
pthread_mutex_t buffer_mutex;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
float read_temperature();
void update_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void *sensor_reading_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Structure to pass arguments to the thread
typedef struct {
    int i2c_handle;
    pthread_mutex_t *buffer_mutex;
    float temperature_buffer[];
} thread_args_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create sensor reading thread
    thread_args_t *thread_args = malloc(sizeof(thread_args_t) + sizeof(float) * BUFFER_SIZE);
    if (thread_args == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }
    thread_args->i2c_handle = i2c_handle;
    thread_args->buffer_mutex = &buffer_mutex;
    memcpy(thread_args->temperature_buffer, temperature_buffer, sizeof(float) * BUFFER_SIZE);

    pthread_t sensor_thread;
    if (pthread_create(&sensor_thread, NULL, sensor_reading_thread, thread_args) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        cleanup();
        return 1;
    }

    // Main loop (optional, can be used for other tasks)
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    // Join the thread
    pthread_join(sensor_thread, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125;

    return temperature;
}

void update_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

float calculate_average() {
    pthread_mutex_lock(&buffer_mutex);
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    float average = sum / BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
    return average;
}

void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

void *sensor_reading_thread(void *arg) {
    thread_args_t *args = (thread_args_t *)arg;
    int i2c_handle = args->i2c_handle;
    pthread_mutex_t *buffer_mutex = args->buffer_mutex;
    float temperature_buffer[] = args->temperature_buffer;

    while (program_running) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            update_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Error reading temperature, attempting re-initialization\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialisation failed\n");
                program_running = 0; // Exit thread if re-initialization fails
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    pthread_exit(NULL);
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    program_running = 0;
}

void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (pthread_mutex_destroy(&buffer_mutex) != 0) {
        fprintf(stderr, "Mutex destruction failed\n");
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

