#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>
#include <math.h>

// Configuration file path
#define CONFIG_FILE "config.json"

// Default values
#define DEFAULT_TARGET_TEMP 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// GPIO pin for PWM output
#define HEATER_GPIO 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-1000)
#define PWM_RANGE 1000

// SPI channel
#define SPI_CHANNEL 0

// SPI baud rate
#define SPI_BAUD 500000

// Global variables
static int spi_handle;
static double target_temperature = DEFAULT_TARGET_TEMP;
static double Kp = DEFAULT_KP;
static double Ki = DEFAULT_KI;
static double Kd = DEFAULT_KD;
static volatile int running = 1;

// PID variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
int read_config(const char *filename, double *target_temp, double *Kp, double *Ki, double *Kd);
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_heater_power(int duty_cycle);
void signal_handler(int signal);
void log_error(const char *message);

// Function to read configuration from JSON file
int read_config(const char *filename, double *target_temp, double *Kp, double *Ki, double *Kd) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return 1; // Indicate failure
    }

    json_t *target_temp_json = json_object_get(root, "target_temperature");
    json_t *Kp_json = json_object_get(root, "Kp");
    json_t *Ki_json = json_object_get(root, "Ki");
    json_t *Kd_json = json_object_get(root, "Kd");

    if (!json_is_real(target_temp_json) || !json_is_real(Kp_json) || !json_is_real(Ki_json) || !json_is_real(Kd_json)) {
        fprintf(stderr, "Error: Invalid config file format\n");
        json_decref(root);
        return 1; // Indicate failure
    }

    *target_temp = json_real_value(target_temp_json);
    *Kp = json_real_value(Kp_json);
    *Ki = json_real_value(Ki_json);
    *Kd = json_real_value(Kd_json);

    json_decref(root);
    return 0; // Indicate success
}

// Function to read temperature from MAX31865
double read_temperature() {
    unsigned char config_data[2];
    unsigned char rtd_data[2];
    int16_t rtd_raw;
    double rtd_resistance;
    double temperature;

    // Read RTD MSB and LSB registers
    config_data[0] = MAX31865_RTD_MSB_REG;
    if (spiXfer(spi_handle, config_data, rtd_data, 2) != 0) {
        log_error("SPI read failed");
        return -1000.0; // Indicate error
    }

    rtd_raw = (rtd_data[0] << 8) | rtd_data[1];
    rtd_raw = rtd_raw >> 1; // Remove fault bit

    // Convert RTD raw value to resistance (PT100)
    rtd_resistance = (double)rtd_raw * 430.0 / 32768.0;

    // Convert resistance to temperature (Celsius) - Linear approximation
    temperature = (rtd_resistance - 100.0) / 0.385;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp output to 0-100%
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

// Function to set heater power using PWM
void set_heater_power(int duty_cycle) {
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to log errors with timestamp
void log_error(const char *message) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[26];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "%s.%06ld: %s\n", timestamp, tv.tv_usec, message);
}

int main() {
    double actual_temperature;
    double pid_output;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        log_error("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Read configuration from file
    if (read_config(CONFIG_FILE, &target_temperature, &Kp, &Ki, &Kd) != 0) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Target Temperature: %.2f °C\n", target_temperature);
    printf("PID Gains: Kp=%.2f, Ki=%.2f, Kd=%.2f\n", Kp, Ki, Kd);

    // Main loop
    while (running) {
        // Read temperature
        actual_temperature = read_temperature();
        if (actual_temperature < -900.0) {
            log_error("Temperature reading error, exiting.");
            running = 0;
            continue; // Skip to next iteration
        }

        // Calculate PID output
        pid_output = calculate_pid(target_temperature, actual_temperature);

        // Set heater power
        duty_cycle = (int)(pid_output * PWM_RANGE / 100.0);
        set_heater_power(duty_cycle);

        // Log temperature and PID output
        printf("Actual Temperature: %.2f °C, PID Output: %.2f\n", actual_temperature, pid_output);

        // Failsafe check
        if (actual_temperature > 80.0) {
            log_error("Temperature exceeds 80°C, shutting down.");
            set_heater_power(0);
            running = 0;
        }

        // Sleep for 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    set_heater_power(0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

