#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define OSS 0

// GPIO pin for fan control
#define FAN_PIN 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold BMP180 calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold BMP180 readings
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} bmp180_reading_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
bmp180_reading_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temperature, const bmp180_calibration_data_t *calibration_data);
float calculate_pressure(int raw_pressure, int raw_temperature, const bmp180_calibration_data_t *calibration_data);
void add_reading_to_buffer(float temperature, float pressure);
void print_buffer();
void control_fan(float temperature);
void timer_callback();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *calibration_data) {
    calibration_data->ac1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    calibration_data->ac2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    calibration_data->ac3 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    calibration_data->ac4 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    calibration_data->ac5 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    calibration_data->ac6 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    calibration_data->b1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    calibration_data->b2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    calibration_data->mb = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    calibration_data->mc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    calibration_data->md = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

