        calibration_data->ac3 == PI_BAD_I2C_ADDR || calibration_data->ac4 == PI_BAD_I2C_ADDR ||
        calibration_data->ac5 == PI_BAD_I2C_ADDR || calibration_data->ac6 == PI_BAD_I2C_ADDR ||
        calibration_data->b1 == PI_BAD_I2C_ADDR || calibration_data->b2 == PI_BAD_I2C_ADDR ||
        calibration_data->mb == PI_BAD_I2C_ADDR || calibration_data->mc == PI_BAD_I2C_ADDR ||
        calibration_data->md == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
