    long X1 = ((long)raw_temperature - (long)calibration_data->ac6) * ((long)calibration_data->ac5) / pow(2, 15);
    long X2 = ((long)calibration_data->mc * pow(2, 11)) / (X1 + calibration_data->md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temperature, const bmp180_calibration_data_t *calibration_data) {
    long X1 = ((long)raw_temperature - (long)calibration_data->ac6) * ((long)calibration_data->ac5) / pow(2, 15);
    long X2 = ((long)calibration_data->mc * pow(2, 11)) / (X1 + calibration_data->md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)calibration_data->b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)calibration_data->ac2 * B6) / pow(2, 11);
    long B3 = (((((long)calibration_data->ac1) * 4 + X3) << OSS) + 2) / 4;

    unsigned long X5 = ((unsigned long)calibration_data->ac3 * B6) / pow(2, 13);
    unsigned long X6 = ((unsigned long)calibration_data->b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    unsigned long B4 = X5 + X6;
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000) {
        pressure = (B7 * 2) / B4;
    } else {
        pressure = (B7 / B4) * 2;
    }

    X1 = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * pressure) / pow(2, 16);

    pressure = pressure + (X1 + X2 + 3791) / pow(2, 4);

    return pressure;
}

// Function to add a reading to the circular buffer
void add_reading_to_buffer(float temperature, float pressure) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("Timestamp,Temperature(C),Pressure(Pa)\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&circular_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f,%.2f\n", timestamp_str, circular_buffer[index].temperature, circular_buffer[index].pressure);
    }
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > 30.0) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0 &&
        read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temperature, &calibration_data);
        pressure = calculate_pressure(raw_pressure, raw_temperature, &calibration_data);

        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        add_reading_to_buffer(temperature, pressure);
        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data in timer callback\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for fan control as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0); // Ensure fan is off initially

    // Set up timer callback (every 500ms)
    gpioSetTimerFunc(0, 500, timer_callback);

    // Main loop (keep the program running until a signal is received)
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

