#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_SAFE_DUTY_CYCLE 0.80
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
float calculate_pid(float current_temperature, float target_temperature, float *integral, float *previous_error);
void set_heater_duty_cycle(float duty_cycle);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// PID parameters
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Anti-windup parameters
float previous_error = 0.0;
float integral = 0.0;

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1000.0;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float current_temperature, float target_temperature, float *integral, float *previous_error) {
    float error = target_temperature - current_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Anti-windup
    if (output > 1.0) {
        output = 1.0;
    } else if (output < 0.0) {
        output = 0.0;
    }

    return output;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_SAFE_DUTY_CYCLE) duty_cycle = MAX_SAFE_DUTY_CYCLE;
    gpioPWM(HEATER_GPIO, (int)(duty_cycle * 255.0)); // pigpio range is 0-255
}

// Function to log data to file
void log_data(float temperature, float duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(HEATER_GPIO, 255); // Set PWM range to 0-255

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature,DutyCycle\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_heater_duty_cycle(0.0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    float temperature, duty_cycle;
    float target_temperature = TARGET_TEMPERATURE;

    while (!terminate) {
        temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            duty_cycle = calculate_pid(temperature, target_temperature, &integral, &previous_error);
            set_heater_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle);
        } else {
            fprintf(stderr, "Invalid temperature reading, setting duty cycle to 0\n");
            set_heater_duty_cycle(0.0);
            log_data(-999.0, 0.0); // Log error
        }

        gpioDelay(100); // 100 ms delay
    }

    cleanup();
    return 0;
}

