    if (duty_cycle > MAX_SAFE_DUTY_CYCLE) duty_cycle = MAX_SAFE_DUTY_CYCLE;
    gpioPWM(HEATER_GPIO, (int)(duty_cycle * 255.0)); // pigpio range is 0-255
}

// Function to log data to file
void log_data(float temperature, float duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(HEATER_GPIO, 255); // Set PWM range to 0-255

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature,DutyCycle\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_heater_duty_cycle(0.0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    float temperature, duty_cycle;
    float target_temperature = TARGET_TEMPERATURE;

    while (!terminate) {
        temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            duty_cycle = calculate_pid(temperature, target_temperature, &integral, &previous_error);
            set_heater_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle);
        } else {
            fprintf(stderr, "Invalid temperature reading, setting duty cycle to 0\n");
            set_heater_duty_cycle(0.0);
            log_data(-999.0, 0.0); // Log error
        }

        gpioDelay(100); // 100 ms delay
    }

    cleanup();
    return 0;
}

