}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    char buffer[10];
    int temp;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading temperature file");
        fclose(fp);
        return -1; // Indicate error
    }

    if (ferror(fp)) {
        perror("Error reading temperature file");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    temp = atoi(buffer);
    return temp;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

