        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        int temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error reading temperature, skipping update\n");
            sleep(0.5);
            continue;
        }

        // Determine LED color based on temperature
        int red = 0, green = 0, blue = 0;
        if (temp < TEMP_LOW) {
            red = 255;
        } else if (temp > TEMP_HIGH) {
            green = 255;
        } else {
            blue = 255;
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature and PWM values
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temp, red, green, blue);

        // Wait 0.5 seconds
        sleep(0.5);
    }

    // Cleanup and exit
    set_led_color(255, 255, 255); // Turn off LED
    gpioTerminate();
    return 0;
}

