#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SERVER_URL "http://yourserver.com/api/humidity"

volatile sig_atomic_t program_running = 1;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int error;
} DHT22Data;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read DHT22 data using pigpio
DHT22Data read_dht22_data() {
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    int bit_idx = 0;
    int byte_idx = 0;
    int data_bits[40] = {0};
    int raw_data[5] = {0};

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Changed from 30us to 30ms
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read data
    for (i = 0; i < 40; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            count++;
            gpioDelay(1); // Delay 1us
            if (count > 200) {
                data.error = -1; // Timeout
                return data;
            }
        }

        count = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            count++;
            gpioDelay(1);
            if (count > 200) {
                data.error = -2; // Timeout
                return data;
            }
        }

        if (count > 40) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // Convert to bytes
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            raw_data[i] <<= 1;
            raw_data[i] |= data_bits[bit_idx++];
        }
    }

    // Validate checksum
    if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) != raw_data[4]) {
        data.error = -3; // Checksum error
        return data;
    }

    // Convert to temperature and humidity
    data.humidity = (float)((raw_data[0] << 8) | raw_data[1]) / 10.0;
    data.temperature = (float)(((raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
    if (raw_data[2] & 0x80) {
        data.temperature *= -1;
    }

    return data;
}

// Function to post data to the server
int post_data(float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    char json_data[100];
    long response_code = 0;

    // Create JSON payload
    snprintf(json_data, sizeof(json_data), "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);

    // Initialize libcurl
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L); // Set timeout to 10 seconds

        // Perform the request, res will get the return code
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            return -1;
        }

        // Get the response code
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
        printf("HTTP Response Code: %ld\n", response_code);

        curl_easy_cleanup(curl);
        return 0;
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }
}

int main() {
    int retries = 0;
    DHT22Data dht22_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("DHT22 sensor reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        dht22_data = read_dht22_data();

        if (dht22_data.error == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", dht22_data.temperature, dht22_data.humidity);

            if (post_data(dht22_data.temperature, dht22_data.humidity) != 0) {
                fprintf(stderr, "Failed to post data. Retrying...\n");
                retries++;
                if (retries > MAX_RETRIES) {
                    fprintf(stderr, "Max retries reached. Exiting.\n");
                    program_running = 0;
                }
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            retries = 0; // Reset retries on success
        } else {
            fprintf(stderr, "Error reading DHT22 data. Error code: %d. Retrying...\n", dht22_data.error);
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                program_running = 0;
            }
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(5000000); // Delay 5 seconds
    }

    // Clean up
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

