        if (timeout > 100) {
            syslog(LOG_ERR, "DHT22 timeout waiting for end of start signal");
            data.error = -1;
            return data;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_PIN) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 timeout waiting for bit start");
                data.error = -1;
                return data;
            }
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_PIN) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 timeout waiting for bit end");
                data.error = -1;
                return data;
            }
        }
        long end = gpioTick();

        if ((end - start) > 50) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // Convert 40 bits to 5 bytes
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            data_bytes[i] <<= 1;
            data_bytes[i] |= data_bits[bit_idx++];
        }
    }

    // Validate checksum
    if ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) != data_bytes[4]) {
        syslog(LOG_ERR, "DHT22 checksum error");
        data.error = -1;
        return data;
    }

    // Convert data to temperature and humidity
    data.humidity = (float)((data_bytes[0] << 8) | data_bytes[1]) / 10.0;
    data.temperature = (float)(((data_bytes[2] & 0x7F) << 8) | data_bytes[3]) / 10.0;
    if (data_bytes[2] & 0x80) {
        data.temperature *= -1;
    }

    return data;
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    json_t *root = json_object();
    json_object_set_new(root, "temperature", json_real(temperature));
    json_object_set_new(root, "humidity", json_real(humidity));
    char *json_string = json_dumps(root, JSON_REAL_PRECISION(2));
    json_decref(root);
    return json_string;
}

// Function to post data to API
int post_data(const char *json_string) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                syslog(LOG_INFO, "Data posted successfully with code %ld", response_code);
            } else {
                syslog(LOG_ERR, "HTTP request failed with code %ld", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        DHT22Data dht22_data;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            dht22_data = read_dht22();
            if (dht22_data.error == 0) {
                success = 1;
            } else {
                syslog(LOG_WARNING, "DHT22 read failed, retrying (%d/%d)", retries + 1, MAX_RETRIES);
                retries++;
                sleep(BACKOFF_DELAY * (1 << retries)); // Exponential backoff
            }
        }

        if (success) {
            char *json_string = format_json(dht22_data.temperature, dht22_data.humidity);
            retries = 0;
            success = 0;

            while (retries < MAX_RETRIES && !success) {
                if (post_data(json_string) == 0) {
                    success = 1;
                } else {
                    syslog(LOG_WARNING, "HTTP POST failed, retrying (%d/%d)", retries + 1, MAX_RETRIES);
                    retries++;
                    sleep(BACKOFF_DELAY * (1 << retries)); // Exponential backoff
                }
            }

            if (!success) {
                syslog(LOG_ERR, "HTTP POST failed after %d retries", MAX_RETRIES);
            }

            free(json_string);
        } else {
            syslog(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
        }

        sleep(10);
    }

    // Cleanup
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

