#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <stdbool.h>

// Constants
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_TEMP 70.0
#define MIN_TEMP 40.0
#define MAX_SPEED 3
#define MIN_SPEED 0
#define POLL_INTERVAL 5 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int current_fan_speed = 0;

// Function prototypes
float read_cpu_temperature();
int read_fan_speed();
int set_fan_speed(int speed);
int validate_max_state();
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read CPU temperature from file
float read_cpu_temperature() {
    FILE *fp;
    int temp_raw;
    float temperature;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening temperature file.");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_raw) != 1) {
        log_event("Error reading temperature from file.");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temperature = (float)temp_raw / 1000.0;
    return temperature;
}

// Function to read current fan speed from file
int read_fan_speed() {
    FILE *fp;
    int speed;

    fp = fopen(FAN_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening fan speed file.");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &speed) != 1) {
        log_event("Error reading fan speed from file.");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return speed;
}

// Function to set fan speed to a specific value
int set_fan_speed(int speed) {
    FILE *fp;

    if (speed < MIN_SPEED || speed > MAX_SPEED) {
        log_event("Invalid fan speed. Must be between 0 and 3.");
        return -1;
    }

    fp = fopen(FAN_FILE, "w");
    if (fp == NULL) {
        log_event("Error opening fan speed file for writing.");
        return -1;
    }

    if (fprintf(fp, "%d", speed) < 0) {
        log_event("Error writing fan speed to file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to validate the max_state value
int validate_max_state() {
    FILE *fp;
    int max_state;

    fp = fopen(FAN_FILE, "r"); // Open for reading to check max_state
    if (fp == NULL) {
        log_event("Error opening fan speed file for max_state validation.");
        return -1;
    }

    // Read the current fan speed to determine max_state
    int current_speed;
    if (fscanf(fp, "%d", &current_speed) != 1) {
        log_event("Error reading current fan speed for max_state validation.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Determine max_state based on the current speed
    if (current_speed == 0) {
        max_state = 3; // Max speed if off
    } else if (current_speed == 1) {
        max_state = 2; // Max speed if low
    } else if (current_speed == 2) {
        max_state = 1; // Max speed if medium
    } else {
        max_state = 0; // Max speed if high
    }

    // Check if the max_state file exists and contains the correct value
    char max_state_str[2];
    snprintf(max_state_str, sizeof(max_state_str), "%d", max_state);

    char max_state_path[256];
    snprintf(max_state_path, sizeof(max_state_path), "%s/max_state", FAN_FILE);

    fp = fopen(max_state_path, "r");
    if (fp == NULL) {
        log_event("Error opening max_state file for reading.");
        return -1;
    }

    char read_max_state_str[2];
    if (fscanf(fp, "%s", read_max_state_str) != 1) {
        log_event("Error reading max_state from file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (strcmp(read_max_state_str, max_state_str) != 0) {
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Max state validation failed. Expected %s, got %s. Setting max_state to %s.", max_state_str, read_max_state_str, max_state_str);
        log_event(log_message);

        fp = fopen(max_state_path, "w");
        if (fp == NULL) {
            log_event("Error opening max_state file for writing.");
            return -1;
        }

        if (fprintf(fp, "%s", max_state_str) < 0) {
            log_event("Error writing max_state to file.");
            fclose(fp);
            return -1;
        }

        fclose(fp);
    }

    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received shutdown signal. Shutting down...");
        program_running = 0;
    }
}

// Cleanup function to set fan to 0 and close log
void cleanup() {
    log_event("Cleaning up and exiting...");
    set_fan_speed(0); // Ensure fan is off
    closelog();
}

int main() {
    // Initialize syslog
    openlog("fan_control", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Validate max_state
    if (validate_max_state() != 0) {
        log_event("Max state validation failed. Exiting.");
        cleanup();
        return 1;
    }

    log_event("Fan control program started.");

    while (program_running) {
        float temperature = read_cpu_temperature();
        if (temperature < 0) {
            log_event("Error reading CPU temperature. Retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        int new_fan_speed = MIN_SPEED;

        if (temperature < MIN_TEMP) {
            new_fan_speed = 0;
        } else if (temperature < 55.0) {
            new_fan_speed = 1;
        } else if (temperature < 65.0) {
            new_fan_speed = 2;
        } else {
            new_fan_speed = 3;
        }

        if (new_fan_speed != current_fan_speed) {
            if (set_fan_speed(new_fan_speed) == 0) {
                char log_message[256];
                snprintf(log_message, sizeof(log_message), "Fan speed set to %d (temperature: %.2f°C).", new_fan_speed, temperature);
                log_event(log_message);
                current_fan_speed = new_fan_speed;
            } else {
                log_event("Error setting fan speed. Retrying...");
            }
        }

        sleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

