#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_heater_pwm(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855 via SPI
double read_temperature() {
    unsigned char data[4];
    int i;
    int fault = 0;
    double temperature = 0.0;

    // Read 4 bytes from SPI
    for (i = 0; i < 4; i++) {
        data[i] = 0;
    }

    if (spiRead(spi_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Error reading from SPI\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fault = 1;
        fprintf(stderr, "Open circuit fault detected\n");
    }
    if (data[3] & 0x02) {
        fault = 1;
        fprintf(stderr, "Short to GND fault detected\n");
    }
    if (data[3] & 0x04) {
        fault = 1;
        fprintf(stderr, "Short to VCC fault detected\n");
    }

    if (fault) {
        set_heater_pwm(0.0); // Turn off heater
        return -1000.0; // Indicate error
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temperature = ((data[0] << 8) | data[1]) >> 2;
    temperature = raw_temperature * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Clamp output to 0-100%
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 1000000.0 / 100.0); // pigpio range is 0-1000000
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

