#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define TEMP_THRESHOLD_LOW 40.0
#define TEMP_THRESHOLD_HIGH 70.0
#define PWM_RANGE 1000000 // pigpio PWM range

// Global variables
static volatile int running = 1;
static FILE *log_fp = NULL;

// Function prototypes
double read_cpu_temperature();
int set_pwm_duty_cycle(int gpio, int duty_cycle);
int map_temperature_to_duty_cycle(double temperature);
int log_data(FILE *fp, double temperature, int duty_cycle);
void signal_handler(int signal);

// Function to read CPU temperature from file
double read_cpu_temperature() {
    FILE *fp;
    int temp_milli_celsius;
    double temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file %s\n", TEMP_FILE);
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file %s\n", TEMP_FILE);
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (double)temp_milli_celsius / 1000.0;
    return temp_celsius;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to map temperature to duty cycle
int map_temperature_to_duty_cycle(double temperature) {
    int duty_cycle;

    if (temperature <= TEMP_THRESHOLD_LOW) {
        duty_cycle = 0;
    } else if (temperature >= TEMP_THRESHOLD_HIGH) {
        duty_cycle = 1000000; // 100%
    } else {
        duty_cycle = (int)(((temperature - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW)) * PWM_RANGE);
    }

    return duty_cycle;
}

// Function to log data to file
int log_data(FILE *fp, double temperature, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    double temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode to PWM output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }
    fflush(log_fp);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error: Failed to read CPU temperature\n");
        } else {
            // Map temperature to duty cycle
            duty_cycle = map_temperature_to_duty_cycle(temperature);

            // Set PWM duty cycle
            if (set_pwm_duty_cycle(FAN_GPIO, duty_cycle) != 0) {
                fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
            }

            // Log data
            if (log_data(log_fp, temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }

            printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_pwm_duty_cycle(FAN_GPIO, 0); // Turn off fan
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

