#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define retry count
#define MAX_RETRIES 3

// Define CRC8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint32_t flow_rate;
    int status;
} sensor_data_t;

// Function prototypes
int init_i2c();
sensor_data_t read_sensor(int i2c_handle);
uint8_t calculate_crc(const uint8_t *data, size_t len);
void log_data(sensor_data_t sensor1_data, sensor_data_t sensor2_data);
void signal_handler(int signal);
void cleanup();

// CRC8 calculation function
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        return -1;
    }

    return 0;
}

// Read data from a sensor
sensor_data_t read_sensor(int i2c_handle) {
    sensor_data_t data = {0, -1};
    uint8_t buffer[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);
        if (bytes_read == 3) {
            // CRC validation
            uint8_t crc = calculate_crc(buffer, 2);
            if (crc == buffer[2]) {
                // Convert data
                data.flow_rate = (uint32_t)buffer[0] << 8 | buffer[1];
                data.status = 0; // Success
                break; // Exit retry loop
            } else {
                fprintf(stderr, "CRC check failed for sensor. Retrying...\n");
            }
        } else {
            fprintf(stderr, "I2C read error (bytes read: %d). Retrying...\n", bytes_read);
        }

        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        data.status = -1; // Indicate failure
    }

    return data;
}

// Log data to file
void log_data(sensor_data_t sensor1_data, sensor_data_t sensor2_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (sensor1_data.status == 0 && sensor2_data.status == 0) {
        fprintf(log_file, "%s,%u,%u\n", timestamp, sensor1_data.flow_rate, sensor2_data.flow_rate);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Skipping log entry due to sensor read errors.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t sensor1_data = read_sensor(i2c_handle1);
        sensor_data_t sensor2_data = read_sensor(i2c_handle2);

        log_data(sensor1_data, sensor2_data);

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

