// Define GPIO pins for encoder A and B
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_encoder_state(int *state);
double calculate_angle(int state);
int log_position(double angle);
void signal_handler(int signal);
void cleanup();

// Structure to hold encoder state
typedef struct {
    int a_state;
    int b_state;
    int current_state;
} EncoderState;

EncoderState encoder;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the current state of the encoder
int read_encoder_state(int *state) {
    int a_val = gpioRead(ENCODER_A_PIN);
    int b_val = gpioRead(ENCODER_B_PIN);

    if (a_val == PI_BAD_GPIO || b_val == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO pin\n");
        return -1;
    }

    *state = (a_val << 1) | b_val;
    return 0;
}

// Function to calculate the angle based on the encoder state
double calculate_angle(int state) {
    // Quadrature encoding table
    int angle_table[4][2] = {
        {0, 0},   // 00
        {90, 0},  // 01
        {180, 0}, // 10
        {270, 0}  // 11
    };

    return angle_table[state][0];
}

// Function to log the position to a file
int log_position(double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, angle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    encoder.a_state = gpioRead(ENCODER_A_PIN);
    encoder.b_state = gpioRead(ENCODER_B_PIN);
    encoder.current_state = (encoder.a_state << 1) | encoder.b_state;

    // Main loop
    while (running) {
        int new_state;
        if (read_encoder_state(&new_state) == 0) {
            if (new_state != encoder.current_state) {
                double angle = calculate_angle(new_state);
                if (log_position(angle) != 0) {
                    fprintf(stderr, "Error logging position\n");
                }
                encoder.current_state = new_state;
            }
        } else {
            fprintf(stderr, "Error reading encoder state\n");
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

