#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int pulse_count, double interval_sec);
void log_rpm(double rpm);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine (ISR)
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user;  // unused

    if (pthread_mutex_lock(&pulse_mutex) != 0) {
        perror("Failed to lock mutex in ISR");
        return;
    }

    pulse_count++;

    if (pthread_mutex_unlock(&pulse_mutex) != 0) {
        perror("Failed to unlock mutex in ISR");
    }
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, double interval_sec) {
    return (double)pulse_count / interval_sec * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
