// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18

// Define constants
#define GAIN_60DB 0
#define GAIN_30DB 1
#define SAMPLE_RATE 10000 // 10 kHz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // 10 ms
#define LOG_FILE "audio_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int set_gain(int gain);
int sample_audio();
int detect_rising_edge();
int log_event();
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int current_gain;
} ProgramState;

ProgramState state = {GAIN_60DB}; // Initialize to 60dB gain

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Set initial gain
    if (set_gain(state.current_gain) != 0) {
        fprintf(stderr, "Failed to set initial gain. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Print startup message
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stdout, "%s Audio monitoring started. Logging to %s\n", timestamp, LOG_FILE);

    // Main loop
    while (running) {
        if (sample_audio() != 0) {
            fprintf(stderr, "Error sampling audio. Continuing.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

