#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_I2C_ADDR 0x36
#define MEASUREMENT_COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define FLOW_RATE_RESOLUTION 0.01
#define MEASUREMENT_DELAY_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t raw_flow_rate;
    float flow_rate_uL_min;
    int crc_valid;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_measurement_command(int i2c_handle);
int read_sensor_data(int i2c_handle, uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
float convert_to_flow_rate(uint16_t raw_flow_rate);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    int handle = i2cOpen(I2C_BUS, SLF3S_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to send measurement command
int send_measurement_command(int i2c_handle) {
    char buf[2];
    buf[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    buf[1] = MEASUREMENT_COMMAND & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to flow rate
float convert_to_flow_rate(uint16_t raw_flow_rate) {
    return (float)raw_flow_rate * FLOW_RATE_RESOLUTION;
}

// Function to log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[3];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_measurement_command(i2c_handle) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Validate CRC
        uint8_t crc_calculated = calculate_crc(data, 2);
        if (crc_calculated != data[2]) {
            fprintf(stderr, "CRC validation failed\n");
            sensor_data.crc_valid = 0;
        } else {
            sensor_data.crc_valid = 1;
        }

        // Convert raw data to flow rate
        sensor_data.raw_flow_rate = (data[0] << 8) | data[1];
        if (sensor_data.crc_valid) {
            sensor_data.flow_rate_uL_min = convert_to_flow_rate(sensor_data.raw_flow_rate);
        } else {
            sensor_data.flow_rate_uL_min = -1.0; // Indicate CRC failure
        }

        // Log flow rate
        if (sensor_data.crc_valid) {
            log_flow_rate(sensor_data.flow_rate_uL_min);
        }

        // Delay
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

