#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
int calculate_iaq_index(uint16_t tvoc, uint16_t eco2);
int log_data(uint16_t iaq_index, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the MICS-VZ-89TE
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[4];
    int result;

    // Read 4 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        data.tvoc = 0; // Set default values in case of error
        data.eco2 = 0;
        return data;
    }

    // Combine the bytes to form the TVOC and eCO2 values
    data.tvoc = (buf[0] << 8) | buf[1];
    data.eco2 = (buf[2] << 8) | buf[3];

    return data;
}

// Function to calculate the IAQ index (example formula)
int calculate_iaq_index(uint16_t tvoc, uint16_t eco2) {
    // This is a placeholder.  A real IAQ index calculation
    // would be based on the sensor's datasheet and calibration data.
    // This example uses a simple linear combination.
    return (int)((tvoc + eco2) / 2); // Replace with a proper formula
}

// Function to log data to a CSV file
int log_data(uint16_t iaq_index, uint16_t tvoc, uint16_t eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u\n", timestamp, iaq_index, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQIndex,TVOC(ppb),eCO2(ppm)\n");
    }
    fflush(log_file);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Calculate IAQ index
        int iaq_index = calculate_iaq_index(sensor_data.tvoc, sensor_data.eco2);

        // Log the data
        log_data(iaq_index, sensor_data.tvoc, sensor_data.eco2);

        // Wait for the next reading
        sleep(READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

