#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define TOUCH_SENSOR_GPIO 17
#define TAMPER_ALERT_DURATION 5 // seconds
#define POLLING_INTERVAL 100 // milliseconds

static volatile int running = 1;
static volatile int tamper_detected = 0;
static volatile time_t tamper_start_time = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_GPIO);
}

// Function to check for tamper event
void check_tamper_event() {
    int sensor_value = read_touch_sensor();

    if (sensor_value == 1) {
        if (tamper_detected == 0) {
            tamper_detected = 1;
            tamper_start_time = time(NULL);
            printf("Tamper event detected!\n");
        } else {
            // Tamper event already detected, check duration
            time_t current_time = time(NULL);
            if (difftime(current_time, tamper_start_time) >= TAMPER_ALERT_DURATION) {
                printf("Tamper alert: Continuous touch detected for %d seconds!\n", (int)difftime(current_time, tamper_start_time));
                tamper_detected = 0; // Reset tamper detection
            }
        }
    } else {
        tamper_detected = 0; // Reset tamper detection if sensor is released
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    printf("GPIO resources released.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        check_tamper_event();
        gpioDelay(POLLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

