#include <pigpio.h>

// Configuration
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 2 // 16-bit samples
#define BUFFER_SIZE 1024
#define GPIO_PIN 17
#define FILE_NAME "audio_capture.pcm"

// Global variables
snd_pcm_t *pcm_handle;
FILE *audio_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int init_gpio(int gpio_pin);
int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file, int gpio_pin);
void signal_handler(int sig);
void cleanup(snd_pcm_t *pcm_handle, FILE *audio_file);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// ALSA initialization function
int init_alsa(snd_pcm_t **pcm_handle) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    // Open PCM device for capture
    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set format to 16-bit little-endian
    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int init_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0); // Initially select left channel
    return 0;
}

// Audio capture function
int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file, int gpio_pin) {
    char buffer[BUFFER_SIZE * SAMPLE_SIZE * NUM_CHANNELS];
    int err;

    while (!terminate) {
        // Read audio data from ALSA
        int frames = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE);
        if (frames < 0) {
            fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(frames));
            return -1;
        } else if (frames == 0) {
            //fprintf(stderr, "End of file\n");
            continue; // Handle end of file gracefully
        }

        // Write data to file
        size_t bytes_written = fwrite(buffer, 1, frames * SAMPLE_SIZE * NUM_CHANNELS, audio_file);
        if (bytes_written != frames * SAMPLE_SIZE * NUM_CHANNELS) {
            fprintf(stderr, "Error writing to file\n");
            return -1;
        }

        // Toggle GPIO to select right channel
        gpioWrite(gpio_pin, 1);
        gpioDelay(1000); // 1ms delay
        gpioWrite(gpio_pin, 0);
        gpioDelay(1000); // 1ms delay
    }

    return 0;
}

// Cleanup function
void cleanup(snd_pcm_t *pcm_handle, FILE *audio_file) {
    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }
    if (audio_file) {
        fclose(audio_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) < 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup(pcm_handle, NULL);
        return 1;
    }

    // Open audio file for writing
    audio_file = fopen(FILE_NAME, "wb");
    if (!audio_file) {
        fprintf(stderr, "Error opening audio file\n");
        cleanup(pcm_handle, NULL);
        return 1;
    }

    // Capture audio
    if (capture_audio(pcm_handle, audio_file, GPIO_PIN) < 0) {
        fprintf(stderr, "Audio capture failed\n");
        cleanup(pcm_handle, audio_file);
        return 1;
    }

    // Cleanup resources
    cleanup(pcm_handle, audio_file);

    printf("Audio capture complete. File saved as %s\n", FILE_NAME);

    return 0;
}

