#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Define timeout time (in milliseconds)
#define TIMEOUT_TIME 1000

// Global variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void start_fan();
void stop_fan();
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int i;
    int low_count = 0;

    // Debounce the sensor
    for (i = 0; i < 5; i++) { // 5 * 50ms = 250ms debounce
        if (gpioRead(FLAME_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_TIME * 1000); // Delay in microseconds
    }

    // Check if the sensor is consistently LOW after debouncing
    if (low_count == 5) {
        return 0; // Flame detected
    } else {
        return 1; // No flame detected
    }
}

// Function to start the fan
void start_fan() {
    gpioPWM(FAN_PIN, 128); // 50% duty cycle
    log_event("FAN_START");
}

// Function to stop the fan
void stop_fan() {
    gpioPWM(FAN_PIN, 0); // 0% duty cycle
    log_event("FAN_STOP");
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    stop_fan();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    log_event("SYSTEM_START");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            // Flame detected
            start_fan();
        } else {
            // No flame detected
            stop_fan();
        }

        gpioDelay(50 * 1000); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

