#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_FRAME_TRIGGER 23
#define GPIO_DATA_READY 24
#define FRAME_PERIOD_MS 100
#define FRAME_SIZE 32768
#define MAGIC_NUMBER 0x41444D414244494E // "ADMIHDR"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t num_chirps;
    uint16_t num_samples;
} radar_config_t;

// Function prototypes
int initialize_spi();
int configure_gpio();
int capture_frame(uint8_t *frame_data);
int log_frame(uint8_t *frame_data, uint64_t timestamp);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Configure GPIO pins
int configure_gpio() {
    if (gpioSetMode(GPIO_FRAME_TRIGGER, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_FRAME_TRIGGER);
        return -1;
    }
    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_DATA_READY);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up resistor on GPIO %d\n", GPIO_DATA_READY);
        return -1;
    }
    return 0;
}

// Capture a frame of data from the radar sensor
int capture_frame(uint8_t *frame_data) {
    int bytes_read = spiRead(spi_handle, frame_data, FRAME_SIZE);
    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "Error reading SPI data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Log a frame to a binary file
int log_frame(uint8_t *frame_data, uint64_t timestamp) {
    // Get current frame number
    static uint32_t frame_number = 0;
    frame_number++;

    // Write header
    if (fwrite(&MAGIC_NUMBER, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing magic number to log file\n");
        return -1;
    }
    if (fwrite(&timestamp, sizeof(uint64_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing timestamp to log file\n");
        return -1;
    }
    if (fwrite(&timestamp, sizeof(uint64_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing timestamp to log file\n");
        return -1;
    }
    if (fwrite(&frame_number, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing frame number to log file\n");
        return -1;
