#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the flame state to a file
int log_flame_state(const char* timestamp, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%d\n", timestamp, state);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main() {
    int current_state = -1; // Initialize to an invalid state
    int previous_state = -1;
    char* timestamp = NULL;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the current state of the GPIO pin
        current_state = gpioRead(GPIO_PIN);

        // Check for errors during GPIO read
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO pin %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        // Check if the state has changed
        if (current_state != previous_state) {
            // Get the current timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp == NULL) {
                fprintf(stderr, "Failed to get timestamp\n");
                gpioTerminate();
                return 1;
            }

            // Log the state change
            if (log_flame_state(timestamp, current_state) != 0) {
                fprintf(stderr, "Failed to log flame state\n");
            }

            // Free the allocated memory for the timestamp
            free(timestamp);

            // Update the previous state
            previous_state = current_state;
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

