#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE_FACTOR 0.0036
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *raw_value);
float calculate_lux(uint16_t raw_value);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (optional)
typedef struct {
    uint16_t config_value;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    uint16_t config_value = 0x0002; // Continuous conversion mode, auto range
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to config register (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to configure sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to read raw sensor data
int read_sensor_data(uint16_t *raw_value) {
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, RESULT_REG);
        if (result >= 0) {
            *raw_value = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading result register (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to calculate lux value
float calculate_lux(uint16_t raw_value) {
    uint16_t exponent = (raw_value >> 12) & 0x0F;
    uint16_t result = raw_value & 0x0FFF;
    return (float)result * LUX_SCALE_FACTOR * (1 << exponent);
}

// Function to log data to file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    uint16_t raw_value;
    float lux_value;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_value) == 0) {
            // Calculate lux value
            lux_value = calculate_lux(raw_value);

            // Log data
            log_data(lux_value);

            // Print to console for debugging
            printf("Lux: %.2f\n", lux_value);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait 100ms
        gpioDelay(100000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

