#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 channels
const int sensor_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of all sensor channels
int read_sensor_state(int *sensor_state) {
    for (int i = 0; i < num_channels; i++) {
        int level = gpioRead(sensor_pins[i]);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", sensor_pins[i], level);
            return -1; // Indicate an error
        }
        sensor_state[i] = level;
    }
    return 0; // Indicate success
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int *sensor_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("%d", sensor_state[i]);
    }
    printf("\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to continuously read and log sensor data
    int sensor_state[num_channels];
    while (program_running) {
        if (read_sensor_state(sensor_state) == 0) {
            log_sensor_data(sensor_state);
        } else {
            fprintf(stderr, "Error reading sensor data. Exiting.\n");
            break; // Exit the loop if there's an error
        }
        gpioDelay(100); // Wait for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

