#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TILT_PIN 4 // BCM pin 7

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state
    int result;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as input with pull-up resistor
    gpioSetMode(TILT_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_PIN, PI_PUD_UP);

    // Print startup banner
    printf("Tilt Sensor Monitoring Program\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the GPIO pin
        result = gpioRead(TILT_PIN);
        if (result < 0) {
            fprintf(stderr, "Error reading GPIO pin: %d\n", result);
            gpioTerminate();
            return 1;
        }

        current_state = result;

        // Check for state change
        if (current_state != previous_state) {
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout); // Flush the output buffer
            previous_state = current_state;
        }

        gpioDelay(100); // Wait 100ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

