#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_UV_INDEX0 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(float *uv_index, int *als_visible);
void log_data(float uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    terminate = 1;
}

// Initialize the Si1145 sensor
int init_si1145() {
    // Check the Part ID register
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register: %d\n", part_id);
        return -1;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x00) < 0) { // PS1_ADCMUX = 0
        fprintf(stderr, "Error writing to PS1_ADCMUX register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x19, 0x00) < 0) { // PS2_ADCMUX = 0
        fprintf(stderr, "Error writing to PS2_ADCMUX register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x1A, 0x00) < 0) { // PS3_ADCMUX = 0
        fprintf(stderr, "Error writing to PS3_ADCMUX register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) { // UCOEF0
        fprintf(stderr, "Error writing to UCOEF0 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x04, 0x02) < 0) { // UCOEF1
        fprintf(stderr, "Error writing to UCOEF1 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x05, 0x03) < 0) { // UCOEF2
        fprintf(stderr, "Error writing to UCOEF2 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x06, 0x04) < 0) { // UCOEF3
        fprintf(stderr, "Error writing to UCOEF3 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x07, 0x05) < 0) { // UCOEF4
        fprintf(stderr, "Error writing to UCOEF4 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x08, 0x06) < 0) { // UCOEF5
        fprintf(stderr, "Error writing to UCOEF5 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x09, 0x07) < 0) { // UCOEF6
        fprintf(stderr, "Error writing to UCOEF6 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0A, 0x08) < 0) { // UCOEF7
        fprintf(stderr, "Error writing to UCOEF7 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0B, 0x09) < 0) { // UCOEF8
        fprintf(stderr, "Error writing to UCOEF8 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0C, 0x0A) < 0) { // UCOEF9
        fprintf(stderr, "Error writing to UCOEF9 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0D, 0x0B) < 0) { // UCOEF10
        fprintf(stderr, "Error writing to UCOEF10 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0E, 0x0C) < 0) { // UCOEF11
        fprintf(stderr, "Error writing to UCOEF11 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0F, 0x0D) < 0) { // UCOEF12
        fprintf(stderr, "Error writing to UCOEF12 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x10, 0x0E) < 0) { // UCOEF13
        fprintf(stderr, "Error writing to UCOEF13 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x11, 0x0F) < 0) { // UCOEF14
        fprintf(stderr, "Error writing to UCOEF14 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x12, 0x10) < 0) { // UCOEF15
        fprintf(stderr, "Error writing to UCOEF15 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x13, 0x11) < 0) { // UCOEF16
        fprintf(stderr, "Error writing to UCOEF16 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x14, 0x12) < 0) { // UCOEF17
        fprintf(stderr, "Error writing to UCOEF17 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x15, 0x13) < 0) { // UCOEF18
        fprintf(stderr, "Error writing to UCOEF18 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x16, 0x14) < 0) { // UCOEF19
        fprintf(stderr, "Error writing to UCOEF19 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x17, 0x15) < 0) { // UCOEF20
        fprintf(stderr, "Error writing to UCOEF20 register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x18, 0x00) < 0) { // PS1_ADCMUX = 0
        fprintf(stderr, "Error writing to PS1_ADCMUX register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x19, 0x00) < 0) { // PS2_ADCMUX = 0
        fprintf(stderr, "Error writing to PS2_ADCMUX register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x1A, 0x00) < 0) { // PS3_ADCMUX = 0
        fprintf(stderr, "Error writing to PS3_ADCMUX register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x01, 0x01) < 0) { // Enable UV index
        fprintf(stderr, "Error writing to MEAS_RATE register\n");
        return -1;
    }

    return 0;
}

// Read UV index and visible ambient light data from the Si1145 sensor
int read_si1145_data(float *uv_index, int *als_visible) {
    int als_vis_low, als_vis_high, uv_index_low;

    als_vis_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    if (als_vis_low < 0) {
        fprintf(stderr, "Error reading ALS Visible Data 0 register: %d\n", als_vis_low);
        return -1;
    }

    als_vis_high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);
    if (als_vis_high < 0) {
        fprintf(stderr, "Error reading ALS Visible Data 1 register: %d\n", als_vis_high);
        return -1;
    }

    uv_index_low = i2cReadByteData(i2c_handle, REG_UV_INDEX0);
    if (uv_index_low < 0) {
        fprintf(stderr, "Error reading UV Index 0 register: %d\n", uv_index_low);
        return -1;
    }

    *als_visible = (als_vis_high << 8) | als_vis_low;
    *uv_index = (float)uv_index_low / 10.0; // UV index is stored as a 8-bit value

    return 0;
}

// Log data to the CSV file
void log_data(float uv_index, int als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    float uv_index;
    int als_visible;

    while (!terminate) {
        if (read_si1145_data(&uv_index, &als_visible) == 0) {
            printf("UV Index: %.2f, Visible Light: %d\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

