int read_si1145_data(float *uv_index, int *als_visible) {
    int als_vis_low, als_vis_high, uv_index_low;

    als_vis_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    if (als_vis_low < 0) {
        fprintf(stderr, "Error reading ALS Visible Data 0 register: %d\n", als_vis_low);
        return -1;
    }

    als_vis_high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);
    if (als_vis_high < 0) {
        fprintf(stderr, "Error reading ALS Visible Data 1 register: %d\n", als_vis_high);
        return -1;
    }

    uv_index_low = i2cReadByteData(i2c_handle, REG_UV_INDEX0);
    if (uv_index_low < 0) {
        fprintf(stderr, "Error reading UV Index 0 register: %d\n", uv_index_low);
        return -1;
    }

    *als_visible = (als_vis_high << 8) | als_vis_low;
    *uv_index = (float)uv_index_low / 10.0; // UV index is stored as a 8-bit value

    return 0;
}

