#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define ALARM_GPIO 17
#define START_COMMAND 0x3090
#define FLOW_RATE_REG 0x00
#define CRC_POLYNOMIAL 0x31
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define ALARM_THRESHOLD 0.5
#define START_DELAY_MS 100
#define READ_DELAY_S 1

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_flow_rate(int i2c_handle, float *flow_rate);
int validate_crc(uint8_t data[], int len);
float calculate_average_flow_rate(float flow_rate1, float flow_rate2);
void set_alarm_state(int state);
void log_error(const char *message);
void signal_handler(int signal);

// CRC calculation function
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

// I2C initialization function
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Flow rate reading function
int read_flow_rate(int i2c_handle, float *flow_rate) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);
    if (bytes_read != 3) {
        log_error("I2C read error");
        return -1;
    }

    if (!validate_crc((uint8_t *)buf, 3)) {
        log_error("CRC validation failed");
        return -1;
    }

    int16_t raw_flow = (buf[0] << 8) | buf[1];
    *flow_rate = (float)raw_flow / 100.0; // Scale factor from datasheet

    if (*flow_rate < FLOW_RATE_MIN || *flow_rate > FLOW_RATE_MAX) {
        log_error("Flow rate out of range");
        return -1;
    }

    return 0;
}

// Average flow rate calculation function
float calculate_average_flow_rate(float flow_rate1, float flow_rate2) {
    if (flow_rate1 == -1.0 && flow_rate2 == -1.0) {
        return -1.0; // Both readings failed
    } else if (flow_rate1 == -1.0) {
        return flow_rate2; // Only sensor 2 valid
    } else if (flow_rate2 == -1.0) {
        return flow_rate1; // Only sensor 1 valid
    } else {
        return (flow_rate1 + flow_rate2) / 2.0; // Both readings valid
    }
}

// Alarm state control function
void set_alarm_state(int state) {
    gpioWrite(ALARM_GPIO, state);
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start command
    char start_cmd[2] = {(START_COMMAND >> 8) & 0xFF, START_COMMAND & 0xFF};
    i2cWriteDevice(i2c_handle1, start_cmd, 2);
    i2cWriteDevice(i2c_handle2, start_cmd, 2);
    gpioDelay(START_DELAY_MS * 1000); // Delay in microseconds

    float flow_rate1, flow_rate2, avg_flow_rate;
    int alarm_state;

    // Main loop
    while (!terminate) {
        // Read flow rates
        if (read_flow_rate(i2c_handle1, &flow_rate1) == -1) {
            flow_rate1 = -1.0; // Mark as invalid
        }
        if (read_flow_rate(i2c_handle2, &flow_rate2) == -1) {
            flow_rate2 = -1.0; // Mark as invalid
        }

        // Calculate average flow rate
        avg_flow_rate = calculate_average_flow_rate(flow_rate1, flow_rate2);

        // Set alarm state
        if (avg_flow_rate < ALARM_THRESHOLD) {
            alarm_state = 1;
        } else {
            alarm_state = 0;
        }
        set_alarm_state(alarm_state);

        // Log data
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Avg: %.2f ml/min, Alarm: %d\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec,
                flow_rate1, flow_rate2, avg_flow_rate, alarm_state);
        fflush(log_file);

        // Wait for next reading
        sleep(READ_DELAY_S);
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();

    return 0;
}

