#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100

// Structure to hold the circular buffer
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer obstacle_buffer;
int running = 1;

// Function prototypes
int initialize_pigpio();
int read_sensor();
void add_to_buffer(CircularBuffer *cb, int value);
void print_buffer(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    } else {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    }
}

// Print the contents of the circular buffer
void print_buffer(CircularBuffer *cb) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    int i;

    printf("Obstacle Detection Log:\n");

    for (i = 0; i < cb->count; i++) {
        int index = (cb->tail + i) % BUFFER_SIZE;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("%s: %s\n", timestamp, cb->buffer[index] == 0 ? "Obstacle Detected" : "No Obstacle");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize the circular buffer
    init_buffer(&obstacle_buffer);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        add_to_buffer(&obstacle_buffer, sensor_value);

        if (sensor_value == 0) {
            printf("Obstacle Detected!\n");
        }

        gpioDelay(50); // Sample every 50ms
    }

    // Print the buffer before exiting
    print_buffer(&obstacle_buffer);

    // Cleanup and exit
    cleanup();
    return 0;
}

