#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    *sensor1_value = gpioRead(SENSOR1_PIN);
    *sensor2_value = gpioRead(SENSOR2_PIN);
    return 0;
}

// Function to control the LED
void control_led(int sensor1_value, int sensor2_value) {
    if (sensor1_value == 0 || sensor2_value == 0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        int sensor1_value, sensor2_value;

        if (read_sensors(&sensor1_value, &sensor2_value) != 0) {
            fprintf(stderr, "Error reading sensors\n");
        }

        control_led(sensor1_value, sensor2_value);

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup GPIO resources
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

