#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_SEC 2
#define LOG_FILE "stall_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
int is_stall(int sensor1_value, int sensor2_value);
void log_stall_event(const char *timestamp);
void signal_handler(int signal);

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to determine if a stall has occurred
int is_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log a stall event to a file
void log_stall_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    // Check if the event is a duplicate
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    fseek(log_file, 0, SEEK_SET);

    char line[256];
    int duplicate = 0;
    while (fgets(line, sizeof(line), log_file) != NULL) {
        if (strstr(line, timestamp) != NULL) {
            duplicate = 1;
            break;
        }
    }

    if (file_size == 0 || !duplicate) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
        printf("Stall event logged: %s\n", timestamp);
    } else {
        printf("Duplicate stall event detected: %s\n", timestamp);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time = 0;
    int stall_confirmed = 0;

    printf("Monitoring conveyor belt... Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, but continue monitoring
            gpioDelay(100); // Small delay to prevent busy-waiting
            continue;
        }

        if (is_stall(sensor1_value, sensor2_value)) {
            if (!stall_confirmed) {
                start_time = time(NULL);
                stall_confirmed = 1;
                printf("Stall confirmed.\n");
            } else {
                time_t current_time = time(NULL);
                if (difftime(current_time, start_time) >= STALL_DURATION_SEC) {
                    char timestamp[32];
                    struct tm *tm_info = localtime(&current_time);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                    log_stall_event(timestamp);
                    stall_confirmed = 0; // Reset stall confirmation
                }
            }
        } else {
            stall_confirmed = 0; // Reset stall confirmation if sensors are not low
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

