#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x08

// TMAG5170 register addresses
#define REG_X_AXIS 0x00
#define REG_Y_AXIS 0x02
#define REG_Z_AXIS 0x04
#define REG_CONFIG 0x06

// Configuration values
#define CONFIG_CONTINUOUS 0x03 // Continuous conversion mode
#define CONFIG_RANGE_50MT 0x00 // 50mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
int log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize the TMAG5170 sensor
int initialize_sensor() {
    char buf[2];
    int result;

    // Set continuous conversion mode and 50mT range
    buf[0] = REG_CONFIG;
    buf[1] = (CONFIG_CONTINUOUS << 4) | CONFIG_RANGE_50MT;

    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read magnetic field data from the sensor
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[1];
    char data[6];
    int result;

    // Read X axis
    buf[0] = REG_X_AXIS;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to X axis register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Log data to CSV file
int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int16_t x, y, z;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Log data
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

