#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"

static volatile int running = 1;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an alert message to the log file
void log_alert(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    char *timestamp = get_timestamp();
    fprintf(fp, "%s ALERT: %s\n", timestamp, message);
    free(timestamp);
    fclose(fp);
}

// Function to read the sensor value from the GPIO pin
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to handle the alert
void handle_alert() {
    log_alert("Water detected!");
}

// Function to initialize the pigpio library and set the GPIO pin mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor
    return 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            handle_alert();
        }

        sleep(2);
    }

    // Cleanup
    gpioTerminate();
    printf("Water level monitoring stopped.\n");

    return 0;
}

