#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/file.h>
#include <wiringPi.h>

// Define the GPIO pin connected to the Hall-effect sensor
#define SENSOR_PIN 4

// Define the log file name
#define LOG_FILE "rpm_log.txt"

// Define the interrupt handler function
void interruptHandler(void);

// Global variables
volatile int pulseCount = 0;
FILE *logFile = NULL;
int logFileDescriptor = -1;
int logFileLocked = 0;

// Function prototypes
int initializeGPIO(void);
int openLogFile(void);
void closeLogFile(void);
void logRPM(int rpm);
void interruptHandler(void);
void signalHandler(int signal);

// Function to initialize the GPIO pin
int initializeGPIO(void) {
  if (wiringPiSetupGpio() == -1) {
    fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
    return -1;
  }

  pinMode(SENSOR_PIN, INPUT);
  pullUpDnControl(SENSOR_PIN, PUD_UP);

  return 0;
}

// Function to open the log file
int openLogFile(void) {
  logFile = fopen(LOG_FILE, "a");
  if (logFile == NULL) {
    fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    return -1;
  }

  logFileDescriptor = fileno(logFile);
  return 0;
}

// Function to close the log file
void closeLogFile(void) {
  if (logFile != NULL) {
    fclose(logFile);
    logFile = NULL;
  }
  if (logFileDescriptor != -1) {
    close(logFileDescriptor);
    logFileDescriptor = -1;
  }
  logFileLocked = 0;
}

// Function to log the RPM to the file
void logRPM(int rpm) {
  time_t now = time(NULL);
  struct tm *t = localtime(&now);
  char timestamp[20];
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

  if (logFile != NULL) {
    flock(logFileDescriptor, LOCK_EX);
    logFileLocked = 1;

    fprintf(logFile, "%s %d\n", timestamp, rpm);
    fflush(logFile);

    flock(logFileDescriptor, LOCK_UN);
    logFileLocked = 0;
  } else {
    fprintf(stderr, "Log file is not open.\n");
  }
}

// Interrupt handler function
void interruptHandler(void) {
  pulseCount++;
}

// Signal handler function
void signalHandler(int signal) {
  printf("Caught signal %d, cleaning up...\n", signal);

  // Disable interrupts
  wiringPiISR(SENSOR_PIN, INT_EDGE_RISING, NULL);

  // Close the log file
  closeLogFile();

  // Exit the program
  exit(0);
}

int main(void) {
  // Install signal handlers
  signal(SIGINT, signalHandler);
  signal(SIGTERM, signalHandler);

  // Initialize GPIO
  if (initializeGPIO() == -1) {
    return 1;
  }

  // Open the log file
  if (openLogFile() == -1) {
    return 1;
  }

  // Set up the interrupt
  if (wiringPiISR(SENSOR_PIN, INT_EDGE_RISING, interruptHandler) < 0) {
    fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
    closeLogFile();
    return 1;
  }

  // Main loop
  while (1) {
    // Wait for one second
    sleep(1);

    // Calculate the RPM
    int rpm = (pulseCount * 60) / 1; // Assuming one pulse per revolution

    // Log the RPM
    logRPM(rpm);

    // Reset the pulse count
    pulseCount = 0;
  }

  return 0;
}

