#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the quadrature states
typedef enum {
    QUAD_STATE_A_LOW_B_LOW,
    QUAD_STATE_A_HIGH_B_LOW,
    QUAD_STATE_A_HIGH_B_HIGH,
    QUAD_STATE_A_LOW_B_HIGH
} quad_state_t;

// Structure to hold the quadrature state and mutex
typedef struct {
    quad_state_t state;
    pthread_mutex_t mutex;
} quad_state_data_t;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static quad_state_data_t quad_state = {QUAD_STATE_A_LOW_B_LOW, PTHREAD_MUTEX_INITIALIZER};

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_rotation_event(const char *direction);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user);
quad_state_t get_next_state(quad_state_t current_state, int sensor_a_level, int sensor_b_level);
void *logging_thread(void *arg);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Set up interrupt handlers
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, EITHER_EDGE, 0, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Sensor A\n");
        return -1;
    }

    if (gpioSetISRFuncEx(SENSOR_B_GPIO, EITHER_EDGE, 0, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Sensor B\n");
        return -1;
    }

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

// Log rotation event to file
void log_rotation_event(const char *direction) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%03ld",
             ts.tv_sec / 100000000 % 1000000000, // Year (not used)
