} LogEvent;

// Circular buffer structure
typedef struct {
    LogEvent buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow_count;
} CircularBuffer;

// Global variables
CircularBuffer log_buffer;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void control_led(int pin, int state);
void add_to_buffer(CircularBuffer *buffer, int sensor_pin, int state);
void print_buffer(CircularBuffer *buffer);
void signal_handler(int signal);

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);

    return 0;
}

// Read sensor value with debouncing
int read_sensor(int pin) {
    int value = gpioRead(pin);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay in microseconds
    return value;
}

// Control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Add log event to circular buffer
void add_to_buffer(CircularBuffer *buffer, int sensor_pin, int state) {
    time_t now = time(NULL);
    buffer->buffer[buffer->head].sensor_pin = sensor_pin;
    buffer->buffer[buffer->head].timestamp = now;
    buffer->buffer[buffer->head].state = state;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->head == buffer->tail) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
        buffer->overflow_count++;
    }
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Print the contents of the circular buffer
void print_buffer(CircularBuffer *buffer) {
    printf("\n--- Log Buffer Contents ---\n");
    int i = buffer->tail;
    for (int j = 0; j < buffer->count; j++) {
        printf("Sensor: %d, Timestamp: %ld, State: %d\n", buffer->buffer[i].sensor_pin, buffer->buffer[i].timestamp, buffer->buffer[i].state);
        i = (i + 1) % BUFFER_SIZE;
    }
    printf("--- End of Log Buffer ---\n");
    printf("Overflow Count: %d\n", buffer->overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize circular buffer
    log_buffer.head = 0;
    log_buffer.tail = 0;
    log_buffer.count = 0;
    log_buffer.overflow_count = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int sensor1_state = 0;
    int sensor2_state = 0;
    int led1_state = 0;
    int led2_state = 0;

    while (running) {
        // Read sensor values
        int new_sensor1_state = read_sensor(SENSOR1_PIN);
        int new_sensor2_state = read_sensor(SENSOR2_PIN);

        // Control LEDs based on sensor states
        if (new_sensor1_state != sensor1_state) {
            control_led(LED1_PIN, new_sensor1_state);
            sensor1_state = new_sensor1_state;
            add_to_buffer(&log_buffer, SENSOR1_PIN, new_sensor1_state);
        }
        if (new_sensor2_state != sensor2_state) {
            control_led(LED2_PIN, new_sensor2_state);
            sensor2_state = new_sensor2_state;
            add_to_buffer(&log_buffer, SENSOR2_PIN, new_sensor2_state);
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Graceful shutdown
    control_led(LED1_PIN, 0);
    control_led(LED2_PIN, 0);
    print_buffer(&log_buffer);
    gpioTerminate();

    return 0;
}

