    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    int previous_state = -1; // Initialize to an invalid state

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0 && previous_state != 0) {
            log_event("Rain Detected");
            previous_state = 0;
        } else if (sensor_value == 1 && previous_state != 1) {
            log_event("No Rain");
            previous_state = 1;
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

