#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in microseconds
#define DEBOUNCE_TIME 5000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static volatile unsigned long last_tick1 = 0;
static volatile unsigned long last_tick2 = 0;
static volatile int sensor1_state = 0;
static volatile int sensor2_state = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
void log_data(int sensor1_state, int sensor2_state);
float calculate_rpm();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int gpio;
    int state;
    unsigned long last_tick;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Enable pull-up resistors (optional, depending on your wiring)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor with debouncing
int read_sensor(int gpio) {
    int current_state = gpioRead(gpio);
    unsigned long current_tick = gpioTick();

    if (gpio == SENSOR1_GPIO) {
        if (current_state != sensor1_state) {
            if (current_tick - last_tick1 > DEBOUNCE_TIME) {
                sensor1_state = current_state;
                last_tick1 = current_tick;
                return sensor1_state;
            }
        }
    } else if (gpio == SENSOR2_GPIO) {
        if (current_state != sensor2_state) {
            if (current_tick - last_tick2 > DEBOUNCE_TIME) {
                sensor2_state = current_state;
                last_tick2 = current_tick;
                return sensor2_state;
            }
        }
    }

    return sensor1_state; // Return the last known state if debounced
}

// Function to log sensor data to a CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate RPM
float calculate_rpm() {
    static unsigned long last_time = 0;
    unsigned long current_time = gpioTick();
    float rpm = 0.0;

    if (last_time != 0) {
        unsigned long time_diff = current_time - last_time;
        if (time_diff > 0) {
            rpm = 60000000.0 / time_diff; // Convert to RPM (ticks per second)
        }
    }
    last_time = current_time;
    return rpm;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor data
        int sensor1 = read_sensor(SENSOR1_GPIO);
        int sensor2 = read_sensor(SENSOR2_GPIO);

        // Log the data
        log_data(sensor1, sensor2);

        // Calculate and print RPM
        float rpm = calculate_rpm();
        printf("RPM: %.2f\n", rpm);

        // Delay to avoid excessive CPU usage
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

