#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x4C
#define CTRL1_REG 0x20
#define CTRL1_VALUE 0x00
#define ALERT_LED_GPIO 17
#define VIBRATION_THRESHOLD 500
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(double magnitude);
void trigger_alert();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure alert LED GPIO
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_LED_GPIO, 0); // Initially off

    // Main loop
    sensor_data_t sensor_data;
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Calculate vibration magnitude
            double magnitude = calculate_magnitude(sensor_data.x, sensor_data.y, sensor_data.z);

            // Check for threshold exceedance
            if (magnitude > VIBRATION_THRESHOLD) {
                log_event(magnitude);
                trigger_alert();
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize the sensor
int initialize_sensor() {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        // Verify sensor presence
        i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Clear power-down bit in CTRL1 register
        result = i2cWriteByteData(i2c_handle, CTRL1_REG, CTRL1_VALUE);
        if (result < 0) {
            fprintf(stderr, "Failed to write to CTRL1 register (attempt %d): %d\n", retries + 1, result);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Verify CTRL1 register write
        int read_value = i2cReadByteData(i2c_handle, CTRL1_REG);
        if (read_value < 0) {
            fprintf(stderr, "Failed to read CTRL1 register (attempt %d): %d\n", retries + 1, read_value);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (read_value != CTRL1_VALUE) {
            fprintf(stderr, "CTRL1 register value mismatch (attempt %d): read 0x%02X, expected 0x%02X\n", retries + 1, read_value, CTRL1_VALUE);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Sensor initialization failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 6);
        if (result == 6) {
            // Success
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0;
        } else {
            fprintf(stderr, "Failed to read sensor data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculate Euclidean vibration magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Log event to file
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk
}

// Trigger alert (turn on LED for 1 second)
void trigger_alert() {
    gpioWrite(ALERT_LED_GPIO, 1); // Turn on LED
    gpioDelay(1000000);           // 1 second
    gpioWrite(ALERT_LED_GPIO, 0); // Turn off LED
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

