    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        closelog();
        return 1;
    }

