    };
    int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

    syslog(LOG_INFO, "Flame monitor started.");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < num_sensors; i++) {
            int sensor_value = sensors[i].read_sensor(sensors[i].pin);

            if (sensor_value == 0) { // Flame detected (LOW signal)
                // Debounce
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
                int debounced_value = sensors[i].read_sensor(sensors[i].pin);

                if (debounced_value == 0) { // Still LOW after debounce
                    syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %d).", sensors[i].id, sensors[i].pin);
                    if (log_event(sensors[i].id, sensors[i].pin) != 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d.", sensors[i].id);
                    }
                }
            }
        }

        gpioDelay(1000000); // Wait 1 second (1000000 microseconds)
    }

    // Cleanup
    syslog(LOG_INFO, "Flame monitor shutting down.");
    cleanup_gpio();
    closelog();

    return 0;
}

