#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO line numbers for the touch sensor channels
const int touch_sensor_lines[] = {5, 6, 13, 19, 26, 12, 16, 20};

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8] = {NULL};

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char *get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read the touch sensor state
int read_touch_sensor()
{
    int current_state = 0;
    int i;

    for (i = 0; i < 8; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", touch_sensor_lines[i], strerror(errno));
            return -1; // Indicate an error
        }
        current_state |= (value << i);
    }

    return current_state;
}

// Function to log a touch event
void log_touch_event(int index, int pin, int state)
{
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        return; // Exit if timestamp allocation fails
    }

    printf("%s - Touch sensor %d (BCM %d) - %s\n", timestamp, index, pin, state ? "Touched" : "Released");
    free(timestamp);
}

int main()
{
    int i, current_state, previous_state;
    struct timespec sleep_time;

    // Set up signal handling for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    for (i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_sensor_lines[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", touch_sensor_lines[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Set the line direction to input
        if (gpiod_line_request_direction_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", touch_sensor_lines[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Initialize the previous state
    previous_state = read_touch_sensor();
    if (previous_state < 0) {
        fprintf(stderr, "Error reading initial touch sensor state\n");
        // Release previously acquired lines
        for (i = 0; i < 8; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50 * 1000 * 1000; // 50ms

    while (!terminate) {
        current_state = read_touch_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading touch sensor state\n");
            break; // Exit loop on read error
        }

        for (i = 0; i < 8; i++) {
            if ((current_state >> i) & 1) {
                if (!(previous_state >> i) & 1) {
                    log_touch_event(i, touch_sensor_lines[i], 1);
                }
            } else {
                if ((previous_state >> i) & 1) {
                    log_touch_event(i, touch_sensor_lines[i], 0);
                }
            }
        }

        previous_state = current_state;
        nanosleep(&sleep_time, NULL);
    }

    // Release the GPIO lines
    for (i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

