#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"
#define LUX_THRESHOLD_1 100
#define LUX_THRESHOLD_2 500
#define LUX_THRESHOLD_3 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_veml7700();
float read_lux();
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Structure for VEML7700 configuration
typedef struct {
    uint16_t config;
} veml7700_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, 100); // Set PWM range to 100 for percentage control

    return 0;
}

// Function to initialize VEML7700 sensor
int init_veml7700() {
    // Configuration: Integration time = 100ms, Gain = 2
    // Refer to VEML7700 datasheet for register addresses and values
    uint16_t config_value = 0x0000; // Default configuration
    uint8_t config_data[3];

    // Write configuration to the sensor
    config_data[0] = 0x00; // Configuration register address
    config_data[1] = (config_value >> 8) & 0xFF; // MSB
    config_data[2] = config_value & 0xFF; // LSB

    if (i2cWriteDevice(i2c_handle, config_data, 3) != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register\n");
        return -1;
    }

    return 0;
}

// Function to read lux value from VEML7700 sensor
float read_lux() {
    uint8_t data[2];
