#include <string.h>

// Define GPIO pins
#define LED_PIN 17
#define SENSOR_PINS {2, 3, 4, 5, 6, 7, 8, 9}

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int channel);
int debounce(int channel);
int log_event(int channel);
void control_led(int state);
void signal_handler(int signal);

// Structure to hold sensor pin configurations
typedef struct {
    int pins[8];
} SensorPins;

SensorPins sensor_pins = {SENSOR_PINS};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        for (int i = 0; i < 8; i++) {
            if (debounce(i + 1)) {
                log_event(i + 1);
                control_led(1); // Turn LED on
                break; // Only log one event per cycle
            }
        }
        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    fclose(log_file);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn LED off

    // Set sensor pins as inputs with pull-down resistors
    for (int i = 0; i < 8; i++) {
        gpioSetMode(sensor_pins.pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins.pins[i], PI_PUD_DOWN);
    }

    return 0;
}

// Read sensor value
int read_sensor(int channel) {
    return gpioRead(sensor_pins.pins[channel - 1]);
}

