    int i;
    for (i = 0; i < 5; i++) {
        if (read_sensor(channel) == 1) {
            gpioDelay(DEBOUNCE_DELAY);
        } else {
            return 0; // Not debounced
        }
    }
    return 1; // Debounced
}

// Log event to file
int log_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open!\n");
        return 1;
    }
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

