#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_opt3001();
int read_opt3001(uint16_t *raw_value);
float convert_to_lux(uint16_t raw_value);
int log_data(float lux_value);
void print_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int opt3001_address;
    char log_file_name[64];
} config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001
int configure_opt3001() {
    uint16_t config_value = 0b0010000000000000; // Continuous conversion mode, 800ms conversion time
    char buf[2];
    buf[0] = (config_value >> 8) & 0xFF; // MSB
    buf[1] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for configuration to take effect
    return 0;
}

// Function to read the OPT3001 result
int read_opt3001(uint16_t *raw_value) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    // Byte swap the result
    *raw_value = ((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    uint16_t exponent = (raw_value >> 12) & 0x0F;
    uint16_t mantissa = raw_value & 0x0FFF;
    return (float)mantissa * (0.01 * (1 << exponent));
}

// Function to log data to file
int log_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print data to stdout
void print_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    printf("%s, %.2f\n", timestamp, lux_value);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint16_t raw_value;
    float lux_value;

    // Main loop
    while (!terminate) {
        // Read OPT3001
        if (read_opt3001(&raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Log data
            log_data(lux_value);

            // Print data
            print_data(lux_value);
        } else {
            fprintf(stderr, "Failed to read OPT3001 data. Retrying...\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

