    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint16_t raw_value;
    float lux_value;

    // Main loop
    while (!terminate) {
        // Read OPT3001
        if (read_opt3001(&raw_value) == 0) {
            // Convert to lux
