#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_MS 50

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in the required format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure the buffer is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a touch event to the file
void log_touch_event(const char *event_type) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to read the GPIO pin with debouncing
int read_gpio_with_debounce() {
    int current_value = gpioRead(GPIO_PIN);
    gpioDelay(DEBOUNCE_MS * 1000); // Delay in microseconds
    return gpioRead(GPIO_PIN) == current_value;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as an input with pull-down bias
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_state = 0; // 0: released, 1: pressed

    // Main loop
    while (running) {
        int current_state = read_gpio_with_debounce();

        if (current_state && !previous_state) {
            // Touch detected
            log_touch_event("Touch Detected");
            previous_state = 1;
        } else if (!current_state && previous_state) {
            // Touch released
            log_touch_event("Touch Released");
            previous_state = 0;
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

