#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t flow_rate;
    uint8_t status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t expected_crc);
float convert_flow_rate(int16_t raw_flow);
void log_data(FILE *fp, float flow_rate, uint8_t status);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int len, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc(data, len - 1); // Exclude the CRC byte itself
    return (calculated_crc == expected_crc);
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw flow rate to ml/min
float convert_flow_rate(int16_t raw_flow) {
    // Conversion formula from the datasheet
    return (float)raw_flow / 120.0; // Example conversion, adjust as needed
}

// Function to log data to file
void log_data(FILE *fp, float flow_rate, uint8_t status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%u\n", timestamp, flow_rate, status);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint8_t data[3];
        sensor_data_t sensor_data;
        int16_t raw_flow;
        float flow_rate;
        uint8_t status;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, attempting recovery...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Small delay before re-initialization
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break; // Exit loop if re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Wait for at least 2 ms
        gpioDelay(2000); // pigpio uses microseconds

        // Read sensor data
        if (read_sensor_data(i2c_handle, data, 3) != 0) {
            fprintf(stderr, "Error reading sensor data, attempting recovery...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Small delay before re-initialization
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break; // Exit loop if re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Validate CRC
        if (!validate_crc(data, 3)) {
            fprintf(stderr, "CRC validation failed, setting status to ERROR\n");
            status = 'E';
            flow_rate = -1.0; // Indicate error
        } else {
            // Convert flow rate
            raw_flow = (data[0] << 8) | data[1];
            flow_rate = convert_flow_rate(raw_flow);

            // Validate flow rate
            if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
                fprintf(stderr, "Flow rate out of range, setting status to INVALID\n");
                status = 'I';
            } else {
                status = 'V';
            }
        }

        // Log data
        log_data(log_file, flow_rate, status);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpio uses microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

