        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Cleanup GPIO resources
    cleanup();

    return 0;
}

