    timeinfo = localtime(&rawtime);

    // Format the timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    // Write the data to the file
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    // Flush the file buffer to ensure data is written to disk
    fflush(fp);

    return 0;
}

