#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip number
#define GPIO_CHIP 4

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static int gpio_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int chip, int pin);
int gpio_unexport(int chip, int pin);
int gpio_set_direction(int chip, int pin, const char *direction);
int gpio_read(int chip, int pin);
int gpio_write(int chip, int pin, int value);
int log_event(const char *timestamp, int led_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("Received signal %d, shutting down...\n", signal);
    }
}

// Function to export a GPIO pin
int gpio_export(int chip, int pin) {
    int fd;
    char buf[64];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error exporting GPIO pin %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int chip, int pin) {
    int fd;
    char buf[64];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d for unexport: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error unexporting GPIO pin %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int chip, int pin, const char *direction) {
    int fd;
    char buf[64];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d for direction setting: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing pin number to GPIO chip %d: %s\n", chip, strerror(errno));
        close(fd);
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error setting direction of GPIO pin %d to %s: %s\n", pin, direction, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int chip, int pin) {
    int fd;
    char buf[64];
    char value_str[3];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d for reading: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing pin number to GPIO chip %d: %s\n", chip, strerror(errno));
        close(fd);
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading value of GPIO pin %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int gpio_write(int chip, int pin, int value) {
    int fd;
    char buf[64];
    char value_str[3];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d for writing: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing pin number to GPIO chip %d: %s\n", chip, strerror(errno));
        close(fd);
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) < 0) {
        fprintf(stderr, "Error writing value %d to GPIO pin %d: %s\n", value, pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log an event to the log file
int log_event(const char *timestamp, int led_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, LED State: %d\n", timestamp, led_state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ
    int touch_value, led_state;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(GPIO_CHIP, TOUCH_SENSOR_PIN) < 0) {
        fprintf(stderr, "Failed to export TOUCH_SENSOR_PIN. Exiting.\n");
        return 1;
    }
    if (gpio_export(GPIO_CHIP, LED_PIN) < 0) {
        fprintf(stderr, "Failed to export LED_PIN. Exiting.\n");
        gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN); // Clean up previously exported pin
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(GPIO_CHIP, TOUCH_SENSOR_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN direction. Exiting.\n");
        gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN);
        gpio_unexport(GPIO_CHIP, LED_PIN);
        return 1;
    }
    if (gpio_set_direction(GPIO_CHIP, LED_PIN, "out") < 0) {
        fprintf(stderr, "Failed to set LED_PIN direction. Exiting.\n");
        gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN);
        gpio_unexport(GPIO_CHIP, LED_PIN);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN);
        gpio_unexport(GPIO_CHIP, LED_PIN);
        return 1;
    }

    // Main loop
    while (program_running) {
        touch_value = gpio_read(GPIO_CHIP, TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor value. Continuing.\n");
            sleep(1); // Avoid spamming errors
            continue;
        }

        if (touch_value == 1) {
            // Toggle LED state
            led_state = !led_state;
            if (gpio_write(GPIO_CHIP, LED_PIN, led_state) < 0) {
                fprintf(stderr, "Error writing to LED. Continuing.\n");
            }

            // Get current timestamp
            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log event
            if (log_event(timestamp, led_state) < 0) {
                fprintf(stderr, "Error logging event. Continuing.\n");
            }

            // Debounce: Wait for a short period to avoid multiple triggers from a single touch
            usleep(500000); // 0.5 seconds
        }

        usleep(1000000); // Check every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_write(GPIO_CHIP, LED_PIN, 0); // Turn off LED
    gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN);
    gpio_unexport(GPIO_CHIP, LED_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
