// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("Received signal %d, shutting down...\n", signal);
    }
}

// Function to export a GPIO pin
int gpio_export(int chip, int pin) {
    int fd;
    char buf[64];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error exporting GPIO pin %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int chip, int pin) {
    int fd;
    char buf[64];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d for unexport: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error unexporting GPIO pin %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int chip, int pin, const char *direction) {
    int fd;
    char buf[64];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d for direction setting: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing pin number to GPIO chip %d: %s\n", chip, strerror(errno));
        close(fd);
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error setting direction of GPIO pin %d to %s: %s\n", pin, direction, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int chip, int pin) {
    int fd;
    char buf[64];
    char value_str[3];

    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d for reading: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing pin number to GPIO chip %d: %s\n", chip, strerror(errno));
        close(fd);
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading value of GPIO pin %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
