    fd = open("/dev/gpiochip" + chip, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %d for writing: %s\n", chip, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing pin number to GPIO chip %d: %s\n", chip, strerror(errno));
        close(fd);
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) < 0) {
        fprintf(stderr, "Error writing value %d to GPIO pin %d: %s\n", value, pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log an event to the log file
int log_event(const char *timestamp, int led_state) {
