        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, LED State: %d\n", timestamp, led_state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ
    int touch_value, led_state;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(GPIO_CHIP, TOUCH_SENSOR_PIN) < 0) {
        fprintf(stderr, "Failed to export TOUCH_SENSOR_PIN. Exiting.\n");
        return 1;
