    if (gpio_export(GPIO_CHIP, LED_PIN) < 0) {
        fprintf(stderr, "Failed to export LED_PIN. Exiting.\n");
        gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN); // Clean up previously exported pin
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(GPIO_CHIP, TOUCH_SENSOR_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN direction. Exiting.\n");
        gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN);
        gpio_unexport(GPIO_CHIP, LED_PIN);
        return 1;
    }
    if (gpio_set_direction(GPIO_CHIP, LED_PIN, "out") < 0) {
        fprintf(stderr, "Failed to set LED_PIN direction. Exiting.\n");
        gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN);
        gpio_unexport(GPIO_CHIP, LED_PIN);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpio_unexport(GPIO_CHIP, TOUCH_SENSOR_PIN);
        gpio_unexport(GPIO_CHIP, LED_PIN);
        return 1;
    }

    // Main loop
