// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define constants
#define BUZZER_DURATION_MS 2000
#define POLL_INTERVAL_MS 500
#define DEBOUNCE_DELAY_MS 100

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void activate_buzzer();
void log_flame_detection();
void signal_handler(int sig);
void cleanup();
void log_message(const char *message);

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("Error getting flame sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_alert") < 0) {
        perror("Error requesting flame sensor line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_alert", 0) < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        perror("Error reading flame sensor value");
        return -1;
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer() {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("Error setting buzzer value to HIGH");
    }
    usleep(BUZZER_DURATION_MS * 1000); // Delay for buzzer duration
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("Error setting buzzer value to LOW");
    }
}

// Function to log flame detection
void log_flame_detection() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - FLAME DETECTED\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    log_message("FLAME DETECTED");
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

// Function to log messages to the alert_log.txt file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Log system start message
    log_message("System started");

    // Main loop
    int last_state = 1; // Assume no flame initially (HIGH)
    while (!terminate) {
        int current_state = read_flame_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading flame sensor. Continuing...\n");
            usleep(POLL_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        if (current_state == 0 && last_state == 1) {
            // Flame detected (LOW to HIGH transition)
            log_flame_detection();
            activate_buzzer();
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

