#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce();
int log_touch_event();
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int last_touch_state;
    unsigned long last_touch_time;
} ProgramState;

ProgramState state = {1, 0}; // Initialize last_touch_state to 1 (released) and last_touch_time to 0

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Continuing without logging.\n");
    }

    // Main loop
    while (running) {
        // Read the touch sensor
        int touch_state = read_touch_sensor();

        // Debounce the touch sensor
        if (debounce() == 0) {
            // Log the touch event
            if (log_touch_event() != 0) {
                fprintf(stderr, "Failed to log touch event.\n");
            }
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup GPIO and close log file
    cleanup_gpio();

    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize LED to off
    gpioWrite(LED_PIN, 0);

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce the touch sensor
int debounce() {
    int current_state = read_touch_sensor();
    unsigned long current_time = gpioTick();

    if (current_state == 0) { // Touch detected (LOW)
        if (state.last_touch_state == 1) { // Was released
            if (current_time - state.last_touch_time > DEBOUNCE_TIME * 1000) { // Check debounce time
                state.last_touch_state = 0;
                state.last_touch_time = current_time;
                return 0; // Valid touch
            }
        }
    } else { // No touch (HIGH)
        state.last_touch_state = 1;
    }

    return 1; // Not a valid touch
}

// Log the touch event to a file
int log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open. Cannot log event.\n");
        return 1;
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    printf("Cleaning up GPIO and exiting.\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down.\n", signal);
    running = 0;
}

