#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define SI1182_PART_ID_REG 0x00
#define SI1182_HW_REV_REG 0x01
#define SI1182_HR_REG 0x24
#define SI1182_CONFIG_REG 0x18
#define SI1182_MEAS_RATE_REG 0x08
#define SI1182_RESET_REG 0x07

#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t meas_rate;
    uint8_t config;
} sensor_config_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(uint16_t *raw_hr);
float apply_moving_average(uint16_t *data, int size);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the Si1182 sensor
int init_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1182_RESET_REG, 0x01) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rate
    if (i2cWriteByteData(i2c_handle, SI1182_MEAS_RATE_REG, 0x0A) < 0) { // Example rate
        fprintf(stderr, "Error configuring measurement rate\n");
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1182_CONFIG_REG, 0x03) < 0) { // Example config
        fprintf(stderr, "Error configuring sensor\n");
        return -1;
    }

    return 0;
}

// Read raw heart rate data from the sensor
int read_sensor_data(uint16_t *raw_hr) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, SI1182_HR_REG);
        if (result >= 0) {
            *raw_hr = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    fprintf(stderr, "Fatal I2C read error after multiple retries\n");
    return -1; // Fatal error
}

// Apply a five-sample moving average filter
float apply_moving_average(uint16_t *data, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    return sum / size;
}

// Validate BPM value
int validate_bpm(float bpm) {
    if (bpm >= MIN_BPM && bpm <= MAX_BPM) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Log data to CSV file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,BPM\n");
    }
    fflush(log_file);

    uint16_t raw_hr_data[MOVING_AVG_SIZE];
    int data_index = 0;

    // Main loop
    while (!terminate) {
        uint16_t raw_hr;
        if (read_sensor_data(&raw_hr) == 0) {
            raw_hr_data[data_index] = raw_hr;
            data_index = (data_index + 1) % MOVING_AVG_SIZE;

            if (data_index == 0) {
                float avg_bpm = apply_moving_average(raw_hr_data, MOVING_AVG_SIZE);

                if (validate_bpm(avg_bpm)) {
                    log_data(avg_bpm);
                } else {
                    fprintf(stderr, "Invalid BPM value: %.2f\n", avg_bpm);
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

