#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_BASE 5
#define OUTPUT_BASE 17
#define NUM_CHANNELS 8

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_lines[NUM_CHANNELS];
static struct gpiod_line *output_lines[NUM_CHANNELS];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int channel);
int write_output(int channel, int value);
int update_counter(int channel);
int log_event(int channel, int counter);
void cleanup_gpio(void);
void signal_handler(int sig);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    struct timeval tv;
    struct tm tm;

    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", &tm);
    return timestamp_str;
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_BASE + i);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    // Get output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, OUTPUT_BASE + i);
        if (!output_lines[i]) {
            fprintf(stderr, "Error getting output line %d: %s\n", i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    // Request sensor lines as input
    for (i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(sensor_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting sensor line %d as input: %s\n", i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    // Request output lines as output
    for (i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(output_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting output line %d as output: %s\n", i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to read sensor value
int read_sensor(int channel) {
    int value = gpiod_line_get_value(sensor_lines[channel]);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor line %d: %s\n", channel, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write output value
int write_output(int channel, int value) {
    int ret = gpiod_line_set_value(output_lines[channel], value);
    if (ret < 0) {
        fprintf(stderr, "Error writing to output line %d: %s\n", channel, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to update counter
int update_counter(int channel) {
    static int counter = 0;
    counter += (1 << channel);
    if (counter >= 256) {
        counter = 0;
    }
    return counter;
}

// Function to log event
int log_event(int channel, int counter) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp, sizeof(timestamp));

    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fclose(fp);

    printf("Touch on channel %d | Counter: %d\n", channel, counter);
    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    // Release output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (output_lines[i]) {
            gpiod_line_release(output_lines[i]);
        }
    }

    // Release sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

int main(void) {
    int i, sensor_value, counter;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Stabilization delay
        usleep(200000); // 200 ms

        // Read sensor values and update counter
        for (i = 0; i < NUM_CHANNELS; i++) {
            sensor_value = read_sensor(i);
            if (sensor_value >= 0) {
                counter = update_counter(i);
                if (log_event(i, counter) < 0) {
                    fprintf(stderr, "Error logging event for channel %d\n", i);
                }
            }
        }

        // Delay for 10 ms
        usleep(10000); // 10 ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

