#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_sensor(int gpio);
int log_event(int sensor_number);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int gpio;
    int last_state;
    struct timespec last_change_time;
} sensor_data_t;

sensor_data_t sensor1_data = {SENSOR1_GPIO, -1, {0, 0}};
sensor_data_t sensor2_data = {SENSOR2_GPIO, -1, {0, 0}};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and SPI
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log events for sensor 1
        if (sensor1_value == 0 && sensor1_data.last_state == 1) {
            if (log_event(1) != 0) {
                fprintf(stderr, "Failed to log event for sensor 1.\n");
            }
            sensor1_data.last_state = 0;
        } else if (sensor1_value == 1 && sensor1_data.last_state == 0) {
            sensor1_data.last_state = 1;
        }

        // Log events for sensor 2
        if (sensor2_value == 0 && sensor2_data.last_state == 1) {
            if (log_event(2) != 0) {
                fprintf(stderr, "Failed to log event for sensor 2.\n");
            }
            sensor2_data.last_state = 0;
        } else if (sensor2_value == 1 && sensor2_data.last_state == 0) {
            sensor2_data.last_state = 1;
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode (CPHA = 0, CPOL = 0)
    int mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word (8 bits)
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed (1 MHz)
    int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read sensor value from GPIO
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return -1;
    }
    return value;
}

// Log event to file
int log_event(int sensor_number) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    // Calculate the time difference since the last change
    struct timespec diff;
    diff.tv_sec = now.tv_sec - sensor1_data.last_change_time.tv_sec;
    diff.tv_nsec = now.tv_nsec - sensor1_data.last_change_time.tv_nsec;
    if (diff.tv_nsec < 0) {
        diff.tv_sec--;
        diff.tv_nsec += 1000000000;
    }

    // Check if the time difference is greater than the debounce time
    if (diff.tv_sec * 1000 + diff.tv_nsec / 1000000 > DEBOUNCE_TIME) {
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));

        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure the log is written immediately
        sensor1_data.last_change_time = now;
        return 0;
    } else {
        return -1; // Debounce time not met
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

