#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate and delay
#define SAMPLING_RATE 8000 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLING_RATE) // microseconds

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to get current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Sampling at %d Hz. Press Ctrl+C to exit.\n", SAMPLING_RATE);

    // Main loop
    while (program_running) {
        // Read microphone input
        int mic_value = gpioRead(MIC_PIN);

        // Check for peak
        if (mic_value == 1) {
            // Get timestamp
            long long timestamp = get_timestamp_ms();

            // Print timestamp
            printf("%lld\n", timestamp);

            // Turn on LED
            gpioWrite(LED_PIN, 1);

            // Wait for 100ms
            gpioDelay(100000); // 100ms

            // Turn off LED
            gpioWrite(LED_PIN, 0);
        }

        // Delay for sample period
