int init_si1175() {
    // Check if the sensor is present by reading the Part ID register
    int part_id = i2cReadByteData(i2c_handle, SI1175_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register: %d\n", part_id);
        return -1;
    }

    if (part_id != 0x75) {
        fprintf(stderr, "Si1175 not detected. Part ID: 0x%02X\n", part_id);
        return -1;
