int read_als_data(uint16_t *als_data) {
    int msb, lsb;

    lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA0);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB register: %d\n", lsb);
        return -1;
    }

    msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA1);
    if (msb < 0) {
