#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the touch sensor channels
#define TP1 5
#define TP2 6
#define TP3 13
#define TP4 19
#define TP5 26
#define TP6 12
#define TP7 16
#define TP8 20

// Structure to hold the state of each touch sensor channel
typedef struct {
    int tp1;
    int tp2;
    int tp3;
    int tp4;
    int tp5;
    int tp6;
    int tp7;
    int tp8;
} TouchSensorState;

// Global variable to store the pigpio initialization status
static int pigpio_initialized = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (pigpio_initialized) {
        gpioTerminate();
    }
    exit(0);
}

// Function to read the state of the touch sensor channels
TouchSensorState read_touch_sensor() {
    TouchSensorState state;
    state.tp1 = gpioRead(TP1);
    state.tp2 = gpioRead(TP2);
    state.tp3 = gpioRead(TP3);
    state.tp4 = gpioRead(TP4);
    state.tp5 = gpioRead(TP5);
    state.tp6 = gpioRead(TP6);
    state.tp7 = gpioRead(TP7);
    state.tp8 = gpioRead(TP8);
    return state;
}

// Function to format the timestamp
char* format_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char* timestamp = malloc(30 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL; // Return NULL to indicate failure
    }
    snprintf(timestamp, 30, "%.3f", (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0);
    return timestamp;
}

// Function to print the sensor data
void print_sensor_data(TouchSensorState state, char* timestamp) {
    printf("[%s] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           timestamp, state.tp1, state.tp2, state.tp3, state.tp4, state.tp5, state.tp6, state.tp7, state.tp8);
}

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set the GPIO pins as inputs
    gpioSetMode(TP1, PI_INPUT);
    gpioSetMode(TP2, PI_INPUT);
    gpioSetMode(TP3, PI_INPUT);
    gpioSetMode(TP4, PI_INPUT);
    gpioSetMode(TP5, PI_INPUT);
    gpioSetMode(TP6, PI_INPUT);
    gpioSetMode(TP7, PI_INPUT);
    gpioSetMode(TP8, PI_INPUT);

    // Main loop
    while (1) {
        // Read the touch sensor state
        TouchSensorState state = read_touch_sensor();

        // Format the timestamp
        char* timestamp = format_timestamp();
        if (timestamp == NULL) {
            // If timestamp formatting failed, continue to the next iteration
            gpioDelay(200); // Delay for 200ms
            continue;
        }

        // Print the sensor data
        print_sensor_data(state, timestamp);

        // Free the allocated memory for the timestamp
        free(timestamp);

        // Delay for 200ms
        gpioDelay(200);
    }

    // The program should never reach here due to the infinite loop, but include cleanup for completeness
    gpioTerminate();
    return 0;
}

