#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Hues for RGB color space (0-255)
#define HUE_RED   0
#define HUE_GREEN 128
#define HUE_BLUE  255

// Number of steps for linear interpolation
#define NUM_STEPS 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_hue(int red_pin, int green_pin, int blue_pin, int hue);
void interpolate_hue(int red_pin, int green_pin, int blue_pin, int start_hue, int end_hue, int num_steps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    closelog();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    return 0;
}

// Set the hue of the RGB LED
void set_hue(int red_pin, int green_pin, int blue_pin, int hue) {
    // Convert hue to RGB values (simplified, using a lookup table)
    // This is a placeholder; a proper lookup table would be more complex
    // and would allow for more accurate color representation.
    // For simplicity, we'll use a basic mapping for each color.

    int red, green, blue;

    if (hue < 85) {
        red = 255 - hue * 3;
        green = hue * 3;
        blue = 0;
    } else if (hue < 170) {
        hue -= 85;
        red = 0;
        green = 255 - hue * 3;
        blue = hue * 3;
    } else {
        hue -= 170;
        red = hue * 3;
        green = 0;
        blue = 255 - hue * 3;
    }

    gpioPWM(red_pin, red);
    gpioPWM(green_pin, green);
    gpioPWM(blue_pin, blue);
}

// Interpolate between two hues
void interpolate_hue(int red_pin, int green_pin, int blue_pin, int start_hue, int end_hue, int num_steps) {
    int hue_range = end_hue - start_hue;
    int step_size = hue_range / num_steps;

    for (int i = 0; i <= num_steps; ++i) {
        int current_hue = start_hue + (i * step_size);
        set_hue(red_pin, green_pin, blue_pin, current_hue);
        gpioDelay(1000000 / num_steps); // Delay for smooth interpolation (microseconds)
    }
}

int main() {
    // Seed the random number generator with /dev/urandom
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        return 1;
    }
    unsigned int seed;
    fread(&seed, sizeof(unsigned int), 1, urandom);
    fclose(urandom);
    srand(seed);

    // Open syslog
    openlog("rgb_led_fade", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "RGB LED fade program started");

    // Main loop
    while (program_running) {
        // Generate random start and end hues
        int start_hue = rand() % 256;
        int end_hue = rand() % 256;

        // Fade between the hues
        interpolate_hue(RED_PIN, GREEN_PIN, BLUE_PIN, start_hue, end_hue, NUM_STEPS);

        // Wait for a random delay before starting the next transition
        gpioDelay(rand() % 5000000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    closelog();

    return 0;
}

