#define LED_GPIO                  (17)

// Red value threshold
#define RED_THRESHOLD             (200)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void control_led(uint16_t red_value);
void signal_handler(int signal);

