    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Enable power and RGBC
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) < 0) {
        fprintf(stderr, "Failed to write to ENABLE register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Set integration time (154ms)
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_INTEGRATIONTIME_154MS) < 0) {
        fprintf(stderr, "Failed to write to ATIME register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Set gain (1x)
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CONTROL, TCS34725_GAIN_1X) < 0) {
        fprintf(stderr, "Failed to write to CONTROL register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read RGBC values from the sensor
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[8];

    // Read all RGBC values in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, buffer, 8) != 8) {
        fprintf(stderr, "Failed to read RGBC values\n");
        return -1;
    }

    // Extract values from the buffer
    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Function to control the LED based on the red value
void control_led(uint16_t red_value) {
    if (red_value > RED_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
