#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define GPIO_PWM 18
#define NUM_LEDS 10
#define PWM_RANGE 1000000 // 1 MHz
#define PWM_FREQUENCY 800 // Hz
#define LOG_BASE 10.0
#define MAX_LUX 1000.0
#define MIN_LUX 0.0
#define MAX_BRIGHTNESS 1000.0
#define MIN_BRIGHTNESS 0.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750();
float read_lux();
float map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialize the BH1750 sensor
int init_bh1750() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Send continuous high-resolution mode command
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from the BH1750 sensor
float read_lux() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (float)raw_value / 1.2;
}

// Map lux value to a logarithmic brightness level
float map_lux_to_brightness(float lux) {
    if (lux <= MIN_LUX) {
        return MIN_BRIGHTNESS;
    } else if (lux >= MAX_LUX) {
        return MAX_BRIGHTNESS;
    }

    float log_lux = log10(lux / MIN_LUX) / log10(MAX_LUX / MIN_LUX);
    return log_base * log_lux;
}

// Set the brightness of the WS2812B strip
void set_led_brightness(int brightness) {
    // Create a buffer for the LED data
    uint32_t led_data[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i] = 0; // Black
    }

    // Set the brightness of the LEDs (all LEDs are set to the same brightness)
    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i] = (uint32_t)((float)brightness / 255.0 * 0xFFFFFF); // Scale brightness to 0xFFFFFF
    }

    // Send the data to the WS2812B strip
    gpioWaveClear();
    gpioPulse_t pulse[NUM_LEDS * 24]; // Each LED has 24 pulses (8 bits per byte)
    int pulse_index = 0;

    for (int i = 0; i < NUM_LEDS; i++) {
        for (int j = 23; j >= 0; j--) {
            uint8_t bit = (led_data[i] >> j) & 1;

            if (bit == 0) {
                pulse[pulse_index].gpioOn = 1 << GPIO_PWM;
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = 0.8; // 0.8us
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = 1 << GPIO_PWM;
                pulse[pulse_index].usDelay = 0.45; // 0.45us
                pulse_index++;
            } else {
                pulse[pulse_index].gpioOn = 1 << GPIO_PWM;
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = 0.45; // 0.45us
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = 1 << GPIO_PWM;
                pulse[pulse_index].usDelay = 0.8; // 0.8us
                pulse_index++;
            }
        }
    }

    gpioWaveAddGeneric(pulse_index, pulse);
    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
        while (gpioWaveTxBusy()) {
            gpioDelay(1000); // Wait for wave to finish
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

// Cleanup resources
void cleanup() {
    // Stop PWM
    gpioPWM(GPIO_PWM, 0);

    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Stop pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PWM, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(GPIO_PWM, PWM_RANGE);
    gpioSetPWMfrequency(GPIO_PWM, PWM_FREQUENCY);

    // Initialize BH1750 sensor
    if (init_bh1750() < 0) {
        fprintf(stderr, "BH1750 initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("BH1750 to WS2812B mapping started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        float brightness = map_lux_to_brightness(lux);
        set_led_brightness((int)brightness);

        gpioDelay(180000); // Wait 180ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

