int read_bh1750(int *lux);
int init_spi();
int set_apa102_brightness(int spi_handle, int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize BH1750 sensor
int init_bh1750() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(int *lux) {
    char config[1] = {0x10}; // Continuous high resolution mode
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(180); // Wait for measurement (at least 180ms)

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *lux = (data[0] << 8) | data[1];
    return 0;
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Set APA102 brightness
int set_apa102_brightness(int spi_handle, int brightness) {
    uint8_t data[4];

    // Start frame
    data[0] = (START_FRAME >> 24) & 0xFF;
    data[1] = (START_FRAME >> 16) & 0xFF;
    data[2] = (START_FRAME >> 8) & 0xFF;
    data[3] = START_FRAME & 0xFF;
    if (spiWrite(spi_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Error writing start frame: %s\n", strerror(errno));
        return -1;
    }

    // LED data
    for (int i = 0; i < NUM_LEDS; i++) {
        data[0] = 0xE0 | (brightness & 0x1F); // Global brightness (E0-FF), brightness (00-1F)
        data[1] = 0x00; // Blue
        data[2] = 0x00; // Green
        data[3] = 0x00; // Red
        if (spiWrite(spi_handle, (char *)data, 4) != 4) {
            fprintf(stderr, "Error writing LED data: %s\n", strerror(errno));
            return -1;
        }
    }

    // End frame
    data[0] = (END_FRAME >> 24) & 0xFF;
    data[1] = (END_FRAME >> 16) & 0xFF;
    data[2] = (END_FRAME >> 8) & 0xFF;
    data[3] = END_FRAME & 0xFF;
    if (spiWrite(spi_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Error writing end frame: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

