    signal(SIGINT, signal_handler);

    // Initialize BH1750
    if (init_bh1750() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int lux;
    int brightness;

    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            // Scale lux to brightness (0-255)
            brightness = (int)(((float)lux / 1000.0) * 255.0); // Assuming max lux is 1000
            if (brightness < 0) brightness = 0;
            if (brightness > 255) brightness = 255;

            // Set APA102 brightness
            if (set_apa102_brightness(spi_handle, brightness) != 0) {
                fprintf(stderr, "Error setting APA102 brightness\n");
            }
        } else {
            fprintf(stderr, "Error reading BH1750\n");
        }

        gpioDelay(120); // Wait 120ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

