#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define constants
#define NUM_LEDS 10
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_BRIGHTNESS 255
#define FADE_DURATION_MS 500

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_bh1750(int handle);
int init_spi(int channel, int speed);
void set_apa102_brightness(int spi_handle, int brightness);
void fade_brightness(int spi_handle, int current_brightness, int target_brightness, int duration_ms);
void signal_handler(int signal);

// Structure to hold LED color data
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} led_color_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read light level from BH1750 sensor
int read_bh1750(int handle) {
    if (i2cWriteByteData(handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        return -1;
    }
    gpioDelay(200); // Wait for conversion (at least 180ms)

    int data = i2cReadWordData(handle, 0x00);
    if (data < 0) {
        fprintf(stderr, "Error reading from BH1750\n");
        return -1;
    }

    // Swap bytes (BH1750 returns MSB first)
    return (data >> 8) | (data << 8);
}

// Function to initialize SPI
int init_spi(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to set APA102 brightness
void set_apa102_brightness(int spi_handle, int brightness) {
    // APA102 start frame (4 bytes of 0x00)
    char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    spiWrite(spi_handle, start_frame, 4);

    // LED data (NUM_LEDS * 4 bytes each: 1 byte start, 3 bytes data)
    for (int i = 0; i < NUM_LEDS; i++) {
        char led_data[4] = {0xE0 | (brightness >> 4), 0x00, 0x00, 0x00}; // Global brightness
        spiWrite(spi_handle, led_data, 4);
    }

    // APA102 end frame (NUM_LEDS * 4 bytes of 0xFF)
    char end_frame[NUM_LEDS * 4 + 4];
    for (int i = 0; i < NUM_LEDS * 4 + 4; i++) {
        end_frame[i] = 0xFF;
    }
    spiWrite(spi_handle, end_frame, NUM_LEDS * 4 + 4);
}

// Function to fade brightness
void fade_brightness(int spi_handle, int current_brightness, int target_brightness, int duration_ms) {
    int steps = 100; // Number of steps in the fade
    int step_size = (target_brightness - current_brightness) / steps;
    if (step_size == 0) return; // Avoid division by zero

    for (int i = 0; i < steps; i++) {
        int brightness = current_brightness + (step_size * i);
        set_apa102_brightness(spi_handle, brightness);
        gpioDelay(duration_ms / steps); // Delay for smooth transition
    }
    set_apa102_brightness(spi_handle, target_brightness); // Ensure final brightness is set
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    int bh1750_handle1 = init_i2c(1, BH1750_ADDR_1);
    int bh1750_handle2 = init_i2c(1, BH1750_ADDR_2);
    int num_sensors = 0;
    if (bh1750_handle1 >= 0) num_sensors++;
    if (bh1750_handle2 >= 0) num_sensors++;

    // Initialize SPI
    spi_handle = init_spi(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int total_lux = 0;
        int valid_readings = 0;

        if (bh1750_handle1 >= 0) {
            int lux = read_bh1750(bh1750_handle1);
            if (lux >= 0) {
                total_lux += lux;
                valid_readings++;
            }
        }
        if (bh1750_handle2 >= 0) {
            int lux = read_bh1750(bh1750_handle2);
            if (lux >= 0) {
                total_lux += lux;
                valid_readings++;
            }
        }

        int average_lux = 0;
        if (valid_readings > 0) {
            average_lux = total_lux / valid_readings;
        }

        // Map lux to brightness (0-255)
        int brightness = (int)(average_lux / 10.0); // Adjust the scaling factor as needed
        if (brightness > MAX_BRIGHTNESS) {
            brightness = MAX_BRIGHTNESS;
        } else if (brightness < 0) {
            brightness = 0;
        }

        // Fade to the new brightness
        fade_brightness(spi_handle, 0, brightness, FADE_DURATION_MS); // Start with 0 brightness

        gpioDelay(100); // Delay between cycles
    }

    // Cleanup
    set_apa102_brightness(spi_handle, 0); // Turn off LED strip
    spiClose(spi_handle);
    i2cClose(bh1750_handle1);
    i2cClose(bh1750_handle2);
    gpioTerminate();

    return 0;
}

