// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// WS2812B GPIO pin (BCM numbering)
#define WS2812B_PIN 18

// Gamma correction parameters
#define GAMMA 2.2

// LED strip parameters
#define NUM_LEDS 1

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int veml7700_init();
float veml7700_read_lux();
float gamma_correct(float lux);
void ws2812b_set_brightness(int brightness);
void ws2812b_send_data(uint8_t *data, int num_leds);
void signal_handler(int signal);

// Function to initialize the VEML7700 sensor
int veml7700_init() {
    // Configure the sensor for continuous mode, integration time, gain
    // Example configuration: Integration time = 100ms, Gain = 1/8
    uint16_t config_value = 0x0000; // Default configuration
    config_value |= (0x03 << 11); // IT = 100ms (bits 11-13)
    config_value |= (0x02 << 9);  // Gain = 1/8 (bits 9-10)

    char buf[3];
    buf[0] = VEML7700_ALS_CONF;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register\n");
        return -1;
    }

    return 0;
}

// Function to read the ambient light level from the VEML7700 sensor
float veml7700_read_lux() {
    char buf[1];
    char read_buf[2];
    uint16_t raw_lux;

    buf[0] = VEML7700_ALS;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to VEML7700 ALS register\n");
        return -1.0;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from VEML7700 ALS register\n");
        return -1.0;
    }

    raw_lux = (read_buf[0] << 8) | read_buf[1];
    return (float)raw_lux; // Return raw value for now, convert to lux later
}

// Function to apply gamma correction to the lux value
float gamma_correct(float lux) {
    return powf(lux / 1000.0, 1.0 / GAMMA) * 1000.0; // Scale to 0-1000 range
}

// Function to set the brightness of the WS2812B LED strip
void ws2812b_set_brightness(int brightness) {
    // Simple threshold-based on/off scheme
    if (brightness > 0) {
        gpioWrite(WS2812B_PIN, 1); // Turn on LED
    } else {
        gpioWrite(WS2812B_PIN, 0); // Turn off LED
    }
}

