#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define SELF_TEST_DURATION 2000 // milliseconds
#define SELF_TEST_INTERVAL 100  // milliseconds
#define MAIN_LOOP_INTERVAL 50   // milliseconds
#define BUZZER_DURATION 200     // milliseconds
#define BUZZER_PULSE_DURATION 200 // milliseconds
#define BUZZER_PULSE_COUNT 3
#define LED_BLINK_COUNT 500
#define LED_RAPID_BLINK_COUNT 5
#define LED_ON_TIME 500
#define LED_OFF_TIME 500

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int self_test();
void main_loop();
void signal_handler(int signal);
void log_event(const char *event);

// Structure to hold GPIO pin configurations
typedef struct {
    int flame_sensor;
    int buzzer;
    int led;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to perform the self-test
int self_test() {
    int flame_detected = 0;
    int consecutive_flame_detected = 0;

    printf("Starting self-test...\n");
    log_event("Self-test started");

    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) { // KY-026 is active low
            flame_detected = 1;
        }

        if (flame_detected) {
            consecutive_flame_detected++;
        } else {
            consecutive_flame_detected = 0;
        }

        gpioDelay(SELF_TEST_INTERVAL * 1000); // Convert ms to us
    }

    if (consecutive_flame_detected == 5) {
        printf("Self-test failed: Persistent flame detected.\n");
        log_event("Self-test failed: Persistent flame detected");
        return 1; // Self-test failed
    }

    printf("Self-test passed.\n");
    log_event("Self-test passed");
    return 0; // Self-test passed
}

// Function to implement the main loop
void main_loop() {
    int flame_detected = 0;
    int flame_cleared = 0;
    int flame_state = 1; // Assume no flame initially (HIGH)

    printf("Starting main loop...\n");
    log_event("Main loop started");

    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0 && flame_state == 1) {
            // Flame detected
            printf("Flame detected!\n");
            log_event("Flame detected");

            flame_detected = 1;
            flame_cleared = 0;
            flame_state = 0;

            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);
            gpioDelay(BUZZER_DURATION * 1000); // Convert ms to us
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);

            while (running) {
                sensor_value = read_flame_sensor();
                if (sensor_value == 1) {
                    printf("Flame cleared!\n");
                    log_event("Flame cleared");
                    flame_detected = 0;
                    flame_cleared = 1;
                    flame_state = 1;
                    break;
                }
                gpioDelay(MAIN_LOOP_INTERVAL * 1000); // Convert ms to us
            }
        } else if (sensor_value == 1 && flame_state == 0) {
            // Flame cleared
            printf("Flame cleared!\n");
            log_event("Flame cleared");
            flame_detected = 0;
            flame_cleared = 1;
            flame_state = 1;
        }

        gpioDelay(MAIN_LOOP_INTERVAL * 1000); // Convert ms to us
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    log_event("Program terminated by signal");

    running = 0;

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);

    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to log events to a file
void log_event(const char *event) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Perform self-test
    if (self_test() != 0) {
        // Rapid blink and buzzer pattern
        printf("Self-test failed, starting rapid blink and buzzer pattern...\n");
        log_event("Self-test failed, starting rapid blink and buzzer pattern");

        for (int i = 0; i < LED_RAPID_BLINK_COUNT; i++) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_TIME * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(LED_OFF_TIME * 1000);
        }

        // Buzzer pattern
        for (int i = 0; i < BUZZER_PULSE_COUNT; i++) {
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(BUZZER_PULSE_DURATION * 1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(BUZZER_PULSE_DURATION * 1000);
            if (i < BUZZER_PULSE_COUNT - 1) {
                gpioWrite(BUZZER_PIN, 1);
                gpioDelay(600 * 1000);
                gpioWrite(BUZZER_PIN, 0);
                gpioDelay(BUZZER_PULSE_DURATION * 1000);
            }
        }

        fclose(log_file);
        gpioTerminate();
        return 1; // Exit with error code
    }

    // Main loop
    main_loop();

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

