#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0
#define MIN_LUX 0
#define MAX_LUX 1000

// Global variables
int i2c_handle;
double lux_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
double read_lux();
void update_buffer(double lux);
double calculate_average_lux();
void set_led_frequency(double average_lux);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
double read_lux() {
    char config_cmd = 0x10; // Continuous high resolution mode
    char buffer[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd); // Send config command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1.0;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (double)raw_value / 1.2;
}

// Update the circular buffer with the latest lux reading
void update_buffer(double lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate the average lux value from the circular buffer
double calculate_average_lux() {
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Set the LED frequency based on the average lux value
void set_led_frequency(double average_lux) {
    double frequency = MIN_FREQUENCY + (average_lux - MIN_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_LUX - MIN_LUX);
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    gpioSetPWMfrequency(GPIO_LED, (int)frequency);
    gpioPWM(GPIO_LED, 128); // 50% duty cycle
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set GPIO to input (safe state)
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        double lux = read_lux();
        if (lux >= 0) {
            update_buffer(lux);
            double average_lux = calculate_average_lux();
            set_led_frequency(average_lux);
            printf("Lux: %.2f, Average Lux: %.2f\n", lux, average_lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

