#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip number
#define GPIOCHIP 0

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *led_line;
struct gpiod_line *button_line;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void blink_led();
void button_callback(struct gpiod_line_event event);
void signal_handler(int sig);

// Signal handler for graceful termination
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines and chip
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_number(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Request LED line as output
    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    // Request button line as input with falling edge detection
    struct gpiod_line_request_config config;
    config.consumer = "blink_button";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_EDGE_RISING;

    if (gpiod_line_request(button_line, &config, 0) < 0) {
        perror("Error requesting button line as input with falling edge detection");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    // Set initial state of LED to off
    gpiod_line_set_value(led_line, 0);

    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio() {
    // Release button line
    gpiod_line_release(button_line);

    // Release LED line
    gpiod_line_release(led_line);

    // Close GPIO chip
    gpiod_chip_close(chip);
}

// Function to blink the LED
void blink_led() {
    struct timespec on_time, off_time;
    on_time.tv_sec = 1;  // 1 second on
    on_time.tv_nsec = 0;
    off_time.tv_sec = 1; // 1 second off
    off_time.tv_nsec = 0;

    while (1) {
        // Turn LED on
        gpiod_line_set_value(led_line, 1);
        nanosleep(&on_time, NULL);

        // Turn LED off
        gpiod_line_set_value(led_line, 0);
        nanosleep(&off_time, NULL);
    }
}

// Callback function for button press
void button_callback(struct gpiod_line_event event) {
    if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        printf("Button pressed!\n");
        // Stop blinking
        gpiod_line_set_value(led_line, 0);

        // Release GPIO lines and chip
        cleanup_gpio();

        // Exit the program
        exit(0);
    }
}

int main() {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Start blinking the LED in a separate thread
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: blink the LED
        blink_led();
        exit(0); // This will never be reached, blink_led is an infinite loop
    } else if (pid < 0) {
        perror("fork failed");
        cleanup_gpio();
        return 1;
    }

    // Set up event monitoring for the button line
    struct gpiod_line_event_consumer consumer;
    consumer.consumer = "blink_button";
    consumer.event = button_callback;

    // Start event monitoring
    if (gpiod_line_event_open(button_line, &consumer) < 0) {
        perror("Error opening event monitoring");
        cleanup_gpio();
        return 1;
    }

    // Wait for events indefinitely
    while (1) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(button_line, NULL);
        if (ret < 0) {
            perror("Error waiting for event");
            cleanup_gpio();
            return 1;
        }
        if (ret > 0) {
            if (gpiod_line_event_read(button_line, &event) < 0) {
                perror("Error reading event");
                cleanup_gpio();
                return 1;
            }
            button_callback(event);
        }
    }

    return 0;
}

