        // Turn LED ON
        gpioWrite(LED_PIN, 1);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(750000); // 750ms

        // Turn LED OFF
        gpioWrite(LED_PIN, 0);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(750000); // 750ms
    }

    // Clean up and terminate pigpio
    gpioWrite(LED_PIN, 0); // Ensure LED is off before exiting
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

