#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Set button pin as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on button pin\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to control the LED
void control_led(int button_state) {
    if (button_state == 1) {
        // Button is pressed
        int on_time = 500; // milliseconds
        int off_time = 500; // milliseconds

        while (program_running) {
            // Turn LED on
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to write to LED pin (on)\n");
                break; // Exit loop on error
            }
            gpioDelay(on_time * 1000); // Convert ms to microseconds

            // Turn LED off
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to write to LED pin (off)\n");
                break; // Exit loop on error
            }
            gpioDelay(off_time * 1000); // Convert ms to microseconds
        }
    } else {
        // Button is released
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Failed to write to LED pin (off)\n");
        }
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button state
        int button_state = gpioRead(BUTTON_PIN);

        // Control LED based on button state
        control_led(button_state);

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

