#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// ADPD188BI I2C address
#define ADPD188BI_ADDR 0x39

// Register addresses (replace with actual values from datasheet)
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07

// GPIO pin for LED PWM control
#define LED_PIN 18

// PWM range (adjust as needed)
#define PWM_RANGE 1024

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_als();
int read_red();
int read_green();
int read_blue();
int combine_als_data(int lsb, int msb);
int log_data(int als, int red, int green, int blue);
void set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close I2C connection
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Turn off LED
    set_led_brightness(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(ADPD188BI_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    printf("I2C initialized successfully.\n");
    return 0;
}

// Read ALS data (LSB and MSB)
int read_als() {
    int lsb = wiringPiI2CReadReg8(i2c_fd, ALS_LSB_REG);
    if (lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB: %s\n", strerror(errno));
        return -1;
    }

    int msb = wiringPiI2CReadReg8(i2c_fd, ALS_MSB_REG);
    if (msb < 0) {
        fprintf(stderr, "Error reading ALS MSB: %s\n", strerror(errno));
        return -1;
    }

    return combine_als_data(lsb, msb);
}

// Read Red data (LSB and MSB)
int read_red() {
    int lsb = wiringPiI2CReadReg8(i2c_fd, RED_LSB_REG);
    if (lsb < 0) {
        fprintf(stderr, "Error reading Red LSB: %s\n", strerror(errno));
        return -1;
    }

    int msb = wiringPiI2CReadReg8(i2c_fd, RED_MSB_REG);
    if (msb < 0) {
        fprintf(stderr, "Error reading Red MSB: %s\n", strerror(errno));
        return -1;
    }

    return combine_als_data(lsb, msb);
}

// Read Green data (LSB and MSB)
int read_green() {
    int lsb = wiringPiI2CReadReg8(i2c_fd, GREEN_LSB_REG);
    if (lsb < 0) {
        fprintf(stderr, "Error reading Green LSB: %s\n", strerror(errno));
        return -1;
    }

    int msb = wiringPiI2CReadReg8(i2c_fd, GREEN_MSB_REG);
    if (msb < 0) {
        fprintf(stderr, "Error reading Green MSB: %s\n", strerror(errno));
        return -1;
    }

    return combine_als_data(lsb, msb);
}

// Read Blue data (LSB and MSB)
int read_blue() {
    int lsb = wiringPiI2CReadReg8(i2c_fd, BLUE_LSB_REG);
    if (lsb < 0) {
        fprintf(stderr, "Error reading Blue LSB: %s\n", strerror(errno));
        return -1;
    }

    int msb = wiringPiI2CReadReg8(i2c_fd, BLUE_MSB_REG);
    if (msb < 0) {
        fprintf(stderr, "Error reading Blue MSB: %s\n", strerror(errno));
        return -1;
    }

    return combine_als_data(lsb, msb);
}

// Combine LSB and MSB into a 16-bit unsigned value
int combine_als_data(int lsb, int msb) {
    return (msb << 8) | lsb;
}

// Log data to CSV file
int log_data(int als, int red, int green, int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Set LED brightness using PWM
void set_led_brightness(int brightness) {
    pwmWrite(LED_PIN, brightness);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Set LED pin as PWM output
    pinMode(LED_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired PWM frequency

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int als = read_als();
        int red = read_red();
        int green = read_green();
        int blue = read_blue();

        if (als != -1 && red != -1 && green != -1 && blue != -1) {
            log_data(als, red, green, blue);

            // Map ALS value to LED brightness (adjust range as needed)
            int brightness = (als * PWM_RANGE) / 65535; // Assuming ALS range is 0-65535
            if (brightness > PWM_RANGE) {
                brightness = PWM_RANGE;
            }
            set_led_brightness(brightness);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        delay(500); // Sample every 500ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    set_led_brightness(0);
    fclose(log_file);

    return 0;
}

