#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_STATUS 0x00
#define FXOS8700CQ_OUT_X_MSB 0x01

// Impact threshold
#define IMPACT_THRESHOLD 2.0f

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the FXOS8700CQ sensor
int initialize_sensor() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set to standby mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Configure for ±2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error setting ±2g range\n");
        return -1;
    }

    // Set output data rate to 200 Hz
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x15) < 0) {
        fprintf(stderr, "Error setting output data rate\n");
        return -1;
    }

    // Set to active mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x15 | 0x01) < 0) {
        fprintf(stderr, "Error setting active mode\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data from the sensor
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 4096.0f; // Assuming ±2g range
    float y_g = (float)y / 4096.0f;
    float z_g = (float)z / 4096.0f;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

