#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SAMPLE_RATE 20.0 // Hz
#define SAMPLE_PERIOD 50000 // us (50 ms)
#define CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50.0 // d/s
#define ALERT_DURATION 1000000 // us (1 second)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_gyro();
int read_gyro_data(gyro_data_t *data);
int calibrate_gyro(gyro_data_t *offsets);
int log_data(gyro_data_t data, gyro_data_t offsets);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the gyroscope
int init_gyro() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set CTRL_REG1 to 0x0F (normal mode, all axes enabled)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set CTRL_REG4 to 0x00 (250 dps full scale)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char raw_data[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, raw_data, 6); // Enable auto-increment
    if (result < 0) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes, and convert to float (2's complement)
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    data->x = (float)x / 131.0; // Sensitivity at 250 dps
    data->y = (float)y / 131.0;
    data->z = (float)z / 131.0;

    return 0;
}

// Function to calibrate the gyroscope
int calibrate_gyro(gyro_data_t *offsets) {
    gyro_data_t sample;
    float x_sum = 0, y_sum = 0, z_sum = 0;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&sample) < 0) {
            fprintf(stderr, "Error reading during calibration\n");
            return -1;
        }
        x_sum += sample.x;
        y_sum += sample.y;
        z_sum += sample.z;
        gpioDelay(SAMPLE_PERIOD);
    }

    offsets->x = x_sum / CALIBRATION_SAMPLES;
    offsets->y = y_sum / CALIBRATION_SAMPLES;
    offsets->z = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", offsets->x, offsets->y, offsets->z);
    return 0;
}

// Function to log data to file
int log_data(gyro_data_t data, gyro_data_t offsets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x - offsets.x, data.y - offsets.y, data.z - offsets.z);

    // Check for alert conditions
    if (fabs(data.x - offsets.x) > ALERT_THRESHOLD ||
        fabs(data.y - offsets.y) > ALERT_THRESHOLD ||
        fabs(data.z - offsets.z) > ALERT_THRESHOLD) {
        fprintf(log_file, "%s,ALERT: X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, data.x - offsets.x, data.y - offsets.y, data.z - offsets.z);
        fflush(log_file); // Ensure the alert is written immediately
        fprintf(stderr, "ALERT: Gyroscope data exceeds threshold!\n");
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() < 0) {
        cleanup();
        return 1;
    }

    // Calibrate gyroscope
    gyro_data_t offsets;
    if (calibrate_gyro(&offsets) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    gyro_data_t gyro_data;
    while (!terminate) {
        if (read_gyro_data(&gyro_data) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        if (log_data(gyro_data, offsets) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

