        return -1;
    }

    // Configure full resolution mode
    if (configure_full_resolution() != 0) {
        fprintf(stderr, "Error: Failed to configure full resolution mode.\n");
        return -1;
    }

    return 0;
}

// Function to verify the device ID
int verify_device_id() {
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }
    return 0;
}

// Function to configure the ADXL345 for full resolution mode
int configure_full_resolution() {
    int status = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08);
    if (status < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %d\n", status);
        return -1;
    }
    return 0;
}

