    int status = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes, and convert to g units
    int16_t x_raw = (buffer[1] << 8) | buffer[0];
    int16_t y_raw = (buffer[3] << 8) | buffer[2];
    int16_t z_raw = (buffer[5] << 8) | buffer[4];

    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

