#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL6180X I2C address
#define VL6180X_ADDR 0x29

// VL6180X register addresses
#define VL6180X_REG_IDENTIFICATION_MODEL_ID 0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_VAL 0x062
#define VL6180X_REG_SYSTEM_INTERRUPT_CLEAR 0x015

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl6180x_init();
int read_distance();
void log_data(int distance);
void signal_handler(int signal);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_register(int handle, uint8_t reg, uint8_t *value);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to write a byte to a VL6180X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL6180X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL6180X sensor
int vl6180x_init() {
    uint8_t model_id;

    // Check sensor presence
    if (read_register(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    if (model_id != 0xB4) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

