#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus
#define I2C_BUS 1

// Define sampling interval (10 ms)
#define SAMPLING_INTERVAL_US 10000

// Define retry delay (1 second)
#define RETRY_DELAY_S 1

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int i2c_handle, int sensor_address, int16_t *data);
void calculate_tdoa(int16_t sensor1, int16_t sensor2, struct timespec timestamp, double *tdoa);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %s\n", strerror(errno));
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int sensor_address, int16_t *data) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read data from sensor 0x%02X: %s\n", sensor_address, strerror(errno));
        return -1;
    }

    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to calculate TDOA
void calculate_tdoa(int16_t sensor1, int16_t sensor2, struct timespec timestamp, double *tdoa) {
    // Simple TDOA calculation (replace with actual algorithm)
    // This is a placeholder and needs to be replaced with a proper TDOA algorithm
    // based on the specific microphone and application requirements.
    // For example, you could use cross-correlation or a more sophisticated algorithm.
    // This example uses a very basic difference between the two signals.
    *tdoa = (double)(sensor1 - sensor2) / 1000.0; // Scale to microseconds
}

// Function to log data to CSV file
void log_data(sensor_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return;
    }

    fprintf(log_file, "%ld,%ld,%d,%d,%.6f\n",
            data.timestamp.tv_sec, data.timestamp.tv_nsec,
            data.sensor1, data.sensor2, data.tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        struct timespec ts;
        int16_t sensor1_data, sensor2_data;
        double tdoa;

        // Read sensor data
        if (read_sensor_data(i2c_handle1, SENSOR1_ADDR, &sensor1_data) != 0) {
            fprintf(stderr, "Failed to read sensor 1, retrying in %d seconds...\n", RETRY_DELAY_S);
            gpioDelay(RETRY_DELAY_S * 1000000); // Delay in microseconds
            continue;
        }

        if (read_sensor_data(i2c_handle2, SENSOR2_ADDR, &sensor2_data) != 0) {
            fprintf(stderr, "Failed to read sensor 2, retrying in %d seconds...\n", RETRY_DELAY_S);
            gpioDelay(RETRY_DELAY_S * 1000000); // Delay in microseconds
            continue;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            continue;
        }

        // Calculate TDOA
        calculate_tdoa(sensor1_data, sensor2_data, ts, &tdoa);

        // Store data
        data.sensor1 = sensor1_data;
        data.sensor2 = sensor2_data;
        data.timestamp = ts;
        data.tdoa = tdoa;

        // Log data
        log_data(data);

        // Delay
        gpioDelay(SAMPLING_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

