#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read a single register from the ADIS16448
int read_register(int reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg_addr | 0x80); // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deassert CS

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    return ((rx_buf[0] << 8) | rx_buf[1]);
}

// Function to convert raw gyroscope data to degrees per second
float convert_gyro(int raw_data) {
    return (float)raw_data * 0.02;
}

// Function to convert raw accelerometer data to g-force
float convert_accel(int raw_data) {
    return (float)raw_data * 0.00025;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deassert CS initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 3); // Mode 3
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int gyro_x_raw = read_register(XGYRO_OUT);
        int gyro_y_raw = read_register(YGYRO_OUT);
        int gyro_z_raw = read_register(ZGYRO_OUT);
        int accel_x_raw = read_register(XACCL_OUT);
        int accel_y_raw = read_register(YACCL_OUT);
        int accel_z_raw = read_register(ZACCL_OUT);

        if (gyro_x_raw == -1 || gyro_y_raw == -1 || gyro_z_raw == -1 ||
            accel_x_raw == -1 || accel_y_raw == -1 || accel_z_raw == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        float gyro_x = convert_gyro(gyro_x_raw);
        float gyro_y = convert_gyro(gyro_y_raw);
        float gyro_z = convert_gyro(gyro_z_raw);
        float accel_x = convert_accel(accel_x_raw);
        float accel_y = convert_accel(accel_y_raw);
        float accel_z = convert_accel(accel_z_raw);

        printf("Gyro X: %.2f dps, Y: %.2f dps, Z: %.2f dps, Accel X: %.4f g, Y: %.4f g, Z: %.4f g\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

