#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CE0 8 // BCM GPIO 8

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec per LSB
#define ACCEL_SCALE 0.00025 // g per LSB

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data_t;

// Function prototypes
int initialize_spi();
imu_data_t read_imu_data();
void print_imu_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read IMU data from ADIS16448
imu_data_t read_imu_data() {
    imu_data_t data;
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Read Gyroscope Data
    tx_buf[0] = (XGYRO_OUT | 0x80); // Set MSB for read
    tx_buf[1] = 0x00; // Dummy value

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading gyro data: %d\n", result);
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0; // Set to 0 on error
    } else {
        int16_t raw_gyro_x = (rx_buf[0] << 8) | rx_buf[1];
        data.gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    }

    // Read Accelerometer Data
    tx_buf[0] = (XACCL_OUT | 0x80); // Set MSB for read
    tx_buf[1] = 0x00; // Dummy value

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading accel data: %d\n", result);
        data.accel_x = data.accel_y = data.accel_z = 0.0; // Set to 0 on error
    } else {
        int16_t raw_accel_x = (rx_buf[0] << 8) | rx_buf[1];
        data.accel_x = (float)raw_accel_x * ACCEL_SCALE;
    }

    return data;
}

// Print IMU data to console
void print_imu_data(imu_data_t data) {
    printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
           data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);
}

// Cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        imu_data_t imu_data = read_imu_data();
        print_imu_data(imu_data);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

