#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit value from the MPU-6886
int16_t read_mpu6886_value(int handle, uint8_t reg)
{
    int16_t value;
    int result;

    for (int i = 0; i < 3; ++i) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            value = (int16_t)result;
            return value;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return 0; // Return 0 on failure
}

