#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_THRESH_TAP 0x1D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_FIFO_CTL 0x38
#define ADXL345_REG_FIFO_STATUS 0x39
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_SELF_TEST 0x0F

// LED GPIO pin (BCM numbering)
#define LED_PIN 17

// Impact threshold (g)
#define IMPACT_THRESHOLD 2.5

// I2C bus
#define I2C_BUS 1

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int adxl345_init();
int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);
int i2c_read_reg(int reg);
int i2c_write_reg(int reg, int value);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    float magnitude;
} sensor_data_t;

// Function to initialize the ADXL345 sensor
int adxl345_init() {
    // Set data format register to full resolution, ±2g range
    if (i2c_write_reg(ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error setting data format register\n");
        return -1;
    }

    // Set bandwidth rate register to 100 Hz
    if (i2c_write_reg(ADXL345_REG_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error setting bandwidth rate register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2c_write_reg(ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error setting power control register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = i2c_read_reg(ADXL345_REG_DATAX0);
    x1 = i2c_read_reg(ADXL345_REG_DATAX1);
    y0 = i2c_read_reg(ADXL345_REG_DATAY0);
    y1 = i2c_read_reg(ADXL345_REG_DATAY1);
    z0 = i2c_read_reg(ADXL345_REG_DATAZ0);
    z1 = i2c_read_reg(ADXL345_REG_DATAZ1);

    if (x0 < 0 || x1 < 0 || y0 < 0 || y1 < 0 || z0 < 0 || z1 < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((x1 << 8) | x0);
    *y = (int16_t)((y1 << 8) | y0);
    *z = (int16_t)((z1 << 8) | z0);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 256.0;
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to log an impact event to a file
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f g\n", timestamp, x, y, z, magnitude);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to read a register from the ADXL345
int i2c_read_reg(int reg) {
    int value = wiringPiI2CReadReg8(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "I2C read error: reg=0x%02X, error=%s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a register to the ADXL345
int i2c_write_reg(int reg, int value) {
    int result = wiringPiI2CWriteReg8(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, value=0x%02X, error=%s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(ADXL345_ADDRESS, I2C_BUS);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize ADXL345 sensor
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting impact detection...\n");

    // Main loop
    while (program_running) {
        int16_t x, y, z;
        if (adxl345_read_acceleration(&x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                digitalWrite(LED_PIN, HIGH);
                delay(500);
                digitalWrite(LED_PIN, LOW);
                log_impact(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Re-initializing...\n");
            // Attempt to re-initialize the sensor
            if (adxl345_init() < 0) {
                fprintf(stderr, "ADXL345 re-initialization failed\n");
                program_running = 0; // Exit if re-initialization fails
            }
        }

        delay(10); // 10 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    digitalWrite(LED_PIN, LOW); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

