int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, REG_X_AXIS, buf, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
