    }

    return 0;
}

// Initialize ADXL345
int adxl345_init(int i2c_fd) {
    // Verify device ID
    if (adxl345_read_device_id(i2c_fd) != 0x53) {
        fprintf(stderr, "Error: Invalid device ID\n");
        return -1;
    }

    // Set standby mode
    if (adxl345_set_standby_mode(i2c_fd) != 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Enable interrupts
    if (adxl345_enable_interrupt(i2c_fd) != 0) {
        fprintf(stderr, "Error enabling interrupts\n");
        return -1;
    }

    return 0;
}

// Read device ID
int adxl345_read_device_id(int i2c_fd) {
    uint8_t devid;
    if (i2c_smbus_read_byte_data(i2c_fd, ADXL345_REG_DEVID) < 0) {
        perror("Error reading device ID");
        return -1;
    }
    devid = i2c_smbus_read_byte_data(i2c_fd, ADXL345_REG_DEVID);
    return devid;
}

// Set ADXL345 to standby mode
int adxl345_set_standby_mode(int i2c_fd) {
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        perror("Error setting standby mode");
        return -1;
    }
    return 0;
}

// Enable interrupts
int adxl345_enable_interrupt(int i2c_fd) {
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_INT_ENABLE, 0x40) < 0) {
        perror("Error enabling interrupts");
        return -1;
    }
    return 0;
}

// Disable interrupts
int adxl345_disable_interrupt(int i2c_fd) {
    if (i2c_smbus_write_byte_data(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00) < 0) {
        perror("Error disabling interrupts");
        return -1;
    }
    return 0;
}

// Read interrupt source register
int adxl345_read_interrupt_source(int i2c_fd) {
    uint8_t interrupt_source;
    interrupt_source = i2c_smbus_read_byte_data(i2c_fd, ADXL345_REG_INT_SOURCE);
    return interrupt_source;
}

// Read free-fall status
int adxl345_read_freefall_status(int i2c_fd) {
    uint8_t freefall_status;
    freefall_status = i2c_smbus_read_byte_data(i2c_fd, ADXL345_REG_INT_SOURCE);
    return freefall_status;
}

// Check if free-fall is active
int is_freefall(int16_t x, int16_t y, int16_t z, float threshold) {
    float x_g = (float)x / 256.0; // Assuming +/- 2g range
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;

    if (x_g < -threshold || x_g > threshold ||
        y_g < -threshold || y_g > threshold ||
        z_g < -threshold || z_g > threshold) {
        return 0; // Not in free-fall
    } else {
        return 1; // In free-fall
    }
}

