int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int16_t x, y, z;

    // Read acceleration data
    if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) != 0) {
        fprintf(stderr, "Error reading acceleration data in interrupt handler\n");
        return;
    }

    // Log the data
    log_data(log_file, x, y, z);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupts
    adxl345_disable_interrupt(i2c_fd);

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Release GPIO line
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT); // Set back to input

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

