int init_lsm6dsr() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 104 Hz, ±2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: 104 Hz, ±250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Function to read data from the LSM6DSR
int read_lsm6dsr(sensor_data_t *data) {
    char raw_data[12];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, raw_data, 12) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Combine high and low bytes for accelerometer
    accel_x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    accel_y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    accel_z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Combine high and low bytes for gyroscope
    gyro_x = (int16_t)((raw_data[7] << 8) | raw_data[6]);
    gyro_y = (int16_t)((raw_data[9] << 8) | raw_data[8]);
    gyro_z = (int16_t)((raw_data[11] << 8) | raw_data[10]);

    // Convert to g and dps
    data->accel_x = (float)accel_x * ACCEL_SCALE;
    data->accel_y = (float)accel_y * ACCEL_SCALE;
    data->accel_z = (float)accel_z * ACCEL_SCALE;
    data->gyro_x = (float)gyro_x * GYRO_SCALE;
    data->gyro_y = (float)gyro_y * GYRO_SCALE;
    data->gyro_z = (float)gyro_z * GYRO_SCALE;

    return 0;
}

