#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_WHO_AM_I 0x02
#define ADIS16266_GYRO_XOUT 0x04
#define ADIS16266_GYRO_YOUT 0x06
#define ADIS16266_GYRO_ZOUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scale factor for angular rate (deg/sec/LSB)
#define SCALE_FACTOR 0.0305

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t address, uint16_t *data);
int spi_write_register(int handle, uint8_t address, uint16_t data);
int verify_who_am_i(int handle);
int read_gyro_data(int handle, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Function to read a register from the ADIS16266
int spi_read_register(int handle, uint8_t address, uint16_t *data) {
    char tx[3];
    char rx[3];

    // Construct the transmit buffer (address + dummy byte)
    tx[0] = address | 0x80; // Set MSB to 1 for read operation
    tx[1] = 0x00;           // Dummy byte
    tx[2] = 0x00;           // Dummy byte

    // Perform the SPI transaction
    int result = spiXfer(handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI read failed (address 0x%02X, error %d)\n", address, result);
        return -1;
    }

    // Extract the 16-bit data from the receive buffer
    *data = (rx[1] << 8) | rx[2];

    return 0;
}

// Function to write a register in the ADIS16266
int spi_write_register(int handle, uint8_t address, uint16_t data) {
    char tx[3];
    char rx[3];

    // Construct the transmit buffer (address + data)
    tx[0] = address & 0x7F; // Set MSB to 0 for write operation
    tx[1] = (data >> 8) & 0xFF; // MSB of data
    tx[2] = data & 0xFF;      // LSB of data

    // Perform the SPI transaction
    int result = spiXfer(handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI write failed (address 0x%02X, data 0x%04X, error %d)\n", address, data, result);
        return -1;
    }

    return 0;
}

// Function to verify the WHO_AM_I register
int verify_who_am_i(int handle) {
    uint16_t who_am_i;

    if (spi_read_register(handle, ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x4143) {
        fprintf(stderr, "Error: WHO_AM_I value mismatch (expected 0x4143, got 0x%04X)\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I verification successful (value: 0x%04X)\n", who_am_i);
    return 0;
}

// Function to read the angular rate data from the ADIS16266
int read_gyro_data(int handle, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;

    if (spi_read_register(handle, ADIS16266_GYRO_XOUT, &raw_x) != 0) {
        fprintf(stderr, "Error: Failed to read GYRO_XOUT register\n");
        return -1;
    }

    if (spi_read_register(handle, ADIS16266_GYRO_YOUT, &raw_y) != 0) {
        fprintf(stderr, "Error: Failed to read GYRO_YOUT register\n");
        return -1;
    }

    if (spi_read_register(handle, ADIS16266_GYRO_ZOUT, &raw_z) != 0) {
        fprintf(stderr, "Error: Failed to read GYRO_ZOUT register\n");
        return -1;
    }

    // Convert raw values to degrees per second
    *x = (float)((int16_t)raw_x) * SCALE_FACTOR;
    *y = (float)((int16_t)raw_y) * SCALE_FACTOR;
    *z = (float)((int16_t)raw_z) * SCALE_FACTOR;

    return 0;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,AngularRateX,AngularRateY,AngularRateZ\n");
    }
    rewind(log_file);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(spi_handle, &x, &y, &z) == 0) {
            // Log the data
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        }

        // Wait for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close SPI channel and log file
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated successfully\n");
    return 0;
}

