#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SENSITIVITY 8.75f / 114.285f // Sensitivity in mdps/LSB
#define SAMPLE_RATE 10000 // 10 ms sample rate

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gyro();
int read_gyro_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Verify WHO_AM_I register
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
        if (status >= 0) {
            if (status == 0xD3) {
                printf("WHO_AM_I register verified: 0x%X\n", status);
                break;
            } else {
                fprintf(stderr, "Error: WHO_AM_I register returned unexpected value: 0x%X\n", status);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        }
        retries--;
        gpioDelay(10000); // 10 ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "Error: WHO_AM_I verification failed after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100 Hz data rate)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); // 0x0F = 0b00001111
        if (status >= 0) {
            printf("CTRL_REG1 configured successfully\n");
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        }
        retries--;
        gpioDelay(10000); // 10 ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "Error: CTRL_REG1 configuration failed after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (Full scale +/- 250 dps)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00); // 0x00 = 0b00000000
        if (status >= 0) {
            printf("CTRL_REG4 configured successfully\n");
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4: %d\n", status);
        }
        retries--;
        gpioDelay(10000); // 10 ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "Error: CTRL_REG4 configuration failed after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (status >= 0) {
            // Combine high and low bytes, convert to float, and scale
            int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

            *x = (float)x_raw * SENSITIVITY;
            *y = (float)y_raw * SENSITIVITY;
            *z = (float)z_raw * SENSITIVITY;

            return 0;
        } else {
            fprintf(stderr, "Error reading gyroscope data: %d\n", status);
        }
        retries--;
        gpioDelay(10000); // 10 ms delay
    }

    fprintf(stderr, "Error: Failed to read gyroscope data after multiple retries.\n");
    return -1;
}

// Log data to CSV file
void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (long)ts.tv_sec * 1000000000L + ts.tv_nsec;

    fprintf(log_file, "%ld,%.3f,%.3f,%.3f\n", timestamp_ns, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

