int configure_gpio() {
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
