    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (flame_detected == 0) {
        fprintf(log_file, "%s - Flame detected: YES\n", timestamp);
        printf("FLAME DETECTED!\n");
    } else {
        fprintf(log_file, "%s - Flame detected: NO\n", timestamp);
    }

    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to close the log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

