        fprintf(stderr, "Error opening log file %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value >= 0) {
            log_flame_event(sensor_value);
        } else {
            fprintf(stderr, "Error reading sensor, logging error to file.\n");
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s - ERROR: Failed to read sensor value\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    close_log_file();
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

