// Define GPIO pins for the Hall Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_sensor_state(SensorStates sensor_states);
void check_conveyor_halt(SensorStates sensor_states);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor state to a file
void log_sensor_state(SensorStates sensor_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor_states.sensor1_state, sensor_states.sensor2_state);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Function to check if both sensors are active and halt the conveyor
void check_conveyor_halt(SensorStates sensor_states) {
    if (sensor_states.sensor1_state == 1 && sensor_states.sensor2_state == 1) {
        printf("HALT: Both sensors are active!\n");
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    SensorStates sensor_states;

    // Main loop
    while (program_running) {
        // Read sensor states
        sensor_states.sensor1_state = read_sensor(SENSOR1_GPIO);
        sensor_states.sensor2_state = read_sensor(SENSOR2_GPIO);

        // Log sensor state
        log_sensor_state(sensor_states);

        // Check for conveyor halt condition
        check_conveyor_halt(sensor_states);

        // Wait for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

