#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x2A
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define DATA_REG 0x01
#define DATA_LENGTH 6
#define TILT_THRESHOLD 45.0f
#define SAMPLE_RATE_MS 10

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mma8452q_init(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_tilt_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }
    if (value == NULL) {
        fprintf(stderr, "Error: Null pointer passed to i2c_read_reg.\n");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// MMA8452Q initialization function
int mma8452q_init(int fd) {
    uint8_t who_am_i;

    // Verify WHO_AM_I register
    if (i2c_read_reg(fd, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Set to standby mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error setting to standby mode.\n");
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2c_write_reg(fd, CTRL_REG2, 0x00) != 0) {
        fprintf(stderr, "Error setting data rate.\n");
        return -1;
    }

    // Set to active mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error setting to active mode.\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data function
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[DATA_LENGTH];

    if (write(fd, DATA_REG, 1) != 1) {
        perror("Error writing data register address");
        return -1;
    }

    if (read(fd, data, DATA_LENGTH) != DATA_LENGTH) {
        perror("Error reading accelerometer data");
        return -1;
    }

    *x = (int16_t)((data[0] << 4) | (data[1] >> 4));
    *y = (int16_t)((data[2] << 4) | (data[3] >> 4));
    *z = (int16_t)((data[4] << 4) | (data[5] >> 4));

    return 0;
}

// Calculate tilt function
float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    float tilt = atan2(sqrt(x * x + y * y), z) * 180.0 / M_PI;
    return tilt;
}

// Log tilt event function
int log_tilt_event(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int16_t x, y, z;
    float tilt;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8452Q
    if (mma8452q_init(i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate tilt
            tilt = calculate_tilt(x, y, z);

            // Check for tilt threshold
            if (fabs(tilt) > TILT_THRESHOLD) {
                // Log tilt event
                if (log_tilt_event(x, y, z) != 0) {
                    fprintf(stderr, "Error logging tilt event.\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data.\n");
        }

        // Delay
        usleep(SAMPLE_RATE_MS * 1000); // 10ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

