#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define CTRL_REG1 0x20
#define CTRL_REG3 0x22
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Calibration values (replace with your calibrated values)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 0.146
#define Y_SCALE 0.146
#define Z_SCALE 0.146

// Metal detector threshold
#define MAGNETIC_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_lis3mdl();
magnetometer_data_t read_magnetometer_data();
float calculate_magnitude(magnetometer_data_t data);
void log_data(magnetometer_data_t data);
void metal_detector_alert(float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the LIS3MDL sensor
int initialize_lis3mdl() {
    int retries = 0;
    while (retries < 3) {
        // Set CTRL_REG1 to 0x70 (Odr = 10 Hz, Temp sensor enable, Continuous conversion mode)
        if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x70) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries++;
            continue;
        }

        // Set CTRL_REG3 to 0x00 (Continuous conversion mode)
        if (i2cWriteByteData(i2c_handle, CTRL_REG3, 0x00) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries++;
            continue;
        }

        // Set CTRL_REG4 to 0x00 (±4 gauss, 110 Hz ODR)
        if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG4, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries++;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize LIS3MDL after 3 retries.\n");
    return -1; // Failure
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    // Read 6 bytes of data (X_L, X_H, Y_L, Y_H, Z_L, Z_H)
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data.\n");
        data.x = 0.0; // Set to 0 to avoid using uninitialized data
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Apply calibration and scaling
    data.x = ((float)x_raw * X_SCALE) + X_OFFSET;
    data.y = ((float)y_raw * Y_SCALE) + Y_OFFSET;
    data.z = ((float)z_raw * Z_SCALE) + Z_OFFSET;

    return data;
}

// Function to calculate the magnitude of the magnetic field
float calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to log data to a file
void log_data(magnetometer_data_t data) {
    fprintf(log_file, "%.3f,%.3f,%.3f\n", data.x, data.y, data.z);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

// Function to check for metal detection
void metal_detector_alert(float magnitude) {
    if (magnitude > MAGNETIC_THRESHOLD) {
        fprintf(stderr, "Metal Detected!\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the LIS3MDL sensor
    if (initialize_lis3mdl() != 0) {
        fprintf(stderr, "LIS3MDL initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("magnetic_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data();

        // Calculate magnitude
        float magnitude = calculate_magnitude(data);

        // Log data
        log_data(data);

        // Check for metal detection
        metal_detector_alert(magnitude);

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100000);
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

