#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_RESET_REG 0x01
#define ADXL354B_POWER_CTL_REG 0x2D
#define ADXL354B_STATUS_REG 0x02
#define ADXL354B_XDATA_L 0x08
#define ADXL354B_XDATA_M 0x09
#define ADXL354B_XDATA_H 0x0A
#define ADXL354B_YDATA_L 0x0B
#define ADXL354B_YDATA_M 0x0C
#define ADXL354B_YDATA_H 0x0D
#define ADXL354B_ZDATA_L 0x0E
#define ADXL354B_ZDATA_M 0x0F
#define ADXL354B_ZDATA_H 0x10
#define ADXL354B_PARTID 0x00

// Reset Value
#define ADXL354B_RESET_VALUE 0x52

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int reg, uint8_t *data, int len);
int spi_write_register(int reg, uint8_t data);
int reset_adxl354b();
int verify_sensor_presence();
int read_acceleration_data(int16_t *x, int16_t *y, int16_t *z);
int log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Function to read from an ADXL354B register via SPI
int spi_read_register(int reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    // Set MSB of register address to 1 for read operation
    tx_buf[0] = (reg | 0x80) | 0x40; // Set MSB for read, bit 6 for multi-byte
    for (int i = 1; i <= len; i++) {
        tx_buf[i] = 0x00; // Dummy data for reading
    }

    int result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    for (int i = 0; i < len; i++) {
        data[i] = rx_buf[i + 1];
    }

    return 0;
}

// Function to write to an ADXL354B register via SPI
int spi_write_register(int reg, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to reset the ADXL354B
int reset_adxl354b() {
    uint8_t reset_value = ADXL354B_RESET_VALUE;
    if (spi_write_register(ADXL354B_RESET_REG, reset_value) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1); // Wait 1 ms
    return 0;
}

// Function to verify sensor presence by reading the PARTID register
int verify_sensor_presence() {
    uint8_t partid;
    if (spi_read_register(ADXL354B_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }

    if (partid != 0xAD) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL354B
int read_acceleration_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_m, x_h, y_l, y_m, y_h, z_l, z_m, z_h;

    if (spi_read_register(ADXL354B_XDATA_L, &x_l, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_XDATA_M, &x_m, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_XDATA_H, &x_h, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_YDATA_L, &y_l, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_YDATA_M, &y_m, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_YDATA_H, &y_h, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_ZDATA_L, &z_l, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_ZDATA_M, &z_m, 1) != 0) return -1;
    if (spi_read_register(ADXL354B_ZDATA_H, &z_h, 1) != 0) return -1;

    *x = ((int16_t)x_h << 8) | x_m;
    *y = ((int16_t)y_h << 8) | y_m;
    *z = ((int16_t)z_h << 8) | z_m;

    return 0;
}

// Function to log data to a file
int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
