// ADIS16362 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 3       // SPI Mode 3

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function prototypes
int initialize_spi();
int read_register(uint8_t address, uint16_t *data);
imu_data_t read_imu_data();
int log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from a specific register
int read_register(uint8_t address, uint16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    tx_buffer[0] = address | 0x80; // Set MSB for read operation
    tx_buffer[1] = 0x00;           // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    *data = (rx_buffer[0] << 8) | rx_buffer[1];
    return 0;
}

// Read IMU data and convert to physical units
imu_data_t read_imu_data() {
    imu_data_t data;
    struct timespec ts;

    // Read gyroscope data
    if (read_register(X_GYRO_OUT, (uint16_t *)&data.x_gyro) != 0) {
        data.x_gyro = 0.0;
    }
    if (read_register(Y_GYRO_OUT, (uint16_t *)&data.y_gyro) != 0) {
        data.y_gyro = 0.0;
    }
    if (read_register(Z_GYRO_OUT, (uint16_t *)&data.z_gyro) != 0) {
        data.z_gyro = 0.0;
    }

    // Read accelerometer data
    if (read_register(X_ACCL_OUT, (uint16_t *)&data.x_accel) != 0) {
        data.x_accel = 0.0;
    }
    if (read_register(Y_ACCL_OUT, (uint16_t *)&data.y_accel) != 0) {
        data.y_accel = 0.0;
    }
    if (read_register(Z_ACCL_OUT, (uint16_t *)&data.z_accel) != 0) {
        data.z_accel = 0.0;
    }

    // Get timestamp
    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    return data;
}

// Log data to CSV file
int log_data(imu_data_t data) {
    fprintf(log_file, "%lf,%lf,%lf,%lf,%lf,%lf,%lf\n",
            data.timestamp, data.x_gyro, data.y_gyro, data.z_gyro,
            data.x_accel, data.y_accel, data.z_accel);
    fflush(log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Main loop
    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(10); // 10 ms delay (approximately 100 Hz)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

