#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define CHIP_ID 4

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    int result;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    result = gpioInitialiseChip(CHIP_ID);
    if (result < 0) {
        fprintf(stderr, "Failed to initialize GPIO chip %d: %d\n", CHIP_ID, result);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    result = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", GPIO_PIN, result);
        gpioTerminate();
        return 1;
    }

    printf("Self-parking sequence started\n");

    // Main loop
    while (running) {
        // Read GPIO value
        int value = gpioRead(GPIO_PIN);

        // Check for obstacle (LOW signal)
        if (value == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Self-parking sequence completed\n", timestamp);
            running = 0; // Exit the loop after completing the sequence
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

