#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    int combined_value = gpioRead(SENSOR1_GPIO) | (gpioRead(SENSOR2_GPIO) << 1);
    *sensor1_value = (combined_value & 1) ? 0 : 1; // Active low
    *sensor2_value = (combined_value & 2) ? 0 : 1; // Active low
    return 0; // Return 0 for success
}

// Function to log the sensor data with a timestamp
void log_data(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
           sensor1_value ? "Clear" : "Obstacle",
           sensor2_value ? "Clear" : "Obstacle");
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Main loop
    while (program_running) {
