#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling factor (deg/sec per LSB)
#define SCALE_FACTOR 0.02

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a 16-bit register from the ADIS16266
int16_t read_register(int reg_addr) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer (MSB set for read)
    tx_buf[0] = (reg_addr << 1) | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the received bytes to form the 16-bit value
    int16_t value = (rx_buf[1] << 8) | rx_buf[2];

    return value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int16_t x_rate = read_register(X_GYRO_OUT);
        int16_t y_rate = read_register(Y_GYRO_OUT);
        int16_t z_rate = read_register(Z_GYRO_OUT);

        if (x_rate == -1 || y_rate == -1 || z_rate == -1) {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue; // Retry the loop
        }

        // Convert to degrees per second
        float x_rate_dps = x_rate * SCALE_FACTOR;
        float y_rate_dps = y_rate * SCALE_FACTOR;
        float z_rate_dps = z_rate * SCALE_FACTOR;

        // Log the data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate_dps, y_rate_dps, z_rate_dps);

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

