#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr()
{
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 104 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: 104 Hz, +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_lsm6dsr(float *ax, float *ay, float *az, float *gx, float *gy, float *gz)
{
    char buffer[12];

    // Read accelerometer and gyroscope data in one go
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);
    if (bytes_read != 12) {
        fprintf(stderr, "Error reading accelerometer and gyroscope data: %d\n", bytes_read);
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_gx = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_gy = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_gz = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t raw_ax = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_ay = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_az = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to g and dps
    *ax = (float)raw_ax / 16384.0f; // +/- 2g range
    *ay = (float)raw_ay / 16384.0f;
    *az = (float)raw_az / 16384.0f;
    *gx = (float)raw_gx / 131.0f;   // +/- 250 dps range
    *gy = (float)raw_gy / 131.0f;
    *gz = (float)raw_gz / 131.0f;

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    float ax, ay, az, gx, gy, gz;
    while (!terminate) {
        if (read_lsm6dsr(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

