#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDRESS 0x1F

// FXOS8700 register addresses
#define FXOS8700_REG_STATUS 0x00
#define FXOS8700_REG_OUT_X_MSB 0x01
#define FXOS8700_REG_OUT_X_LSB 0x02
#define FXOS8700_REG_OUT_Y_MSB 0x03
#define FXOS8700_REG_OUT_Y_LSB 0x04
#define FXOS8700_REG_OUT_Z_MSB 0x05
#define FXOS8700_REG_OUT_Z_LSB 0x06
#define FXOS8700_REG_OUT_MAG_X_MSB 0x33
#define FXOS8700_REG_OUT_MAG_X_LSB 0x34
#define FXOS8700_REG_OUT_MAG_Y_MSB 0x35
#define FXOS8700_REG_OUT_MAG_Y_LSB 0x36
#define FXOS8700_REG_OUT_MAG_Z_MSB 0x37
#define FXOS8700_REG_OUT_MAG_Z_LSB 0x38
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_ID 0x0D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    // Set to active mode, 100 Hz data rate, and +/- 2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set to hybrid mode (accelerometer and magnetometer enabled)
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x05) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, FXOS8700_REG_OUT_X_MSB, buffer, 12) == 12) {
            // Combine MSB and LSB for accelerometer data
            *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
            *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
            *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

            // Combine MSB and LSB for magnetometer data
            *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
            *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
            *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries\n");
    return -1; // Failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, FXOS8700_REG_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (device_id != 0xC7) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d, Mag X: %d, Mag Y: %d, Mag Z: %d\n",
                   accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

