#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_S 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold = 0;
    int i, count;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int result;

    // Parse command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring sound sensor with threshold: %d\n", threshold);

    while (program_running) {
        count = 0;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        for (i = 0; i < WINDOW_DURATION_S * 1000 / SAMPLE_INTERVAL_MS; i++) {
            result = gpioRead(GPIO_PIN);
            if (result < 0) {
                fprintf(stderr, "Error reading GPIO pin: %d\n", result);
                gpioTerminate();
                return 1;
            }
            if (result == 1) {
                count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
        }

        if (count > threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s OK (Count: %d)\n", timestamp, count);
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Clean up
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

