#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define log file name
#define LOG_FILE "access_log.txt"

// Define security code range
#define MIN_CODE 100000
#define MAX_CODE 999999

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int generate_security_code(int *code);
int unlock_door(int door_pin, int duration_ms);
int log_access(int code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal, exiting gracefully...\n");
    }
}

// Function to generate a random security code
int generate_security_code(int *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Invalid code pointer in generate_security_code\n");
        return -1;
    }

    *code = (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
    return 0;
}

// Function to unlock a door for a specified duration
int unlock_door(int door_pin, int duration_ms) {
    if (door_pin != DOOR_A_PIN && door_pin != DOOR_B_PIN) {
        fprintf(stderr, "Error: Invalid door pin in unlock_door\n");
        return -1;
    }

    if (gpioWrite(door_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to write HIGH to GPIO %d\n", door_pin);
        return -1;
    }

    gpioDelay(duration_ms);

    if (gpioWrite(door_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to write LOW to GPIO %d\n", door_pin);
        return -1;
    }

    return 0;
}

// Function to log access to a file
int log_access(int code) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d\n", timestamp, code);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(DOOR_A_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", DOOR_A_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(DOOR_B_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", DOOR_B_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int code;
        char input[10]; // Buffer for user input

        // Generate security code
        if (generate_security_code(&code) != 0) {
            fprintf(stderr, "Error: Failed to generate security code\n");
            continue; // Continue to the next iteration
        }

        // Print security code to stdout
        printf("Security Code: %d\n", code);

        // Read user input
        printf("Enter the security code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            fprintf(stderr, "Error: Failed to read input from stdin\n");
            continue; // Continue to the next iteration
        }

        // Remove trailing newline character
        input[strcspn(input, "\n")] = 0;

        // Validate user input
        if (strlen(input) != 6 || !isdigit(input[0]) || !isdigit(input[1]) || !isdigit(input[2]) || !isdigit(input[3]) || !isdigit(input[4]) || !isdigit(input[5])) {
            fprintf(stderr, "Error: Invalid input. Please enter a 6-digit number.\n");
            continue; // Continue to the next iteration
        }

        // Convert input to integer
        int entered_code = atoi(input);

        // Compare entered code to generated code
        if (entered_code == code) {
            printf("Access granted!\n");

            // Unlock door A for 5 seconds
            if (unlock_door(DOOR_A_PIN, 5000) != 0) {
                fprintf(stderr, "Error: Failed to unlock door A\n");
            }

            // Unlock door B for 5 seconds
            if (unlock_door(DOOR_B_PIN, 5000) != 0) {
                fprintf(stderr, "Error: Failed to unlock door B\n");
            }

            // Log access
            if (log_access(code) != 0) {
                fprintf(stderr, "Error: Failed to log access\n");
            }
        } else {
            printf("Access denied!\n");
        }

        // Wait for 10 seconds before the next attempt
        gpioDelay(10000); // 10 seconds
    }

    // Set GPIO pins to LOW before exiting
    gpioWrite(DOOR_A_PIN, 0);
    gpioWrite(DOOR_B_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

