    if (gpioSetMode(DOOR_A_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", DOOR_A_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(DOOR_B_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", DOOR_B_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize random number generator
    srand(time(NULL));

