#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define PWM_PIN 18
#define PWM_FREQUENCY 440 // Initial frequency
#define PWM_DUTYCYCLE 500000 // 50% duty cycle (1/2 of 1000000)
#define I2C_BUS 1
#define MPR121_ADDRESS 0x5A
#define MOTION_DETECTED_PREFIX "MOTION_DETECTED:"
#define SECRET_KEY "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define PORT 12345
#define SAMPLE_INTERVAL_MS 20

// Global variables
int i2c_handle;
int server_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_data(int *touch_data);
float calculate_frequency(int electrode_value);
int play_tone(float frequency);
int log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signal);
void cleanup();

// Structure to hold MPR121 configuration
typedef struct {
    unsigned char electrode_config[12];
} mpr121_config_t;

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        perror("Error: MPR121 soft reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0F) < 0) { // Touch threshold
            perror("Error: Failed to write touch threshold");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x0A) < 0) { // Release threshold
            perror("Error: Failed to write release threshold");
            return -1;
        }
    }

    // Configure electrode configuration (enable all electrodes)
    for (int i = 0; i < 12; i++) {
        mpr121_config_t config;
        config.electrode_config[i] = 0x0F; // Enable all electrodes
        if (i2cWriteByteData(i2c_handle, 0x5E, config.electrode_config[i]) < 0) {
            perror("Error: Failed to write electrode config");
            return -1;
        }
    }

    // Enable electrode sensing
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        perror("Error: Failed to enable electrode sensing");
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        perror("Error: Failed to read touch data");
        return -1;
    }

    touch_data[0] = ((buf[1] & 0x0F) << 8) | (buf[0] & 0xFF);
    touch_data[1] = ((buf[1] & 0xF0) << 4) | ((buf[0] >> 4) & 0x0F);

    return 0;
}

// Function to calculate frequency based on electrode value
float calculate_frequency(int electrode_value) {
    // Map electrode value (0-2047) to frequency range (200-1000 Hz)
    return 200.0 + (float)electrode_value * (1000.0 - 200.0) / 2047.0;
}

// Function to play a tone on the PWM pin
int play_tone(float frequency) {
    if (frequency <= 0) return -1; // Invalid frequency

    // Calculate PWM period
    int period = 1000000 / frequency; // Period in microseconds
    int half_period = period / 2;

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);

    // Set PWM duty cycle (50%)
    gpioPWM(PWM_PIN, PWM_DUTYCYCLE / 1000); // pigpio duty cycle is 0-1000

    // Play for 5 seconds
    gpioDelay(5000000); // 5 seconds

    // Stop PWM
    gpioPWM(PWM_PIN, 0); // Set duty cycle to 0 to stop the PWM signal

    return 0;
}

// Function to log the frequency to a file
int log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Frequency: %.2f Hz\n", timestamp, frequency);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        perror("Error: Log file is not open");
        return -1;
    }
}

// Function to handle a client connection
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error: Receive failed");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';

    // Validate the received message
    if (strncmp(buffer, MOTION_DETECTED_PREFIX, strlen(MOTION_DETECTED_PREFIX)) == 0) {
        // Extract the secret key from the message
        char *secret_start = strstr(buffer, SECRET_KEY);
        if (secret_start != NULL) {
            // Check if the secret key is present and matches the expected value
            if (strncmp(secret_start, SECRET_KEY, strlen(SECRET_KEY)) == 0) {
                // Extract the frequency from the message (assuming it's the part after the secret key)
                char *frequency_str = secret_start + strlen(SECRET_KEY) + 1; // Move past the secret key and colon
                if (frequency_str != NULL && frequency_str[0] != '\0') {
                    int frequency = atoi(frequency_str);
                    if (frequency > 0) {
                        // Play the tone
                        if (play_tone((float)frequency) == 0) {
                            // Log the frequency
                            if (log_frequency((float)frequency) != 0) {
                                fprintf(stderr, "Error: Failed to log frequency\n");
                            }
                        } else {
                            fprintf(stderr, "Error: Failed to play tone\n");
                        }
                    } else {
                        fprintf(stderr, "Error: Invalid frequency value\n");
                    }
                } else {
                    fprintf(stderr, "Error: No frequency value provided\n");
                }
            } else {
                fprintf(stderr, "Error: Invalid secret key\n");
            }
        } else {
            fprintf(stderr, "Error: Secret key not found\n");
        }
    } else {
        fprintf(stderr, "Error: Invalid message format\n");
    }

    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    // Stop PWM
    gpioPWM(PWM_PIN, 0);

    // Close I2C interface
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close server socket
    if (server_socket >= 0) {
        close(server_socket);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create server socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Error: Socket creation failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error: Socket bind failed");
        cleanup();
        return 1;
    }

    // Listen for incoming connections
    if (listen(server_socket, 5) < 0) {
        perror("Error: Socket listen failed");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Server listening on port %d...\n", PORT);

    // Main loop to accept connections
    while (!terminate) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("Error: Socket accept failed");
            continue; // Continue listening for other connections
        }

        fprintf(stderr, "Client connected\n");
        handle_client(client_socket);
        fprintf(stderr, "Client disconnected\n");
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

