float read_magnetic_field() {
    char buffer[6];
    int16_t x, y, z;

    // Read six bytes from the magnetometer
    if (i2cReadI2CBlockData(i2c_handle, LSM303_OUT_X_L_M, buffer, 6) != 6) {
        fprintf(error_log_file, "Error reading magnetometer data\n");
        return 0.0; // Return 0.0 to avoid further issues
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((buffer[1] << 8) | buffer[0]);
    y = (int16_t)((buffer[3] << 8) | buffer[2]);
    z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Calculate magnitude
    return calculate_magnitude((float)x, (float)y, (float)z);
}

