    // Map magnitude (0-1000) to PWM range (0-1000)
    int pwm_value = (int)(magnitude / 1000.0 * 1000.0); // Scale to 0-1000
    if (pwm_value > 1000) {
        pwm_value = 1000; // Cap at 1000
    }
    gpioPWM(LED_GPIO, pwm_value);
}

