#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int init_hmc5883l();
magnetometer_data_t read_magnetometer_data();
void apply_hard_iron_offset(magnetometer_data_t *data, int16_t x_offset, int16_t y_offset, int16_t z_offset);
void print_data(magnetometer_data_t data);
void signal_handler(int signal);

// Running average filter
#define NUM_SAMPLES 100
int16_t x_offset_history[NUM_SAMPLES];
int16_t y_offset_history[NUM_SAMPLES];
int16_t z_offset_history[NUM_SAMPLES];
int offset_index = 0;

// Function to initialize the HMC5883L
int init_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; // Set to 0 to avoid garbage values
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to apply hard-iron offset
void apply_hard_iron_offset(magnetometer_data_t *data, int16_t x_offset, int16_t y_offset, int16_t z_offset) {
    data->x -= x_offset;
    data->y -= y_offset;
    data->z -= z_offset;
}

// Function to print data
void print_data(magnetometer_data_t data) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize offset history
    for (int i = 0; i < NUM_SAMPLES; i++) {
        x_offset_history[i] = 0;
        y_offset_history[i] = 0;
        z_offset_history[i] = 0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        magnetometer_data_t raw_data = read_magnetometer_data();

        // Update running average filter
        x_offset_history[offset_index] = raw_data.x;
        y_offset_history[offset_index] = raw_data.y;
        z_offset_history[offset_index] = raw_data.z;
        offset_index = (offset_index + 1) % NUM_SAMPLES;

        // Calculate average offsets
        int16_t x_offset = 0;
        int16_t y_offset = 0;
        int16_t z_offset = 0;
        for (int i = 0; i < NUM_SAMPLES; i++) {
            x_offset += x_offset_history[i];
            y_offset += y_offset_history[i];
            z_offset += z_offset_history[i];
        }
        x_offset /= NUM_SAMPLES;
        y_offset /= NUM_SAMPLES;
        z_offset /= NUM_SAMPLES;

        // Apply hard-iron offset
        apply_hard_iron_offset(&raw_data, x_offset, y_offset, z_offset);

        // Print data
        print_data(raw_data);

        // Delay
        gpioDelay(500000); // 500 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

