#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define INT1_CFG 0x30

// Interrupt threshold (2000 mg = 32 LSBs)
#define INT_THRESHOLD 32

// Interrupt duration (0 = immediate)
#define INT_DURATION 0

// Circular buffer size
#define BUFFER_SIZE 64

// GPIO pin for interrupt
#define INT_PIN 23

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
int16_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_lsm303d();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void dump_buffer();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to initialize the LSM303D
int init_lsm303d() {
    // Verify device ID
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x0F, buf, 2) != 2) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (buf[0] != 0x33) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", buf[0]);
        return -1;
    }

    // Configure CTRL_REG1_A (Enable accelerometer, 100Hz data rate)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // Configure CTRL_REG4_A (Full scale +/- 2g)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    // Configure INT1_CFG (INT1 active high, level mode, 2000 mg threshold)
    if (i2cWriteByteData(i2c_handle, INT1_CFG, INT_THRESHOLD << 4 | INT_DURATION) != 0) {
        fprintf(stderr, "Error writing to INT1_CFG\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to dump the circular buffer
void dump_buffer() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%d ", buffer[index]);
    }
    printf("\n");
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        dump_buffer();
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioSetISRFuncEx(INT_PIN, RISING_EDGE, 0, interrupt_handler, NULL); // Disable interrupt
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() != 0) {
        fprintf(stderr, "LSM303D initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for interrupt pin
    gpioSetMode(INT_PIN, PI_INPUT);
    gpioSetPullUpDown(INT_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler
    if (gpioSetISRFuncEx(INT_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            buffer[buffer_index] = x;
            buffer[buffer_index] = y;
            buffer[buffer_index] = z;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }
        gpioDelay(10); // 10ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

