#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_GPIO);
        gpioTerminate();
        return -1;
    }

    // Initialize solenoids to OFF state
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);

    return 0;
}

// Function to alternate solenoid activation
void alternate_solenoid_activation() {
    // Activate solenoid 1
    gpioWrite(SOLENOID_1_GPIO, 1);
    gpioWrite(SOLENOID_2_GPIO, 0);
    nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500ms

    // Deactivate solenoid 1 and activate solenoid 2
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 1);
    nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500ms
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Solenoid control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        alternate_solenoid_activation();
    }

    // Cleanup and exit
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

