#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART device paths
#define UART1_DEVICE "/dev/serial0"
#define UART2_DEVICE "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout in seconds
#define TIMEOUT 5

// Define expected code
#define EXPECTED_CODE "123456"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart1_fd = -1;
int uart2_fd = -1;

// Function prototypes
int initialize_uart(const char *device, int *fd);
int read_code(int fd, char *buffer, size_t buffer_size);
int validate_code(const char *code);
void activate_locks(int gpio1, int gpio2);
void deactivate_locks(int gpio1, int gpio2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
    deactivate_locks(LOCK1_GPIO, LOCK2_GPIO);
    if (uart1_fd != -1) {
        close(uart1_fd);
    }
    if (uart2_fd != -1) {
        close(uart2_fd);
    }
    gpioTerminate();
    exit(0);
}

// Initialize UART function
int initialize_uart(const char *device, int *fd) {
    int fd_temp = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd_temp == -1) {
        fprintf(stderr, "Error opening UART %s: %m\n", device);
        return -1;
    }

    struct termios tty;
