#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLL_INTERVAL_MS 50
#define RELAY_ON_DURATION_S 1
#define FAILSAFE_TIMEOUT_S 10

// Global variables
static volatile int running = 1;
static volatile int motion_detected = 0;
static volatile time_t motion_start_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_relay();
void deactivate_relay();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW); // Ensure relay is initially off

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to activate the relay
void activate_relay() {
    gpioWrite(RELAY_PIN, PI_HIGH);
    log_event("Relay activated");
}

// Function to deactivate the relay
void deactivate_relay() {
    gpioWrite(RELAY_PIN, PI_LOW);
    log_event("Relay deactivated");
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    deactivate_relay();
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
    closelog();
}

int main() {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Motion detector started");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == PI_HIGH) {
            if (!motion_detected) {
                motion_detected = 1;
                motion_start_time = time(NULL);
                log_event("Motion detected");
            } else {
                time_t current_time = time(NULL);
                if (difftime(current_time, motion_start_time) >= FAILSAFE_TIMEOUT_S) {
                    syslog(LOG_WARNING, "Potential malfunction: Motion detected for %d seconds, triggering failsafe", (int)difftime(current_time, motion_start_time));
                    log_event("Failsafe triggered");
                    deactivate_relay();
                    running = 0; // Exit the loop after failsafe
                }
            }
            activate_relay();
            sleep(RELAY_ON_DURATION_S);
            deactivate_relay();
        } else {
            motion_detected = 0;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpio uses microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

