// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the number of relays
#define NUM_RELAYS 4

// Define the duration of each relay activation (in seconds)
#define RELAY_DURATION 300

// Define the pause between relay activations (in seconds)
#define PAUSE_DURATION 60

// Define the timer interval (in seconds)
#define TIMER_INTERVAL 60

// Define the timer ID
#define TIMER_ID 0

// Define the state machine states
typedef enum {
    STATE_INIT,
    STATE_RELAY1,
    STATE_RELAY2,
    STATE_RELAY3,
    STATE_RELAY4,
    STATE_PAUSE,
    STATE_DONE
} state_t;

// Global variables
volatile sig_atomic_t program_running = 1;
state_t current_state = STATE_INIT;

// Function prototypes
void signal_handler(int signal);
void timer_callback(int timer_id);
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void log_message(int priority, const char *message);
void initialize_gpio();
void cleanup_gpio();

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Function to activate a relay (set GPIO pin LOW)
void activate_relay(int relay_pin) {
    gpioWrite(relay_pin, 0); // Set the pin LOW to activate the relay
    char message[100];
    snprintf(message, sizeof(message), "Relay %d activated", relay_pin);
    log_message(LOG_INFO, message);
}

// Function to deactivate a relay (set GPIO pin HIGH)
void deactivate_relay(int relay_pin) {
    gpioWrite(relay_pin, 1); // Set the pin HIGH to deactivate the relay
    char message[100];
    snprintf(message, sizeof(message), "Relay %d deactivated", relay_pin);
    log_message(LOG_INFO, message);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

// Function to initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    log_message(LOG_INFO, "GPIO initialization complete");
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    log_message(LOG_INFO, "Cleaning up GPIO resources...");
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);
    gpioTerminate();
    log_message(LOG_INFO, "GPIO cleanup complete");
}

// Timer callback function
void timer_callback(int timer_id) {
    char message[100];

    switch (current_state) {
        case STATE_RELAY1:
            activate_relay(RELAY1_PIN);
            current_state = STATE_RELAY2;
            snprintf(message, sizeof(message), "Timer fired, activating relay %d", RELAY1_PIN);
            log_message(LOG_INFO, message);
            break;
        case STATE_RELAY2:
            activate_relay(RELAY2_PIN);
            current_state = STATE_RELAY3;
            snprintf(message, sizeof(message), "Timer fired, activating relay %d", RELAY2_PIN);
            log_message(LOG_INFO, message);
            break;
        case STATE_RELAY3:
            activate_relay(RELAY3_PIN);
            current_state = STATE_RELAY4;
            snprintf(message, sizeof(message), "Timer fired, activating relay %d", RELAY3_PIN);
            log_message(LOG_INFO, message);
            break;
        case STATE_RELAY4:
            activate_relay(RELAY4_PIN);
            current_state = STATE_PAUSE;
            snprintf(message, sizeof(message), "Timer fired, activating relay %d", RELAY4_PIN);
            log_message(LOG_INFO, message);
            break;
        case STATE_PAUSE:
            deactivate_relay(RELAY4_PIN);
            current_state = STATE_INIT;
            snprintf(message, sizeof(message), "Timer fired, pausing");
            log_message(LOG_INFO, message);
            break;
        case STATE_DONE:
            log_message(LOG_INFO, "Irrigation cycle complete");
            break;
        default:
            log_message(LOG_WARNING, "Invalid state in timer callback");
            break;
    }

    // Schedule the next timer event
    if (current_state != STATE_DONE) {
        gpioSetTimerFuncEx(TIMER_ID, TIMER_INTERVAL, timer_callback, NULL);
    } else {
        gpioSetTimerFuncEx(TIMER_ID, 0, NULL, NULL); // Disable timer
    }
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Set up the timer callback function
    gpioSetTimerFuncEx(TIMER_ID, TIMER_INTERVAL, timer_callback, NULL);

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup and exit
    cleanup_gpio();
    log_message(LOG_INFO, "Program terminated");
    return 0;
}

