#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/file.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

// Global variables
int i2c_fd;
int buffer_index = 0;
accel_data_t circular_buffer[BUFFER_SIZE];
int running = 1;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void store_data(int16_t x, int16_t y, int16_t z);
accel_data_t get_latest_data();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050
    if (i2cWriteByteData(i2c_fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Set accelerometer range to +/- 2g
    if (i2cWriteByteData(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        perror("Error writing to ACCEL_CONFIG");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_fd, ACCEL_XOUT_H, buf, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to store data in circular buffer
void store_data(int16_t x, int16_t y, int16_t z) {
    circular_buffer[buffer_index].x = x;
    circular_buffer[buffer_index].y = y;
    circular_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get the latest data from the circular buffer
accel_data_t get_latest_data() {
    int index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return circular_buffer[index];
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;
    struct timeval tv;
    char timestamp[30];
    int fd;

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Store data in circular buffer
            store_data(x, y, z);

            // Get the latest data
            accel_data_t latest_data = get_latest_data();

            // Get current timestamp
            gettimeofday(&tv, NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
            snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", tv.tv_usec);

            // Write data to file
            fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY | O_CREAT, 0644);
            if (fd != -1) {
                if (flock(fd, LOCK_EX) == 0) {
                    dprintf(fd, "%s,%d,%d,%d\n", timestamp, latest_data.x, latest_data.y, latest_data.z);
                    flock(fd, LOCK_UN);
                } else {
                    perror("Error acquiring lock");
                }
                close(fd);
            } else {
                perror("Error opening file");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }

        // Delay to achieve 100 Hz sampling rate
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup resources
    cleanup();

    return 0;
}

