#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime intervals in seconds
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variables for intervals
int interval1 = INTERVAL1;
int interval2 = INTERVAL2;
int interval3 = INTERVAL3;
int interval4 = INTERVAL4;

// Function prototypes
void toggleRelay(int gpioPin);
void signalHandler(int signal);
void setRelayInterval(int relayNumber, int newInterval);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off all relays
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

// Function to toggle a relay
void toggleRelay(int gpioPin) {
    int currentLevel = gpioRead(gpioPin);
    gpioWrite(gpioPin, !currentLevel);
}

// Function to set a relay's interval
void setRelayInterval(int relayNumber, int newInterval) {
    switch (relayNumber) {
        case 1:
            interval1 = newInterval;
            break;
        case 2:
            interval2 = newInterval;
            break;
        case 3:
            interval3 = newInterval;
            break;
        case 4:
            interval4 = newInterval;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay number: %d\n", relayNumber);
            return;
    }
    printf("Relay %d interval set to %d seconds\n", relayNumber, newInterval);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize relays to OFF state
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // Toggle relays with specified intervals
        toggleRelay(RELAY1_PIN);
        gpioDelay(interval1 * 1000000); // Convert seconds to microseconds

        toggleRelay(RELAY2_PIN);
        gpioDelay(interval2 * 1000000);

        toggleRelay(RELAY3_PIN);
        gpioDelay(interval3 * 1000000);

        toggleRelay(RELAY4_PIN);
        gpioDelay(interval4 * 1000000);
    }

    return 0;
}

