#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time (in seconds)
#define DEBOUNCE_TIME 0.5

// Global variables
static volatile int relay_active = 0; // Flag to indicate if the relay is active
static volatile unsigned long last_activation_time = 0; // Timestamp of the last activation
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
