#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Structure to hold gyroscope data and timestamp
typedef struct {
    gyro_data_t data;
    uint32_t timestamp;
} gyro_sample_t;

// Circular buffer structure
typedef struct {
    gyro_sample_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
gyro_data_t read_gyro_data();
float calculate_angular_velocity(gyro_data_t data);
void add_sample(circular_buffer_t *buffer, gyro_sample_t sample);
int check_threshold(float angular_velocity);
void callback_function();
void signal_handler(int signal);
void cleanup();

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Configure gyroscope range to +/- 250 degrees/second
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    char buf[6];
    gyro_data_t data;

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        data.x = 0; // Set to 0 to avoid garbage values
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buf[0] << 8) | buf[1]);
    data.y = (int16_t)((buf[2] << 8) | buf[3]);
    data.z = (int16_t)((buf[4] << 8) | buf[5]);

    return data;
}

// Function to calculate angular velocity
float calculate_angular_velocity(gyro_data_t data) {
    // Convert raw data to degrees/second (assuming +/- 250 degrees/second range)
    float x = (float)data.x / 131.0;
    float y = (float)data.y / 131.0;
    float z = (float)data.z / 131.0;

    // Calculate magnitude
    float magnitude = sqrt(x * x + y * y + z * z);

    return magnitude;
}

// Function to add a sample to the circular buffer
void add_sample(circular_buffer_t *buffer, gyro_sample_t sample) {
    buffer->buffer[buffer->head] = sample;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Function to check if the angular velocity exceeds the threshold
int check_threshold(float angular_velocity) {
    return (fabs(angular_velocity) > 50.0) ? 1 : 0;
}

// Callback function
void callback_function() {
    printf("Threshold exceeded!\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data();

        // Calculate angular velocity
        float angular_velocity = calculate_angular_velocity(gyro_data);

        // Get timestamp
        uint32_t timestamp = gpioTick();

        // Create sample
        gyro_sample_t sample = {gyro_data, timestamp};

        // Add sample to circular buffer
        add_sample(&gyro_buffer, sample);

        // Check threshold
        if (check_threshold(angular_velocity)) {
            callback_function();
        }

        // Delay
        gpioDelay(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

