    if (serWrite(uart_handle, command, sizeof(command)) != sizeof(command)) {
        log_error("Failed to send command");
        return -1;
    }

    // Wait for a short period
    gpioDelay(100); // 100 ms

    // Read the response
    bytes_read = serRead(uart_handle, response, sizeof(response));
    if (bytes_read != sizeof(response)) {
        log_error("Failed to read response");
        return -1;
    }

    // Calculate checksum
    checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = 0xFF - checksum + 1;

    // Verify checksum
    if (checksum != response[8]) {
        log_error("Checksum mismatch");
        return -1;
    }

    // Extract CO2 value
    *co2_ppm = (response[2] << 8) | response[3];

    return 0;
}

// Function to log data to a file
void log_data(FILE *log_file, int co2_ppm, int error_flag) {
    char *timestamp = get_timestamp();
    fprintf(log_file, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %d}\n", timestamp, co2_ppm, error_flag);
    fflush(log_file);
    printf("{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": %d}\n", timestamp, co2_ppm, error_flag);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int co2_ppm, error_flag;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open UART
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        log_error("Failed to open UART");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        retries = 0;
        error_flag = 0;
        while (retries < MAX_RETRIES) {
            if (read_co2(uart_handle, &co2_ppm) == 0) {
                log_data(log_file, co2_ppm, error_flag);
                break; // Exit retry loop on success
            } else {
                error_flag = 1; // Set error flag for logging
                retries++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            log_error("Max retries reached");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    serClose(uart_handle);
    fclose(log_file);
    fclose(error_log_file);
    gpioTerminate();
    return 0;
}

