#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_REG_A 0x00
#define CONFIG_REG_B 0x01
#define MODE_REG 0x02
#define DATA_X_MSB 0x03
#define DATA_X_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define DATA_Y_MSB 0x07
#define DATA_Y_LSB 0x08
#define GPIO_PIN 17
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0

// Global variables
int i2c_handle;
double x_offset = 100.0;
double y_offset = -50.0;
double heading_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_hmc5883l();
double read_heading();
double apply_hard_iron_compensation(double x, double y);
double calculate_deviation(double heading);
void update_gpio(double deviation);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int hmc5883l_address;
    int gpio_pin;
    double x_offset;
    double y_offset;
    double target_heading;
    double deviation_threshold;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Set configuration register A (8 samples averaged, 15 Hz data output rate)
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Set configuration register B (Gain = 1.3 Ga)
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set mode register (Continuous measurement mode)
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read heading from HMC5883L
double read_heading() {
    char data[6];
    int16_t x, y, z;

    if (i2cReadI2CBlockData(i2c_handle, DATA_X_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return NAN; // Not a Number
    }

    x = (int16_t)((data[0] << 8) | data[1]);
    z = (int16_t)((data[2] << 8) | data[3]);
    y = (int16_t)((data[4] << 8) | data[5]);

    return atan2(y, x) * 180 / M_PI;
}

// Apply hard-iron compensation
double apply_hard_iron_compensation(double x, double y) {
    return atan2(y - y_offset, x - x_offset) * 180 / M_PI;
}

// Calculate deviation from target heading
double calculate_deviation(double heading) {
    double deviation = fmod(heading - TARGET_HEADING + 180, 360) - 180;
    return fabs(deviation);
}

// Update GPIO pin based on deviation
void update_gpio(double deviation) {
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    gpioWrite(GPIO_PIN, 0); // Set GPIO low
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C and HMC5883L
    if (init_i2c() < 0 || init_hmc5883l() < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        double heading = read_heading();
        if (!isnan(heading)) {
            double compensated_heading = apply_hard_iron_compensation(heading, heading); // Using heading twice as it's the same
            heading_buffer[buffer_index] = compensated_heading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            double deviation = calculate_deviation(compensated_heading);
            update_gpio(deviation);

            printf("Heading: %.2f, Compensated Heading: %.2f, Deviation: %.2f\n", heading, compensated_heading, deviation);
        } else {
            fprintf(stderr, "Error reading heading, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

