#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LUX_THRESHOLD_1 50
#define LUX_THRESHOLD_2 150
#define LUX_THRESHOLD_3 300
#define LOG_FILE "lighting_log.txt"
#define SLEEP_DURATION_SEC 1

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(int fd, float *lux);
void control_relays(float lux);
int log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read data from BH1750 sensor
int read_bh1750(int fd, float *lux) {
    unsigned char data[2];
    int result;

    // Send start measurement command (High Resolution Mode)
    result = write(fd, "\x10", 1);
    if (result != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 120ms)
    gpioDelay(120000); // 120ms

    // Read 2 bytes of data
    result = read(fd, data, 2);
    if (result != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert data to lux value
    unsigned int raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relays based on lux value
void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_THRESHOLD_1) {
        red_state = 1;
    } else if (lux < LUX_THRESHOLD_2) {
        green_state = 1;
    } else if (lux < LUX_THRESHOLD_3) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpioWrite(RED_GPIO, red_state);
    gpioWrite(GREEN_GPIO, green_state);
    gpioWrite(BLUE_GPIO, blue_state);
}

// Log data to file
int log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off relays
    gpioWrite(RED_GPIO, 0);
    gpioWrite(GREEN_GPIO, 0);
    gpioWrite(BLUE_GPIO, 0);

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int red_state, green_state, blue_state;

    printf("Starting lighting control program...\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(i2c_fd, &lux) == 0) {
            // Control relays
            control_relays(lux);

            // Get relay states
            red_state = gpioRead(RED_GPIO);
            green_state = gpioRead(GREEN_GPIO);
            blue_state = gpioRead(BLUE_GPIO);

            // Log data
            if (log_data(lux, red_state, green_state, blue_state) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        // Sleep for 1 second
        sleep(SLEEP_DURATION_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

