    terminate = 1;
    printf("\nCaught signal, stopping motors and exiting...\n");
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle)
{
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to set the motor direction and speed
int set_motor_direction(int motor, int direction, int distance)
{
    int duty_cycle;

    if (distance < 50) {
        // Forward
        if (direction == 1) {
            gpioWrite(MOTOR_A_IN1, 1);
            gpioWrite(MOTOR_A_IN2, 0);
            gpioWrite(MOTOR_B_IN3, 1);
            gpioWrite(MOTOR_B_IN4, 0);
        } else {
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_A_IN2, 1);
            gpioWrite(MOTOR_B_IN3, 0);
            gpioWrite(MOTOR_B_IN4, 1);
        }

        duty_cycle = (int)(KP * (50 - distance));
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;

