        return 1;
    }

    // Parse distance arguments
    distance_a = atoi(argv[1]);
    distance_b = atoi(argv[2]);

    // Validate distance values
    if (distance_a < MIN_DISTANCE || distance_a > MAX_DISTANCE ||
        distance_b < MIN_DISTANCE || distance_b > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance values must be between %d and %d cm\n", MIN_DISTANCE, MAX_DISTANCE);
        return 1;
    }

