#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for L293D IN1-IN4 connections
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22

// Define GPIO pins for buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define motor parameters
#define STEPS_PER_REVOLUTION 512
#define STEP_DELAY 2 // milliseconds

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void lock_door();
void unlock_door();
void handle_button_press(int button_pin);
void signal_handler(int signal);
void cleanup();

// Function to set the state of the L293D IN1-IN4 pins
void set_step(int step) {
    switch (step) {
        case 0:
            gpioWrite(IN1, 1);
            gpioWrite(IN2, 0);
            gpioWrite(IN3, 0);
            gpioWrite(IN4, 0);
            break;
        case 1:
            gpioWrite(IN1, 0);
            gpioWrite(IN2, 1);
            gpioWrite(IN3, 0);
            gpioWrite(IN4, 0);
            break;
        case 2:
            gpioWrite(IN1, 0);
            gpioWrite(IN2, 0);
            gpioWrite(IN3, 1);
            gpioWrite(IN4, 0);
            break;
        case 3:
            gpioWrite(IN1, 0);
            gpioWrite(IN2, 0);
            gpioWrite(IN3, 0);
            gpioWrite(IN4, 1);
            break;
        default:
            fprintf(stderr, "Invalid step number: %d\n", step);
            break;
    }
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    for (int i = 0; i < STEPS_PER_REVOLUTION; i++) {
        set_step(i % 4);
        gpioDelay(STEP_DELAY * 1000); // Convert milliseconds to microseconds
    }
    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    for (int i = 0; i < STEPS_PER_REVOLUTION; i++) {
        set_step(3 - (i % 4)); // Reverse the step sequence
        gpioDelay(STEP_DELAY * 1000); // Convert milliseconds to microseconds
    }
    printf("Door unlocked.\n");
}

// Function to handle button press
void handle_button_press(int button_pin) {
    if (button_pin == LOCK_BUTTON) {
        lock_door();
    } else if (button_pin == UNLOCK_BUTTON) {
        unlock_door();
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
    cleanup();
    exit(0);
}

// Cleanup function to de-energize the motor and terminate pigpio
void cleanup() {
    // De-energize the motor by setting all IN pins LOW
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);

    // Enable pull-up resistors on the button pins
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for button presses
        if (gpioRead(LOCK_BUTTON) == 0) {
            handle_button_press(LOCK_BUTTON);
            gpioDelay(200000); // Debounce delay (200ms)
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            handle_button_press(UNLOCK_BUTTON);
            gpioDelay(200000); // Debounce delay (200ms)
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    return 0;
}

