#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_RANGE 2000
#define PWM_FREQUENCY 50
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int pin, int angle);
int log_data(FILE *fp, float pitch, float roll, int angle);
void signal_handler(int sig);

// I2C initialization function with exponential backoff
int init_i2c(int bus, int addr) {
    int fd, retries = 0;
    int delay_ms = 10;

    while (retries < 10) {
        fd = open("/dev/i2c-" + bus, O_RDWR);
        if (fd < 0) {
            fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            close(fd);
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        return fd;
    }

    fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
    return -1;
}

// MPU6050 data reading function
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    int retries = 0;
    int delay_ms = 10;

    while (retries < 5) {
        if (read(fd, buffer, 14) == 14) {
            *accel_x = (buffer[0] << 8) | buffer[1];
            *accel_y = (buffer[2] << 8) | buffer[3];
            *accel_z = (buffer[4] << 8) | buffer[5];
            *gyro_x = (buffer[8] << 8) | buffer[9];
            *gyro_y = (buffer[10] << 8) | buffer[11];
            *gyro_z = (buffer[12] << 8) | buffer[13];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading MPU6050 data: %s\n", strerror(errno));
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "Failed to read MPU6050 data after multiple retries.\n");
    return -1; // Failure
}

// MPU6050 data processing function
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll) {
    float accel_x_g = (float)accel_x / 16384.0f; // Assuming sensitivity of +/- 2g
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    *pitch = atan2(accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;
    *roll = atan2(accel_y_g, sqrt(accel_x_g * accel_x_g + accel_z_g * accel_z_g)) * 180 / M_PI;
}

// Servo motor control function
int set_servo_angle(int pin, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    int pulse_width = (int)((angle / 180.0) * PWM_RANGE + 1); // Map angle (0-180) to pulse width (1-2000)
    gpioPWM(pin, pulse_width);
    return 0;
