int set_servo_angle(int pin, int angle);
int log_data(FILE *fp, float pitch, float roll, int angle);
void signal_handler(int sig);

// I2C initialization function with exponential backoff
int init_i2c(int bus, int addr) {
    int fd, retries = 0;
    int delay_ms = 10;

    while (retries < 10) {
        fd = open("/dev/i2c-" + bus, O_RDWR);
        if (fd < 0) {
            fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            close(fd);
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        return fd;
    }

    fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
    return -1;
}

// MPU6050 data reading function
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    int retries = 0;
    int delay_ms = 10;

    while (retries < 5) {
        if (read(fd, buffer, 14) == 14) {
            *accel_x = (buffer[0] << 8) | buffer[1];
            *accel_y = (buffer[2] << 8) | buffer[3];
            *accel_z = (buffer[4] << 8) | buffer[5];
            *gyro_x = (buffer[8] << 8) | buffer[9];
            *gyro_y = (buffer[10] << 8) | buffer[11];
            *gyro_z = (buffer[12] << 8) | buffer[13];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading MPU6050 data: %s\n", strerror(errno));
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
        }
