#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 1800

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Global variables
FILE *schedule_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_schedule(const char *filename, int *schedule);
int set_relay_state(int gpio, int state);
int fade_brightness(int gpio, int start_duty, int end_duty, int duration);
int get_current_time(int *hour, int *minute, int *second);
int apply_schedule(int current_hour, int current_minute, int current_second, int *schedule);
void signal_handler(int signal);

// Structure to hold relay states
typedef struct {
    int relay1_state;
    int relay2_state;
    int relay3_state;
    int relay4_state;
} RelayStates;

RelayStates current_relay_states = {0, 0, 0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    return 0;
}

// Function to read the lighting schedule from a file
int read_schedule(const char *filename, int *schedule) {
    schedule_file = fopen(filename, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), schedule_file) != NULL) {
        // Parse the line
        char *token = strtok(line, ",");
        if (token == NULL) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            fclose(schedule_file);
            return 1;
        }

        int hour = atoi(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            fclose(schedule_file);
            return 1;
        }

        int minute = atoi(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            fclose(schedule_file);
            return 1;
        }

        int second = atoi(token);
        token = strtok(NULL, ";");
        if (token == NULL) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            fclose(schedule_file);
            return 1;
        }

        int relay_number = atoi(token);
        token = strtok(NULL, ";");
        if (token == NULL) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            fclose(schedule_file);
            return 1;
        }

        char *on_off = token;

        // Validate schedule entries
        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59) {
            fprintf(stderr, "Invalid time format in schedule entry: %s", line);
            fclose(schedule_file);
            return 1;
        }

        if (relay_number < 1 || relay_number > 4) {
            fprintf(stderr, "Invalid relay number in schedule entry: %s", line);
            fclose(schedule_file);
            return 1;
        }

        if (strcmp(on_off, "on") != 0 && strcmp(on_off, "off") != 0) {
            fprintf(stderr, "Invalid on/off value in schedule entry: %s", line);
            fclose(schedule_file);
            return 1;
        }

        // Calculate the schedule index
        int schedule_index = hour * 3600 + minute * 60 + second;

        // Set the schedule value
        schedule[schedule_index] = (strcmp(on_off, "on") == 0) ? 1 : 0;
    }

    fclose(schedule_file);
    return 0;
}

// Function to set the state of a relay
int set_relay_state(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Function to fade the brightness of a relay
int fade_brightness(int gpio, int start_duty, int end_duty, int duration) {
    int steps = duration * 10; // 10 Hz
    int increment = (end_duty - start_duty) / steps;
    int current_duty = start_duty;

    for (int i = 0; i < steps; i++) {
        gpioPWM(gpio, current_duty);
        current_duty += increment;
        if (current_duty > end_duty) {
            current_duty = end_duty;
        }
        gpioDelay(10000); // 10 ms delay (10 Hz)
    }
    gpioPWM(gpio, end_duty); // Ensure final duty cycle is set
    return 0;
}

// Function to get the current time
int get_current_time(int *hour, int *minute, int *second) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    *hour = timeinfo->tm_hour;
    *minute = timeinfo->tm_min;
    *second = timeinfo->tm_sec;

    return 0;
}

// Function to apply the schedule
int apply_schedule(int current_hour, int current_minute, int current_second, int *schedule) {
    int schedule_index = current_hour * 3600 + current_minute * 60 + current_second;

    // Check if the current time matches the schedule
    if (schedule[schedule_index] == 1) {
        // Turn on the relay
        set_relay_state(RELAY1_GPIO, 1); // Example: Turn on relay 1
        set_relay_state(RELAY2_GPIO, 1); // Example: Turn on relay 2
        set_relay_state(RELAY3_GPIO, 1); // Example: Turn on relay 3
        set_relay_state(RELAY4_GPIO, 1); // Example: Turn on relay 4
        current_relay_states.relay1_state = 1;
        current_relay_states.relay2_state = 1;
        current_relay_states.relay3_state = 1;
        current_relay_states.relay4_state = 1;
    } else {
        // Turn off the relay
        set_relay_state(RELAY1_GPIO, 0); // Example: Turn off relay 1
        set_relay_state(RELAY2_GPIO, 0); // Example: Turn off relay 2
        set_relay_state(RELAY3_GPIO, 0); // Example: Turn off relay 3
        set_relay_state(RELAY4_GPIO, 0); // Example: Turn off relay 4
        current_relay_states.relay1_state = 0;
        current_relay_states.relay2_state = 0;
        current_relay_states.relay3_state = 0;
        current_relay_states.relay4_state = 0;
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off all relays
    set_relay_state(RELAY1_GPIO, 0);
    set_relay_state(RELAY2_GPIO, 0);
    set_relay_state(RELAY3_GPIO, 0);
    set_relay_state(RELAY4_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Allocate memory for the schedule
    int *schedule = (int *)malloc(86400 * sizeof(int)); // 24 hours * 60 minutes * 60 seconds
    if (schedule == NULL) {
        perror("Failed to allocate memory for schedule");
        gpioTerminate();
        return 1;
    }

    // Read the schedule from the file
    if (read_schedule(SCHEDULE_FILE, schedule) != 0) {
        free(schedule);
        gpioTerminate();
        return 1;
    }

    int current_hour, current_minute, current_second;
    int last_hour, last_minute, last_second;

    // Main loop
    while (running) {
        // Get the current time
        get_current_time(&current_hour, &current_minute, &current_second);

        // Apply the schedule
        apply_schedule(current_hour, current_minute, current_second, schedule);

        // Check if the time has changed
        if (current_hour != last_hour || current_minute != last_minute || current_second != last_second) {
            // Update last time
            last_hour = current_hour;
            last_minute = current_minute;
            last_second = current_second;
        }

        // Sleep for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Free allocated memory
    free(schedule);

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

