        current_relay_states.relay1_state = 1;
        current_relay_states.relay2_state = 1;
        current_relay_states.relay3_state = 1;
        current_relay_states.relay4_state = 1;
    } else {
        // Turn off the relay
        set_relay_state(RELAY1_GPIO, 0); // Example: Turn off relay 1
        set_relay_state(RELAY2_GPIO, 0); // Example: Turn off relay 2
        set_relay_state(RELAY3_GPIO, 0); // Example: Turn off relay 3
        set_relay_state(RELAY4_GPIO, 0); // Example: Turn off relay 4
        current_relay_states.relay1_state = 0;
        current_relay_states.relay2_state = 0;
        current_relay_states.relay3_state = 0;
        current_relay_states.relay4_state = 0;
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off all relays
    set_relay_state(RELAY1_GPIO, 0);
    set_relay_state(RELAY2_GPIO, 0);
    set_relay_state(RELAY3_GPIO, 0);
    set_relay_state(RELAY4_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Allocate memory for the schedule
    int *schedule = (int *)malloc(86400 * sizeof(int)); // 24 hours * 60 minutes * 60 seconds
    if (schedule == NULL) {
        perror("Failed to allocate memory for schedule");
        gpioTerminate();
        return 1;
    }

    // Read the schedule from the file
    if (read_schedule(SCHEDULE_FILE, schedule) != 0) {
        free(schedule);
        gpioTerminate();
        return 1;
    }

    int current_hour, current_minute, current_second;
    int last_hour, last_minute, last_second;

    // Main loop
    while (running) {
        // Get the current time
        get_current_time(&current_hour, &current_minute, &current_second);

        // Apply the schedule
        apply_schedule(current_hour, current_minute, current_second, schedule);

        // Check if the time has changed
        if (current_hour != last_hour || current_minute != last_minute || current_second != last_second) {
            // Update last time
            last_hour = current_hour;
            last_minute = current_minute;
            last_second = current_second;
        }

        // Sleep for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Free allocated memory
    free(schedule);

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

