#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout for echo pulse in microseconds
#define MIN_DISTANCE 2.0       // Minimum distance in cm
#define MAX_DISTANCE 200.0      // Maximum distance in cm
#define MIN_FREQUENCY 200.0     // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0    // Maximum frequency in Hz
#define LOOP_DELAY_MS 20        // Loop delay in milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long getPulseWidth();
double calculateDistance(long pulseWidth);
double mapDistanceToFrequency(double distance);
void setBuzzerFrequency(double frequency);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth() {
    long startTime = 0, endTime = 0;
    int timeout = 0;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo high.\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for echo to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1);
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo low.\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate distance from pulse width
double calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (double)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to frequency
double mapDistanceToFrequency(double distance) {
    if (distance < MIN_DISTANCE) {
        return MAX_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MIN_FREQUENCY;
    } else {
        return MAX_FREQUENCY - (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency
void setBuzzerFrequency(double frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: Frequency out of range. Clamping to valid range.\n");
        if (frequency < MIN_FREQUENCY) {
            frequency = MIN_FREQUENCY;
        } else {
            frequency = MAX_FREQUENCY;
        }
    }

    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop the buzzer
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 255);
    gpioSetPWMfrequency(BUZZER_PIN, 440); // Initial frequency

    // Register signal handler
    signal(SIGINT, signalHandler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseWidth = getPulseWidth();
        if (pulseWidth > 0) {
            double distance = calculateDistance(pulseWidth);
            if (distance > 0) {
                double frequency = mapDistanceToFrequency(distance);
                setBuzzerFrequency(frequency);
            } else {
                fprintf(stderr, "Error: Invalid distance reading.\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid pulse width reading.\n");
        }

        gpioDelay(LOOP_DELAY_MS * 1000); // Delay for 20ms (50Hz)
    }

    return 0;
}

