// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the color of the RGB LED using PWM
void set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, red) != 0) {
        fprintf(stderr, "Error setting red PWM\n");
    }
    if (gpioPWM(GREEN_PIN, green) != 0) {
        fprintf(stderr, "Error setting green PWM\n");
    }
    if (gpioPWM(BLUE_PIN, blue) != 0) {
        fprintf(stderr, "Error setting blue PWM\n");
    }
}

// Function to calculate the PWM duty cycle based on proximity value
void calculate_color(float proximity, int *red, int *green, int *blue) {
    // Sine wave function for proximity simulation
    float sine_value = sin(proximity * M_PI);

    // Map sine wave value to PWM duty cycle (0-255)
    *red   = (int)(128.0 + 127.0 * sine_value);   // Red
    *green = (int)(128.0 - 127.0 * sine_value);   // Green
    *blue  = (int)(128.0 + 127.0 * sine_value);   // Blue
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting RED_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GREEN_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting BLUE_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for RED_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    float proximity = 0.0;
    int red, green, blue;
    while (program_running) {
        // Calculate color based on proximity value
        calculate_color(proximity, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Increment proximity value (0.0 to 1.0)
        proximity += 0.001; // Increment by 0.001 to reach 1.0 in approximately 10 seconds
        if (proximity > 1.0) {
            proximity = 0.0;
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Turn off LED before exiting
    set_led_color(0, 0, 0);

    // Release pigpio resources
    gpioTerminate();

    return 0;
}

