#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 440 // Example frequency (A4)
#define PWM_DUTY_CYCLE 500000 // 50% duty cycle (half of 1000000)

// Define melody lookup table (frequencies in Hz)
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int melody_playing = 0;
volatile int button_pressed = 0;
volatile int button_released = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Function to play a tone on the buzzer
void play_tone(int frequency) {
    if (frequency > 0) {
        gpioPWM(BUZZER_PIN, PWM_DUTY_CYCLE);
        gpioSetPWMfrequency(BUZZER_PIN, frequency);
    } else {
        gpioPWM(BUZZER_PIN, 0); // Turn off the buzzer
    }
}

// Interrupt service routine for the button
void button_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) { // Button pressed (active low)
        if (current_tick - last_tick > 50000) { // Debounce
            button_pressed = 1;
            last_tick = current_tick;
        }
    } else { // Button released
        button_released = 1;
    }
}

// Function to play the melody
void play_melody() {
    if (!melody_playing) {
        melody_playing = 1;
        for (int i = 0; i < melody_length; i++) {
            play_tone(melody[i]);
            gpioDelay(200000); // 200ms delay
            if (!melody_playing) break; // Stop if button is pressed again
        }
        stop_melody();
    }
}

// Function to stop the melody
void stop_melody() {
    melody_playing = 0;
    play_tone(0); // Turn off the buzzer
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQUENCY);

    // Set PWM range (optional, but good practice)
    gpioSetPWMrange(BUZZER_PIN, 1000000); // Set range to 1MHz

    // Set PWM duty cycle (initial value)
    gpioPWM(BUZZER_PIN, 0); // Initially off

    // Set interrupt service routine for the button
    gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, 0, button_isr, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            play_melody();
            button_pressed = 0;
        }
        if (button_released) {
            button_released = 0;
        }
        gpioDelay(10000); // 10ms delay
    }

    return 0;
}

