#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define ALERT_THRESHOLD 3

// Global variables
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;

// Structure to hold the sliding window
typedef struct {
    int window[WINDOW_SIZE];
    int head;
    int count;
} SlidingWindow;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_window(SlidingWindow *window, int value);
int check_threshold(const SlidingWindow *window);
void log_event(int value);
void print_alert();
void signal_handler(int signal);
void cleanup();

// Initialize the sliding window
void init_sliding_window(SlidingWindow *window) {
    window->head = 0;
    window->count = 0;
    memset(window->window, 0, sizeof(window->window));
}

int main(int argc, char *argv[]) {
    int timeout_ms = 1000; // Default timeout
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                timeout_ms = atoi(optarg);
                if (timeout_ms <= 0) {
                    fprintf(stderr, "Error: Invalid timeout value. Using default (1000ms).\n");
                    timeout_ms = 1000;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t timeout_ms]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    // Initialize sliding window
    SlidingWindow window;
    init_sliding_window(&window);

    // Open log file
    log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        if (sensor_value != -1) {
            add_to_window(&window, sensor_value);
            if (check_threshold(&window)) {
                print_alert();
            }
            log_event(sensor_value);
        }
        gpioDelay(timeout_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Read sensor value with debouncing
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    gpioDelay(5000); // Debounce delay (5ms)
    return value;
}

// Add a value to the sliding window
void add_to_window(SlidingWindow *window, int value) {
    window->window[window->head] = value;
    window->head = (window->head + 1) % WINDOW_SIZE;
    if (window->count < WINDOW_SIZE) {
        window->count++;
    }
}

// Check if the threshold is exceeded
int check_threshold(const SlidingWindow *window) {
    int high_count = 0;
    for (int i = 0; i < window->count; i++) {
        if (window->window[i] == 1) {
            high_count++;
        }
    }
    return high_count >= ALERT_THRESHOLD;
}

// Log event to file
void log_event(int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d\n", timestamp, value);
        fflush(log_file); // Flush the buffer to ensure data is written
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Print earthquake alert
void print_alert() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("EARTHQUAKE ALERT: %s\n", timestamp);
    if (log_file != NULL) {
        fprintf(log_file, "EARTHQUAKE ALERT: %s\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

