#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_CTRL_REG1_M 0x20
#define LSM303_OUT_X_L_M   0x08
#define LSM303_OUT_X_H_M   0x09
#define LSM303_OUT_Y_L_M   0x0A
#define LSM303_OUT_Y_H_M   0x0B
#define LSM303_OUT_Z_L_M   0x0C
#define LSM303_OUT_Z_H_M   0x0D

// Calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass directions
#define NORTH 0
#define NORTHEAST 1
#define EAST 2
#define SOUTHEAST 3
#define SOUTH 4
#define SOUTHWEST 5
#define WEST 6
#define NORTHWEST 7

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z);
float calculate_heading(int16_t calibrated_x, int16_t calibrated_y);
int determine_compass_direction(float heading);
void log_data(int16_t calibrated_x, int16_t calibrated_y, int16_t calibrated_z, float heading, int compass_direction);
void signal_handler(int signal);

// Function to initialize the I2C interface
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Enable the magnetometer (10 Hz data rate, continuous conversion)
    if (i2cWriteByteData(i2c_handle, LSM303_CTRL_REG1_M, 0x70) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_M\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM303_OUT_X_L_M | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calibrate the magnetometer data
void calibrate_data(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z) {
    *calibrated_x = x - X_OFFSET;
    *calibrated_y = y - Y_OFFSET;
    *calibrated_z = z - Z_OFFSET;
}

// Function to calculate the heading
