#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce_touch();
int toggle_relay();
int log_relay_state(int relay_state);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int touch_pin;
    int relay_pin;
    int debounce_ms;
    char *log_file_name;
} Config;

Config config = {TOUCH_SENSOR_PIN, RELAY_PIN, DEBOUNCE_TIME, "relay_log.json"};

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            if (debounce_touch()) {
                if (toggle_relay() == 0) {
                    log_relay_state(relay_state);
                } else {
                    fprintf(stderr, "Failed to toggle relay.\n");
                }
            }
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

// Initialize pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.touch_pin, PI_INPUT);
    gpioSetPullUpDown(config.touch_pin, PI_PUD_DOWN); // Use pull-down resistor

    gpioSetMode(config.relay_pin, PI_OUTPUT);
    gpioWrite(config.relay_pin, 0); // Initialize relay to OFF state

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(config.touch_pin);
}

// Debounce the touch sensor reading
int debounce_touch() {
    unsigned long current_time = gpioTick();

    if (current_time - last_touch_time > config.debounce_ms * 1000) {
        last_touch_time = current_time;
        return 1; // Valid touch
    } else {
        return 0; // Debounced
    }
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(config.relay_pin, relay_state);
    return 0;
}

// Log the relay state to a file
int log_relay_state(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting.\n");

    // Turn off the relay
    gpioWrite(config.relay_pin, 0);
    log_relay_state(0); // Log the final state

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

