#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void log_event(int relay_number, int moisture_level);
void signal_handler(int signal);

// Structure to hold relay pins
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} RelayPins;

RelayPins relay_pins = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read moisture sensor
        int moisture_level = read_moisture_sensor();

        // Check if moisture level is below threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            // Activate relays sequentially
            activate_relay(relay_pins.relay1);
            log_event(1, moisture_level);
            gpioDelay(5000); // 5 seconds
            deactivate_relay(relay_pins.relay1);

            activate_relay(relay_pins.relay2);
            log_event(2, moisture_level);
            gpioDelay(5000); // 5 seconds
            deactivate_relay(relay_pins.relay2);

            activate_relay(relay_pins.relay3);
            log_event(3, moisture_level);
            gpioDelay(5000); // 5 seconds
            deactivate_relay(relay_pins.relay3);

            activate_relay(relay_pins.relay4);
            log_event(4, moisture_level);
            gpioDelay(5000); // 5 seconds
            deactivate_relay(relay_pins.relay4);
        }

        // Wait for 10 seconds
        gpioDelay(10000);
    }

    // Cleanup
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

// Initialize pigpio and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(relay_pins.relay1, PI_OUTPUT);
    gpioSetMode(relay_pins.relay2, PI_OUTPUT);
    gpioSetMode(relay_pins.relay3, PI_OUTPUT);
    gpioSetMode(relay_pins.relay4, PI_OUTPUT);

    return 0;
}

// Read moisture sensor value (simulated)
int read_moisture_sensor() {
    // Simulate moisture level between 0 and 100
    return rand() % 101;
}

// Activate relay (set GPIO pin low)
void activate_relay(int relay_pin) {
    gpioWrite(relay_pin, 0); // Active-low
}

// Deactivate relay (set GPIO pin high)
void deactivate_relay(int relay_pin) {
    gpioWrite(relay_pin, 1); // Active-low
}

// Log event to file
void log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Deactivate all relays
    deactivate_relay(relay_pins.relay1);
    deactivate_relay(relay_pins.relay2);
    deactivate_relay(relay_pins.relay3);
    deactivate_relay(relay_pins.relay4);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
