#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servo motors
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture levels
#define MOISTURE_LEVEL_1 20
#define MOISTURE_LEVEL_2 40
#define MOISTURE_LEVEL_3 60
#define MOISTURE_LEVEL_4 80
#define MOISTURE_LEVEL_5 100

// Define servo pulse widths for each angle
#define SERVO_ANGLE_0 500
#define SERVO_ANGLE_45 1000
#define SERVO_ANGLE_90 1500
#define SERVO_ANGLE_135 2000
#define SERVO_ANGLE_180 2500

// Define watering cycle parameters
#define WATERING_DURATION 5 // seconds
#define NOZZLE_SWEEP_DURATION 2 // seconds

// Define valve closing parameters
#define VALVE_CLOSE_DURATION 5 // seconds

// Define moisture levels array
int moisture_levels[] = {MOISTURE_LEVEL_1, MOISTURE_LEVEL_2, MOISTURE_LEVEL_3, MOISTURE_LEVEL_4, MOISTURE_LEVEL_5};
int num_moisture_levels = sizeof(moisture_levels) / sizeof(moisture_levels[0]);

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t valve_open = 0;

// Function prototypes
int set_servo_pulse_width(int gpio, int pulse_width);
int read_soil_moisture();
void open_valve();
void close_valve();
void sweep_nozzle();
void water_plant();
void signal_handler(int signal);

// Function to set the pulse width of a servo motor
int set_servo_pulse_width(int gpio, int pulse_width) {
    int result, retries = 0;
    while (retries < 3) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse width for GPIO %d, pulse width %d, error code %d. Retry %d/3\n", gpio, pulse_width, result, retries + 1);
            gpioDelay(100000); // 100ms delay
            retries++;
        }
    }
    fprintf(stderr, "Critical error: Failed to set servo pulse width for GPIO %d, pulse width %d after 3 retries. Exiting.\n", gpio, pulse_width);
    program_running = 0; // Stop the program
    return -1; // Failure
}

// Function to read the simulated soil moisture value
int read_soil_moisture() {
    static int moisture_index = 0;
    moisture_index = (moisture_index + 1) % num_moisture_levels;
    return moisture_levels[moisture_index];
}

// Function to open the valve
void open_valve() {
    if (set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_ANGLE_90) != 0) {
        fprintf(stderr, "Error opening valve. Valve may be stuck.\n");
        program_running = 0; // Stop the program
    } else {
        valve_open = 1; // Mark the valve as open
    }
}

// Function to close the valve
void close_valve() {
    if (set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_ANGLE_0) != 0) {
        fprintf(stderr, "Critical error: Failed to close valve.\n");
        program_running = 0; // Stop the program
    }
}

// Function to sweep the nozzle
void sweep_nozzle() {
    int angles[] = {SERVO_ANGLE_0, SERVO_ANGLE_45, SERVO_ANGLE_90, SERVO_ANGLE_135, SERVO_ANGLE_180};
    int num_angles = sizeof(angles) / sizeof(angles[0]);
    for (int i = 0; i < num_angles; i++) {
        if (set_servo_pulse_width(NOZZLE_SERVO_PIN, angles[i]) != 0) {
            fprintf(stderr, "Error setting nozzle angle %d. Skipping.\n", i);
            return; // Skip to the next angle
        }
        gpioDelay(NOZZLE_SWEEP_DURATION * 1000000); // Delay for the specified duration
    }
}

// Function to water the plant
void water_plant() {
    open_valve();
    if (valve_open) {
        sweep_nozzle();
        gpioDelay(WATERING_DURATION * 1000000); // Hold the spray for the specified duration
        close_valve();
        gpioDelay(VALVE_CLOSE_DURATION * 1000000); // Wait for the valve to close
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Stopping program.\n", signal);
    program_running = 0; // Stop the program
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int moisture = read_soil_moisture();
        printf("Soil moisture: %d%%\n", moisture);

        if (moisture < 50) {
            printf("Watering plant...\n");
            water_plant();
        } else {
            printf("Moisture level sufficient. Skipping watering.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds before the next cycle
    }

    // Cleanup and exit
    printf("Cleaning up and exiting.\n");
    close_valve(); // Ensure valve is closed
    gpioTerminate(); // Terminate pigpio library
    return 0;
}

