    static uint32_t last_tick[2] = {0, 0}; // Store last tick for each button
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick[gpio == LOCK_BUTTON ? 0 : 1] < DEBOUNCE_DELAY * 1000) {
        return; // Ignore the event
    }

    last_tick[gpio == LOCK_BUTTON ? 0 : 1] = current_tick;

    if (gpio == LOCK_BUTTON && level == 0) { // LOCK button pressed
        lock_door();
    } else if (gpio == UNLOCK_BUTTON && level == 0) { // UNLOCK button pressed
        unlock_door();
    }
}

