    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    set_gpio(IN1, 0);
    set_gpio(IN2, 0);
    set_gpio(IN3, 0);
    set_gpio(IN4, 0);
    gpioTerminate();
    exit(0);
}

