    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register callback functions for button presses
    gpioSetAlertFunc(LOCK_BUTTON, button_callback);
    gpioSetAlertFunc(UNLOCK_BUTTON, button_callback);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door control system started. Press LOCK or UNLOCK buttons.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100000); // Sleep for 0.1 seconds
    }

