#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MEASUREMENT_INTERVAL_S 1 // Measurement interval in seconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
double calculateDistance(long pulse_duration);
void logDistance(double distance);
void signalHandler(int signal);
int initializeGPIO();
void cleanupGPIO();

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1ms delay

    return 0;
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse duration
long pulseIn(int pin, int level, int timeout) {
    long start_time = gpioTick();
    long end_time = start_time;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        end_time = gpioTick();
        if (end_time - start_time > timeout) {
            return -1; // Timeout
        }
    }

    start_time = end_time;

    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        end_time = gpioTick();
        if (end_time - start_time > timeout) {
            return -1; // Timeout
        }
    }

    return end_time - start_time;
}

// Function to calculate the distance
double calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Convert us to s
}

// Function to log the distance to a file
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup GPIO resources
void cleanupGPIO() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    fprintf(stderr, "GPIO resources released.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize GPIO
    if (initializeGPIO() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanupGPIO();
        return 1;
    }

    fprintf(stderr, "Distance logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        triggerSensor();
        long pulse_duration = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulse_duration < 0) {
            fprintf(stderr, "Timeout occurred during pulse measurement.\n");
            if (log_file != NULL) {
                fprintf(log_file, "-1\n");
                fflush(log_file);
            }
        } else {
            double distance = calculateDistance(pulse_duration);
            if (distance < 0) {
                fprintf(stderr, "Error calculating distance.\n");
                if (log_file != NULL) {
                    fprintf(log_file, "-1\n");
                    fflush(log_file);
                }
            } else {
                logDistance(distance);
            }
        }

        gpioDelay(60000); // 60ms delay
    }

    // Cleanup and exit
    cleanupGPIO();
    return 0;
}

