#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_GPIO 18
#define DISTANCE_THRESHOLD 50 // cm

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_relay(int distance);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Implement VL53L1X initialization sequence here
    // This is a placeholder - refer to the VL53L1X datasheet for the correct initialization sequence
    // Example: Writing to a register
    char init_data[] = {0x00, 0x01}; // Example initialization data
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X during initialization: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance() {
    // Implement VL53L1X distance reading here
    // This is a placeholder - refer to the VL53L1X datasheet for the correct reading sequence
    // Example: Reading from a register
    char cmd[] = {VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY}; // Command to trigger reading
    char data[2]; // Buffer to store the distance data (2 bytes for example)
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, sizeof(cmd));
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X for data ready: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay for the sensor to prepare data

    result = i2cReadDevice(i2c_handle, data, sizeof(data));
    if (result != sizeof(data)) {
        fprintf(stderr, "Error reading from VL53L1X: %d\n", result);
        return -1;
    }

    // Convert the received data to distance (example - adjust based on datasheet)
    int distance = (data[0] << 8) | data[1]; // Assuming 2 bytes for distance

    return distance;
}

// Function to control the relay based on the distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Set relay HIGH
    } else {
        gpioWrite(RELAY_GPIO, 0); // Set relay LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for the relay
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to LOW

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_relay(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Set relay to LOW before exiting
    gpioTerminate();

    return 0;
}

