#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read a 16-bit value from the MPU-6050
int16_t read_gyro_axis(int handle, uint8_t reg)
{
    int16_t value;
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading gyro axis data from register 0x%02X\n", reg);
        return 0; // Return 0 on error
    }

    value = (buf[0] << 8) | buf[1];
    return value;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int16_t gyro_x = read_gyro_axis(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_gyro_axis(i2c_handle, GYRO_YOUT_H);
        int16_t gyro_z = read_gyro_axis(i2c_handle, GYRO_ZOUT_H);

        // Print the gyroscope data
        printf("Gyro X: %6d, Gyro Y: %6d, Gyro Z: %6d\n", gyro_x, gyro_y, gyro_z);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

