// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the watering cycle duration (seconds)
#define WATERING_CYCLE_DURATION 86400

// Define the relay activation duration (seconds)
#define RELAY_ACTIVATION_DURATION 5

// Global variable to store the start time of the watering cycle
time_t watering_cycle_start_time = 0;

// Function prototypes
int initialize_gpio();
void activate_relay(int gpio_pin);
void deactivate_relay(int gpio_pin);
void log_watering_cycle_start();
void signal_handler(int signal);

// Structure to hold relay pins
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} RelayPins;

RelayPins relay_pins = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Log the start time of the watering cycle
    log_watering_cycle_start();

    // Main loop to activate the relays sequentially
    while (1) {
        // Activate relay 1
        activate_relay(relay_pins.relay1);
        sleep(RELAY_ACTIVATION_DURATION);

        // Deactivate relay 1
        deactivate_relay(relay_pins.relay1);
        sleep(RELAY_ACTIVATION_DURATION);

        // Activate relay 2
        activate_relay(relay_pins.relay2);
        sleep(RELAY_ACTIVATION_DURATION);

        // Deactivate relay 2
        deactivate_relay(relay_pins.relay2);
        sleep(RELAY_ACTIVATION_DURATION);

        // Activate relay 3
        activate_relay(relay_pins.relay3);
        sleep(RELAY_ACTIVATION_DURATION);

        // Deactivate relay 3
        deactivate_relay(relay_pins.relay3);
        sleep(RELAY_ACTIVATION_DURATION);

        // Activate relay 4
        activate_relay(relay_pins.relay4);
        sleep(RELAY_ACTIVATION_DURATION);

        // Deactivate relay 4
        deactivate_relay(relay_pins.relay4);
        sleep(RELAY_ACTIVATION_DURATION);

        // Check if the watering cycle duration has elapsed
        time_t current_time = time(NULL);
        if (difftime(current_time, watering_cycle_start_time) >= WATERING_CYCLE_DURATION) {
            // Log the start time of the next watering cycle
            log_watering_cycle_start();
        }
    }

    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(relay_pins.relay1, PI_OUTPUT);
    gpioSetMode(relay_pins.relay2, PI_OUTPUT);
    gpioSetMode(relay_pins.relay3, PI_OUTPUT);
    gpioSetMode(relay_pins.relay4, PI_OUTPUT);

    // Set all relays to inactive (HIGH) state
    gpioWrite(relay_pins.relay1, 1);
    gpioWrite(relay_pins.relay2, 1);
    gpioWrite(relay_pins.relay3, 1);
    gpioWrite(relay_pins.relay4, 1);

    return 0;
}

// Function to activate a relay by setting the GPIO pin LOW
void activate_relay(int gpio_pin) {
    gpioWrite(gpio_pin, 0);
}

// Function to deactivate a relay by setting the GPIO pin HIGH
void deactivate_relay(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
}

// Function to log the start time of the watering cycle to a file
void log_watering_cycle_start() {
    FILE *fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening watering_log.txt for writing\n");
        return;
    }

    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    watering_cycle_start_time = current_time;
}

// Signal handler function to release GPIO lines and terminate the pigpio library
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up and exiting.\n", signal);

    // Deactivate all relays
    deactivate_relay(relay_pins.relay1);
    deactivate_relay(relay_pins.relay2);
    deactivate_relay(relay_pins.relay3);
    deactivate_relay(relay_pins.relay4);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

