        set_pwm_frequency(RELAY3_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        log_event("Failed to set PWM frequency");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to set GPIO mode
int set_gpio_mode(int pin, int mode) {
    int result = gpioSetMode(pin, mode);
    if (result != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Failed to set GPIO %d mode to %d", pin, mode);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM frequency
int set_pwm_frequency(int pin, int frequency) {
    int result = gpioSetPWMfrequency(pin, frequency);
    if (result != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Failed to set PWM frequency for GPIO %d to %d", pin, frequency);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_dutycycle(int pin, int dutycycle) {
    int result = gpioPWM(pin, dutycycle);
    if (result != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Failed to set PWM duty cycle for GPIO %d to %d", pin, dutycycle);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        return 1;
    }

    log_event("Smart Lighting Sunrise Effect Started");

    // Calculate the increment per second
    int increment = 255 / NUM_STEPS;

    // Main loop
    for (int i = 0; i < NUM_STEPS && program_running; ++i) {
        // Calculate the duty cycle for each relay
        int dutycycle1 = i * increment;
        int dutycycle2 = i * increment;
        int dutycycle3 = i * increment;
        int dutycycle4 = i * increment;

        // Set the PWM duty cycle for each relay
        if (set_pwm_dutycycle(RELAY1_PIN, dutycycle1) != 0 ||
            set_pwm_dutycycle(RELAY2_PIN, dutycycle2) != 0 ||
            set_pwm_dutycycle(RELAY3_PIN, dutycycle3) != 0 ||
            set_pwm_dutycycle(RELAY4_PIN, dutycycle4) != 0) {
            log_event("Failed to set PWM duty cycle, exiting");
            program_running = 0; // Stop the loop if there's an error
        }

        // Log the current state
        char message[200];
        snprintf(message, sizeof(message), "Relay 1: %d, Relay 2: %d, Relay 3: %d, Relay 4: %d", dutycycle1, dutycycle2, dutycycle3, dutycycle4);
        log_event(message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio uses microseconds
    }

    // Turn off all relays
    set_pwm_dutycycle(RELAY1_PIN, 0);
    set_pwm_dutycycle(RELAY2_PIN, 0);
    set_pwm_dutycycle(RELAY3_PIN, 0);
    set_pwm_dutycycle(RELAY4_PIN, 0);

    log_event("Smart Lighting Sunrise Effect Finished");

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

