#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) == 0) {
            // Wake up the MPU-6050
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to initialize MPU-6050. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            retries--;
        }
    }
    fprintf(stderr, "Error: Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data.\n");
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Get data from the circular buffer
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    return buffer->data[(buffer->tail + index) % BUFFER_SIZE];
}

// Control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec ts;
    gyro_data_t gyro_data;
    int led_state = 0;

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Get current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Add data to circular buffer
                add_to_buffer(&gyro_buffer, gyro_data);

                // Check if any axis exceeds the threshold
                if (abs(gyro_data.x) > 250 || abs(gyro_data.y) > 250 || abs(gyro_data.z) > 250) {
                    led_state = 1;
                } else {
                    led_state = 0;
                }

                // Control the LED
                control_led(led_state);
            } else {
                fprintf(stderr, "Error: Failed to get timestamp\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        }

        // Delay for 50ms (20Hz sampling rate)
        gpioDelay(50000); // 50000 microseconds = 50 milliseconds
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

