#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_BUS "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO_PIN 8 // GPIO8 (BCM)
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_RATE_MS 10

// MPU-9250 Registers
#define MPU9250_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Global variables
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double convert_to_degrees_per_second(int16_t raw_data);
int log_data(FILE *fp, double timestamp, double x_rate, double y_rate, double z_rate);
void signal_handler(int sig);
int initialize();
void cleanup();

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[6];
    uint8_t rx_buf[6];

    // Read GYRO_XOUT_H to GYRO_ZOUT_H (6 bytes)
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read bit set

    if (spi_transfer(fd, tx_buf, rx_buf, 6) != 0) {
        return -1;
    }

    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[0]);
    *y = (int16_t)((rx_buf[3] << 8) | rx_buf[2]);
    *z = (int16_t)((rx_buf[5] << 8) | rx_buf[4]);

    return 0;
}

// Convert raw data to degrees per second
double convert_to_degrees_per_second(int16_t raw_data) {
    // Sensitivity scale factor for +/- 250 deg/s range
    double sensitivity = 131.0;
    return (double)raw_data / sensitivity;
}

// Log data to file
int log_data(FILE *fp, double timestamp, double x_rate, double y_rate, double z_rate) {
    if (fprintf(fp, "%.9f,%.6f,%.6f,%.6f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Open SPI device
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure CS GPIO line
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_PIN);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gyro_logger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(cs_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    // Initialize MPU-9250 (wake up and set gyro range)
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Wake up the MPU-9250
    tx_buf[0] = PWR_MGMT_1 | 0x80; // Reset bit
    tx_buf[1] = 0x00; // Clear reset bit
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error initializing MPU-9250 (PWR_MGMT_1): %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    // Set gyro range to +/- 250 deg/s
    tx_buf[0] = GYRO_CONFIG | 0x80; // Bit 7 = 1 for gyro config
    tx_buf[1] = 0x00; // Set gyro full scale range to +/- 250 deg/s
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error initializing MPU-9250 (GYRO_CONFIG): %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        double x_rate, y_rate, z_rate;
        struct timespec ts;
        double timestamp;

        // Read gyroscope data with retries
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_gyro_data(spi_fd, &raw_x, &raw_y, &raw_z) == 0) {
                break; // Success
            } else {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)\n", retry + 1, RETRY_COUNT);
                nanosleep((const struct timespec[]){{0, RETRY_DELAY_MS * 1000000L}}, NULL);
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read gyro data after %d retries\n", RETRY_COUNT);
            continue; // Skip logging this iteration
        }

        // Convert raw data to degrees per second
        x_rate = convert_to_degrees_per_second(raw_x);
        y_rate = convert_to_degrees_per_second(raw_y);
        z_rate = convert_to_degrees_per_second(raw_z);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            continue; // Skip logging this iteration
        }
        timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

        // Log data
        if (log_data(log_file, timestamp, x_rate, y_rate, z_rate) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = SAMPLE_RATE_MS * 1000000L; // 10ms
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

