#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define LED_PIN 17        // BCM GPIO 17
#define BUFFER_SIZE 64
#define THRESHOLD 200.0f  // degrees per second
#define BLINK_DURATION 500 // milliseconds

// MPU-6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Data structure for gyroscope data
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variable for SPI file descriptor
int spi_fd = -1;

// Function prototypes
int init_spi();
int init_gpio();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(struct timespec ts, float x, float y, float z);
bool check_threshold(float x, float y, float z);
void blink_led();
void signal_handler(int signal);
void print_buffer();

// Function to initialize SPI
int init_spi() {
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially off
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    unsigned char data[6];
    int16_t raw_x, raw_y, raw_z;

    // Read all gyroscope data at once
    if (wiringPiSPIDataRW(SPI_CHANNEL, data, 6) == -1) {
        fprintf(stderr, "Error reading SPI data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (data[0] << 8) | data[1];
    raw_y = (data[2] << 8) | data[3];
    raw_z = (data[4] << 8) | data[5];

    // Convert to degrees per second (assuming sensitivity of 131 LSB/deg/s)
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(struct timespec ts, float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = ts;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check if any axis exceeds the threshold
bool check_threshold(float x, float y, float z) {
    return (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD);
}

// Function to blink the LED
void blink_led() {
    digitalWrite(LED_PIN, HIGH); // Turn LED on
    delay(BLINK_DURATION);
    digitalWrite(LED_PIN, LOW);  // Turn LED off
    delay(BLINK_DURATION);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI
    if (spi_fd != -1) {
        // No explicit SPI close function in wiringPi, but we can reset the channel
        wiringPiSPIClose(SPI_CHANNEL);
    }

    // Reset GPIO
    digitalWrite(LED_PIN, LOW); // Ensure LED is off
    pinMode(LED_PIN, INPUT);    // Set back to input

    exit(0);
}

// Function to print the circular buffer as CSV
void print_buffer() {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct index calculation
        char timestamp_str[30];
        struct timespec ts = gyro_buffer[index].timestamp;
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        printf("%s.%09ld,%.2f,%.2f,%.2f\n", timestamp_str, ts.tv_nsec, gyro_buffer[index].x, gyro_buffer[index].y, gyro_buffer[index].z);
    }
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (init_spi() == -1) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() == -1) {
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize MPU-6050 (wake up)
    unsigned char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep mode bit
    wiringPiSPIDataRW(SPI_CHANNEL, data, 2);

    float x, y, z;
    struct timespec ts;

    printf("Starting data acquisition...\n");

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == -1) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Add data to buffer
        add_to_buffer(ts, x, y, z);

        // Check for threshold crossing
        if (check_threshold(x, y, z)) {
            blink_led();
        }

        // Delay for a short period
        delay(10); // Adjust as needed
    }

    return 0;
}

