#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define GPIO_LED 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// Si1145 Registers
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02
#define REG_INTCFG 0x03
#define REG_IRQEN 0x04
#define REG_ALS_VIS_DATA0 0x10
#define REG_ALS_VIS_DATA1 0x11
#define REG_ALS_IR_DATA0 0x12
#define REG_ALS_IR_DATA1 0x13
#define REG_PS1_DATA0 0x18
#define REG_PS1_DATA1 0x19
#define REG_COMMAND 0x30

// Global Variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_ambient_light(int fd);
int read_proximity(int fd);
void log_data(FILE *fp, int ambient_light, int proximity);
void control_led(int gpio, int state);
void signal_handler(int signal);

// I2C Read Function
int i2c_read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C Write Function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Read Ambient Light Function
int read_ambient_light(int fd) {
    int ambient_light = i2c_read_register(fd, REG_ALS_VIS_DATA0);
    if (ambient_light < 0) {
        fprintf(stderr, "Error reading ambient light\n");
        return -1;
    }
    return ambient_light;
}

// Read Proximity Function
int read_proximity(int fd) {
    int proximity = i2c_read_register(fd, REG_PS1_DATA0);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity\n");
        return -1;
    }
    return proximity;
}

// Log Data Function
void log_data(FILE *fp, int ambient_light, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%d,Proximity:%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp); // Ensure data is written to file immediately
}

// Control LED Function
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int ambient_light = -1, proximity = -1;
        int retries = 0;

        // Read ambient light with retries
        while (ambient_light < 0 && retries < MAX_RETRIES) {
            ambient_light = read_ambient_light(i2c_fd);
            if (ambient_light < 0) {
                fprintf(stderr, "Retrying ambient light read (%d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        // Read proximity with retries
        retries = 0;
        while (proximity < 0 && retries < MAX_RETRIES) {
            proximity = read_proximity(i2c_fd);
            if (proximity < 0) {
                fprintf(stderr, "Retrying proximity read (%d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (ambient_light >= 0 && proximity >= 0) {
            log_data(log_file, ambient_light, proximity);

            // Control LED based on proximity
            if (proximity > PROXIMITY_THRESHOLD) {
                control_led(GPIO_LED, 1); // Turn LED on
            } else {
                control_led(GPIO_LED, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
        }

        gpioDelay(100 * 1000); // Delay for 100ms (100000 microseconds)
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    control_led(GPIO_LED, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

