#include <unistd.h>
#include <pigpio.h>

// ADXRS290 Register Addresses
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02
#define ADXRS290_REG_TEMP 0x04
#define ADXRS290_REG_DIAG 0x06
#define ADXRS290_REG_RESET 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0       // CPOL=0, CPHA=0

// Global Variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(int channel, int speed, int mode);
int spi_read_register(int handle, uint8_t address, uint8_t *data);
int spi_write_register(int handle, uint8_t address, uint8_t data);
int read_gyro_data(int handle, int16_t *x_rate, int16_t *y_rate);
int log_data(FILE *fp, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);
void cleanup();

// SPI Initialization Function
int spi_init(int channel, int speed, int mode) {
    int handle = spiOpen(channel, speed, mode);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// SPI Read Register Function
int spi_read_register(int handle, uint8_t address, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00;           // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error reading SPI register 0x%02X\n", address);
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t address, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error writing SPI register 0x%02X\n", address);
        return -1;
    }

    return 0;
}

// Read Gyro Data Function
int read_gyro_data(int handle, int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_rate_data[2];
    uint8_t y_rate_data[2];

    if (spi_read_register(handle, ADXRS290_REG_X_RATE, &x_rate_data[1]) != 0) {
        fprintf(stderr, "Error reading X-axis rate\n");
        return -1;
    }
    x_rate_data[0] = 0x00; // Dummy byte

    if (spi_read_register(handle, ADXRS290_REG_Y_RATE, &y_rate_data[1]) != 0) {
        fprintf(stderr, "Error reading Y-axis rate\n");
        return -1;
    }
    y_rate_data[0] = 0x00; // Dummy byte

    *x_rate = (int16_t)((x_rate_data[1] << 8) | x_rate_data[0]);
    *y_rate = (int16_t)((y_rate_data[1] << 8) | y_rate_data[0]);

    return 0;
}

// Log Data Function
int log_data(FILE *fp, int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (fprintf(fp, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000, x_rate, y_rate) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    return 0;
}

// Signal Handler Function
