    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    int attempts = 0;
    while (spi_handle < 0 && attempts < 3) {
        spi_handle = spi_init(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        if (spi_handle < 0) {
            fprintf(stderr, "SPI initialization failed, retrying... (%d/3)\n", attempts + 1);
            attempts++;
            sleep(1); // Wait before retrying
        }
