#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define alert duration in seconds
#define ALERT_DURATION 2

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void alert_callback(int gpio, int level, uint32_t tick);
void log_seismic_event();
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    uint32_t last_tick;
} SensorState;

SensorState sensor_state = {0, 0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read sensor value with debouncing
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    uint32_t current_tick = gpioTick();

    if (value == 1) {
        if (current_tick - sensor_state.last_tick > DEBOUNCE_TIME * 1000) {
            sensor_state.last_tick = current_tick;
            return 1;
        }
    } else {
        sensor_state.last_tick = current_tick;
    }

    return 0;
}

// Callback function for sensor interrupts
void alert_callback(int gpio, int level, uint32_t tick) {
    if (gpio == SENSOR1_PIN || gpio == SENSOR2_PIN) {
        // Update sensor state
        if (gpio == SENSOR1_PIN) {
            sensor_state.sensor1_state = level;
        } else {
            sensor_state.sensor2_state = level;
        }

        // Check if both sensors are HIGH
        if (sensor_state.sensor1_state == 1 && sensor_state.sensor2_state == 1) {
            gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
            gpioDelay(ALERT_DURATION * 1000); // Wait for alert duration
            gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
        }
    }
}

// Function to log seismic event to file
void log_seismic_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate(); // Terminate pigpio

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register callback functions for sensor interrupts
    gpioSetAlertFuncEx(SENSOR1_PIN, alert_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_PIN, alert_callback, NULL);

    printf("Seismic event detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Log seismic event if both sensors are HIGH
        if (sensor1_value == 1 && sensor2_value == 1) {
            log_seismic_event();
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

