#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // Chip Select (CE0)
#define LED_PIN 17        // LED control
#define THRESHOLD 20.0    // Angular rate threshold (deg/s)
#define BUFFER_SIZE 100

// ADXRS290 Register Addresses
#define REG_X_RATE 0x00
#define REG_TEMP 0x02
#define REG_DIAG 0x04
#define REG_RESET 0x06

// Data structure for storing readings
typedef struct {
    struct timespec timestamp;
    float rate;
} Reading;

// Circular buffer structure
typedef struct {
    Reading buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int mutex; // Mutex for thread safety
} CircularBuffer;

// Global variables
int spi_handle;
CircularBuffer gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int init_gpio();
int init_circular_buffer(CircularBuffer *cb);
int read_gyro_rate(float *rate);
void add_reading(CircularBuffer *cb, struct timespec ts, float rate);
int check_threshold(float rate);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        return -1;
    }
    gpioWrite(LED_PIN, 0); // Initially off
    return 0;
}

// Initialize circular buffer
int init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->mutex = 0; // Initialize mutex to 0 (not locked)
    return 0;
}

// Read gyroscope rate
int read_gyro_rate(float *rate) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Read X-axis rate
    tx_buf[0] = REG_X_RATE | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte for reading

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Combine bytes to form 16-bit value
    int16_t raw_rate = (rx_buf[0] << 8) | rx_buf[1];

    // Convert to degrees per second (adjust based on datasheet)
    *rate = (float)raw_rate * 0.00875; // Example conversion factor

    return 0;
}

// Add reading to circular buffer
void add_reading(CircularBuffer *cb, struct timespec ts, float rate) {
    gpioDelay(1); // Small delay to prevent race conditions
    cb->mutex = 1; // Lock the mutex
    cb->buffer[cb->head].timestamp = ts;
    cb->buffer[cb->head].rate = rate;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    cb->mutex = 0; // Unlock the mutex
}

// Check if rate exceeds threshold
int check_threshold(float rate) {
    return (rate > THRESHOLD) ? 1 : 0;
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    if (init_circular_buffer(&gyro_buffer) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float rate;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        if (read_gyro_rate(&rate) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_reading(&gyro_buffer, ts, rate);

            if (check_threshold(rate)) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }

            printf("Rate: %.2f deg/s\n", rate);
        } else {
            fprintf(stderr, "Failed to read gyro rate\n");
        }

        gpioDelay(10); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

