    cb->buffer[cb->head].rate = rate;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    cb->mutex = 0; // Unlock the mutex
}

// Check if rate exceeds threshold
int check_threshold(float rate) {
    return (rate > THRESHOLD) ? 1 : 0;
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    if (init_circular_buffer(&gyro_buffer) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float rate;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        if (read_gyro_rate(&rate) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_reading(&gyro_buffer, ts, rate);

            if (check_threshold(rate)) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }

            printf("Rate: %.2f deg/s\n", rate);
        } else {
            fprintf(stderr, "Failed to read gyro rate\n");
        }

        gpioDelay(10); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

