    total_duration = atoi(argv[1]);

    // Validate the total duration
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_PIN, PI_OUTPUT);
    gpioSetMode(LAMP2_PIN, PI_OUTPUT);
    gpioSetMode(LAMP3_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LAMP1_PIN, 255);
    gpioSetPWMrange(LAMP2_PIN, 255);
    gpioSetPWMrange(LAMP3_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start the sunset simulation
    sunset_simulation(total_duration);

    // Cleanup (should not reach here if signal handler works correctly)
    turn_off_lamp(LAMP1_PIN);
    turn_off_lamp(LAMP2_PIN);
    turn_off_lamp(LAMP3_PIN);
    gpioTerminate();

    return 0;
}

