#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the traffic lights
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

// Define the duration of each state in seconds
#define RED_DURATION   10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION  3

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nSIGINT received, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nSIGTERM received, exiting gracefully...\n");
}

// Function to set the state of a traffic light
void set_traffic_light(int gpio_pin, int state)
{
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        exit(EXIT_FAILURE);
    }
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting mode for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(YELLOW_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting mode for GPIO %d\n", YELLOW_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting mode for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting mode for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop to cycle through the traffic light sequence
    while (program_running) {
        // Red light
        set_traffic_light(RED_PIN, 0); // Active low
        set_traffic_light(YELLOW_PIN, 1);
        set_traffic_light(GREEN_PIN, 1);
        set_traffic_light(BLUE_PIN, 1);
        printf("Red light on\n");
        sleep(RED_DURATION);

        // Red + Yellow light
        set_traffic_light(RED_PIN, 0);
        set_traffic_light(YELLOW_PIN, 0);
        set_traffic_light(GREEN_PIN, 1);
        set_traffic_light(BLUE_PIN, 1);
        printf("Red + Yellow light on\n");
        sleep(RED_YELLOW_DURATION);

        // Green light
        set_traffic_light(RED_PIN, 1);
        set_traffic_light(YELLOW_PIN, 1);
        set_traffic_light(GREEN_PIN, 0);
        set_traffic_light(BLUE_PIN, 1);
        printf("Green light on\n");
        sleep(GREEN_DURATION);

        // Yellow light
        set_traffic_light(RED_PIN, 1);
        set_traffic_light(YELLOW_PIN, 1);
        set_traffic_light(GREEN_PIN, 1);
        set_traffic_light(BLUE_PIN, 0);
        printf("Yellow light on\n");
        sleep(YELLOW_DURATION);
    }

    // Clean up and terminate the pigpio library
    set_traffic_light(RED_PIN, 1);
    set_traffic_light(YELLOW_PIN, 1);
    set_traffic_light(GREEN_PIN, 1);
    set_traffic_light(BLUE_PIN, 1);
    gpioTerminate();

    return EXIT_SUCCESS;
}

