#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define constants
#define MPR121_I2C_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define TOUCH_THRESHOLD 0x0F
#define RELEASE_THRESHOLD 0x05

// Global variables
int i2c_fd;
FILE *log_file;
bool relay_state = false;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void relay_toggle();
void debounce();
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2B, 0x00) < 0) {
        log_message("Error: Failed to set MPR121 to stop mode.");
        return -1;
    }
    delay(1);

    // Electrode configuration
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5E, 0x0C) < 0) {
        log_message("Error: Failed to set electrode configuration.");
        return -1;
    }

    // Touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(i2c_fd, 0x41 + (i * 2), TOUCH_THRESHOLD) < 0) {
            log_message("Error: Failed to set touch threshold.");
            return -1;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, 0x42 + (i * 2), RELEASE_THRESHOLD) < 0) {
            log_message("Error: Failed to set release threshold.");
            return -1;
        }
    }

    // Enable electrodes
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5B, 0x01) < 0) {
        log_message("Error: Failed to enable electrodes.");
        return -1;
    }

    // Start mode
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2B, 0x01) < 0) {
        log_message("Error: Failed to set MPR121 to start mode.");
        return -1;
    }
    delay(1);

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status = wiringPiI2CReadReg16(i2c_fd, 0x00);
    if (touch_status < 0) {
        log_message("Error: Failed to read touch status.");
        return -1;
    }
    return touch_status;
}

// Function to toggle the relay state
void relay_toggle() {
    relay_state = !relay_state;
    digitalWrite(RELAY_GPIO, relay_state);
    char message[100];
    snprintf(message, sizeof(message), "Relay toggled to %s", relay_state ? "HIGH" : "LOW");
    log_message(message);
}

// Function to debounce the touch event
void debounce() {
    delay(DEBOUNCE_DELAY_MS);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Received signal, shutting down...");
    digitalWrite(RELAY_GPIO, LOW); // Ensure relay is off
    if (i2c_fd >= 0) {
        // No specific I2C close function in wiringPi, but we can reset the device
        wiringPiI2CWriteReg8(i2c_fd, 0x2B, 0x00); // Put MPR121 in stop mode
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_I2C_ADDR);
    if (i2c_fd == -1) {
        log_message("Error: Failed to initialize I2C.");
        fclose(log_file);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() == -1) {
        log_message("Error: Failed to initialize MPR121.");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Set relay GPIO as output
    pinMode(RELAY_GPIO, OUTPUT);
    digitalWrite(RELAY_GPIO, LOW); // Initialize relay to LOW

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("System started successfully.");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status >= 0) {
            if (touch_status & 0x01) { // Check if electrode 0 is touched
                relay_toggle();
            }
        }
        delay(10); // 10ms delay
    }

    return 0;
}

