// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define the log file name
#define LOG_FILE "dispense_log.txt"

// Define the dispense interval in milliseconds
#define DISPENSE_INTERVAL_MS 5000

// Define the duration of each solenoid activation in milliseconds
#define SOLENOID_DURATION_MS 500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int dispense_solenoid(int gpio_pin, int duration_ms);
int log_dispense_event(int gpio_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Shutting down gracefully...\n");
        program_running = 0;

        // Deactivate solenoids
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);

        // Terminate pigpio
        gpioTerminate();

        exit(0);
    }
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to dispense a solenoid for a specified duration
int dispense_solenoid(int gpio_pin, int duration_ms) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO %d\n", gpio_pin);
        return 1; // Indicate failure
    }

    gpioDelay(duration_ms * 1000); // Delay for the specified duration

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO %d\n", gpio_pin);
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to log a dispense event to a file
int log_dispense_event(int gpio_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, GPIO %d, %d ms\n", timestamp, gpio_pin, duration_ms);

    fclose(fp);
    return 0; // Indicate success
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense solenoid 1
        if (dispense_solenoid(SOLENOID_1_PIN, SOLENOID_DURATION_MS) != 0) {
            fprintf(stderr, "Failed to dispense solenoid 1\n");
        }

        // Dispense solenoid 2
        if (dispense_solenoid(SOLENOID_2_PIN, SOLENOID_DURATION_MS) != 0) {
            fprintf(stderr, "Failed to dispense solenoid 2\n");
        }

        // Log the dispense events
        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_DURATION_MS) != 0) {
            fprintf(stderr, "Failed to log dispense event for solenoid 1\n");
        }
        if (log_dispense_event(SOLENOID_2_PIN, SOLENOID_DURATION_MS) != 0) {
            fprintf(stderr, "Failed to log dispense event for solenoid 2\n");
        }

        // Wait for the next interval
        gpioDelay(DISPENSE_INTERVAL_MS * 1000);
    }

    // Terminate the pigpio library (should not reach here if signal handler works)
    gpioTerminate();

    return 0;
}

