#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define ENA 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENB 25

// Obstacle avoidance distance threshold (cm)
#define OBSTACLE_THRESHOLD 20.0

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global variables
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float generate_tilt_error();
float generate_distance();
void set_motor_speed(int motor, int speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, stopping motors and exiting...\n");
        stop_motors();
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Generates a random tilt error between -10.0 and 10.0
float generate_tilt_error() {
    return ((float)(rand() % 21) - 10.0);
}

// Generates a random distance between 2.0 and 400.0
float generate_distance() {
    return ((float)(rand() % 1999) + 2.0);
}

// Sets the speed of a motor (0-255)
void set_motor_speed(int motor, int speed) {
    if (motor == 'A') {
        if (speed > 255) speed = 255;
        if (speed < -255) speed = -255;
        gpioPWM(MOTOR_A_FORWARD, abs(speed));
        if (speed > 0) gpioWrite(MOTOR_A_BACKWARD, 0);
        else gpioWrite(MOTOR_A_BACKWARD, 1);
    } else if (motor == 'B') {
        if (speed > 255) speed = 255;
        if (speed < -255) speed = -255;
        gpioPWM(MOTOR_B_FORWARD, abs(speed));
        if (speed > 0) gpioWrite(MOTOR_B_BACKWARD, 0);
        else gpioWrite(MOTOR_B_BACKWARD, 1);
    } else {
        fprintf(stderr, "Invalid motor character: %c\n", motor);
        log_data(0.0, 0.0, 0, 0); // Log invalid data
    }
}

// Stops both motors
void stop_motors() {
    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
}

// Logs the data to the file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Enable PWM on ENA and ENB
    gpioSetPWMfrequency(ENA, 1000); // 1 kHz
    gpioSetPWMfrequency(ENB, 1000); // 1 kHz
    gpioPWM(ENA, 0);
    gpioPWM(ENB, 0);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Seed the random number generator
    srand(time(NULL));

    // PID variables
    float integral = 0.0;
    float previous_error = 0.0;

    // Main loop
    while (1) {
        // Generate sensor data
        float tilt_error = generate_tilt_error();
        float distance = generate_distance();

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            printf("Obstacle detected! Reversing...\n");
            set_motor_speed('A', -50);
            set_motor_speed('B', -50);
            log_data(tilt_error, distance, -50, -50);
            gpioDelay(200); // Obstacle avoidance for 200ms
            stop_motors();
            log_data(tilt_error, distance, 0, 0);
        } else {
            // PID control
            float error = tilt_error;
            integral += error;
            float derivative = error - previous_error;
            float output = KP * error + KI * integral + KD * derivative;

            // Motor speeds
            int motor_a_speed = (int)output;
            int motor_b_speed = (int)output;

            // Clamp motor speeds
            if (motor_a_speed > 255) motor_a_speed = 255;
            if (motor_a_speed < -255) motor_a_speed = -255;
            if (motor_b_speed > 255) motor_b_speed = 255;
            if (motor_b_speed < -255) motor_b_speed = -255;

            // Set motor speeds
            set_motor_speed('A', motor_a_speed);
            set_motor_speed('B', motor_b_speed);

