#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Configuration
#define SAMPLE_RATE 8000
#define CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S16_LE
#define PERIOD_SIZE 1024
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // PWM range for pigpio

// GPIO pins
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

// Global variables
snd_pcm_t *pcm_handle = NULL;
int running = 1;
double sensitivity = 1.0;

// Function prototypes
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size);
double calculate_rms(short *buffer, int buffer_size);
void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signum);
int initialize_alsa(snd_pcm_t **pcm_handle);
void cleanup();

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        running = 0;
    }
}

// ALSA initialization
int initialize_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Audio capture
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, buffer_size)) != buffer_size) {
        if (err == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            return -1;
        }
    }
    return 0;
}

// RMS calculation
double calculate_rms(short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / buffer_size);
}

// Color mapping
void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue) {
    double normalized_amplitude = amplitude / 32768.0; // Assuming 16-bit samples
    normalized_amplitude = fmax(0.0, fmin(1.0, normalized_amplitude)); // Clamp to [0, 1]

    // Non-linear mapping (example: logarithmic)
    double log_amplitude = log10(1.0 + sensitivity * normalized_amplitude); // Scale and apply log
    log_amplitude = fmax(0.0, fmin(1.0, log_amplitude)); // Clamp again

    *red = (int)(log_amplitude * PWM_RANGE);
    *green = (int)((1.0 - log_amplitude) * PWM_RANGE);
    *blue = 0; // Example: Blue component

    // Ensure values are within the valid range
    *red = fmax(0, fmin(PWM_RANGE, *red));
    *green = fmax(0, fmin(PWM_RANGE, *green));
    *blue = fmax(0, fmin(PWM_RANGE, *blue));
}

// LED control
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity value. Using default (1.0).\n");
            sensitivity = 1.0;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Initialize ALSA
    if (initialize_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed. Falling back to simulated audio.\n");
        // Simulate audio input
        short *simulated_buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
        if (simulated_buffer == NULL) {
            fprintf(stderr, "Failed to allocate memory for simulated audio buffer.\n");
            cleanup();
            return 1;
        }

        // Generate a simple sine wave for simulation
        for (int i = 0; i < PERIOD_SIZE; i++) {
            double t = (double)i / SAMPLE_RATE;
            simulated_buffer[i] = (short)(32768 * sin(2 * M_PI * 440 * t)); // 440 Hz
        }

        // Main loop (simulated audio)
        while (running) {
            // Calculate RMS
            double rms = calculate_rms(simulated_buffer, PERIOD_SIZE);

            // Map amplitude to color
            int red, green, blue;
            map_amplitude_to_color(rms, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            // Print status
            printf("RMS: %.2f, Red: %d, Green: %d, Blue: %d\n", rms, red, green, blue);

            // Sleep for 10ms
            usleep(10000); // 10ms
        }

        free(simulated_buffer);
    } else {
        // Main loop (real audio)
        short *buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
        if (buffer == NULL) {
            fprintf(stderr, "Failed to allocate memory for audio buffer.\n");
            cleanup();
            return 1;
        }

        while (running) {
            // Capture audio
            if (capture_audio(pcm_handle, buffer, PERIOD_SIZE) != 0) {
                break; // Exit loop on error
            }

            // Calculate RMS
            double rms = calculate_rms(buffer, PERIOD_SIZE);

            // Map amplitude to color
            int red, green, blue;
            map_amplitude_to_color(rms, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            // Print status
            printf("RMS: %.2f, Red: %d, Green: %d, Blue: %d\n", rms, red, green, blue);

            // Sleep for 10ms
            usleep(10000); // 10ms
        }

        free(buffer);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

