#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Integration time values
#define TCS34725_INTEGRATIONTIME_154MS 0xD9

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int initialize_sensor();
color_data_t read_sensor_data();
void log_data(color_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable sensor.\n");
        return -1;
    }

    // Set integration time to 154ms
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_154MS) < 0) {
        fprintf(stderr, "Error: Could not set integration time.\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
color_data_t read_sensor_data() {
    color_data_t data;
    unsigned char buffer[8];

    // Read all color data registers at once
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error: Could not read sensor data.\n");
        data.clear = 0; data.red = 0; data.green = 0; data.blue = 0;
        return data;
    }

    // Combine MSB and LSB for each color value
    data.clear = (buffer[1] << 8) | buffer[0];
    data.red   = (buffer[3] << 8) | buffer[2];
    data.green = (buffer[5] << 8) | buffer[4];
    data.blue  = (buffer[7] << 8) | buffer[6];

    return data;
}

// Function to log data to a CSV file
void log_data(color_data_t data) {
    time_t now = time(NULL);
    if (fprintf(fp, "%ld,%u,%u,%u,%u\n", now, data.clear, data.red, data.green, data.blue) < 0) {
        fprintf(stderr, "Error: Could not write to file.\n");
    }
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to clean up resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open color_data.csv.\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,C,R,G,B\n");
    }
    rewind(fp);

    // Main loop
    while (!terminate) {
        color_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(500); // Sample every 500ms
    }

    // Clean up and exit
    cleanup();
    return 0;
}

