#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1 17
#define RELAY2 27
#define RELAY3 22
#define RELAY4 23

// Define the number of steps for the PWM-like duty cycle
#define NUM_STEPS 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a relay (active-low)
void set_relay_state(int gpio_pin, int state) {
    gpioWrite(gpio_pin, !state); // pigpio uses active-high, so invert the state
}

// Function to simulate sunrise
void sunrise(int gpio_pins[], int num_pins) {
    printf("Sunrise phase starting...\n");
    for (int i = 0; i < NUM_STEPS; i++) {
        for (int j = 0; j < num_pins; j++) {
            set_relay_state(gpio_pins[j], i < (NUM_STEPS / 2));
        }
        gpioDelay(1000); // 1 second delay
    }
    printf("Sunrise phase complete.\n");
}

// Function to simulate daytime
void daytime(int gpio_pins[], int num_pins) {
    printf("Daytime phase starting...\n");
    for (int i = 0; i < 6 * 60 * 60; i++) {
        for (int j = 0; j < num_pins; j++) {
            set_relay_state(gpio_pins[j], 1); // Keep all relays on during daytime
        }
        gpioDelay(1000); // 1 second delay
    }
    printf("Daytime phase complete.\n");
}

// Function to simulate sunset
void sunset(int gpio_pins[], int num_pins) {
    printf("Sunset phase starting...\n");
    for (int i = NUM_STEPS - 1; i >= 0; i--) {
        for (int j = 0; j < num_pins; j++) {
            set_relay_state(gpio_pins[j], i < (NUM_STEPS / 2));
        }
        gpioDelay(1000); // 1 second delay
    }
    printf("Sunset phase complete.\n");
}

// Function to simulate nighttime
void nighttime(int gpio_pins[], int num_pins) {
    printf("Nighttime phase starting...\n");
    for (int i = 0; i < 14.4 * 60 * 60; i++) {
        for (int j = 0; j < num_pins; j++) {
            set_relay_state(gpio_pins[j], 0); // Keep all relays off during nighttime
        }
        gpioDelay(1000); // 1 second delay
    }
    printf("Nighttime phase complete.\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1, PI_OUTPUT);
    gpioSetMode(RELAY2, PI_OUTPUT);
    gpioSetMode(RELAY3, PI_OUTPUT);
    gpioSetMode(RELAY4, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Array of GPIO pins for the relays
    int gpio_pins[] = {RELAY1, RELAY2, RELAY3, RELAY4};
    int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

    // Main loop
    while (program_running) {
        sunrise(gpio_pins, num_pins);
        daytime(gpio_pins, num_pins);
        sunset(gpio_pins, num_pins);
        nighttime(gpio_pins, num_pins);
    }

    // Turn off all relays before exiting
    for (int i = 0; i < num_pins; i++) {
        set_relay_state(gpio_pins[i], 0);
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

