#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 17
#define DEBOUNCE_TIME 200 // milliseconds
#define CAPTURE_DURATION 5 // seconds
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to capture video using raspivid
int capture_video() {
    char timestamp[25];
    get_iso8601_timestamp();
    sprintf(timestamp, "%s.h264", timestamp);

    char command[256];
    sprintf(command, "raspivid -o /home/pi/videos/%s -t %d", timestamp, CAPTURE_DURATION * 1000);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspivid command.\n");
        return -1;
    }
    return 0;
}

// Function to log motion events
int log_motion(const char* timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to handle motion detection
void handle_motion() {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return;
    }

    if (capture_video() == 0) {
        if (log_motion(timestamp) == 0) {
            printf("Motion detected at %s. Video captured and logged.\n", timestamp);
        } else {
            fprintf(stderr, "Failed to log motion event.\n");
        }
    } else {
        fprintf(stderr, "Failed to capture video.\n");
    }

    free(timestamp);
}

// Debounce function
void debounce() {
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

