#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for +/- 250 deg/s
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the MPU-6050 (clear sleep mode bit)
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0);
        if (status != 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Configure gyroscope sensitivity (+/- 250 deg/s)
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0);
        if (status != 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Log data to file
void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld.%03ld,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec / 1000000, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp_ms,X_degps,Y_degps,Z_degps\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    // Close log file and I2C handle
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

