#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_BW_RATE 0x2C

// Free-fall threshold (0.2g)
#define FREEFALL_THRESHOLD 0.2

// Free-fall duration (0.5 seconds)
#define FREEFALL_DURATION 500 // milliseconds

// Alarm GPIO pin (BCM numbering)
#define ALARM_GPIO 27

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
int detect_freefall(accelerometer_data_t data);
void trigger_alarm();
void log_freefall_event(accelerometer_data_t data);
void signal_handler(int signal);

// Function to initialize the ADXL345 accelerometer
int initialize_adxl345() {
    // Set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, ADXL345_BW_RATE, 0x0B) < 0) {
        fprintf(stderr, "Error setting data rate\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error enabling measurement mode\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

