#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_US 100000 // 100ms timeout
#define MAX_DISTANCE_CM 400 // Maximum measurable distance in cm
#define MAX_PULSE_WIDTH_US 23200 // Maximum pulse width in us (4m)
#define TRIGGER_PULSE_US 10 // 10us trigger pulse

// Define data structures
typedef struct {
    uint32_t rising_tick;
    uint32_t falling_tick;
    int valid;
} echo_data_t;

// Global variables
static volatile int running = 1;
static volatile uint32_t tick_counter = 0;
static FILE *log_file = NULL;
static int echo_data_valid = 0;
static echo_data_t echo_data;

// Function prototypes
void timer_callback(int timer_id);
void trigger_pulse();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void cleanup();
void timer_callback(int timer_id);

// Function to get nanosecond timestamp
uint64_t get_timestamp_ns() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
}

// Function to handle SIGINT signal
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt handler for rising edge of ECHO signal
void echo_rising_edge(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN && level == 1) {
        echo_data.rising_tick = tick;
        echo_data_valid = 1; // Mark as valid
    }
}

// Interrupt handler for falling edge of ECHO signal
void echo_falling_edge(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN && level == 0) {
        echo_data.falling_tick = tick;
        echo_data_valid = 1; // Mark as valid
    }
}

// Timer callback function
void timer_callback(int timer_id) {
    uint64_t start_time = get_timestamp_ns();
    uint32_t pulse_width;
    float distance_cm;
    uint32_t rising_tick, falling_tick;

    // Generate trigger pulse
    trigger_pulse();

    // Wait for echo
    int timeout_count = 0;
    while (echo_data_valid == 0 && timeout_count < (TIMEOUT_US / 1000)) {
        gpioDelay(1000); // Wait 1ms
        timeout_count++;
    }

    if (echo_data_valid == 0) {
        // Timeout occurred
        fprintf(log_file, "%llu,timeout\n", get_timestamp_ns());
        fflush(log_file);
        echo_data_valid = 0; // Reset flag
        return;
    }

    // Calculate pulse width
    rising_tick = echo_data.rising_tick;
    falling_tick = echo_data.falling_tick;
    pulse_width = falling_tick - rising_tick;

    // Validate pulse width
    if (pulse_width > MAX_PULSE_WIDTH_US) {
        fprintf(log_file, "%llu,invalid_pulse_width\n", get_timestamp_ns());
        fflush(log_file);
        echo_data_valid = 0; // Reset flag
        return;
    }

    // Calculate distance in centimeters
    distance_cm = (float)pulse_width / 2.0 / 29.1;

    // Log distance to file
    fprintf(log_file, "%llu,%.2f\n", get_timestamp_ns(), distance_cm);
    fflush(log_file);

    echo_data_valid = 0; // Reset flag
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set up interrupt handlers for ECHO pin
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_rising_edge, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_falling_edge, NULL);

    // Set up timer callback function
    gpioSetTimerFuncEx(0, 100, timer_callback, NULL); // Timer 0, every 100ms

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup resources
    cleanup();

    return 0;
}

