#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Free-fall and impact thresholds (g)
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration parameters
typedef struct {
    float freefall_threshold;
    float impact_threshold;
} Config;

// Function to parse command-line arguments
Config parse_arguments(int argc, char *argv[]) {
    Config config;
    config.freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    config.impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) {
        config.freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        config.impact_threshold = atof(argv[2]);
    }

    return config;
}

int main(int argc, char *argv[]) {
    Config config = parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue; // Try again
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(x, y, z);

        // Check for free-fall
        if (magnitude < config.freefall_threshold) {
            printf("Free-fall detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer();
        }

        // Check for impact
        if (magnitude > config.impact_threshold) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer();
        }

        // Delay
        gpioDelay(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0); // Bus 1, address 0x18, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

