#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Constants
#define STEP_DELAY_US 1000  // 1ms delay
#define GEAR_RATIO 64
#define STEPS_PER_REV 2048
#define SQUARE_SIDE_MM 50.0
#define PI 3.14159265359

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGINT, stopping motors and exiting...\n");
}

// Function to set the GPIO pins for a specific step
void set_step(int motor, int step)
{
    int in1, in2, in3, in4;

    if (motor == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    }

    switch (step) {
        case 0:
            gpioWrite(in1, 1);
            gpioWrite(in2, 0);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 1:
            gpioWrite(in1, 1);
            gpioWrite(in2, 1);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 2:
            gpioWrite(in1, 0);
            gpioWrite(in2, 1);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 3:
            gpioWrite(in1, 0);
            gpioWrite(in2, 1);
            gpioWrite(in3, 1);
            gpioWrite(in4, 0);
            break;
        default:
            fprintf(stderr, "Error: Invalid step number: %d\n", step);
            break;
    }
}

// Function to move a motor a specified number of steps
int move_motor(int motor, int steps, int direction)
{
    int i, step;

    if (direction != 1 && direction != -1) {
        fprintf(stderr, "Error: Invalid direction. Must be 1 (clockwise) or -1 (counter-clockwise).\n");
        return -1;
    }

    for (i = 0; i < steps; i++) {
        step = (i % 4) + 1; // 4-step wave drive
        if (direction == -1) {
            step = 4 - step + 1; // Reverse the step sequence for counter-clockwise
        }
        set_step(motor, step);
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

// Function to calculate the number of steps required to move a distance
int calculate_steps(float distance_mm)
{
    float circumference = 2 * PI * 0.0254 * distance_mm; // Circumference in mm
    float steps_per_mm = (float)STEPS_PER_REV / (GEAR_RATIO * 2 * PI * 0.0254); // Steps per mm
    return (int)(circumference * steps_per_mm);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Move the motors to trace a 50mm square
    printf("Moving motors to trace a 50mm square...\n");

    // Move Motor 1 (X-axis) to the right
    int steps_x = calculate_steps(SQUARE_SIDE_MM);
    if (move_motor(1, steps_x, 1) != 0) {
        fprintf(stderr, "Error: Failed to move Motor 1 (X-axis)\n");
        gpioTerminate();
        return 1;
    }

    // Move Motor 2 (Y-axis) up
    int steps_y = calculate_steps(SQUARE_SIDE_MM);
    if (move_motor(2, steps_y, 1) != 0) {
        fprintf(stderr, "Error: Failed to move Motor 2 (Y-axis)\n");
        gpioTerminate();
        return 1;
    }

    // Move Motor 1 (X-axis) back to the original position
    if (move_motor(1, steps_x, -1) != 0) {
        fprintf(stderr, "Error: Failed to move Motor 1 (X-axis) back\n");
        gpioTerminate();
        return 1;
    }

    // Move Motor 2 (Y-axis) down
    if (move_motor(2, steps_y, -1) != 0) {
        fprintf(stderr, "Error: Failed to move Motor 2 (Y-axis) down\n");
        gpioTerminate();
        return 1;
    }

    // Stop motors and release GPIO pins
    printf("Stopping motors and releasing GPIO pins...\n");
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

