#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LIS3DH Registers
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Default I2C address
#define DEFAULT_I2C_ADDRESS 0x18

// Default threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int check_threshold(float x, float y, float z, float threshold);
void log_data(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the LIS3DH sensor
int init_lis3dh(int i2c_handle) {
    // Configure CTRL1 register: 100Hz, Normal mode, Enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, 0x77) != 0) {
        fprintf(stderr, "Error writing to CTRL1 register\n");
        return -1;
    }

    // Configure CTRL4 register: ±2g range, High-resolution mode
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, 0x88) != 0) {
        fprintf(stderr, "Error writing to CTRL4 register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH sensor
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw acceleration value to g-force units
float convert_to_g(int16_t raw_value) {
    // Assuming ±2g range and 12-bit resolution
    return (float)raw_value * 2.0 / 4096.0;
}

// Function to check if any axis exceeds the threshold
int check_threshold(float x, float y, float z, float threshold) {
    if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
        return 1;
    }
    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", s, x, y, z);
    fclose(fp);
}

// Function to shutdown the system
void shutdown_system() {
    printf("Threshold exceeded. Shutting down...\n");
    gpioTerminate();
    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x03 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x03 and 0x77\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0\n");
