        int leftValue = readSensor(LEFT_SENSOR);
        int centerValue = readSensor(CENTER_SENSOR);
        int rightValue = readSensor(RIGHT_SENSOR);

        // Update circular buffer
        updateCircularBuffer(leftValue);
        updateCircularBuffer(centerValue);
        updateCircularBuffer(rightValue);

