                if (leftValue == SENSOR_PRESENT) {
                    turnLeft();
                } else {
                    // Check if right sensor detects line
                    if (rightValue == SENSOR_PRESENT) {
                        turnRight();
                    } else {
                        stop();
                    }
                }
            }
        } else {
            // Center sensor detects no line
            if (checkCircularBuffer(SENSOR_ABSENT)) {
                alertCount++;
                if (alertCount >= 5) {
                    alert();
                    alertCount = 0; // Reset alert count after alert
                }
            } else {
                alertCount = 0; // Reset alert count if center sensor detects line
            }
        }

        // Delay for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    return 0;
}

