#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define MAGNETIC_THRESHOLD 5.0 // mT
#define RETRY_COUNT 50
#define RETRY_DELAY_MS 10
#define LOG_FILE "magnetic_events.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_magnetic_field(float *magnetic_field);
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_address;
    int relay_pin;
    float threshold;
} sensor_config_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error opening I2C bus.");
        return -1;
    }
    return 0;
}

// Function to read magnetic field data from Si7210
int read_magnetic_field(float *magnetic_field) {
    char buf[2];
    int result;

    // Read two bytes from register 0x00
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        log_event("Error reading magnetic field data.");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (buf[0] << 8) | buf[1];

    // Convert raw value to mT (example conversion, adjust as needed)
    *magnetic_field = (float)raw_value * 0.1; // Example: 0.1 mT per unit

    return 0;
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char message[100];
    snprintf(message, sizeof(message), "Relay set to %s", state ? "ON" : "OFF");
    log_event(message);
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    control_relay(0); // Turn off relay
    i2cClose(i2c_handle);
    gpioTerminate();
    log_event("Cleanup complete.");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float magnetic_field;
    int relay_state = 0; // 0 = OFF, 1 = ON

    log_event("Program started.");

    while (program_running) {
        if (read_magnetic_field(&magnetic_field) == 0) {
            char message[100];
            snprintf(message, sizeof(message), "Magnetic field: %.2f mT", magnetic_field);
            log_event(message);

            if (magnetic_field > MAGNETIC_THRESHOLD && relay_state == 0) {
                control_relay(1); // Turn on relay
                relay_state = 1;
            } else if (magnetic_field <= MAGNETIC_THRESHOLD && relay_state == 1) {
                control_relay(0); // Turn off relay
                relay_state = 0;
            }
        } else {
            log_event("Failed to read magnetic field.");
        }

        gpioDelay(100); // Wait 100ms
    }

    cleanup();
    return 0;
}

