    log_event("Program started.");

    while (program_running) {
        if (read_magnetic_field(&magnetic_field) == 0) {
            char message[100];
            snprintf(message, sizeof(message), "Magnetic field: %.2f mT", magnetic_field);
            log_event(message);

            if (magnetic_field > MAGNETIC_THRESHOLD && relay_state == 0) {
                control_relay(1); // Turn on relay
                relay_state = 1;
            } else if (magnetic_field <= MAGNETIC_THRESHOLD && relay_state == 1) {
                control_relay(0); // Turn off relay
                relay_state = 0;
            }
        } else {
            log_event("Failed to read magnetic field.");
        }

        gpioDelay(100); // Wait 100ms
    }

    cleanup();
    return 0;
