#include <arpa/inet.h>
#include <pigpio.h>
#include <ctype.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
int server_socket = -1;

// Function prototypes
int initialize_gpio();
int create_server_socket();
int accept_connection(int server_socket);
int read_command(int client_socket);
int process_command(const char *command);
int control_relay(int state);
int log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Function to create a TCP server socket
int create_server_socket() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Could not create socket");
        return -1;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Bind failed");
        close(server_socket);
        return -1;
    }

    if (listen(server_socket, 3) < 0) {
        perror("Listen failed");
        close(server_socket);
        return -1;
    }

    printf("Listening on port %d...\n", PORT);
    return server_socket;
}

// Function to accept a connection from a client
int accept_connection(int server_socket) {
    struct sockaddr_in client_address;
    socklen_t client_address_len = sizeof(client_address);

    int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
    if (client_socket < 0) {
        perror("Accept failed");
        return -1;
    }

    printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
    return client_socket;
}

// Function to read a command from the client socket
int read_command(int client_socket) {
    char buffer[BUFFER_SIZE];
    memset(buffer, 0, BUFFER_SIZE);

    ssize_t bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        return -1;
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
        return 0; // Indicate client disconnected
    }

    // Convert to uppercase for case-insensitive comparison
    for (int i = 0; i < bytes_received; i++) {
        buffer[i] = toupper(buffer[i]);
    }

    return (int)bytes_received; // Return the number of bytes received
}

// Function to process the command
int process_command(const char *command) {
    if (strcmp(command, "ON") == 0) {
        return 1; // Turn ON
    } else if (strcmp(command, "OFF") == 0) {
        return 0; // Turn OFF
    } else {
        log_event("Invalid command received");
        return -1; // Invalid command
    }
}

// Function to control the relay (turn ON or OFF)
int control_relay(int state) {
    gpioWrite(GPIO_PIN, state);
    return 0;
}

// Function to log an event to the log file
int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received: %d. Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    if (server_socket != -1) {
        close(server_socket);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(GPIO_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Could not open log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        cleanup();
        return 1;
    }

    // Create server socket
    server_socket = create_server_socket();
    if (server_socket == -1) {
        log_event("Server socket creation failed");
        cleanup();
        return 1;
    }

    // Main loop to handle client connections and commands
    while (program_running) {
        int client_socket = accept_connection(server_socket);
        if (client_socket == -1) {
            continue; // Continue to the next iteration if accept fails
        }

        int bytes_received;
        while (program_running && (bytes_received = read_command(client_socket)) > 0) {
            char command[bytes_received + 1];
            strncpy(command, buffer, bytes_received);
            command[bytes_received] = '\0'; // Null-terminate the command

            int state = process_command(command);
            if (state != -1) {
                control_relay(state);
                log_event(state ? "Relay ON" : "Relay OFF");
