#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0 // ml/min
#define CRC_POLYNOMIAL 0x31 // CRC-8 polynomial
#define CRC_INIT 0x00
#define CRC_FINAL 0x00
#define START_MEASUREMENT_CMD 0x3608

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor(int i2c_handle, float *flow_rate);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len, uint8_t expected_crc);
int control_relay(int gpio_pin, int state);
void log_data(float flow_rate1, float flow_rate2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == expected_crc);
}

// I2C initialization function
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Sensor reading function
int read_sensor(int i2c_handle, float *flow_rate) {
    uint8_t buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // CRC validation
    if (!validate_crc(buffer, 3, buffer[2])) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert raw data to flow rate (ml/min)
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 100.0; // Scaling factor from datasheet

    return 0;
}

// Relay control function
int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Data logging function
void log_data(float flow_rate1, float flow_rate2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%s, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n", timestamp, flow_rate1, flow_rate2);
    fflush(fp);
    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    control_relay(RELAY_GPIO, 0); // De-energize relay
    gpioTerminate();
    fprintf(stderr, "Cleanup complete, exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float flow_rate1, flow_rate2;
    int relay_state = 0; // 0 = de-energized, 1 = energized

    while (!terminate) {
        // Read sensor data
        if (read_sensor(i2c_handle1, &flow_rate1) == 0 && read_sensor(i2c_handle2, &flow_rate2) == 0) {
            // Validate flow rates
            if (flow_rate1 < 0 || flow_rate2 < 0) {
                fprintf(stderr, "Invalid flow rate detected\n");
            } else {
                // Control relay
                if (flow_rate1 >= FLOW_THRESHOLD && flow_rate2 >= FLOW_THRESHOLD) {
                    relay_state = 0; // De-energize
                } else {
                    relay_state = 1; // Energize
                }

                if (relay_state != control_relay(RELAY_GPIO, relay_state)) {
                    fprintf(stderr, "Error controlling relay\n");
                }

                // Log data
                log_data(flow_rate1, flow_rate2);
            }
        } else {
            fprintf(stderr, "Sensor read failed, skipping relay control\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

