#define MOTOR_STOP_DURATION 1000  // milliseconds

// Define rain detection debounce time
#define RAIN_DEBOUNCE_TIME 600   // milliseconds

// Global variables
static volatile int running = 1;
static int rain_state = 1; // Assume initially dry
static int consecutive_rain_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void control_motor(int direction);
void stop_motor();
void log_event(int priority, const char *message);
void signal_handler(int signal);
