        usleep(MOTOR_CLOSE_DURATION * 1000); // Wait for specified duration
        stop_motor();
    } else { // Stop motor
        stop_motor();
    }
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    log_event(LOG_INFO, "Motor stopped");
}

