    if (initialize_gpio() != 0) {
        log_event(LOG_ERR, "GPIO initialisation failed, exiting");
        cleanup();
        return 1;
    }

    log_event(LOG_INFO, "Rain window control system started");

    // Main loop
    while (running) {
        int sensor_value = read_rain_sensor();

        if (sensor_value == 0 && rain_state == 1) { // Rain detected (sensor low)
            log_event(LOG_INFO, "Rain detected");
            control_motor(1); // Close window
            rain_state = 0; // Update rain state
            consecutive_rain_count = 0; // Reset debounce counter
        } else if (sensor_value == 1 && rain_state == 0) { // No rain (sensor high)
            log_event(LOG_INFO, "No rain detected");
            rain_state = 1; // Update rain state
            consecutive_rain_count++; // Increment debounce counter
            if (consecutive_rain_count >= (RAIN_DEBOUNCE_TIME / 200)) { // Check if debounce time has passed
                consecutive_rain_count = 0; // Reset debounce counter
            }
        }

        usleep(200000); // Poll every 200ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

