#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

// Define servo pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000
#define STOP_PULSE_WIDTH 0

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_lock_button();
int read_unlock_button();
int set_servo_pulse_width(int pulse_width);
void lock_door();
void unlock_door();
void shutdown();
void signal_handler(int signal);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_pressed = read_lock_button();
        int unlock_pressed = read_unlock_button();

        // Control servo based on button presses
        if (lock_pressed) {
            lock_door();
        } else if (unlock_pressed) {
            unlock_door();
        }

        // Small delay to reduce CPU usage
        gpioDelay(10000); // 10ms
    }

    // Shutdown before exiting
    shutdown();

    printf("Door lock control program stopped.\n");

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    return 0;
}

// Read lock button state
int read_lock_button() {
    return gpioRead(LOCK_BUTTON);
}

// Read unlock button state
int read_unlock_button() {
    return gpioRead(UNLOCK_BUTTON);
}

// Set servo pulse width
int set_servo_pulse_width(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width to %d\n", pulse_width);
        return 1;
    }
    return 0;
}

// Lock the door
void lock_door() {
    if (set_servo_pulse_width(LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to lock door\n");
        return;
    }
    printf("Door locked\n");
}

// Unlock the door
void unlock_door() {
    if (set_servo_pulse_width(UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to unlock door\n");
        return;
    }
    printf("Door unlocked\n");
}

// Shutdown the system
void shutdown() {
    printf("Shutting down...\n");
    set_servo_pulse_width(STOP_PULSE_WIDTH);
    gpioDelay(500000); // 0.5 second delay
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, stopping program...\n");
}

