#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Define constants
#define POLLING_INTERVAL_MS 100
#define LED_ON_DURATION_S 60

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, int duration);
void signal_handler(int signal);

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, int duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        if (strcmp(event_type, "motion_detected") == 0) {
            fprintf(log_file, "%s Motion detected\n", timestamp);
        } else if (strcmp(event_type, "led_activated") == 0) {
            fprintf(log_file, "%s LED activated for %d seconds\n", timestamp, duration);
        } else if (strcmp(event_type, "led_deactivated") == 0) {
            fprintf(log_file, "%s LED deactivated\n", timestamp);
        } else {
            fprintf(log_file, "%s Unknown event type: %s\n", timestamp, event_type);
        }
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    int led_state = 0; // 0 = off, 1 = on
    int led_on_time = 0;

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1 && led_state == 0) {
            // Motion detected
            printf("Motion detected!\n");
            log_event("motion_detected", 0); // Log motion detection

            // Activate LED
            control_led(1);
            led_state = 1;
            led_on_time = 0;
            log_event("led_activated", 0); // Log LED activation

            // Wait for LED_ON_DURATION_S seconds
            while (led_state == 1 && running) {
                gpioDelay(1000); // 1 second delay
                led_on_time++;
                if (led_on_time >= LED_ON_DURATION_S) {
                    led_state = 0;
                    control_led(0);
                    log_event("led_deactivated", 0); // Log LED deactivation
                    break;
                }
            }
        } else if (pir_value == 0) {
            // No motion
            gpioDelay(100); // Small delay to avoid busy-waiting
        } else {
            gpioDelay(100); // Small delay to avoid busy-waiting
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

