#define RELAY_GPIO 17
#define DEBOUNCE_TIME 200 // milliseconds
#define NUM_ELECTRODES 12

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTERING 0x41
#define MPR121_DEBOUNCE 0x5B
#define MPR121_FILTERTHRESHOLD 0x42
#define MPR121_FILTERCONFIG 0x5C
#define MPR121_AUTOCONFIG 0x5D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status(uint16_t *status);
void toggle_relay();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not disable electrodes during reset.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x80) < 0) {
        fprintf(stderr, "Error: Could not reset MPR121.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTERING, 0x24) < 0) {
        fprintf(stderr, "Error: Could not set baseline filtering.\n");
        return -1;
    }

    // Configure debounce
    if (i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE, 0x0A) < 0) {
        fprintf(stderr, "Error: Could not set debounce.\n");
        return -1;
    }

    // Configure FFI, SFI, and CDT
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTHRESHOLD, 0x05) < 0) {
        fprintf(stderr, "Error: Could not set FFI.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERCONFIG, 0x06) < 0) {
        fprintf(stderr, "Error: Could not set SFI.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_AUTOCONFIG, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set CDT.\n");
        return -1;
    }

    // Enable auto-config with range 0-7
    if (i2cWriteByteData(i2c_handle, MPR121_AUTOCONFIG, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set auto-config range.\n");
        return -1;
    }

    // Enable all 12 electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Could not enable electrodes.\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Could not read touch status.\n");
        return -1;
    }

    *status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to toggle the relay
void toggle_relay() {
    gpioWrite(RELAY_GPIO, 1); // Turn on relay
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus.\n");
        cleanup();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & (1 << 0)) { // Check if electrode 0 is touched
                toggle_relay();
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

