#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_SERVO 17
#define GPIO_PIR 4
#define PWM_FREQUENCY 50
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define PIR_READ_INTERVAL 100 // milliseconds

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
void log_message(int priority, const char *format, ...);
int initialize_gpio();
int setup_socket();
void handle_client(int client_fd);
void process_command(int client_fd, char *command);
void set_servo_angle(int angle);
int read_pir_sensor();
void signal_handler(int signal);
void cleanup();

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);

    if (log_file != NULL) {
        va_start(args, format);
        vfprintf(log_file, format, args);
        va_end(args);
        fflush(log_file);
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_SERVO, PI_OUTPUT);
    gpioSetMode(GPIO_PIR, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIR, PI_PUD_DOWN); // Optional: Pull-down resistor

    gpioSetPWMfrequency(GPIO_SERVO, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_SERVO, 1000); // Range of 0-1000 for 1ms-2ms

    log_message(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Setup TCP socket
int setup_socket() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed");
        close(server_fd);
        return -1;
    }

    log_message(LOG_INFO, "Socket setup successfully");
    return server_fd;
}

// Handle client connection
void handle_client(int client_fd) {
    char buffer[1024] = {0};
    int valread;

    valread = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        log_message(LOG_ERR, "Receive failed");
        close(client_fd);
        return;
    }
    buffer[valread] = '\0';
    log_message(LOG_INFO, "Received command: %s", buffer);

    process_command(client_fd, buffer);

    close(client_fd);
}

// Process command
void process_command(int client_fd, char *command) {
    char response[1024] = {0};
    int angle;

    if (strncmp(command, "the library's API call", 25) == 0) {
        // Extract angle from the command
        if (sscanf(command, "the library's API call %d", &angle) == 1) {
            if (angle >= 0 && angle <= 180) {
                set_servo_angle(angle);
                snprintf(response, sizeof(response), "Servo angle set to %d", angle);
            } else {
                snprintf(response, sizeof(response), "Invalid angle: %d. Angle must be between 0 and 180", angle);
            }
        } else {
            snprintf(response, sizeof(response), "Invalid command format");
        }
    } else if (strcmp(command, "PIR") == 0) {
        int pir_value = read_pir_sensor();
        if (pir_value == 1) {
            snprintf(response, sizeof(response), "PIR:1");
        } else {
            snprintf(response, sizeof(response), "PIR:0");
        }
    } else {
        snprintf(response, sizeof(response), "Unknown command");
    }

    send(client_fd, response, strlen(response), 0);
    log_message(LOG_INFO, "Sent response: %s", response);
}

// Set servo angle
void set_servo_angle(int angle) {
    int pulse_width = (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    gpioPWM(GPIO_SERVO, pulse_width);
    log_message(LOG_INFO, "Servo angle set to %d, pulse width: %d", angle, pulse_width);
}

// Read PIR sensor
int read_pir_sensor() {
    int pir_value = gpioRead(GPIO_PIR);
    log_message(LOG_INFO, "PIR sensor value: %d", pir_value);
    return pir_value;
}

// Signal handler
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received: %d. Shutting down...", signal);
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    log_message(LOG_INFO, "Cleaning up resources...");

    if (server_fd != -1) {
        close(server_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    log_message(LOG_INFO, "Cleanup complete. Exiting.");
    closelog();
}

int main() {
    // Open syslog
    openlog("servo_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Setup socket
    server_fd = setup_socket();
    if (server_fd == -1) {
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int new_socket;

    log_message(LOG_INFO, "Listening for connections...");

    while (program_running) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            if (program_running) {
                log_message(LOG_ERR, "Accept failed");
            }
            break;
        }

        handle_client(new_socket);
    }

    cleanup();
    return 0;
}

