#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_S 2

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_lux();
void control_relay(int lux);
void log_data(int lux);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int relay_pin;
    int lux_threshold;
    int retry_delay_ms;
    int sample_interval_s;
} Config;

Config config = {
    I2C_BUS,
    BH1750_ADDR,
    RELAY_GPIO,
    LUX_THRESHOLD,
    RETRY_DELAY_MS,
    SAMPLE_INTERVAL_S
};

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.bh1750_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read lux value from BH1750
int read_lux() {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char buffer[2];
    int lux = -1; // Default to error value

    if (i2cWriteByteData(i2c_handle, 0x00, config_cmd) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    gpioDelay(120); // Wait for measurement (at least 120ms)

    if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2) == 2) {
        lux = (buffer[0] << 8) | buffer[1];
    } else {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    return lux;
}

// Function to control the relay
void control_relay(int lux) {
    if (lux < config.lux_threshold) {
        gpioWrite(config.relay_pin, 1); // Activate relay
    } else {
        gpioWrite(config.relay_pin, 0); // Deactivate relay
    }
}

