            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, ERROR: Failed to read lux value\n", timestamp);
            fflush(log_file);
        }

        sleep(config.sample_interval_s);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

