#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <getopt.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;

// Function prototypes
int init_gpio();
int tare();
int read_hx711(int retries);
double calculate_weight(int raw_value);
void control_solenoid(double weight);
void signal_handler(int signal);
void cleanup();

// Structure to hold program configuration
typedef struct {
    double threshold;
    double scale;
    int duration;
} ProgramConfig;

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio. Exiting.");
        closelog();
        return 1;
    }

    // Tare the load cells
    if (tare() != 0) {
        syslog(LOG_ERR, "Failed to tare load cells. Exiting.");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read weight
        int raw_value = read_hx711(3);
        if (raw_value == -1) {
            syslog(LOG_ERR, "Failed to read HX711. Retrying.");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate weight
        double weight = calculate_weight(raw_value);

        // Control solenoid
        control_solenoid(weight);

        // Log weight
        syslog(LOG_INFO, "Weight: %.2f grams", weight);

        // Wait 500ms
        gpioDelay(500);
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Tare the load cells
int tare() {
    int i;
    long sum = 0;

    for (i = 0; i < 10; i++) {
        int raw_value = read_hx711(3);
        if (raw_value == -1) {
            syslog(LOG_ERR, "Failed to read HX711 during tare. Aborting.");
            return -1;
        }
        sum += raw_value;
        gpioDelay(100); // Small delay between readings
    }

    // Calculate average
    long average = sum / 10;

    // Subtract average from all readings
    for (i = 0; i < 10; i++) {
        int raw_value = read_hx711(3);
        if (raw_value == -1) {
            syslog(LOG_ERR, "Failed to read HX711 during tare. Aborting.");
            return -1;
        }
        raw_value -= average;
        gpioDelay(100); // Small delay between readings
    }

    return 0;
}

// Read HX711 amplifier
int read_hx711(int retries) {
    int i;
    int data = 0;

    // Wait for DOUT to go LOW
    int timeout = 1000; // 1 second timeout
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "Timeout waiting for HX711 DOUT to go LOW");
        return -1;
    }

    // Clock out 24 bits
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Clock out one extra pulse to select Channel A gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    return data;
}

// Calculate weight
double calculate_weight(int raw_value) {
    return (double)raw_value / scale;
}

// Control solenoid lock
void control_solenoid(double weight) {
    if (weight > threshold) {
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
        gpioDelay(duration);
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    }
}

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Terminate pigpio
}

