#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <getopt.h>
#include <mosquitto.h>
#include <pigpio.h>

#define DEFAULT_BROKER_ADDRESS "localhost"
#define DEFAULT_BROKER_PORT 1883
#define DEFAULT_CLIENT_ID "relay_controller_1"
#define DEFAULT_TOPIC "home/lights/control"
#define DEFAULT_KEEP_ALIVE 60

#define GPIO_PIN 17

struct relay_state {
    int state;
};

struct relay_state relay_state = {0}; // Initialize relay state to OFF

static struct mosquitto *mosq = NULL;
static char *broker_address = DEFAULT_BROKER_ADDRESS;
static int broker_port = DEFAULT_BROKER_PORT;
static char *client_id = DEFAULT_CLIENT_ID;
static char *topic = DEFAULT_TOPIC;
static int keep_alive = DEFAULT_KEEP_ALIVE;

static volatile int running = 1;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", broker_address, broker_port);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
    return 0;
}

int mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
    return 0;
}

int mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        const char *payload = (const char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1); // Turn relay ON
            relay_state.state = 1;
            syslog(LOG_INFO, "Relay set to ON");
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0); // Turn relay OFF
            relay_state.state = 0;
            syslog(LOG_INFO, "Relay set to OFF");
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
    return 0;
}

