#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <string.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target RPM
#define TARGET_RPM 50.0

// PI Controller Gains
#define Kp 10.0
#define Ki 0.1

// Anti-Windup Gain
#define AntiWindupGain 0.1

// Stall Detection Time (seconds)
#define STALL_TIME 2.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 10000.0

// Global Variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;

volatile int motor_a_stalled = 0;
volatile int motor_b_stalled = 0;

double integral_a = 0.0;
double integral_b = 0.0;

pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void motor_a_isr(int gpio, int level, uint32_t tick, void *user);
void motor_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double pi_controller(double setpoint, double actual, double *integral, double Kp, double Ki);
void set_motor_speed(int motor, double pwm);
void stop_motors();
void signal_handler(int signal);
void *stall_detection_thread(void *arg);

// Motor A Interrupt Service Routine
void motor_a_isr(int gpio, int level, uint32_t tick, void *user) {
    int a_state = gpioRead(ENCODER_A_A);
    int b_state = gpioRead(ENCODER_A_B);

    if (a_state && !b_state) {
        pthread_mutex_lock(&encoder_mutex);
        encoder_a_ticks++;
        pthread_mutex_unlock(&encoder_mutex);
    } else if (!a_state && b_state) {
        pthread_mutex_lock(&encoder_mutex);
        encoder_a_ticks--;
        pthread_mutex_unlock(&encoder_mutex);
    }
}

// Motor B Interrupt Service Routine
void motor_b_isr(int gpio, int level, uint32_t tick, void *user) {
    int a_state = gpioRead(ENCODER_B_A);
    int b_state = gpioRead(ENCODER_B_B);

    if (a_state && !b_state) {
        pthread_mutex_lock(&encoder_mutex);
        encoder_b_ticks++;
        pthread_mutex_unlock(&encoder_mutex);
    } else if (!a_state && b_state) {
        pthread_mutex_lock(&encoder_mutex);
        encoder_b_ticks--;
        pthread_mutex_unlock(&encoder_mutex);
    }
}

// Calculate RPM from encoder ticks
double calculate_rpm(int ticks) {
    return (double)ticks * 60.0 / 64.0; // 64 ticks per revolution
}

// PI Controller
double pi_controller(double setpoint, double actual, double *integral, double Kp, double Ki) {
    double error = setpoint - actual;
    *integral += error;
    return Kp * error + Ki * (*integral);
}

// Set motor speed using PWM
void set_motor_speed(int motor, double pwm) {
    int pwm_value = (int)pwm;

    if (pwm_value < 0) {
        pwm_value = 0;
    } else if (pwm_value > 255) {
        pwm_value = 255;
    }

    if (motor == 0) { // Motor A
        gpioWrite(MOTOR_A_DIR, 1); // Forward
        gpioPWM(MOTOR_A_PWM, pwm_value);
    } else { // Motor B
        gpioWrite(MOTOR_B_DIR, 1); // Forward
        gpioPWM(MOTOR_B_PWM, pwm_value);
    }
}

// Stop motors
void stop_motors() {
    gpioWrite(MOTOR_A_DIR, 0); // Stop
    gpioWrite(MOTOR_B_DIR, 0); // Stop
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    stop_motors();
    gpioTerminate();
    exit(0);
}

// Stall detection thread
void *stall_detection_thread(void *arg) {
    time_t start_time;
    while (1) {
        time(&start_time);
        motor_a_stalled = 0;
        motor_b_stalled = 0;

        while (1) {
            time_t current_time;
            time(&current_time);
            double elapsed_time = difftime(current_time, start_time);

            if (elapsed_time >= STALL_TIME) {
                break;
            }

            pthread_mutex_lock(&encoder_mutex);
            int a_ticks = encoder_a_ticks;
            int b_ticks = encoder_b_ticks;
            pthread_mutex_unlock(&encoder_mutex);

            if (a_ticks == 0) {
                motor_a_stalled = 1;
            }
            if (b_ticks == 0) {
                motor_b_stalled = 1;
            }

            gpioDelay(100000); // 100ms delay
        }

        if (motor_a_stalled) {
            printf("Motor A stalled!\n");
        }
        if (motor_b_stalled) {
            printf("Motor B stalled!\n");
        }

        // Reset stall flags
        motor_a_stalled = 0;
        motor_b_stalled = 0;

        gpioDelay(1000000); // Wait 1 second before checking again
    }
    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP);

    // Register interrupt handlers
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, motor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Motor A Encoder A A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_A, FALLING_EDGE, 0, motor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Motor A Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, motor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Motor A Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, FALLING_EDGE, 0, motor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Motor A Encoder A A\n");
        gpioTerminate();
        return 1;
    }

