#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYSTERESIS 10
#define I2C_BUS 1
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_bh1750(int *lux);
void control_relay(int state);
void log_data(int lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int relay_gpio;
    int dusk_threshold;
    int dawn_threshold;
    int hysteresis;
    char log_file[64];
} Config;

Config config = {
    I2C_BUS,
    BH1750_ADDR,
    GPIO_RELAY,
    LUX_THRESHOLD_DUSK,
    LUX_THRESHOLD_DAWN,
    HYSTERESIS,
    LOG_FILE
};

int main() {
    int lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        cleanup();
        return 1;
    }
    if (init_logging() != 0) {
        fprintf(stderr, "Failed to initialize logging. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            // Control relay based on lux value
            if (lux < config.dusk_threshold && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux > config.dawn_threshold && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_data(lux, relay_state);
            } else {
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Failed to read lux value. Retrying.\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.bh1750_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(config.relay_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        return -1;
    }
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int *lux) {
    char buf[2];
    int result;

    // Set mode to continuous high-resolution mode
    result = i2cWriteByteData(i2c_handle, 0x00, 0x10); // 0x10 = Continuous H-resolution mode
    if (result != 0) {
        fprintf(stderr, "Error setting BH1750 mode: %d\n", result);
        return -1;
    }
    gpioDelay(180); // Wait 180ms

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading BH1750 data: %d\n", result);
        return -1;
    }

    *lux = (buf[0] << 8) | buf[1];
    return 0;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(config.relay_gpio, state);
}

// Log data to file
void log_data(int lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.relay_gpio, 0); // Turn off relay
    gpioTerminate();
}

