#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define VALVE_GPIO 27
#define PULSES_PER_LITER 450.0
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5
#define DEBOUNCE_TIME_US 1000 // 1 millisecond debounce time

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file;
int valve_state = 1; // 1 = open, 0 = closed
int running = 1;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulses);
void control_valve(double flow_rate);
void log_data(double flow_rate, int valve_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for the flow sensor
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate flow rate in LPM
double calculate_flow_rate(int pulses) {
    double flow_rate = (double)pulses / PULSES_PER_LITER * 60.0; // pulses per second * 60 seconds/minute
    return flow_rate;
}

// Function to control the solenoid valve
void control_valve(double flow_rate) {
    if (flow_rate > FLOW_THRESHOLD_HIGH && valve_state == 1) {
        gpioWrite(VALVE_GPIO, 0); // Close the valve
        valve_state = 0;
        log_data(0.0, valve_state);
    } else if (flow_rate < FLOW_THRESHOLD_LOW && valve_state == 0) {
        gpioWrite(VALVE_GPIO, 1); // Open the valve
        valve_state = 1;
        log_data(0.0, valve_state);
    }
}

// Function to log data to a file
void log_data(double flow_rate, int valve_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow Rate: %.2f LPM, Valve State: %s\n", timestamp, flow_rate, valve_state ? "OPEN" : "CLOSED");
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set initial valve state
    gpioWrite(VALVE_GPIO, 1); // Open the valve initially

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(VALVE_GPIO, 1); // Ensure valve is open on exit
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    // Set up interrupt on flow sensor pin
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIME_US, pulse_counter_isr, NULL);

    time_t last_log_time = time(NULL);
    int last_valve_state = valve_state;

    while (running) {
        // Sample pulse count and calculate flow rate
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = calculate_flow_rate(current_pulse_count);

        // Control the valve
        control_valve(flow_rate);

        // Log data every second
        time_t current_time = time(NULL);
        if (difftime(current_time, last_log_time) >= 1.0) {
            log_data(flow_rate, valve_state);
            last_log_time = current_time;
        }

        // Hysteresis logic: only log valve state changes if the valve state has changed
        if (valve_state != last_valve_state) {
            log_data(flow_rate, valve_state);
            last_valve_state = valve_state;
        }

        gpioDelay(1000); // Delay for 1 second (1000 ms)
    }

    cleanup();
    return 0;
}

