#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <cjson/cJSON.h>
#include <errno.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default values
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_SERVO_PIN 18
#define DEFAULT_TCP_PORT 12345
#define DEFAULT_LOG_FILE "dispensing_log.json"

// HX711 GPIO pins
#define HX711_DATA_PIN 23
#define HX711_CLOCK_PIN 24

// Servo motor GPIO pin
#define SERVO_PIN 18

// TCP port
#define TCP_PORT DEFAULT_TCP_PORT

// Global variables
static int tcp_socket = -1;
static int servo_pin = DEFAULT_SERVO_PIN;
static int calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char *log_file_path = DEFAULT_LOG_FILE;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config();
int hx711_read();
double hx711_calibrate();
int hx711_set_zero();
int hx711_get_offset();
double hx711_get_weight();
int servo_set_pulse_width(int pulse_width);
int servo_set_angle(double angle);
double map_weight_to_pulse_width(double target_weight, double calibration_factor);
int tcp_listen();
int tcp_accept();
int tcp_read(int socket, char *buffer, int buffer_size);
int tcp_write(int socket, const char *buffer);
int log_event(const char *event);
void signal_handler(int signal);

// HX711 read function
int hx711_read() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    gpioWrite(HX711_CLOCK_PIN, 0);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 1000) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "HX711 timeout: Data pin never went low\n");
        return -1; // Timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us pulse width
    }

    // 25th pulse for gain 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us pulse width
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us pulse width

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// HX711 calibrate function
double hx711_calibrate() {
    double known_weight;
    double offset;
    int raw_value;

    printf("Place the known weight on the load cell: ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input for known weight\n");
        return -1.0;
    }

    raw_value = hx711_read();
    if (raw_value == -1) {
        fprintf(stderr, "Error reading HX711 during calibration\n");
        return -1.0;
    }

    offset = raw_value - (known_weight * calibration_factor);
    printf("Calibration offset: %lf\n", offset);
    return offset;
}

// HX711 set zero function
int hx711_set_zero() {
    double offset = hx711_calibrate();
    if (offset == -1.0) {
        fprintf(stderr, "Calibration failed\n");
        return -1;
    }
    return 0;
}

// HX711 get offset function
int hx711_get_offset() {
    FILE *fp = fopen("hx711_offset.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Offset file not found, using default calibration factor\n");
        return -1;
    }
    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Invalid offset file format\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration factor from file: %lf\n", calibration_factor);
    return 0;
}

// HX711 get weight function
double hx711_get_weight() {
    int raw_value = hx711_read();
    if (raw_value == -1) {
        fprintf(stderr, "Error reading HX711\n");
        return -1.0;
    }
    return (double)raw_value / calibration_factor;
}

// Servo set pulse width function
int servo_set_pulse_width(int pulse_width) {
    if (pulse_width < 1000 || pulse_width > 2000) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioPWM(SERVO_PIN, pulse_width);
    return 0;
}

// Servo set angle function
int servo_set_angle(double angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle: %lf\n", angle);
        return -1;
    }

    int pulse_width = (int)(1000 + (angle / 180.0) * 1000);
    return servo_set_pulse_width(pulse_width);
}

// Map weight to pulse width function
double map_weight_to_pulse_width(double target_weight, double calibration_factor) {
    // Assuming a linear relationship between weight and pulse width
    // Adjust these values based on your specific setup
    double min_weight = 0.0;  // Minimum weight to dispense
    double max_weight = 100.0; // Maximum weight to dispense
    double min_pulse_width = 1000.0; // Minimum pulse width
    double max_pulse_width = 2000.0; // Maximum pulse width

    double pulse_width = min_pulse_width + (target_weight - min_weight) * (max_pulse_width - min_pulse_width) / (max_weight - min_weight);

    // Ensure pulse width is within the valid range
    if (pulse_width < min_pulse_width) {
        pulse_width = min_pulse_width;
    } else if (pulse_width > max_pulse_width) {
        pulse_width = max_pulse_width;
    }

    return pulse_width;
}

// TCP listen function
int tcp_listen() {
    struct sockaddr_in server_addr;

    tcp_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (tcp_socket == -1) {
        perror("Error creating socket");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(TCP_PORT);

    if (bind(tcp_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error binding socket");
        close(tcp_socket);
        return -1;
    }

    if (listen(tcp_socket, 5) < 0) {
        perror("Error listening on socket");
        close(tcp_socket);
        return -1;
    }

    printf("Listening on port %d...\n", TCP_PORT);
    return 0;
}

// TCP accept function
int tcp_accept() {
    struct sockaddr_in client_addr;
    int client_socket;
    socklen_t client_len = sizeof(client_addr);

    client_socket = accept(tcp_socket, (struct sockaddr *)&client_addr, &client_len);
    if (client_socket < 0) {
        perror("Error accepting connection");
        return -1;
    }

    printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
    return client_socket;
}

// TCP read function
int tcp_read(int socket, char *buffer, int buffer_size) {
    ssize_t bytes_read = recv(socket, buffer, buffer_size - 1, 0);
    if (bytes_read < 0) {
        perror("Error reading from socket");
        return -1;
    } else if (bytes_read == 0) {
        printf("Client disconnected\n");
        return 0;
    }
    buffer[bytes_read] = '\0';
    return bytes_read;
}

// TCP write function
int tcp_write(int socket, const char *buffer) {
    ssize_t bytes_sent = send(socket, buffer, strlen(buffer), 0);
    if (bytes_sent < 0) {
        perror("Error writing to socket");
        return -1;
    }
    return 0;
}

// Log event function
int log_event(const char *event) {
    FILE *fp = fopen(log_file_path, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Read configuration from file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Configuration file not found. Using default values.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse the line
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "servo_pin") == 0) {
                servo_pin = atoi(value);
            } else if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "tcp_port") == 0) {
                TCP_PORT = atoi(value);
            } else if (strcmp(key, "log_file") == 0) {
                log_file_path = strdup(value); // Allocate memory for the string
            }
        }
    }

    fclose(fp);
    printf("Configuration loaded:\n");
    printf("  Servo pin: %d\n", servo_pin);
    printf("  Calibration factor: %lf\n", calibration_factor);
    printf("  TCP port: %d\n", TCP_PORT);
    printf("  Log file: %s\n", log_file_path);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

