// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time in milliseconds
#define DEFAULT_DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int debounce_time = DEFAULT_DEBOUNCE_TIME;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce(int current_state, int previous_state, int debounce_time_ms);
int toggle_relay(int current_state);
int log_relay_state(int relay_state);
void signal_handler(int signal);
