// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce(int current_state, int previous_state, int debounce_time_ms) {
    gpioDelay(debounce_time_ms * 1000); // Convert ms to microseconds
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
int toggle_relay(int current_state) {
    int new_state = !current_state;
    gpioWrite(RELAY_PIN, new_state);
    return new_state;
}

// Function to log the relay state to a file
int log_relay_state(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

