void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        long debounce_time_long = strtol(argv[1], &endptr, 10);

        if (*endptr != '\0' || debounce_time_long <= 0) {
            fprintf(stderr, "Invalid debounce time. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_TIME);
        } else {
            debounce_time = (int)debounce_time_long;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0; // Initial relay state: OFF
    int touch_state = 0;  // Initial touch sensor state

    // Main loop
    while (running) {
        touch_state = read_touch_sensor();

        if (touch_state == 1) {
            // Debounce the touch sensor
            if (debounce(touch_state, touch_state, debounce_time) == 1) {
                // Toggle the relay
                relay_state = toggle_relay(relay_state);

                // Log the relay state
                log_relay_state(relay_state);
            }
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

