#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_S 5

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    int gpio_pin;
    int debounce_ms;
    int sample_interval_s;
    volatile int pulse_count;
    volatile unsigned long last_pulse_time;
} program_state_t;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio(int gpio_pin);
void cleanup_gpio(int gpio_pin);
void log_rpm(FILE *fp, double rpm);
void pulse_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_rpm(int pulse_count, double time_interval_s);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the specified GPIO pin for input with pull-up bias
int initialize_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", gpio_pin);
        return -1;
    }
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO %d to pull-up mode\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Releases the specified GPIO pin and terminates the pigpio library
void cleanup_gpio(int gpio_pin) {
    gpioSetMode(gpio_pin, PI_INPUT); // Set to input to avoid spurious interrupts
    gpioTerminate();
}

// Logs the RPM value to the specified file in CSV format
void log_rpm(FILE *fp, double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.2f\n", timestamp, rpm);
    fflush(fp); // Ensure data is written to disk immediately
}

// Callback function for pulse detection
void pulse_callback(int gpio, int level, unsigned int tick, void *user_data) {
    program_state_t *state = (program_state_t *)user_data;
    unsigned long current_time = tick;

    if (current_time - state->last_pulse_time > state->debounce_ms * 1000) {
        state->pulse_count++;
        state->last_pulse_time = current_time;
    }
}

// Calculates the RPM based on the pulse count and time interval
double calculate_rpm(int pulse_count, double time_interval_s) {
    return (double)pulse_count / time_interval_s * 60.0;
}

int main() {
    program_state_t state = {
        .gpio_pin = GPIO_PIN,
        .debounce_ms = DEBOUNCE_MS,
        .sample_interval_s = SAMPLE_INTERVAL_S,
        .pulse_count = 0,
        .last_pulse_time = 0
    };

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pin
    if (initialize_gpio(state.gpio_pin) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup_gpio(state.gpio_pin);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt callback for rising edge detection
    if (gpioSetISRFuncEx(state.gpio_pin, RISING_EDGE, 0, pulse_callback, &state) != 0) {
        fprintf(stderr, "Error setting up interrupt callback\n");
        fclose(log_file);
        cleanup_gpio(state.gpio_pin);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        gpioDelay(state.sample_interval_s * 1000); // Sleep for the sample interval

        // Calculate RPM
        double rpm = calculate_rpm(state.pulse_count, state.sample_interval_s);

        // Log RPM
        log_rpm(log_file, rpm);

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Reset pulse count
        state.pulse_count = 0;
    }

    // Cleanup and exit
    gpioSetISRFuncEx(state.gpio_pin, RISING_EDGE, 0, NULL, &state); // Disable interrupt
    fclose(log_file);
    cleanup_gpio(state.gpio_pin);
    gpioTerminate();

    return 0;
}

