// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 500000 // 0.5 seconds in microseconds
#define DEBOUNCE_DELAY 50000  // 50ms in microseconds
#define FORCE_OFF_DELAY 10000000 // 10 seconds in microseconds

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially OFF

    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
}

// Function to force the relay OFF
void force_relay_off() {
    gpioWrite(RELAY_PIN, 0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    int touch_detected = 0;
    unsigned long last_touch_time = 0;
    unsigned long force_off_timer = 0;

    while (program_running) {
        int touch_value = read_touch_sensor();

        if (touch_value == 1) {
            if (!touch_detected) {
                touch_detected = 1;
                last_touch_time = gpioTick();
                toggle_relay();
                gpioDelay(RELAY_ON_TIME);
                gpioWrite(RELAY_PIN, 0); // Turn off after on time
            }
        } else {
            touch_detected = 0;
        }

        if (touch_detected) {
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_DELAY) {
                last_touch_time = current_time;
            } else {
                // Debounce delay exceeded, force relay off
                if (current_time - force_off_timer > FORCE_OFF_DELAY) {
                    force_relay_off();
                    force_off_timer = current_time;
                }
            }
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup and exit
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated.\n");
    return 0;
}

