#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100kHz

// Define RFID tag
#define VALID_TAG 0x0102030405060708090A

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid();
int verify_tag(unsigned char *tag);
void engage_locks();
void disengage_locks();
void log_access(int valid_tag, int button_pressed);
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to read RFID tag
int read_rfid() {
    unsigned char buffer[10];
    int result;

    result = spiXfer(spi_handle, buffer, buffer, 10);
    if (result != 10) {
        fprintf(stderr, "Error: SPI read failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Check for no tag present (all zeros)
    if (buffer[0] == 0 && buffer[1] == 0 && buffer[2] == 0 && buffer[3] == 0 &&
        buffer[4] == 0 && buffer[5] == 0 && buffer[6] == 0 && buffer[7] == 0 &&
        buffer[8] == 0 && buffer[9] == 0) {
        return 0; // No tag
    }

    // Convert to unsigned char array
    unsigned char tag[10];
    for (int i = 0; i < 10; i++) {
        tag[i] = buffer[i];
    }

    return 0; // Indicate success
}

// Function to verify RFID tag
int verify_tag(unsigned char *tag) {
    return (tag[0] == (VALID_TAG & 0xFF) && tag[1] == ((VALID_TAG >> 8) & 0xFF) &&
            tag[2] == ((VALID_TAG >> 16) & 0xFF) && tag[3] == ((VALID_TAG >> 24) & 0xFF) &&
            tag[4] == ((VALID_TAG >> 32) & 0xFF) && tag[5] == ((VALID_TAG >> 40) & 0xFF) &&
            tag[6] == ((VALID_TAG >> 48) & 0xFF) && tag[7] == ((VALID_TAG >> 56) & 0xFF));
}

// Function to engage locks
void engage_locks() {
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    printf("Locks engaged\n");
}

// Function to disengage locks
void disengage_locks() {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    printf("Locks disengaged\n");
}

// Function to log access attempts
void log_access(int valid_tag, int button_pressed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Valid Tag: %s, Button Pressed: %s\n",
            timestamp, valid_tag ? "Yes" : "No", button_pressed ? "Yes" : "No");
    fflush(log_file);
}

// Callback function for button press
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active low)
        printf("Button pressed\n");
        log_access(0, 1); // Log button press
        disengage_locks();
        gpioDelay(5000); // Wait 5 seconds
        engage_locks();
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;

    // Close SPI interface
    spiClose(spi_handle);

    // Force locks to engaged state
    engage_locks();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Call the library's API call() before exiting
    // (Replace with the actual API call if needed)

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function for button press
    gpioSetAlertFunc(BUTTON_PIN, button_callback);

    printf("Door access control system started\n");

    // Main loop
    while (!terminate) {
        int rfid_result = read_rfid();
        if (rfid_result == 0) {
            int valid_tag = verify_tag((unsigned char *)spi_handle); //spi_handle is a file descriptor, not a pointer to an array
            log_access(valid_tag, 0); // Log RFID read
            if (valid_tag) {
                printf("Valid tag detected\n");
                // Add code here to grant access (e.g., call button_callback)
            }
        } else if (rfid_result < 0) {
            fprintf(stderr, "Error: RFID read failed\n");
            log_access(0, 0); // Log RFID read failure
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup (should not reach here if signal handler is working)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

