void set_motor_speed(int motor, double duty_cycle);
void signal_handler(int signal);

// Quadrature decoding function
int decode_quadrature(int a, int b) {
    if (a == 1 && b == 0) return 1;  // Clockwise
    if (a == 0 && b == 1) return -1; // Counter-clockwise
    return 0; // No change
}

