#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define POLLING_INTERVAL_MS 50

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTER_CONFIG 0x5B
#define MPR121_TOUCH_THRESHOLD_L 0x41
#define MPR121_RELEASE_THRESHOLD_L 0x4D
#define MPR121_SOFTRESET 0x80

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int touch_status);
void log_relay_state(int touch_status);
void signal_handler(int signal);

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filter
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTER_CONFIG, 0x05) < 0) {
        fprintf(stderr, "Error: Baseline filter config failed\n");
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD_L + 2 * i, 0x30) < 0) {
            fprintf(stderr, "Error: Touch threshold config failed for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD_L + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Release threshold config failed for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Electrode config failed\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to control the relay based on the touch status
void control_relay(int touch_status) {
    if (touch_status > 0) {
        gpioWrite(RELAY_GPIO, 1); // Set relay HIGH
    } else {
        gpioWrite(RELAY_GPIO, 0); // Set relay LOW
    }
}

// Function to log the relay state to a file
void log_relay_state(int touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Relay state: %s\n", timestamp, (touch_status > 0) ? "HIGH" : "LOW");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            control_relay(touch_status);
            log_relay_state(touch_status);
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }
        gpioDelay(POLLING_INTERVAL_MS); // Delay for polling interval
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

