// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FILTER_CONFIG 0x2B
#define MPR121_ELECTRODE_CONFIG_1 0x5F
#define MPR121_ELECTRODE_CONFIG_2 0x60
#define MPR121_ELECTRODE_CONFIG_3 0x61
#define MPR121_ELECTRODE_CONFIG_4 0x62
#define MPR121_ELECTRODE_CONFIG_5 0x63
#define MPR121_ELECTRODE_CONFIG_6 0x64
#define MPR121_ELECTRODE_CONFIG_7 0x65
#define MPR121_ELECTRODE_CONFIG_8 0x66
#define MPR121_ELECTRODE_CONFIG_9 0x67
#define MPR121_ELECTRODE_CONFIG_10 0x68
#define MPR121_ELECTRODE_CONFIG_11 0x69

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void relay_toggle();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// MPR121 initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode.\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (i2cWriteByteData(i2c_handle, MPR121_FILTER_CONFIG, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set filter config.\n");
        return -1;
    }

    // Configure electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG_1, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current.\n");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode.\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

// Function to read touch status from MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to toggle the relay
void relay_toggle() {
    static int relay_state = 0;
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    printf("Relay toggled to %d\n", relay_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                relay_toggle();
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

