#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLLING_INTERVAL_MS 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_relay();
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int pir_state;
    unsigned long last_unlock_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1 && state.pir_state == 0) {
            // Motion detected
            log_event("Motion Detected");
            activate_relay();
            state.last_unlock_time = time(NULL) * 1000; // Store the current time in milliseconds
            state.pir_state = 1; // Set the PIR state to 1 to prevent multiple triggers
        } else if (pir_value == 0) {
            state.pir_state = 0; // Reset PIR state when motion stops
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Activate the relay for a specified duration
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    log_event("Door Unlocked");
}

// Log an event to the log file
