#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define minimum and maximum step durations (ms)
#define MIN_STEP_DURATION 50
#define MAX_STEP_DURATION 200

// Define minimum and maximum duty cycles (0-255)
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global variable to track program state for graceful shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down...\n");
        shutdown_flag = 1;
    }
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes for the motor pins
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    // Set PWM range
    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a random PWM duty cycle
int generate_duty_cycle() {
    return rand() % (PWM_RANGE + 1);
}

// Function to generate a random step duration
int generate_step_duration() {
    return (rand() % (MAX_STEP_DURATION - MIN_STEP_DURATION + 1)) + MIN_STEP_DURATION;
}

// Function to set the PWM duty cycle for a motor
int set_motor_pwm(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to generate a random haptic feedback pattern
int generate_pattern(int *pattern, int pattern_length) {
    for (int i = 0; i < pattern_length; i++) {
        pattern[i * 3 + 0] = generate_duty_cycle(); // Motor 1 duty cycle
        pattern[i * 3 + 1] = generate_duty_cycle(); // Motor 2 duty cycle
        pattern[i * 3 + 2] = generate_step_duration(); // Step duration
    }
    return 0;
}

// Function to play a haptic feedback pattern
void play_pattern(int *pattern, int pattern_length) {
    for (int i = 0; i < pattern_length; i++) {
        if (set_motor_pwm(MOTOR1_PIN, pattern[i * 3 + 0]) != 0) {
            fprintf(stderr, "Error setting PWM for Motor 1\n");
        }
        if (set_motor_pwm(MOTOR2_PIN, pattern[i * 3 + 1]) != 0) {
            fprintf(stderr, "Error setting PWM for Motor 2\n");
        }
        gpioDelay(pattern[i * 3 + 2] * 1000); // Convert ms to microseconds
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!shutdown_flag) {
        // Generate a random pattern length (5-15)
        int pattern_length = (rand() % 11) + 5;

        // Allocate memory for the pattern
        int *pattern = (int *)malloc(pattern_length * 3 * sizeof(int));
        if (pattern == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            break; // Exit the loop if memory allocation fails
        }

        // Generate the pattern
        if (generate_pattern(pattern, pattern_length) != 0) {
            fprintf(stderr, "Failed to generate pattern\n");
            free(pattern);
            break; // Exit the loop if pattern generation fails
        }

        // Play the pattern
        play_pattern(pattern, pattern_length);

        // Free the allocated memory
        free(pattern);
    }

    // Stop the motors
    set_motor_pwm(MOTOR1_PIN, 0);
    set_motor_pwm(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

