#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define weight threshold (in kg)
#define WEIGHT_THRESHOLD 10.0

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Define log file name
#define LOG_FILE "weight_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;
static double scale_factor = 1.0;
static double offset = 0.0;

// Function prototypes
int initialize_gpio();
int read_hx711();
double calculate_weight(int raw_value);
void control_solenoid(double weight);
void log_data(int raw_value, double weight);
int load_calibration();
int save_calibration();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially unlocked

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioWrite(HX711_CLOCK_PIN, 0);
    while (gpioRead(HX711_DATA_PIN) == 1) {
        timeout++;
        if (timeout > 1000) {
            fprintf(stderr, "HX711 read timeout\n");
            return -1; // Indicate timeout error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
    }

    // 25th pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    }
}

// Function to log data to file
void log_data(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_value, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load calibration data from file
int load_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Failed to open calibration file, using defaults\n");
        return 1; // Indicate failure to open file
    }

    if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Failed to read calibration data, using defaults\n");
        fclose(calibration_file);
        return 1; // Indicate failure to read data
    }

    fclose(calibration_file);
    return 0; // Indicate success
}

// Function to save calibration data to file
int save_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Failed to open calibration file for writing\n");
        return 1; // Indicate failure to open file
    }

    fprintf(calibration_file, "%lf %lf", scale_factor, offset);
    fclose(calibration_file);
    return 0; // Indicate success
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked on exit

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Release GPIO resources

    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Load calibration data
    if (load_calibration() != 0) {
        fprintf(stderr, "Using default calibration values\n");
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Weight-triggered solenoid lock system started\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value);
            control_solenoid(weight);
            log_data(raw_value, weight);
        } else {
            fprintf(stderr, "Skipping iteration due to HX711 read error\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Save calibration data before exiting
    save_calibration();

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

