    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Weight-triggered solenoid lock system started\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
