#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define constants
#define WEIGHT_THRESHOLD 100.0  // grams
#define SOLENOID_DURATION 5.0   // seconds
#define CALIBRATION_FACTOR 100.0 // Example calibration factor
#define TIMEOUT_US 1000000       // 1 second timeout

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
float convert_to_grams(int raw_value, float calibration_factor);
void activate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for the HX711 to be ready
    while (gpioRead(HX711_DT) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        log_event("HX711 timeout");
        return -1; // Indicate timeout error
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to grams
float convert_to_grams(int raw_value, float calibration_factor) {
    return (float)raw_value / calibration_factor;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    log_event("Solenoid activated");
    gpioDelay(SOLENOID_DURATION * 1000); // Wait for 5 seconds
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    log_event("Solenoid deactivated");
}

