void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            float weight = convert_to_grams(raw_value, CALIBRATION_FACTOR);
            char message[100];
            snprintf(message, sizeof(message), "Weight: %.2f grams", weight);
            log_event(message);

            if (weight < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold, activating solenoid");
                activate_solenoid();
            }
        } else {
            log_event("Failed to read HX711");
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup and exit
    log_event("Program exiting");
    cleanup_gpio();
    fclose(log_file);
    return 0;
}

