#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Define log file name
#define LOG_FILE "security.log"

// Define weight threshold (in kg)
#define WEIGHT_THRESHOLD 5.0

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 100

// Define solenoid activation duration (in seconds)
#define SOLENOID_DURATION 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Function prototypes
int init_gpio();
int read_hx711();
double calibrate_weight();
double get_weight();
void activate_solenoid();
void log_event(double weight);
void signal_handler(int signal);
void cleanup();

// Structure to hold calibration data
typedef struct {
    double offset;
    double scale;
} CalibrationData;

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int32_t data = 0;
    int timeout_count = 0;

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1us delay

    while (gpioRead(HX711_DATA_PIN) == 1) {
        timeout_count++;
        if (timeout_count > 1000) { // Timeout after 1000 loops (approx. 100ms)
            fprintf(stderr, "HX711 timeout\n");
            return -1; // Indicate timeout
        }
        gpioDelay(1); // 1us delay
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1us delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1us delay
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1us delay

    data = data ^ 0x800000; // Convert to signed 24-bit integer

    return data;
}

// Function to calibrate the weight
double calibrate_weight() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input\n");
        return -1.0;
    }

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "HX711 read error during calibration\n");
        return -1.0;
