#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_PWM_PIN 22
#define RIGHT_MOTOR_PWM_PIN 23
#define LEFT_MOTOR_DIR_PIN 24
#define RIGHT_MOTOR_DIR_PIN 25

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define motor speeds
#define BASE_SPEED 150
#define HALF_SPEED (BASE_SPEED / 2)

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensors(int *left, int *middle, int *right);
void set_motor_speed(int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Structure to hold motor direction and speed
typedef struct {
    int direction;
    int speed;
} MotorState;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set sensor pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Set motor control pins as outputs
    gpioSetMode(LEFT_MOTOR_PWM_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM_PIN, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to read sensor values
int read_sensors(int *left, int *middle, int *right) {
    *left = gpioRead(LEFT_SENSOR_PIN);
    *middle = gpioRead(MIDDLE_SENSOR_PIN);
    *right = gpioRead(RIGHT_SENSOR_PIN);

    // Invert the readings because of active-low signal
    *left = !(*left);
    *middle = !(*middle);
    *right = !(*right);

    return 0;
}

// Function to set motor speeds
void set_motor_speed(int left_speed, int right_speed) {
    // Ensure speeds are within valid range
    if (left_speed < 0) left_speed = 0;
    if (left_speed > 255) left_speed = 255;
    if (right_speed < 0) right_speed = 0;
    if (right_speed > 255) right_speed = 255;

    // Set motor directions based on sensor readings
    if (*middle == 0) {
        // Straight
        gpioWrite(LEFT_MOTOR_DIR_PIN, PI_HIGH);
        gpioWrite(RIGHT_MOTOR_DIR_PIN, PI_HIGH);
        gpioPWM(LEFT_MOTOR_PWM_PIN, left_speed);
        gpioPWM(RIGHT_MOTOR_PWM_PIN, right_speed);
    } else if (*left == 0) {
        // Turn right
        gpioWrite(LEFT_MOTOR_DIR_PIN, PI_HIGH);
        gpioWrite(RIGHT_MOTOR_DIR_PIN, PI_LOW);
        gpioPWM(LEFT_MOTOR_PWM_PIN, left_speed);
        gpioPWM(RIGHT_MOTOR_PWM_PIN, right_speed / 2);
    } else if (*right == 0) {
        // Turn left
        gpioWrite(LEFT_MOTOR_DIR_PIN, PI_LOW);
        gpioWrite(RIGHT_MOTOR_DIR_PIN, PI_HIGH);
        gpioPWM(LEFT_MOTOR_PWM_PIN, left_speed / 2);
        gpioPWM(RIGHT_MOTOR_PWM_PIN, right_speed);
    } else {
        // Stop
        gpioPWM(LEFT_MOTOR_PWM_PIN, 0);
        gpioPWM(RIGHT_MOTOR_PWM_PIN, 0);
    }
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;

    // Stop motors
    gpioPWM(LEFT_MOTOR_PWM_PIN, 0);
    gpioPWM(RIGHT_MOTOR_PWM_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    int left_sensor, middle_sensor, right_sensor;
    int left_speed, right_speed;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensors
        if (read_sensors(&left_sensor, &middle_sensor, &right_sensor) != 0) {
            fprintf(stderr, "Error reading sensors!\n");
        }

        // Determine motor speeds based on sensor readings
        if (*middle_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (*left_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = HALF_SPEED;
        } else if (*right_sensor == 0) {
            left_speed = HALF_SPEED;
            right_speed = BASE_SPEED;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        // Set motor speeds
        set_motor_speed(left_speed, right_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        // Delay for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    return 0;
}

