#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid pulse width (%d). Must be between %d and %d.\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1; // Indicate failure
    }

    gpioServo(gpio, pulse_width);
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read lock button state
        int lock_button_state = gpioRead(LOCK_BUTTON_PIN);

        // Read unlock button state
        int unlock_button_state = gpioRead(UNLOCK_BUTTON_PIN);

        // Debounce lock button
        if (lock_button_state == 0) { // Active low
            gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
            if (gpioRead(LOCK_BUTTON_PIN) == 0) { // Re-read to confirm
                printf("Lock button pressed. Setting servo to 0 degrees.\n");
                if (set_servo_pulse_width(SERVO_PIN, SERVO_MIN_PULSE_WIDTH) != 0) {
                    fprintf(stderr, "Error setting servo pulse width for lock.\n");
                }
                gpioDelay(500000); // Keep servo at 0 for 0.5 seconds
                set_servo_pulse_width(SERVO_PIN, 1500); // Reset to a safe position
            }
        }

        // Debounce unlock button
        if (unlock_button_state == 0) { // Active low
            gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) { // Re-read to confirm
                printf("Unlock button pressed. Setting servo to 180 degrees.\n");
                if (set_servo_pulse_width(SERVO_PIN, SERVO_MAX_PULSE_WIDTH) != 0) {
                    fprintf(stderr, "Error setting servo pulse width for unlock.\n");
                }
                gpioDelay(500000); // Keep servo at 180 for 0.5 seconds
                set_servo_pulse_width(SERVO_PIN, 1500); // Reset to a safe position
            }
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

