#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define pulse durations in milliseconds
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Function prototypes
int initialize_gpio();
void motor1_pulse();
void motor2_pulse();
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop to repeatedly pulse the motors
    while (program_running) {
        motor1_pulse();
        motor2_pulse();
    }

    // Cleanup GPIO pins before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an output
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as an output
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to pulse motor 1
void motor1_pulse() {
    // Set GPIO17 HIGH
    if (gpioWrite(MOTOR1_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write HIGH to GPIO%d\n", MOTOR1_PIN);
    }

    // Delay for MOTOR1_DURATION milliseconds
    gpioDelay(MOTOR1_DURATION * 1000); // pigpioDelay takes microseconds

    // Set GPIO17 LOW
    if (gpioWrite(MOTOR1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write LOW to GPIO%d\n", MOTOR1_PIN);
    }
}

// Function to pulse motor 2
void motor2_pulse() {
    // Set GPIO27 HIGH
    if (gpioWrite(MOTOR2_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write HIGH to GPIO%d\n", MOTOR2_PIN);
    }

    // Delay for MOTOR2_DURATION milliseconds
    gpioDelay(MOTOR2_DURATION * 1000); // pigpioDelay takes microseconds

    // Set GPIO27 LOW
    if (gpioWrite(MOTOR2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write LOW to GPIO%d\n", MOTOR2_PIN);
    }
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Set both GPIO pins LOW
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();
    printf("GPIO cleanup and pigpio termination complete.\n");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d).  Stopping motors and cleaning up GPIO.\n", signal);
    program_running = 0; // Set the flag to exit the main loop
    cleanup_gpio();       // Call the cleanup function
    exit(0);              // Exit the program
}

