#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ topic
#define ZMQ_TOPIC "SOUND_ALERTS"

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
void *zmq_context = NULL;
void *zmq_socket = NULL;

// Function prototypes
int initialize_gpio();
int initialize_zmq();
int sound_sensor_mode();
int alarm_node_mode();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Initialize ZeroMQ
int initialize_zmq() {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        return -1;
    }

    zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
    if (!zmq_socket) {
        fprintf(stderr, "Failed to create ZeroMQ socket\n");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    int rc = zmq_connect(zmq_socket, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to connect ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    rc = zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (rc != 0) {
        fprintf(stderr, "Failed to set ZeroMQ subscribe option: %s\n", zmq_strerror(errno));
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    return 0;
}

// Sound sensor mode
int sound_sensor_mode() {
    printf("Sound sensor mode started\n");
    while (program_running) {
        int sensor_value = gpioRead(SOUND_SENSOR_PIN);
        if (sensor_value == 0) { // Sound detected (active low)
            printf("Sound detected!\n");
            // Publish alert
            char *message = strdup(ZMQ_TOPIC);
            if (!message) {
                fprintf(stderr, "Failed to allocate memory for message\n");
                break;
            }
            int rc = zmq_send(zmq_socket, message, strlen(message), 0);
            free(message);
            if (rc == -1) {
                fprintf(stderr, "Failed to send message: %s\n", zmq_strerror(errno));
                break;
            }
        }
        gpioDelay(10); // 10ms delay
    }
    return 0;
}

// Alarm node mode
int alarm_node_mode() {
    printf("Alarm node mode started\n");
    while (program_running) {
        zmq_msg_t message;
        zmq_msg_init(&message);
        int rc = zmq_msg_recv(&message, zmq_socket, 0);
        if (rc == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "Failed to receive message: %s\n", zmq_strerror(errno));
            break;
        }

        char *data = zmq_msg_data(&message);
        size_t size = zmq_msg_size(&message);

        if (size > 0 && strncmp(data, ZMQ_TOPIC, size) == 0) {
            printf("Received alert: %s\n", data);
            gpioWrite(ALARM_LED_PIN, 1); // Turn on LED
            gpioDelay(1000);             // Wait for 1 second
            gpioWrite(ALARM_LED_PIN, 0); // Turn off LED
        }

        zmq_msg_close(&message);
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (zmq_socket) {
        zmq_close(zmq_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return 1;
    }

    const char *mode = argv[1];

    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize ZeroMQ
    if (strcmp(mode, "alarm_node") == 0 && initialize_zmq() != 0) {
        cleanup();
        return 1;
    }

    // Execute the appropriate mode
    if (strcmp(mode, "sound_sensor") == 0) {
        sound_sensor_mode();
    } else {
        alarm_node_mode();
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

