#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

// Configuration
#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define CHECKSUM_MASK 0x7E
#define CHECKSUM_SHIFT 4

// NEC Command Structure
typedef struct {
    unsigned int address;
    unsigned int command;
} nec_command_t;

// Global Variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int pulse_count = 0;
static unsigned int pulse_times[MAX_PULSES];

// Function Prototypes
void signal_handler(int signal);
int initialize_pigpio();
int initialize_mqtt();
void cleanup();
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(unsigned int *pulse_times, int pulse_count, nec_command_t *command);
int validate_checksum(unsigned int address, unsigned int command);
int publish_mqtt(nec_command_t command);
void log_message(int priority, const char *message);

// Signal Handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Initialize MQTT
int initialize_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }

    gpioTerminate();
    closelog();
}

// IR Receiver Callback
void ir_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t pulse_length;

    if (level == FALLING_EDGE) {
        pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < MAX_PULSES) {
            pulse_times[pulse_count++] = pulse_length;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
            pulse_count = 0; // Reset to avoid further overflows
        }
    }
}

// Decode NEC command
int decode_nec(unsigned int *pulse_times, int pulse_count, nec_command_t *command) {
    if (pulse_count < 68) {
        syslog(LOG_ERR, "Not enough pulses received (%d)", pulse_count);
        return -1;
    }

    // Check for valid NEC header
    if (pulse_times[0] < 8000 || pulse_times[0] > 9000 || pulse_times[1] < 4000 || pulse_times[1] > 5000) {
        syslog(LOG_ERR, "Invalid NEC header");
        return -1;
    }

    command->address = 0;
    command->command = 0;

    // Decode address (bits 0-7)
    for (int i = 2; i < 10; i++) {
        command->address <<= 1;
        if (pulse_times[2 * i] > 1500) {
            command->address |= 1;
        }
    }

    // Decode command (bits 8-15)
    for (int i = 10; i < 18; i++) {
        command->command <<= 1;
        if (pulse_times[2 * i] > 1500) {
            command->command |= 1;
        }
    }

    // Decode inverted address (bits 16-23)
    for (int i = 18; i < 26; i++) {
        command->address <<= 1;
        if (pulse_times[2 * i] > 1500) {
            command->address |= 1;
        }
    }

    // Decode inverted command (bits 24-31)
    for (int i = 26; i < 34; i++) {
        command->command <<= 1;
        if (pulse_times[2 * i] > 1500) {
            command->command |= 1;
        }
    }

    return 0;
}

// Validate checksum
int validate_checksum(unsigned int address, unsigned int command) {
    unsigned int inverted_address = ~address;
    unsigned int inverted_command = ~command;

    if ((inverted_address & CHECKSUM_MASK) != ((inverted_command >> CHECKSUM_SHIFT) & CHECKSUM_MASK)) {
        syslog(LOG_ERR, "Checksum validation failed");
        return -1;
    }

    return 0;
}

// Publish to MQTT
int publish_mqtt(nec_command_t command) {
    json_t *root = json_object();
    json_object_set_new(root, "address", json_integer(command.address));
    json_object_set_new(root, "command", json_integer(command.command));

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(6));
    if (!json_str) {
        syslog(LOG_ERR, "Failed to serialize JSON");
        json_decref(root);
        return -1;
    }

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(json_str), json_str, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(rc));
        free(json_str);
        json_decref(root);
        return -1;
    }

    free(json_str);
    json_decref(root);

    return 0;
}

// Log message
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        syslog(LOG_ERR, "pigpio initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (initialize_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up callback
    gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL);

    // Main loop
    while (running) {
        // Check for MQTT connection
        if (mosquitto_loop(mosq, 0, 1) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_WARNING, "MQTT connection lost, attempting to reconnect...");
            mosquitto_reconnect(mosq);
        }

        // Process pulses
        if (pulse_count > 0) {
            nec_command_t command;
            if (decode_nec(pulse_times, pulse_count, &command) == 0) {
                if (validate_checksum(command.address, command.command) == 0) {
                    if (publish_mqtt(command) == 0) {
                        char log_message_buffer[256];
                        snprintf(log_message_buffer, sizeof(log_message_buffer), "Decoded command: Address=0x%02X, Command=0x%02X", command.address, command.command);
                        log_message(LOG_INFO, log_message_buffer);
                    } else {
                        syslog(LOG_ERR, "Failed to publish MQTT message");
                    }
                } else {
                    syslog(LOG_ERR, "Checksum validation failed");
                }
            } else {
                syslog(LOG_ERR, "Failed to decode NEC command");
            }
            pulse_count = 0; // Reset pulse count after processing
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    cleanup();

    return 0;
}

