#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x23
#define SENSOR2_ADDR 0x24
#define SENSOR3_ADDR 0x25
#define SENSOR4_ADDR 0x26

// Define multicast address and port
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005

// Define BH1750 command for continuous high-resolution mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
int i2c_handle1, i2c_handle2, i2c_handle3, i2c_handle4;
int udp_socket;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float lux;
} sensor_data_t;

// Function prototypes
int init_i2c(int addr);
float read_lux(int i2c_handle);
int send_udp_packet(sensor_data_t *data, int num_sensors);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c(int addr) {
    int handle = i2cOpen(1, addr, 0); // I2C bus 1
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read lux value from BH1750 sensor
float read_lux(int i2c_handle) {
    char buf[2];
    int result;

    // Send start conversion command
    result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return NAN;
    }

    // Wait for conversion (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read two bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return NAN;
    }

    // Convert data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Send UDP multicast packet
int send_udp_packet(sensor_data_t *data, int num_sensors) {
    char buffer[256];
    int offset = 0;

    // Format data into comma-separated string
    for (int i = 0; i < num_sensors; i++) {
        offset += snprintf(buffer + offset, sizeof(buffer) - offset, "%d,%.1f", data[i].sensor_id, data[i].lux);
        if (i < num_sensors - 1) {
