#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_MSB_REG 0x00
#define FLOW_LSB_REG 0x01
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *msb, uint8_t *lsb);
float convert_to_slpm(uint16_t raw_flow);
char* get_timestamp();
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        printf("I2C connection closed.\n");
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        printf("Log file closed.\n");
    }

    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    printf("I2C bus opened successfully.\n");
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint8_t *msb, uint8_t *lsb) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, FLOW_MSB_REG, (char*)msb, 1); // Read MSB
        if (result != 1) {
            fprintf(stderr, "Error reading MSB (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        result = i2cReadI2CBlockData(i2c_handle, FLOW_LSB_REG, (char*)lsb, 1); // Read LSB
        if (result != 1) {
            fprintf(stderr, "Error reading LSB (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw data to SLPM
float convert_to_slpm(uint16_t raw_flow) {
    // Mask the 14-bit flow value
    uint16_t masked_flow = raw_flow & 0x3FFF; // 0x3FFF is 14 bits of 1

    // Convert to SLPM (0-20 SLPM range)
    float flow_rate = (float)masked_flow * 20.0 / 16383.0;
    return flow_rate;
}

// Get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t msb, lsb;
    uint16_t raw_flow;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&msb, &lsb) == 0) {
            // Combine MSB and LSB
            raw_flow = (msb << 8) | lsb;

            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_flow);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

