#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 register addresses
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0x86
#define AS7341_F1DATAH 0x94
#define AS7341_F1DATAL 0x95
#define AS7341_F2DATAH 0x96
#define AS7341_F2DATAL 0x97
#define AS7341_F3DATAH 0x98
#define AS7341_F3DATAL 0x99
#define AS7341_F4DATAH 0x9A
#define AS7341_F4DATAL 0x9B
#define AS7341_F5DATAH 0x9C
#define AS7341_F5DATAL 0x9D
#define AS7341_F6DATAH 0x9E
#define AS7341_F6DATAL 0x9F
#define AS7341_F7DATAH 0xA0
#define AS7341_F7DATAL 0xA1
#define AS7341_F8DATAH 0xA2
#define AS7341_F8DATAL 0xA3
#define AS7341_CDATAL 0xA4
#define AS7341_NIDATAL 0xA5

// Sensor identification value
#define AS7341_ID 0x4133373334310000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *channel_data);
float calculate_lux(uint16_t *channel_data);
int log_data(uint16_t *channel_data, float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the AS7341 sensor
int initialize_sensor() {
    // Verify sensor ID
    uint16_t sensor_id;
    if (i2cReadWordData(i2c_handle, AS7341_ENABLE) < 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    sensor_id = i2cReadWordData(i2c_handle, AS7341_ENABLE);

    if (sensor_id != AS7341_ID) {
        fprintf(stderr, "Incorrect sensor ID: 0x%08X (expected 0x%08X)\n", sensor_id, AS7341_ID);
        return -1;
    }

    // Power on the sensor
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error powering on sensor\n");
        return -1;
    }

    // Configure SMUX
    if (i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x00) < 0) {
        fprintf(stderr, "Error configuring SMUX\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error enabling spectral measurement\n");
        return -1;
    }

    return 0;
}

// Reads spectral data from the AS7341 sensor
int read_sensor_data(uint16_t *channel_data) {
    int result;

    result = i2cReadWordData(i2c_handle, AS7341_F1DATAH);
    if (result < 0) return -1;
    channel_data[0] = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, AS7341_F2DATAH);
    if (result < 0) return -1;
    channel_data[1] = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, AS7341_F3DATAH);
    if (result < 0) return -1;
    channel_data[2] = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, AS7341_F4DATAH);
