#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x4C
#define D7S_REG_X_LSB 0x28
#define D7S_REG_X_MSB 0x29
#define D7S_REG_Y_LSB 0x2A
#define D7S_REG_Y_MSB 0x2B
#define D7S_REG_Z_LSB 0x2C
#define D7S_REG_Z_MSB 0x2D
#define D7S_REG_STATUS 0x20
#define D7S_REG_CTRL 0x2E
#define D7S_CTRL_MEASURE 0x01
#define D7S_CTRL_RESET 0x02
#define D7S_STATUS_SENSOR_ABSENT 0x01
#define D7S_STATUS_BUS_ERROR 0x02
#define D7S_STATUS_MEASURING 0x04
#define D7S_STATUS_READY 0x08

#define DEFAULT_SAMPLE_INTERVAL 1 // seconds
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"

// Global variables
int i2c_handle;
int i2c_address = D7S_ADDR;
int sample_interval = DEFAULT_SAMPLE_INTERVAL;
char *output_filename = DEFAULT_OUTPUT_FILENAME;
FILE *error_log_file = NULL;
FILE *data_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int log_data(float x_g, float y_g, float z_g);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, D7S_REG_CTRL, D7S_CTRL_RESET) < 0) {
        log_error("Failed to reset sensor");
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure for continuous measurement mode
    if (i2cWriteByteData(i2c_handle, D7S_REG_CTRL, D7S_CTRL_MEASURE) < 0) {
        log_error("Failed to configure sensor");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, D7S_REG_X_LSB, buffer, 6);
    if (result != 6) {
        log_error("Failed to read sensor data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to g
float convert_to_g(int16_t raw_value) {
    // D7S sensitivity is 0.001 g/LSB
    return (float)raw_value * 0.001;
}

// Function to log data to CSV file
int log_data(float x_g, float y_g, float z_g) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
    fflush(data_log_file); // Ensure data is written immediately

    return 0;
}

// Function to log errors to log file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
    perror(message); // Also print to stderr

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and files
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_log_file != NULL) {
        fclose(data_log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sample_interval = strtol(optarg, NULL, 0);
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sample_interval] [-f output_filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_log_file = fopen("seismic_error.log", "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        gpioTerminate();
        return 1;
    }

    // Open data log file
    data_log_file = fopen(output_filename, "a");
    if (data_log_file == NULL) {
        log_error("Failed to open data log file");
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(data_log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            x_g = convert_to_g(sensor_data.x);
            y_g = convert_to_g(sensor_data.y);
            z_g = convert_to_g(sensor_data.z);

            log_data(x_g, y_g, z_g);
        } else {
            log_error("Failed to read sensor data, retrying...");
        }

        gpioDelay(sample_interval * 1000); // Delay for sample_interval seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

