#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define I2C_BUS 1

int i2c_handle = -1;
int udp_socket = -1;

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

float read_bh1750() {
    char config_cmd = CONTINUOUS_HIGH_RES_MODE;
    char buffer[2];
    int lux_raw;

    if (i2cWriteByteData(i2c_handle, 0x00, config_cmd) != 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        return -1.0;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750\n");
        return -1.0;
    }

    lux_raw = (buffer[0] << 8) | buffer[1];
    return (float)lux_raw / 1.2;
}

int main() {
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    float lux;
    char lux_str[20];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    while (1) {
        lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        snprintf(lux_str, sizeof(lux_str), "%.2f", lux);

        if (sendto(udp_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&addr, addrlen) < 0) {
            perror("sendto");
        }

        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

