FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    double timestamp;
    int object_index;
    double range_m;
    double velocity_mps;
} RadarData;

// Function prototypes
int initialize_uart();
int read_uart_data(char *buffer, int max_size);
int validate_magic_word(const char *buffer, int size);
int parse_tlv_data(const char *buffer, int size, RadarData *data);
int write_data_to_csv(const RadarData *data);
void signal_handler(int signal);
