// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", UART_DEVICE);
        return -1;
    }
    return 0;
}

// Read data from UART
int read_uart_data(char *buffer, int max_size) {
    int bytes_read = serRead(uart_handle, buffer, max_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    }
    return bytes_read;
}

// Validate magic word
int validate_magic_word(const char *buffer, int size) {
    if (size < MAGIC_WORD_SIZE) {
        return -1; // Not enough data
    }

    unsigned long long magic = 0;
    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        magic = (magic << 8) | (unsigned char)buffer[i];
    }

    if (magic != MAGIC_WORD) {
        return -1; // Magic word mismatch
    }

    return 0;
}

// Parse TLV data (simplified example)
int parse_tlv_data(const char *buffer, int size, RadarData *data) {
    // This is a placeholder.  A real implementation would parse the TLV structure.
    // For this example, we'll just extract some dummy data.
    if (size < 8) return -1; // Need at least timestamp and object index

    memcpy(&data->timestamp, buffer, sizeof(double));
    memcpy(&data->object_index, buffer + sizeof(double), sizeof(int));

    // Dummy data for range and velocity
    data->range_m = (double)(rand() % 100) / 10.0; // Range between 0.0 and 10.0
    data->velocity_mps = (double)(rand() % 20) / 10.0 - 1.0; // Velocity between -1.0 and 1.9

    return 0;
}

