    if (csv_file == NULL) {
        fprintf(stderr, "CSV file is not open.\n");
        return -1;
    }

    fprintf(csv_file, "%.6f,%d,%.2f,%.2f\n", data->timestamp, data->object_index, data->range_m, data->velocity_mps);
    fflush(csv_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

