    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    char buffer[MAX_FRAME_SIZE];
    int bytes_read;
    RadarData radar_data;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        bytes_read = read_uart_data(buffer, MAX_FRAME_SIZE);
        if (bytes_read > 0) {
            if (validate_magic_word(buffer, bytes_read) == 0) {
                if (parse_tlv_data(buffer, bytes_read, &radar_data) == 0) {
                    write_data_to_csv(&radar_data);
                } else {
                    fprintf(stderr, "Error parsing TLV data.\n");
                }
            } else {
                fprintf(stderr, "Invalid magic word.\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            gpioDelay(100); // Small delay before retrying
        }
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Exiting.\n");
    return 0;
}

