#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_SEC 0.5
#define MAX_BUFFER_SIZE 256
#define MAX_LINE_SIZE 64

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Structure to hold program state
typedef struct {
    char line_buffer[MAX_BUFFER_SIZE];
    int line_buffer_index;
    int uart_fd;
} ProgramState;

// Function prototypes
int setup_uart(const char *device, speed_t baud_rate);
int read_uart(int fd, char *buffer, int max_len);
int parse_data(const char *data, ProgramState *state);
int log_data(const char *data);
void signal_handler(int signal);
void cleanup(int fd);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
    }
}

// Setup UART
int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = (int)(INTER_BYTE_TIMEOUT_SEC * 10); // Timeout in deciseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART
int read_uart(int fd, char *buffer, int max_len) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select");
        return -1;
    } else if (retval) {
        int bytes_read = read(fd, buffer, max_len - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            return bytes_read;
        } else if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else {
            return 0; // No data available
        }
    } else {
        // Timeout occurred
        return 0;
    }
}

// Parse data from the line buffer
int parse_data(const char *data, ProgramState *state) {
    char *line = strdup(data);
    if (line == NULL) {
        perror("strdup failed");
        return -1;
    }

    char *newline = strchr(line, '\n');
    if (newline != NULL) {
        *newline = '\0'; // Null-terminate at the newline character
        if (log_data(line) != 0) {
            fprintf(stderr, "Error logging data: %s\n", line);
        }
        state->line_buffer_index = 0;
        memset(state->line_buffer, 0, sizeof(state->line_buffer));
    } else {
        // Line is incomplete, append to the buffer
        size_t line_len = strlen(line);
        size_t remaining_space = sizeof(state->line_buffer) - state->line_buffer_index - 1;
        if (line_len > remaining_space) {
            fprintf(stderr, "Line too long, discarding: %s\n", line);
            free(line);
            return -1;
        }
        strncpy(state->line_buffer + state->line_buffer_index, line, line_len);
        state->line_buffer_index += line_len;
        state->line_buffer[state->line_buffer_index] = '\0';
        free(line);
        return 0;
    }
    free(line);
    return 0;
}

// Log data to stdout
int log_data(const char *data) {
    char timestamp_str[32];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %s meters\n", timestamp_str, data);
    return 0;
}

// Cleanup resources
void cleanup(int fd) {
    if (fd != -1) {
        close(fd);
    }
    program_running = 0;
}

int main() {
    ProgramState state = {0}; // Initialize the program state
    state.line_buffer_index = 0;

    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    // Setup UART
    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("UART setup complete. Reading data...\n");

    while (program_running) {
        char buffer[MAX_LINE_SIZE];
        int bytes_read = read_uart(uart_fd, buffer, MAX_LINE_SIZE);

        if (bytes_read > 0) {
            parse_data(buffer, &state);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }

        // Small delay to prevent busy-waiting
        usleep(10000); // 10ms
    }

    cleanup(uart_fd);
    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

