#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART port
#define UART_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables
int uart_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_uart();
void cleanup();
void signal_handler(int signal);
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void send_uart_message(const char *message);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} SensorData;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        fprintf(stderr, "UART initialization failed. Continuing without UART.\n");
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left, middle, right);

        // Check for emergency stop condition
        if (left == 0 && middle == 0 && right == 0) {
            send_uart_message("EMERGENCY STOP!\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup resources
    cleanup();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_PORT, BAUD_RATE, 0); // 0 for no flags
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", UART_PORT);
        return 1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close UART port if open
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Read sensor data
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Log sensor data with timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Send message over UART
void send_uart_message(const char *message) {
    if (uart_handle >= 0) {
        int bytes_written = serWrite(uart_handle, message, strlen(message));
        if (bytes_written < 0) {
            fprintf(stderr, "Error writing to UART: %s\n", message);
        }
    } else {
        fprintf(stderr, "UART not initialized. Message: %s\n", message);
    }
}

